export default {"1":{"html":"<p>तुम्ही एक रुपया जोखीम पत्करण्याआधी महत्त्वाच्या असलेल्या प्रश्नाचे उत्तर देणारा एकल तक्ता चित्रित करा. जर NIFTY येथे वरती, किंवा मध्यभागी सपाट, किंवा तळाशी खूप कमी असेल, तर तुम्ही खरोखर काय बनवाल किंवा गमावाल? तो एक तक्ता आहे <strong>पेऑफ आकृती</strong>, आणि ते वाचायला शिकणे हे या कोर्समधील प्रत्येक नामांकित धोरणामागील खरे कौशल्य आहे. स्ट्रॅटेजी म्हणजे पर्याय पायांच्या एका संचापेक्षा अधिक काही नाही आणि त्याचा पेऑफ डायग्राम हा स्टॅक कसा वागतो याचे प्रामाणिक चित्र आहे. चित्रावर प्रभुत्व मिळवा आणि फॅन्सी नावे महत्त्वाची ठरतील. तुम्ही कोणतेही संयोजन पहाल आणि काही सेकंदात सांगाल, ते कुठे कमावते, कुठे रक्तस्त्राव होतो आणि ओळीवर किती आहे. OpenAlgo <strong>धोरण बिल्डर</strong> तुमच्यासाठी हे चित्र काढतो आणि या कोर्समधील प्रत्येक चार्ट थेट त्यातून येतो, 26 जून 2026 रोजी कॅप्चर केलेल्या वास्तविक NIFTY पर्यायांच्या किमतींवर बनवलेला.</p>\n<h2 id=\"a-payoff-diagram-is-a-picture-of-your-money\">पेऑफ डायग्राम हे तुमच्या पैशाचे चित्र आहे</h2>\n<p>या कोर्समधील प्रत्येक पेऑफ चार्ट समान दोन अक्ष सामायिक करतो, म्हणून तुम्ही एकदा वाचले की तुम्ही ते सर्व वाचू शकता.</p>\n<ul>\n<li>क्षैतिज अक्ष आहे <strong>एक्सपायरीच्या वेळी NIFTY ची किंमत</strong>. NIFTY हा निर्देशांक आहे, या धोरणांचे नैसर्गिक घर आहे, कारण त्याचे पर्याय देशातील सर्वात द्रव आहेत. 26 जून 2026 रोजी निर्देशांक एका ठिकाणी बसला <strong>24,056</strong>, at-द-मनी स्ट्राइक सह <strong>24,050</strong>. साठी प्रत्येक तक्ता काढला आहे <strong>28 जुलै 2026</strong> मासिक कालबाह्यता, NSE मासिक जे मंगळवारी येते सुमारे 32 दिवस बाहेर. तुमचा डोळा डावीकडे प्रवास करताना NIFTY खाली पडला आणि उजवीकडे प्रवास करत असताना NIFTY वर आला.</li>\n<li>उभा अक्ष तुझा <strong>नफा किंवा तोटा</strong> संपूर्ण स्थितीवर, एका लॉटसाठी रुपयांमध्ये <strong>65</strong>. शून्य रेषेच्या वर तुम्ही नफ्यात आहात, त्याखाली तुम्ही तोट्यात आहात.</li>\n</ul>\n<p>एकल सर्वात महत्वाचे वैशिष्ट्य आहे <strong>शून्य रेषा</strong>, ज्या पातळीवर नफा आणि तोटा काहीच नाही. जिथे स्ट्रॅटेजी वर बसली आहे तिथे तुम्ही पैसे कमवत आहात आणि जिथे ते खाली बसले आहे तिथे तुमचे नुकसान होत आहे. संपूर्ण गेम वाचत आहे जेथे ओळ प्रत्येक संभाव्य बंद किंमतीवर राहते.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>पेऑफ डायग्राम तुमचा नफा किंवा तोटा (उभ्या) कालबाह्यतेच्या वेळी (क्षैतिज) NIFTY च्या किमतीच्या विरूद्ध 65 च्या एका लॉटमध्ये रुपयात प्लॉट करतो. शून्य रेषेच्या वर नफा आहे, खाली तोटा आहे. ओळ कुठे बसते ते वाचा आणि तुम्हाला कोणत्याही किंमतीला तुमचा निकाल कळेल.</p>\n</div></div>\n<h2 id=\"the-two-lines-at-expiry-and-today\">दोन ओळी: एक्सपायरी आणि आज</h2>\n<p>कोणत्याही बिल्डर चार्टकडे बारकाईने पहा आणि तुम्हाला एक नव्हे तर दोन ओळी दिसतील. ते वेगवेगळ्या कथा सांगतात आणि तुम्हाला दोन्हीची गरज आहे.</p>\n<ul>\n<li>द <strong>केशरी \"एक्सपायरी\" ओळ</strong> शेवटच्या दिवशी, 28 जुलै 2026 रोजी तुमच्या स्थितीचे मूल्य आहे, जेव्हा सर्व वेळ मूल्य संपुष्टात आले आहे आणि फक्त आंतरिक मूल्य शिल्लक आहे. हा स्वच्छ, गुंतासारखा आकार आहे ज्याचा अर्थ बहुतेक लोक पेऑफ करतात. जर तुम्ही शेवटची घंटा धरली तर तुम्ही काय ठेवता किंवा देणे लागतो.</li>\n<li>द <strong>निळ्या डॅशची \"T+0\" ओळ</strong> तुमच्या आजच्या स्थितीचे मूल्य आहे, आत्ता, शून्य दिवस उलटून गेले आहेत, ज्याचा अर्थ T+0 आहे. हे नितळ आणि गोलाकार आहे कारण पर्याय अजूनही वेळेचे मूल्य धारण करतात.</li>\n</ul>\n<p>वेळेमुळे दोघांमध्ये फरक आहे. NIFTY च्या समान किमतीसाठी एक्सपायरी होण्यापेक्षा एक्सपायरीपूर्वी पर्याय अधिक मोलाचा आहे, कारण इंडेक्सला तुमचा मार्ग हलवायला अजून वेळ आहे. ते अतिरिक्त मूल्य आहे <strong>वेळेचे मूल्य</strong>, आणि कालबाह्यता जवळ आल्यावर ते वितळते. शेवटच्या दिवसापर्यंत ब्लू टुडे लाइन ऑरेंज एक्सपायरी लाईनवर कोसळली आहे. त्यामुळे तुमची स्क्रीन आता दाखवते ती निळी डॅश केलेली रेषा आहे, आणि काहीही लवकर बंद न केल्यास तुम्ही कुठे जात आहात हे केशरी रेषा दाखवते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>ऑरेंज ॲट एक्स्पायरी लाइन हे तुमचे गंतव्यस्थान आहे. आज तुम्ही जिथे उभे आहात तिथे निळ्या रंगाची T+0 लाईन आहे. जसजसे दिवस निघून जातात तसतसे निळी रेषा केशरी रेषेकडे सरकते, कारण प्रत्येक पर्यायामध्ये भाजलेले वेळ मूल्य कालबाह्यतेने शून्यावर जाते.</p>\n</div></div>\n<h2 id=\"profit-zones-loss-zones-and-the-breakeven\">नफा क्षेत्र, नुकसान क्षेत्र आणि ब्रेकवेन</h2>\n<p>एकदा तुम्हाला शून्य रेषा सापडली की, चार्ट दोन छायांकित प्रदेशांमध्ये विभाजित होतो.</p>\n<ul>\n<li>द <strong>नफा क्षेत्र</strong> ही प्रत्येक क्लोजिंग किंमत आहे जिथे ऑरेंज एक्सपायरी लाइन शून्याच्या वर बसते. बिल्डर या हिरव्या रंगाची छटा देतो.</li>\n<li>द <strong>नुकसान क्षेत्र</strong> ही प्रत्येक क्लोजिंग किंमत आहे जिथे केशरी रेषा शून्याच्या खाली बसते, लाल छायांकित.</li>\n</ul>\n<p>ऑरेंज लाईन शून्य ओलांडते तिथे अचूक किंमत a आहे <strong>ब्रेकवेन</strong>, ज्या जवळ तुम्ही बनवत नाही आणि गमावत नाही. काही रणनीतींमध्ये एक ब्रेकवेन असतो, अनेकांना दोन असतात, काहींमध्ये चार असतात. बिल्डर थेंब an <strong>एम्बर ब्रेकवेन डॉट</strong> प्रत्येक क्रॉसिंगवर जेणेकरून तुमची नजर त्यावर पडेल. त्या बिंदूच्या एका बाजूला सर्व काही नफा आहे, सर्व काही तोटा आहे, म्हणून ब्रेकईव्हन हे हिरवे आणि लाल यांच्यामधील सीमा कुंपण आहे.</p>\n<p>दोन सपाट खुणा हे दृश्य पूर्ण करतात. द <strong>जास्तीत जास्त नफा</strong> केशरी रेषा आतापर्यंत पोहोचलेली सर्वोच्च आहे, आणि <strong>जास्तीत जास्त नुकसान</strong> तो बुडणारा सर्वात कमी आहे. परिभाषित-जोखीम धोरणासाठी दोन्ही सपाट, मर्यादित शेल्फ् 'चे अव रुप आहेत, त्यामुळे तुम्ही ऑर्डर देण्यापूर्वी तुमची सर्वोत्तम आणि सर्वात वाईट स्थिती तुम्हाला माहीत आहे.</p>\n<h2 id=\"the-sigma-bands-and-the-spot-line\">सिग्मा बँड आणि स्पॉट लाइन</h2>\n<p>प्रत्येक बिल्डरच्या चार्टवर आणखी दोन वैशिष्ट्ये तुम्हाला सांगतात की बाजाराला काय अपेक्षित आहे.</p>\n<ul>\n<li>एक तेजस्वी <strong>गुलाबी उभी रेषा</strong> वर्तमान चिन्हांकित करते <strong>24,056 वर स्पॉट</strong>, म्हणून तुम्ही एका दृष्टीक्षेपात पाहू शकता की आजNIFTY′ जेथून प्रत्येक ब्रेकइव्हन किती अंतरावर आहे.</li>\n<li>पेऑफच्या मागे फिकट छायांकित बसा <strong>सिग्मा बँड</strong>, ज्याला मानक विचलन बँड देखील म्हणतात. आतील जोडी एक मानक विचलन हलवा चिन्हांकित करते आणि बाहेरील जोडी दोन मानक विचलन चाल दर्शवते, ज्याचे मोजमाप पैसे एट-द-मनी गर्भित अस्थिरतेवरून केले जाते <strong>12.7 टक्के</strong> आणि दिवस संपायला उरले आहेत. सोप्या शब्दात, ते पर्याय बाजाराची किंमत किती श्रेणीत आहे ते दर्शवितात. NIFTY आतील बँडमध्ये तीनपैकी दोन वेळा आणि बाहेरील बँडमध्ये जवळजवळ नेहमीच पूर्ण होणे अपेक्षित आहे.</li>\n</ul>\n<p>ते बँड रिॲलिटी चेक आहेत. जर एखादी स्ट्रॅटेजी फक्त NIFTY बाहेरील बँडच्या बाहेर उतरते तेव्हाच फायदा होत असेल, तर बाजार तुम्हाला सांगत आहे की परिणाम संभव नाही. जर त्याचा लाभ क्षेत्र आरामात आतील बँड व्यापत असेल, तर शक्यता अधिक अनुकूल असतात. तुम्ही बाजाराला प्रत्यक्षात अपेक्षित असलेल्या हालचालींच्या विरुद्ध व्यापार वाचत आहात, इच्छाशक्तीच्या विरोधात नाही.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>कोणतीही रणनीती ठरवण्यापूर्वी, त्याचा ग्रीन प्रॉफिट झोन अस्पष्ट सिग्मा बँड्सच्या विरुद्ध कुठे आहे ते पहा. आतील एक मानक विचलन बँड कव्हर करणारा नफा क्षेत्र संभाव्य परिणामांवर सट्टा लावत आहे. ज्याला बाह्य बँडच्या पलीकडे NIFTY आवश्यक आहे तो दुर्मिळ एकावर सट्टा लावत आहे. बँड अंदाजाला माहितीपूर्ण वाचनात बदलतात.</p>\n</div></div>\n<h2 id=\"legs-the-pieces-you-stack\">पाय: तुम्ही स्टॅक केलेले तुकडे</h2>\n<p>ए <strong>पाय</strong> तुमच्या स्थितीत एकच पर्याय आहे. तुम्हाला ऑप्शन्स बेसिकमधील चार पाय आधीच माहित आहेत, प्रत्येक रणनीती ज्या चार अणूंपासून तयार केली जाते.</p>\n<ul>\n<li>कॉल खरेदी करा, खरेदी करण्याचा अधिकार, जेव्हा तुम्ही वाढीची अपेक्षा करता.</li>\n<li>कॉल विक्री करा, नियुक्त केल्यास खरेदीदाराचा नफा देण्याचे बंधन, जेव्हा तुम्ही NIFTY पातळी खाली राहण्याची अपेक्षा करता.</li>\n<li>एक पुट विकत घ्या, विक्री करण्याचा अधिकार, जेव्हा तुम्हाला घसरण अपेक्षित असते.</li>\n<li>पुट विक्री करा, नियुक्त केल्यास खरेदीदाराचा नफा देण्याचे बंधन, जेव्हा तुम्हीNIFTY′ पातळीच्या वर राहण्याची अपेक्षा करता.</li>\n</ul>\n<p>NIFTY इंडेक्स पर्यायांसाठी, असाइनमेंट रोखीने सेटल केले जाते: कालबाह्य झाल्यावर विक्रेते फक्त पर्यायाचे अंतर्गत मूल्य अदा करतात, कोणतेही शेअर्स बदलत नाहीत. (सिंगल-स्टॉक पर्याय त्याऐवजी भौतिक वितरणाद्वारे सेटलमेंट करू शकतात, हे आणखी एक कारण आहे की व्यापारी सामान्यतः एखाद्या पोझिशनला सेटलमेंटमध्ये नेण्याऐवजी एक्सपायरीपूर्वी बंद करतात.)</p>\n<p>ए <strong>धोरण</strong> एकाच वेळी दोन किंवा अधिक पाय धरले जातात, समान अंतर्निहित आणि कालबाह्यतेवर, निवडले जातात जेणेकरून त्यांच्या एकत्रित पेऑफला तुम्हाला हवा असलेला आकार असेल. जेव्हा तुम्ही एक पाय विकता, तेव्हा तुम्ही गोळा केलेला प्रीमियम तुम्ही खरेदी केलेल्या पायासाठी भरण्यास मदत करतो. जवळजवळ प्रत्येक स्प्रेडमागे ते शांत इंजिन आहे. तुमचा रिवॉर्ड कॅप करण्याच्या बदल्यात तुमची किंमत किंवा तुमची जोखीम कमी करून एक पाय दुसऱ्याला निधी देतो. एकत्रित मोबदला ही फक्त पायांची बेरीज आहे, प्रत्येक किमतीत रुपयाने रुपया जोडला जातो आणि बिल्डर तुमच्यासाठी नेमके काय करतो.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>स्ट्रॅटेजी बिल्डर तुमच्या पायाचा एकत्रित मोबदला वास्तविक NIFTY पर्याय किमतींमधून काढतो, ज्याचे मॉडेल सिंथेटिक भविष्यातील ब्लॅक-76 सह मॉडेल केलेले आहे, भारतीय पर्यायांसाठी योग्य पद्धत. याच इंजिनने या कोर्समधील प्रत्येक चार्ट तयार केला. स्पॉट 24,056, ATM स्ट्राइक 24,050, लॉट 65, 50-पॉइंट ग्रिडवर स्ट्राइक, 28 जुलै 2026 रोजी एक्सपायरी.</p>\n</div></div>\n<h2 id=\"reading-one-real-example-end-to-end\">एक वास्तविक उदाहरण शेवटपर्यंत वाचत आहे</h2>\n<p>चला एकत्र एक वास्तविक रणनीती वाचूया, द <strong>बैल कॉल पसरला</strong>, त्यामुळे संपूर्ण चित्र क्लिक होते. 28 जुलै 2026 च्या एक्सपायरीला दोन पाय, दोन्ही कॉल्स असलेला हा एक सौम्यपणे तेजीचा व्यापार आहे.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रकार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>खरेदी करा</td>\n<td>24,050</td>\n<td>कॉल करा</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री करा</td>\n<td>24,150</td>\n<td>कॉल करा</td>\n</tr>\n</tbody></table>\n<p>तुम्ही 24,050 कॉल खरेदी करता आणि 24,150 कॉल विकता. तुम्ही विकत असलेला कॉल प्रीमियम आणतो जो तुम्ही खरेदी करता त्या कॉलची बहुतेक किंमत कमी करते, त्यामुळे पोझिशनची किंमत एकाकी कॉलपेक्षा खूपच कमी असते. तो निव्वळ खर्च, द <strong>निव्वळ डेबिट</strong> 3,624 रुपये, तुम्ही गमावू शकता. बिल्डरने काय अहवाल दिला ते येथे आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ब्रेकवेन</td>\n<td>24,106</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>रु. 2,876</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>3,624 रु</td>\n</tr>\n</tbody></table>\n<p>आता चार्ट वाचा. डावीकडे, 24,050 च्या खाली, दोन्ही कॉल निरुपयोगी कालबाह्य होतात आणि तुम्ही संपूर्ण निव्वळ डेबिट, रु 3,624 गमावाल. तो सपाट लाल मजला तुमचे कमाल नुकसान आहे. जसजसे NIFTY 24,050 च्या पुढे जाईल तसतसे खरेदी केलेल्या कॉलचे मूल्य वाढेल आणि तोटा कमी होईल, जोपर्यंत <strong>24,106 चे ब्रेकईव्हन</strong>, एम्बर डॉटने चिन्हांकित केशरी रेषा शून्य ओलांडून हिरव्या रंगात जाते. 24,150 च्या वर दोन्ही कॉल्स पैशात खोलवर आहेत, स्प्रेड पूर्णपणे खुला आहे आणि तुमचा नफा त्याच्या कमाल मर्यादेपर्यंत वाढणे थांबेल <strong>रु. 2,876</strong>, एक सपाट हिरवे छत. निळ्या डॅशची T+0 रेषा समान प्रवास पूर्ण बंद दर्शवते, कारण वेळ मूल्य आजही आहे आणि 28 जुलैपर्यंत निघून जाईल. लक्षात घ्या की 24,106 चे ब्रेकइव्हन फक्त आतील सिग्मा बँडच्या आत बसते, त्यामुळे हा व्यापार मूनशॉट नव्हे तर माफक, विश्वासार्ह वाढीवर सट्टा लावत आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-call-spread.png\" alt=\"वास्तविक NIFTY बुल कॉल स्प्रेड, 24,050 कॉल खरेदी करून 24,150 कॉलची विक्री, 24,106 वर एम्बर ब्रेकवेन डॉटसह, 24,050 च्या खाली 3,624 चा लाल कमाल तोटा फ्लोअर आणि 2,84760 रुपये 2,8476 वरील ग्रीन कमाल नफा कमाल मर्यादा. गुलाबी ओळ स्पॉट 24,056 चिन्हांकित करते आणि फिकट सिग्मा बँड बाजाराला अपेक्षित चाल दाखवतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>खरा NIFTY बुल कॉल स्प्रेड, 24,050 कॉल खरेदी करून 24,150 कॉलची विक्री, 24,106 वर एम्बर ब्रेकेव्हन डॉटसह, 24,050 च्या खाली 3,624 चा लाल कमाल तोटा फ्लोअर आणि 2,84760 रुपये 2,8476 वरील ग्रीन कमाल नफा कमाल मर्यादा. गुलाबी ओळ स्पॉट 24,056 चिन्हांकित करते आणि फिकट सिग्मा बँड बाजाराला अपेक्षित चाल दाखवतात.</figcaption></figure>\n<p>ती संपूर्ण पद्धत आहे. शून्य रेषा, एम्बर ब्रेकवेन ठिपके, हिरवे आणि लाल झोन, दोन सपाट मर्यादा, गुलाबी स्पॉट लाइन आणि फिकट सिग्मा बँड शोधा. ते कोणत्याही चार्टवर करा आणि तुम्ही धोरण वाचले आहे. OpenAlgo मधील प्रत्येक चार्ट सारखाच स्वच्छ openalgo.in लुक धारण करतो, त्यामुळे तुम्ही तयार कराल त्या प्रत्येक पेऑफमध्ये कौशल्य हस्तांतरित होते. रिअल पैसे धोक्यात येण्यापूर्वी तुम्ही ऑर्डर मेकॅनिक्सचा अभ्यास देखील करू शकता <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong>, म्हणून जेव्हा वास्तविक भांडवल गुंतलेले असते तेव्हा काहीही विचित्र वाटत नाही. पुढील प्रकरणामध्ये आपण या प्रत्येक चार्टच्या बाजूला बसलेल्या नऊ संख्यांच्या पूर्ण पॅनेलचा वेग कमी करतो आणि त्याचा अभ्यास करतो.</p>\n","toc":[{"level":2,"text":"पेऑफ डायग्राम हे तुमच्या पैशाचे चित्र आहे","id":"a-payoff-diagram-is-a-picture-of-your-money"},{"level":2,"text":"दोन ओळी: एक्सपायरी आणि आज","id":"the-two-lines-at-expiry-and-today"},{"level":2,"text":"नफा क्षेत्र, नुकसान क्षेत्र आणि ब्रेकवेन","id":"profit-zones-loss-zones-and-the-breakeven"},{"level":2,"text":"सिग्मा बँड आणि स्पॉट लाइन","id":"the-sigma-bands-and-the-spot-line"},{"level":2,"text":"पाय: तुम्ही स्टॅक केलेले तुकडे","id":"legs-the-pieces-you-stack"},{"level":2,"text":"एक वास्तविक उदाहरण शेवटपर्यंत वाचत आहे","id":"reading-one-real-example-end-to-end"}],"imgCount":1,"hasContent":true},"2":{"html":"<p>या कोर्समधील जवळजवळ प्रत्येक रणनीती त्याच्या चार्टच्या बाजूला बसलेल्या संख्येच्या पॅनेलसह येते. OpenAlgo बिल्डरने अहवाल दिला <strong>नऊ</strong> त्यापैकी, आणि एकत्रितपणे ते व्यापाराचे पूर्ण स्कोअरकार्ड आहेत. तक्ता तुम्हाला आकार दाखवतो; या नऊ संख्या त्यावर अचूक आकडे टाकतात. सर्व नऊ वाचायला शिका आणि तुम्ही एकच ऑर्डर देण्याआधी तुम्ही एखाद्या स्थानाचा आकार घेऊ शकता, त्याच्या शक्यतांचा न्याय करू शकता आणि ते किती रोख रक्कम बांधते हे तंतोतंत जाणून घेऊ शकता. हा धडा त्यांच्यापैकी प्रत्येकाला शिकवतो, खरा NIFTY ट्रेड वापरून तुम्हाला नंतर पुन्हा भेटेल, <strong>बैल पसरला</strong>, आणि नंतर ते अगदी वेगळ्या व्यापाराच्या बाजूला सेट करते त्यामुळे सर्वात महत्त्वाचा धडा येतो.</p>\n<h2 id=\"the-nine-numbers-on-the-panel\">पॅनेलवरील नऊ संख्या</h2>\n<p>कोणत्याही रणनीतीसाठी बिल्डर दाखवतो ते संपूर्ण पॅनेल येथे आहे. आम्ही प्रत्येकाची व्याख्या करू, नंतर त्यांना वास्तविक व्यापार वाचू.</p>\n<ul>\n<li><strong>कमाल नफा</strong>: प्रति लॉट, कालबाह्यतेच्या वेळी पोझिशन सर्वोत्तम करू शकते.</li>\n<li><strong>कमाल तोटा</strong>: प्रति लॉट, कालबाह्यतेवर ते करू शकते सर्वात वाईट. \"अमर्यादित\" म्हणजे तोटा वाढतच जातो कारण अंतर्निहित तुमच्या विरोधात फिरत राहते. काटेकोर अर्थाने ही केवळ नग्न शॉर्ट कॉल किंवा लहान भविष्याची वरची बाजू आहे, कारण किंमतीला वर मर्यादा नाही. एक लहान पुट किंवा दीर्घ भविष्यातील नकारात्मक बाजू गमावते, परंतु तो तोटा मर्यादित आहे, कारण किंमत शून्याच्या खाली येऊ शकत नाही, म्हणून ती खरोखर अमर्याद होण्याऐवजी खूप मोठी आहे. विकत घेतलेला पर्याय, कॉल किंवा पुट, तुम्ही त्यासाठी भरलेल्या प्रीमियमपेक्षा जास्त कधीही गमावू शकत नाही. जेव्हा बिल्डर \"अनलिमिटेड\" मुद्रित करतो, तेव्हा ते \"या बाजूला कमाल मर्यादा नाही\" असे वाचा आणि वास्तविकपणे दुखापत होईल अशा वास्तववादी हालचालींसह ते नेहमी जोडा.</li>\n<li><strong>ब्रेकवेन्स</strong>: किंमत किंवा किमती जेथे केशरी एक्सपायरी लाइन शून्य ओलांडते.</li>\n<li><strong>नफ्याची संभाव्यता (POP)</strong>: बाजार-निहित शक्यता व्यापार नफ्यात संपतो.</li>\n<li><strong>पुरस्कारासाठी धोका</strong>: जास्तीत जास्त नफा जास्तीत जास्त तोट्याच्या विरुद्ध सेट केला आहे, 1 ते कशासाठी तरी दर्शविले आहे.</li>\n<li><strong>नेट क्रेडिट किंवा नेट डेबिट</strong>: तुम्ही प्रीमियम अप फ्रंट (क्रेडिट) प्राप्त करा किंवा ते भरा (डेबिट).</li>\n<li><strong>अंदाज प्रीमियम</strong>: एकत्रितपणे जोडलेल्या सर्व पायांचा एकूण प्रीमियम, उलाढालीचा आकडा.</li>\n<li><strong>एकूण P&amp;L</strong>: आत्ता उघडा नफा किंवा तोटा, तुम्ही प्रवेश करता तेव्हा जवळपास शून्य.</li>\n<li><strong>समास विनंती</strong>: मार्जिन (रोख किंवा तारण संपार्श्विक) स्थान धारण करण्यासाठी एक्सचेंज ब्लॉक.</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>नऊ संख्या व्यापाराचे संपूर्ण वर्णन करतात: कमाल नफा, कमाल तोटा, ब्रेकवेव्हन्स, नफ्याची संभाव्यता, रिवॉर्डची जोखीम, निव्वळ क्रेडिट किंवा डेबिट, अंदाजे प्रीमियम, थेट एकूण P&amp;L आणि मार्जिन आवश्यक आहे. तक्ता चित्र आहे; हे नऊ त्यामागचे अचूक आकडे आहेत.</p>\n</div></div>\n<h2 id=\"the-bull-put-spread-in-numbers\">बैल संख्येने पसरला</h2>\n<p>द <strong>बैल पसरला</strong> 28 जुलै 2026 च्या एक्सपायरीला दोन पायांचा, दोन्ही पुट असलेला एक सौम्यपणे तेजीचा, परिभाषित-जोखीम असलेला क्रेडिट ट्रेड आहे.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रकार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री करा</td>\n<td>24,050</td>\n<td>ठेवा</td>\n</tr>\n<tr>\n<td>2</td>\n<td>खरेदी करा</td>\n<td>23,950</td>\n<td>ठेवा</td>\n</tr>\n</tbody></table>\n<p>तुम्ही 24,050 पुट विकता, जे तुम्हाला जोपर्यंत NIFTY ठेवते तोपर्यंत पैसे देतात आणि संरक्षण म्हणून त्याखालील 23,950 पुट खरेदी करतात. विकत घेतलेल्या पुटच्या किंमतीपेक्षा जास्त खर्च येतो, त्यामुळे तुम्ही निव्वळ क्रेडिटसह निघून जाता. येथे संपूर्ण नऊ क्रमांकाचे फलक आहे.</p>\n<table>\n<thead>\n<tr>\n<th>मेट्रिक</th>\n<th>मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ब्रेकवेन</td>\n<td>24,011</td>\n</tr>\n<tr>\n<td>कमाल नफा</td>\n<td>2,506 रु</td>\n</tr>\n<tr>\n<td>कमाल तोटा</td>\n<td>3,994 रु</td>\n</tr>\n<tr>\n<td>नफ्याची शक्यता</td>\n<td>51 टक्के</td>\n</tr>\n<tr>\n<td>पुरस्कारासाठी धोका</td>\n<td>1 : 0.63</td>\n</tr>\n<tr>\n<td>निव्वळ क्रेडिट</td>\n<td>2,506 रु</td>\n</tr>\n<tr>\n<td>अंदाज प्रीमियम</td>\n<td>दोन्ही पुटचा एकत्रित प्रीमियम</td>\n</tr>\n<tr>\n<td>एकूण P&amp;L</td>\n<td>प्रवेशासाठी सुमारे रु</td>\n</tr>\n<tr>\n<td>समास विनंती</td>\n<td>35,358 रु</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-put-spread.png\" alt=\"NIFTY बुल पुट स्प्रेड, 24,050 पुट विकला आणि 23,950 पुट खरेदी केला, एम्बर ब्रेकेव्हन डॉट 24,011 वर, 2,506 चे संपूर्ण क्रेडिट 24,050 वर ठेवले आणि तोटा 23,950 च्या खाली 3,994 रुपये झाला. गुलाबी ओळ स्पॉट 24,056 चिन्हांकित करते आणि उजवीकडील पॅनेल सर्व नऊ संख्या दर्शविते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY बुल पुट स्प्रेड, 24,050 पुट विकला आणि 23,950 पुट खरेदी केला, एम्बर ब्रेकेव्हन डॉट 24,011 वर, 2,506 चे पूर्ण क्रेडिट 24,050 वर ठेवले, आणि तोटा 23,950 च्या खाली 3,994 रुपये झाला. गुलाबी ओळ स्पॉट 24,056 चिन्हांकित करते आणि उजवीकडील पॅनेल सर्व नऊ संख्या दर्शविते.</figcaption></figure>\n<h2 id=\"walking-the-numbers-one-by-one\">एकामागून एक संख्या चालत आहे</h2>\n<p><strong>कमाल नफा, रु. 2,506.</strong> तुम्ही गोळा केलेले निव्वळ क्रेडिट हेच आहे आणि NIFTY 24,050 वर किंवा त्यापेक्षा जास्त बंद झाल्यास तुम्ही ते सर्व ठेवता, जेथे दोन्ही पुट निरर्थक कालबाह्य होतात. क्रेडिट हे बक्षीस आहे आणि तुम्ही ते फक्तNIFTY′ द्वारे बँक करा.</p>\n<p><strong>कमाल तोटा, रु. 3,994.</strong> NIFTY 23,950 वर किंवा खाली बंद झाल्यास, जेथे विकत घेतलेले नुकसान कमी करते, तर याचा त्रास होतो. दोन स्ट्राइक 100 पॉइंट्सच्या अंतरावर आहेत, 65 च्या लॉटसाठी 6,500 रुपये किमतीचे आहेत. तुम्ही क्रेडिट म्हणून 2,506 रुपये ठेवले आहेत, त्यामुळे तुम्ही सर्वात जास्त गमावू शकता बाकीचे 6,500 वजा 2,506 रुपये, जे रुपये 3,994 आहे. क्रेडिट अधिक कमाल तोटा नेहमी पूर्ण स्ट्राइक रुंदीच्या बरोबरीचा असतो.</p>\n<p><strong>ब्रेकवेन, 24,011.</strong> NIFTY 24,011 पर्यंत थोडं खाली वाहून जाऊ शकतं, आणि तुम्ही तरीही बाहेर पडता, कारण क्रेडिट कोणत्याही घसरणीच्या पहिल्या भागावर अवलंबून असते. ते म्हणजे 24,050 स्ट्राइक वजा क्रेडिट सुमारे 39 पॉइंट्स प्रति शेअर. 24,011 च्या वर तुम्ही कमीत कमी काही नफा ठेवता, त्याखाली तुम्हाला तोटा होऊ लागतो.</p>\n<p><strong>निव्वळ क्रेडिट, रु 2,506.</strong> स्थिती पहिल्या दिवशी तुम्हाला पैसे देते. ए <strong>क्रेडिट</strong> म्हणजे तुमच्या खात्यात प्रीमियम जमीन, निव्वळ विक्रेत्याचे चिन्ह. ए <strong>डेबिट</strong> याचा अर्थ असा आहे की तुम्ही समोर पैसे दिले आहेत, निव्वळ खरेदीदाराचे चिन्ह. येथे क्रेडिट आणि कमाल नफा हा समान आकडा आहे, जो प्रत्येक साध्या क्रेडिट स्प्रेडसाठी सत्य आहे.</p>\n<p><strong>पुरस्काराचा धोका, 1 ते 0.63.</strong> तुम्ही जोखीम पत्करलेल्या प्रत्येक रुपयासाठी तुम्ही सुमारे 63 पैसे कमवू शकता. तुम्ही रु. 2,506 कमावण्यासाठी 3,994 रु.ची जोखीम पत्करत आहात, त्यामुळे तुम्ही कमावण्यापेक्षा जास्त जोखीम घेता. हा दोष नाही, जिंकण्याच्या उच्च संधीच्या बदल्यात तुम्ही स्वीकारलेले ट्रेड-ऑफ आहे, जे पुढील क्रमांक स्पष्ट करते.</p>\n<p><strong>अंदाज प्रीमियम</strong> हे दोन्ही पुट एकत्र जोडलेले एकूण प्रीमियम आहे, उलाढालीचा आकडा, तुमची जोखीम नाही. जास्तीत जास्त तोटा सह भ्रमित करू नका. तुमची खरी जोखीम म्हणजे रु. 3,994 कमाल तोटा, कधीही एकूण प्रीमियम नाही.</p>\n<p><strong>एकूण P&amp;L, सुमारे शून्य.</strong> तुम्ही ज्या क्षणी प्रवेश करता त्या क्षणी, तुम्ही जे पैसे दिले किंवा प्राप्त केले त्या स्थितीचे मूल्य असते, त्यामुळे खुला नफा किंवा तोटा शून्याच्या जवळ असतो. NIFTY प्रवास करताना आणि वेळ क्षीण होत असताना ते हिरव्या किंवा लाल रंगात सरकते.</p>\n<p><strong>मार्जिन आवश्यक आहे, रु. 35,358.</strong> हे मार्जिन आहे (रोख किंवा तारण संपार्श्विक) तुम्हाला व्यापार ठेवू देण्यासाठी एक्सचेंज ब्लॉक्स, OpenAlgo मार्जिन कॅल्क्युलेटरमधील SPAN अधिक एक्सपोजर मार्जिन. खरेदी केलेल्या संरक्षणात्मक पुटसह हा एक परिभाषित-जोखीम पसरल्यामुळे, मार्जिन माफक आहे. समान दृश्यासह एक नग्न शॉर्ट पुट कित्येक पट अधिक ब्लॉक करेल.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>या बुल पुट स्प्रेडसाठी स्ट्राइक 100 पॉइंट्सच्या अंतरावर आहेत, 65 च्या लॉटची किंमत 6,500 रुपये आहे. 2,506 रुपये क्रेडिट हे तुमचे बक्षीस आहे आणि उर्वरित 3,994 रुपये तुमची जोखीम आहे. क्रेडिट अधिक कमाल तोटा नेहमी पूर्ण स्ट्राइक रुंदीच्या बरोबरीचा असतो. पॅनेलवरील प्रत्येक आकृती प्रति एक लॉट आहे.</p>\n</div></div>\n<h2 id=\"probability-of-profit-and-the-trade-it-implies\">नफ्याची संभाव्यता, आणि त्याचा अर्थ असा व्यापार</h2>\n<p>नवशिक्या बहुतेकदा चुकीचे वाचतो ती संख्या <strong>नफ्याची शक्यता</strong>, द <strong>POP</strong>. जवळपास 12.7 टक्के एट-द-मनी गर्भित अस्थिरता आणि कालबाह्य होण्याच्या दिवसांचा वापर करून, 28 जुलैपर्यंतNIFTY′ कुठे उतरू शकेल या मॉडेलवरून तयार केलेला, व्यापार नफ्यात पूर्ण होण्याची ही बाजार-निहित संधी आहे. तुम्हाला सूत्राची गरज नाही. व्यापाराने एक विजेता संपवल्याच्या शक्यतांनुसार ते वाचा.</p>\n<p>बैल पुट स्प्रेडसाठी POP आहे <strong>51 टक्के</strong>. NIFTY फक्त आजच्या 24,056 पेक्षा किंचित खाली, 24,011 जवळ किंवा त्यापेक्षा जास्त ठेवायचे आहे, त्यामुळे व्यापार अर्ध्यापेक्षा थोडा जास्त वेळ जिंकतो. 1 ते 0.63 च्या रिवॉर्डच्या जोखमीसह ते पेअर करा आणि पूर्ण चित्र दिसेल: जिंकण्याची साधारणतः एक संधी, जोखमीपेक्षा थोडेसे लहान बक्षीसासह. हा एक संतुलित, प्रामाणिक व्यापार आहे, म्हणूनच तो चांगला प्रथम क्रेडिट स्प्रेड बनवतो.</p>\n<p>येथे नियम आहे जो तुम्हाला भेटणार असलेल्या जवळजवळ प्रत्येक रणनीतीवर नियंत्रण ठेवतो.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>फायद्याची उच्च संभाव्यता सहसा लहान बक्षीसासह येते आणि मोठे बक्षीस सहसा नफ्याच्या कमी संभाव्यतेसह येते. बाजारभाव हे अशा प्रकारे ठेवतात की कोणताही आकार फुकट पैसा नसतो. जेव्हा व्यापार अनेकदा जिंकतो, तेव्हा प्रत्येक विजय लहान असतो; जेव्हा व्यापार जास्त पैसे देतो तेव्हा तो क्वचितच जिंकतो.</p>\n</div></div>\n<h2 id=\"a-high-pop-trade-the-short-iron-condor\">उच्च POP ट्रेड: शॉर्ट आयर्न कंडोर</h2>\n<p>तो व्यापार-ऑफ अनुभवण्यासाठी, चार पायांच्या परिभाषित-जोखीम संरचनेच्या बाजूला वळू ठेवलेला ठेवा, तुम्हाला नंतर भेटेल, <strong>लहान लोखंडी कंडोर</strong>. सध्या त्याच्या बांधकामाकडे दुर्लक्ष करा आणि तुम्हाला आधीच माहित असलेल्या स्प्रेडच्या विरूद्ध फक्त त्याची संख्या वाचा.</p>\n<table>\n<thead>\n<tr>\n<th>मेट्रिक</th>\n<th>बुल पुट स्प्रेड</th>\n<th>लहान लोह कंडोर</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नफा</td>\n<td>2,506 रु</td>\n<td>रु 884</td>\n</tr>\n<tr>\n<td>कमाल तोटा</td>\n<td>3,994 रु</td>\n<td>५,६१६ रु</td>\n</tr>\n<tr>\n<td>नफ्याची शक्यता</td>\n<td>51 टक्के</td>\n<td>83 टक्के</td>\n</tr>\n<tr>\n<td>पुरस्कारासाठी धोका</td>\n<td>1 : 0.63</td>\n<td>1 : 0.16</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>24,011</td>\n<td>23,864 / 24,236</td>\n</tr>\n<tr>\n<td>समास विनंती</td>\n<td>35,358 रु</td>\n<td>68,864 रु</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-iron-condor.png\" alt=\"NIFTY शॉर्ट आयर्न कंडोर, 23,864 आणि 24,236 वर एम्बर ब्रेकवेन डॉट्स असलेली चार पायांची परिभाषित-जोखीम संरचना. त्याचे पॅनेल 83 टक्के नफ्याची उच्च संभाव्यता दर्शविते आणि 884 रुपयांच्या लहान कमाल नफ्यासह आणि 5,616 रुपयांच्या मोठ्या तोट्यासह, क्लासिक उच्च-विषम, कमी-रिवॉर्ड सौदा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY शॉर्ट आयर्न कंडोर, 23,864 आणि 24,236 वर एम्बर ब्रेकेव्हन ठिपके असलेली चार पायांची परिभाषित-जोखीम संरचना. त्याचे पॅनेल 83 टक्के नफ्याची उच्च संभाव्यता दर्शविते आणि 884 रुपयांच्या लहान कमाल नफ्यासह आणि 5,616 रुपयांच्या मोठ्या तोट्यासह, क्लासिक उच्च-विषम, कमी-रिवॉर्ड सौदा.</figcaption></figure>\n<p>लहान लोखंडी कंडर जिंकतो <strong>83 टक्के</strong> वेळ, कितीतरी वेळा बैल ठेवले पसरला. जोपर्यंत तुम्ही उर्वरित पॅनेल वाचत नाही तोपर्यंत ते छान वाटते. प्रत्येक विजय फक्त आहे <strong>रु 884</strong>, तर प्रत्येक नुकसान होऊ शकते <strong>५,६१६ रु</strong>, फक्त 1 ते 0.16 पर्यंत बक्षीस मिळण्याचा धोका. तुम्ही एक बनवण्यासाठी सहा रुपयांपेक्षा जास्त धोका पत्करत आहात. उच्च विजयाचा दर आणि लहान बक्षीस या एकाच नाण्याच्या दोन बाजू आहेत: बाजार तुम्हाला वारंवार विजय मिळवून देतो कारण ते प्रत्येकाला लहान आणि दुर्मिळ नुकसान मोठे बनवते.</p>\n<p>पॅनेल वाचण्याचा हा एकमेव सर्वात महत्त्वाचा धडा आहे. उच्च POP हा चांगल्या व्यापारासारखाच नाही आणि बक्षीसासाठी कमी धोका हा वाईट व्यापारासारखा नाही. NIFTY कुठे जाण्याची शक्यता आहे याच्या तुमच्या स्वत:च्या प्रामाणिक दृष्टिकोनाबरोबरच दोन संख्या नेहमी एकत्र वाचल्या पाहिजेत. एकतर व्यापार योग्य परिस्थितीत समजूतदार असू शकतो आणि एकतर तुम्ही निष्काळजीपणे आकार घेतल्यास तुम्हाला त्रास होऊ शकतो.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>POP एकट्याने किंवा एकट्याने बक्षीस मिळण्याच्या जोखमीनुसार कधीही धोरण ठरवू नका. त्यांना जोडी म्हणून वाचा. 1 ते 0.16 रिवॉर्डसह 83 टक्के POP आणि 1 ते 0.63 रिवॉर्डसह 51 टक्के POP हे फक्त दोन भिन्न सौदे आहेत, एक चांगले आणि वाईट नाही. NIFTY वरील तुमचा दृष्टिकोन कोणता सौदा फिट होईल हे ठरवतो.</p>\n</div></div>\n<h2 id=\"margin-and-defined-risk-for-beginners\">नवशिक्यांसाठी मार्जिन आणि परिभाषित जोखीम</h2>\n<p>नऊ पैकी दोन संख्या तुमचे उर्वरित पेक्षा जास्त संरक्षण करतात <strong>जास्तीत जास्त नुकसान</strong> आणि <strong>मार्जिन आवश्यक आहे</strong>. ते एकत्रितपणे तुम्हाला सांगतात की व्यापारासाठी काय खर्च येऊ शकतो आणि तो खुला असताना तो काय बांधला जातो.</p>\n<p>ही दोन्ही उदाहरणे आहेत <strong>परिभाषित-जोखीम</strong>. कमाल तोटा हा चार्टवर छापलेला सपाट, मर्यादित मजला आहे, बुल पुट स्प्रेडसाठी रु. 3,994 आणि शॉर्ट आयर्न काँडरसाठी रु 5,616, कारण खरेदी केलेला पाय प्रत्येक बाजूचे नुकसान भरून काढतो. त्यांचे मार्जिन, रु. 35,358 आणि रु 68,864, त्याच कारणास्तव माफक आहेत. त्याची तुलना अभ्यासक्रमाच्या नंतरच्या नग्न शॉर्ट पोझिशन्सशी करा, जिथे तोटा अमर्यादित आहे आणि मार्जिन दीड लाखाच्या पुढे आहे. एक नवशिक्या म्हणून तुम्हाला असे ट्रेड हवे आहेत ज्यांची सर्वात वाईट स्थिती ही ज्ञात संख्या आहे जी तुम्ही टिकून राहू शकता आणि ज्याचे मार्जिन तुम्ही आरामात बाजूला ठेवू शकता.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>नेहमी एखाद्या स्थानाचा आकार त्याच्या कमाल तोट्याने करा, कधीही त्याच्या क्रेडिट किंवा त्याच्या अंदाजे प्रीमियमने नाही. बुल पुट स्प्रेड रिस्क रु. 2,506 करण्यासाठी रु. 3,994, आणि विजयाची स्ट्रिंग पुढील नुकसान कमी करत नाही. वाईट दिवशी तुमचे खाते काय शोषून घेऊ शकते यावर तुमची लॉट गणती ठरवा, प्रत्येक संरक्षणात्मक पाय जागी ठेवा आणि मार्जिन आकृतीला वास्तविक रोख समजा जे व्यापार उघडे असताना लॉक केलेले आहे.</p>\n</div></div>\n<p>आता तुमच्याकडे पूर्ण स्कोअरकार्ड आहे. येथून, प्रत्येक धडा त्याच्या आकार आणि नऊ संख्यांनुसार एक धोरण सादर करतो आणि ते सर्व कसे वाचायचे हे तुम्हाला आधीच माहित आहे. पुढे आम्ही त्यांना सगळ्यात सोप्या ट्रेड्सवर काम करायला लावतो, सिंगल-लेग लाँग कॉल आणि शॉर्ट पुट.</p>\n","toc":[{"level":2,"text":"पॅनेलवरील नऊ संख्या","id":"the-nine-numbers-on-the-panel"},{"level":2,"text":"बैल संख्येने पसरला","id":"the-bull-put-spread-in-numbers"},{"level":2,"text":"एकामागून एक संख्या चालत आहे","id":"walking-the-numbers-one-by-one"},{"level":2,"text":"नफ्याची संभाव्यता, आणि त्याचा अर्थ असा व्यापार","id":"probability-of-profit-and-the-trade-it-implies"},{"level":2,"text":"उच्च POP ट्रेड: शॉर्ट आयर्न कंडोर","id":"a-high-pop-trade-the-short-iron-condor"},{"level":2,"text":"नवशिक्यांसाठी मार्जिन आणि परिभाषित जोखीम","id":"margin-and-defined-risk-for-beginners"}],"imgCount":2,"hasContent":true},"3":{"html":"<p>तुमचे स्पष्ट मत आहे: NIFTY येत्या महिन्याभरात उच्च पातळीवर जात आहे. एकाच पर्यायासह त्या एकाच दृश्याचे समर्थन करण्याचे दोन साधे मार्ग आहेत आणि ते त्याच व्यापाराच्या विरुद्ध बाजूंना बसतात. आपण करू शकता <strong>एक कॉल खरेदी</strong>, वाढत्या सवारीच्या अधिकारासाठी आता प्रीमियम भरणे. किंवा तुम्ही करू शकता <strong>एक पुट विक्री</strong>, आता प्रीमियम गोळा करत आहे आणि तुमच्या स्ट्राइकवर पडल्यासNIFTY′ खरेदी करण्याचे वचन देतो. तुमच्यापैकी एक खरेदीदार आहे, आशावादी आणि धीर धरणारा, एक लहान निश्चित खर्च उचलतो. दुसरा विक्रेता आहे, ज्याला आगाऊ पैसे दिले जातात परंतु वास्तविक दायित्व आहे. हा धडा 26 जून 2026 रोजी कॅप्चर केलेल्या रिअल NIFTY ऑप्शन डेटावर, निर्देशांक 24,056, 24,050 वर मनी स्ट्राइक, 65 युनिट्सचा एक लॉट आणि 28 जुलै 2026 ची मुदत जवळपास 32 दिवसांनंतर या दोन्ही गोष्टींवर आधारित आहे.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>लांब कॉल</strong> अमर्यादित अपसाइडसाठी एक छोटा प्रीमियम भरतो. ए <strong>शॉर्ट पुट</strong> एक लहान प्रीमियम गोळा करतो आणि एक मोठा लपलेला नकारात्मक बाजू स्वीकारतो. दोघेही समान तेजस्वी दृष्टिकोन व्यक्त करतात, परंतु ते संपूर्ण सौदे बदलतात: खरेदीदार ओपन-एंडेड विजयाच्या बदल्यात कमी शक्यता आणि मर्यादित, ज्ञात नुकसान घेतो, तर विक्रेत्याने कॅप केलेल्या विजयाच्या बदल्यात उच्च शक्यता आणि अनुकूल घड्याळ घेतो.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>त्याच तेजीच्या दृश्यावर आणि त्याच 24,050 स्ट्राइकवर, लाँग कॉल कमी विषमतेवर अमर्यादित लाभासाठी निश्चित रु. 27,677 चा धोका पत्करतो, तर शॉर्ट पुट उच्च शक्यतांवर निश्चित रु. 19,182 कमावतो परंतुNIFTY′ कोसळल्यास मोठ्या प्रमाणात नुकसान होण्याचा धोका असतो. खरेदीदार मोठ्या विजयासाठी पैसे देतात जे त्यांना क्वचितच मिळतात. विक्रेत्यांना अनेकदा पैसे दिले जातात, परंतु दुर्मिळ तोटा खूप मोठा असतो.</p>\n</div></div>\n<h2 id=\"the-long-call-rupee-by-rupee\">लांबलचक कॉल, रुपयाने रुपया</h2>\n<p>तुम्ही एट-द-मनी कॉल खरेदी करा. तो एक पाय म्हणजे संपूर्ण स्थिती.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>रु 27,677 बाहेर</strong></td>\n</tr>\n</tbody></table>\n<p>24,050 कॉलची किंमत प्रति शेअर 425.8 आहे, जी 425.8 पट 65 आहे किंवा <strong>रु 27,677</strong> एका लॉटसाठी. तुम्ही खरेदी करताच ते पैसे तुमच्या खात्यातून निघून जातात आणि तुम्हाला एक रुपयाही जास्त मागता येणार नाही. ही एक वस्तुस्थिती म्हणजे पर्याय खरेदी करण्याचा संपूर्ण आराम आहे. तुमचा जास्तीत जास्त तोटा हा प्रीमियम, पूर्णविराम आहे आणि तुमच्या स्ट्राइकच्या वरच्या बाजूस कोणतीही कमाल मर्यादा नाही.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-call.png\" alt=\"NIFTY वर दीर्घ कॉल, रु. 27,677 मध्ये 24,050 कॉल खरेदी. ऑरेंज ॲट-एक्सपायरी लाइन स्ट्राइकच्या खाली फ्लॅट लॉस फ्लोअरवर टिकते, 24,476 च्या ब्रेकईव्हनवर शून्य ओलांडते, नंतर ग्रीन प्रॉफिट झोनमध्ये मर्यादेशिवाय चढते. निळ्या डॅशची T+0 रेषा त्याच्या वर बसते, क्षय कमी होईल असे वेळेचे मूल्य धरून.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वर दीर्घ कॉल, 24,050 कॉल 27,677 रुपयांना विकत घेतला. ऑरेंज ॲट-एक्सपायरी लाइन स्ट्राइकच्या खाली फ्लॅट लॉस फ्लोअरवर टिकते, 24,476 च्या ब्रेकईव्हनवर शून्य ओलांडते, नंतर ग्रीन प्रॉफिट झोनमध्ये मर्यादेशिवाय चढते. निळ्या डॅशची T+0 रेषा त्याच्या वर बसते, क्षय कमी होईल असे वेळेचे मूल्य धरून.</figcaption></figure>\n<h2 id=\"the-long-call-s-three-numbers\">लांब कॉलचे तीन नंबर</h2>\n<p>प्रत्येक संख्या थेट व्यापाराच्या बाहेर पडते. एकदा लॉजिक पाहिल्यावर लक्षात ठेवण्यासारखे काहीही नाही.</p>\n<p><strong>कमाल तोटा प्रीमियम आहे, रु. 27,677.</strong> NIFTY 24,050 वर किंवा त्यापेक्षा कमी असल्यास, 24,050 वर खरेदी करण्याचा अधिकार व्यर्थ आहे आणि तुमचा संपूर्ण खर्च निघून जाईल. चार्टच्या डावीकडील सपाट मजला आहे.</p>\n<p><strong>जास्तीत जास्त नफा अमर्यादित आहे.</strong> प्रत्येक बिंदू NIFTY स्ट्राइकच्या वर चढत असताना कॉलचे मूल्य वाढवते, आणि काहीही थांबवत नाही, त्यामुळे ओळ कायमची वाढते.</p>\n<p><strong>ब्रेकईव्हन हा स्ट्राइक अधिक प्रीमियम प्रति शेअर, 24,476 आहे.</strong> तुम्ही प्रीमियमचे 425.8 पॉइंट दिले आहेत, म्हणून NIFTY ने स्ट्राइक क्लिअर करणे आवश्यक आहे आणि तुम्ही एक रुपया बनवण्यापूर्वी ते 425.8 परत मिळवा. ते 24,050 अधिक 425.8 किंवा 24,476 वर येते, जे स्पॉटपेक्षा सुमारे 420 पॉइंट्स वर आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>तुम्ही भरलेला प्रीमियम</td>\n<td>रु 27,677</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>स्ट्राइकच्या वर कमाल मर्यादा नाही</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>स्ट्राइक अधिक प्रीमियम प्रति शेअर</td>\n<td>24,050 अधिक 425.8 बरोबर 24,476</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-long-call-to-expiry\">कालबाह्य होण्यासाठी लांब कॉल चालणे</h2>\n<p>मूठभर बंद किंमतींवर कॉल सेटल करा आणि आकार स्वतःच दिसून येईल. कॉलचे मूळ मूल्य आहे, कमाल(NIFTY वजा 24,050, 0), आणि तुमचा नफा म्हणजे तुम्ही दिलेले 425.8 वजा मूल्य, सर्व वेळा 65.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>तुम्ही विकत घेतलेला २४,०५० कॉल</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>मूल्य 0</td>\n<td>उणे रु 27,677 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>उणे रु 27,677 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,476</td>\n<td>426 किमतीची</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,800</td>\n<td>750 किमतीची</td>\n<td>अधिक 21,073 रु</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>1,250 किमतीची</td>\n<td>अधिक रु 53,573 (आणि गिर्यारोहण)</td>\n</tr>\n</tbody></table>\n<p>24,050 वर किंवा त्यापेक्षा कमी कुठेही तुम्ही पूर्ण प्रीमियम गमावाल. स्ट्राइक आणि 24,476 दरम्यान तोटा कमी होतो परंतु आपण अद्याप लाल आहात. 24,476 वरून तुम्ही हिरवे झाले, आणि तेथून प्रत्येक अतिरिक्त बिंदू कोणत्याही मर्यादेशिवाय शुद्ध लाभ आहे. ते संपूर्ण मोबदला आहे आणि ते ऑरेंज लाईनशी अगदी जुळते.</p>\n<h2 id=\"the-short-put-rupee-by-rupee\">शॉर्ट पुट, रुपया दर रुपया</h2>\n<p>आता दुसऱ्या बाजूला जा. कॉलसाठी पैसे देण्याऐवजी, तुम्ही एट-द-मनी पुट विकता आणि प्रीमियम अगोदर घ्या.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>24,050</td>\n<td>295.1 मिळाले</td>\n<td>अधिक 19,182 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक 19,182 रु</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही प्रति शेअर २९५.१ गोळा करता, जे आहे <strong>19,182 रु</strong> लॉटसाठी, तुम्ही लगेच विकता. ते क्रेडिट तुम्ही कधीही बनवू शकता. NIFTY 24,050 वर किंवा त्यापेक्षा जास्त बंद झाल्यास तुम्ही ते सर्व ठेवता, कारण तुम्ही विकलेला पुट कालबाह्य होतो आणि खरेदीदार निघून जातो. प्रत्यक्षात ते बुडल्यास 24,050 वर NIFTY खरेदी करण्याचे आश्वासन दिल्याबद्दल तुम्हाला भाडे दिले जाते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-put.png\" alt=\"NIFTY वर शॉर्ट पुट, 24,050 पुट 19,182 च्या क्रेडिटसाठी विकले. नारिंगी रेषा स्ट्राइकच्या वर जास्तीत जास्त नफ्यावर सपाट आहे, 23,755 च्या ब्रेकईव्हनवर शून्य ओलांडते, नंतर तोटा झोनमध्ये खोलवर सरकते आणि मजला नसलेल्या खूप मोठ्या डाउनसाइडकडे जाते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वर शॉर्ट पुट, 24,050 पुट 19,182 च्या क्रेडिटसाठी विकले. नारिंगी रेषा स्ट्राइकच्या वर जास्तीत जास्त नफ्यावर सपाट आहे, 23,755 च्या ब्रेकईव्हनवर शून्य ओलांडते, नंतर तोटा झोनमध्ये खोलवर सरकते आणि मजला नसलेल्या खूप मोठ्या डाउनसाइडकडे जाते.</figcaption></figure>\n<h2 id=\"the-short-put-s-three-numbers\">शॉर्ट पुटचे तीन आकडे</h2>\n<p><strong>कमाल नफा क्रेडिट आहे, रु. 19,182.</strong> 24,050 वरील पुट निरुपयोगी मरतो आणि तुम्ही भाडे ठेवता. म्हणजे उजवीकडे सपाट शेल्फ.</p>\n<p><strong>जास्तीत जास्त तोटा शून्याकडे जातो, सुमारे रु 1,544,068.</strong> स्ट्राइकच्या खाली, पुट तुमच्या विरुद्ध रुपयाच्या तुलनेत बदलते, अगदी जसे की तुमची मालकी NIFTY 24,050 वरून खाली आहे. जवळपास एकूण कोसळून सैद्धांतिक मजला रु. 1,544,068 आहे, जे क्रेडिट कमी करते. हे वास्तववादी एकल सत्र नाही, परंतु ते सर्वात वाईट प्रकरण आहे.</p>\n<p><strong>ब्रेकइव्हन हा स्ट्राइक वजा क्रेडिट प्रति शेअर, 23,755 आहे.</strong> NIFTY स्ट्राइकच्या खाली 295.1 पॉइंट्सने 23,755 पर्यंत घसरू शकतो, पुटवरील तोटा संपूर्ण क्रेडिट खाण्यापूर्वी.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>तुम्ही गोळा केलेला प्रीमियम</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>स्ट्राइक मूल्य शून्याकडे नेले</td>\n<td>सुमारे रु 1,544,068</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>स्ट्राइक वजा क्रेडिट प्रति शेअर</td>\n<td>24,050 वजा 295.1 बरोबर 23,755</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-short-put-to-expiry\">एक्सपायरी करण्यासाठी शॉर्ट पुट चालणे</h2>\n<p>येथे पुट कमाल (24,050 वजा NIFTY, 0) मूल्य आहे, आणि तुमचा परिणाम 295.1 क्रेडिट वजा मूल्य आहे, गुणा 65.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 ला तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,300</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 19,182 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 19,182 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>23,755</td>\n<td>295 किमतीची</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>23,500</td>\n<td>550 किमतीची</td>\n<td>उणे रु. 16,569</td>\n</tr>\n<tr>\n<td>23,000</td>\n<td>1,050 किमतीची</td>\n<td>उणे ४९,०६९ रुपये (आणि घसरण)</td>\n</tr>\n</tbody></table>\n<p>23,755 वर किंवा त्यावरील प्रत्येक गोष्ट तुम्हाला नफ्यात ठेवते, एक विस्तृत सुरक्षित क्षेत्र. त्याच्या खाली तोटा उघडतो आणि खोल होत जातो, जोपर्यंत NIFTY शून्याजवळ येत नाही तोपर्यंत कोणताही सपाट मजला नसतो. आकार लांब कॉल च्या मिरर प्रतिमा आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>शॉर्ट पुट म्हणजे नग्न लहान पाय. त्याचा नफा तुम्ही गोळा केलेला 19,182 रुपये आहे, परंतु त्याचा तोटा कोसळून सुमारे 1,544,068 रुपयांपर्यंत पोहोचला आहे आणि एक्सचेंजने तो रोखण्यासाठी 165,042 रुपयांच्या जवळ मोठा मार्जिन रोखला आहे. 1 ते 0.01 पर्यंत बक्षीस मिळण्याची जोखीम हे स्पष्टपणे सांगते: मोठ्या ढेकूळ धोक्याच्या विरूद्ध एक लहान निश्चित बक्षीस. जेव्हा तुम्ही 23,755 च्या जवळ NIFTY च्या मालकीमध्ये खऱ्या अर्थाने समाधानी असाल आणि मार्जिनला निधी देऊ शकता आणि शेपटीचा पूर्ण आदर करू शकता तेव्हाच ते विका.</p>\n</div></div>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>तुम्ही जिंकू शकता किंवा गमावू शकता ते फक्त अर्धी कथा आहे. इतर अर्धा प्रत्येक परिणाम किती शक्यता आहे, आणि ते आहे <strong>नफ्याची शक्यता</strong>, बाजार-निहित संधी व्यापार हिरवा समाप्त.</p>\n<p>द <strong>लाँग कॉलचे POP सुमारे 31 टक्के आहे</strong>. त्याचे 24,476 चे ब्रेकईव्हन चार्टवरील प्लस वन सिग्मा बँडच्या वर बसले आहे, त्यामुळे ऑप्शन मार्केटचा अर्थ तीनपैकी फक्त एक संधी आहेNIFTY′ कालबाह्यतेने ते उच्च पूर्ण करते. द <strong>शॉर्ट पुटचे POP सुमारे 62 टक्के आहे</strong>, कारण त्याचे 23,755 चे ब्रेकइव्हन सुरक्षित झोनमध्ये आरामात ठिकठिकाणी खाली बसते. समान तेजीचे दृश्य, दोन अतिशय भिन्न शक्यता, कारण खरेदीदाराला खरी हालचाल आवश्यक असते तर विक्रेत्याला फक्त मार्केट क्रॅश होऊ नये म्हणून आवश्यक असते.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>नेहमी जास्तीत जास्त नुकसानापुढील POP वाचा, कधीही एकटे नाही. शॉर्ट पुटचे 62 टक्के आकर्षक दिसत आहे जोपर्यंत तुम्ही ते रु. 1,544,068 शेपटीच्या बाजूला सेट करत नाही. लाँग कॉलचे 31 टक्के कमी दिसत आहेत जोपर्यंत तुम्ही ते त्याच्या लहान, निश्चित रु 27,677 जोखमीच्या बाजूला सेट करत नाही. व्यापार म्हणजे परिणामाची त्याच्या शक्यतांसह जोडणी करणे, एकतर स्वतःहून नाही.</p>\n</div></div>\n<h2 id=\"margin-and-return\">मार्जिन आणि परतावा</h2>\n<p>लांब कॉल साठी <strong>मार्जिन डेबिटच्या बरोबरीचे आहे, रु. 27,677</strong>. कारण तुम्ही तुम्ही भरलेल्यापेक्षा जास्त गमावू शकत नाही, एक्सचेंज फक्त प्रीमियम ब्लॉक करते आणि काहीही अतिरिक्त नाही. हे अभ्यासक्रमातील सर्वात स्वच्छ मार्जिन आहे. शॉर्ट पुट उलट आहे: ते सुमारे बांधते <strong>रु. 165,042</strong>, क्रेडिटच्या अंदाजे सहा पट, कारण एक्सचेंजने उघडलेल्या शॉर्टवर उघडलेल्या नकारात्मक बाजूंना कव्हर केले पाहिजे.</p>\n<p>ते अंतर रिटर्न रिफ्रेम करते. शॉर्ट पुट रु. 165,042 ब्लॉक्डवर 19,182 रुपये कमावतो, जर ते काम करत असेल तर भांडवलावर सुमारे 12 टक्के, परंतु अशा शेपटीने एकाच वेळी अनेक विजय मिटवू शकतात. लाँग कॉलमुळे त्याचे संपूर्ण रु. 27,677 धोक्यात येतात परंतु अधिक नाही, आणि एक मजबूत रॅली त्याच्या कितीतरी पटीने परत येऊ शकते. एक व्यापार म्हणजे मोठ्या हालचालीवर एक लहान पैज आहे, तर दुसरा दुर्मिळ आपत्तीसह स्थिर भाडे आहे.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>पहा <strong>निळ्या डॅशची T+0 रेखा</strong> स्पॉट जवळ घन नारिंगी एक्सपायरी लाईन विरुद्ध. दीर्घ कॉलसाठी निळी रेषा केशरी रेषेच्या वर बसते आणि 28 जुलै जवळ येताच तिच्याकडे बुडते. ते पडणारे अंतर आहे <strong>वेळ क्षय खरेदीदार eroding</strong>: जरी NIFTY कडेकडेने वाहून गेले तरी, कॉल ब्लीड प्रत्येक शांत दिवसाला महत्त्व देतो, त्यामुळे एक लांब कॉल प्रत्यक्षात आणि वाजवीपणे लवकरच होण्यासाठी हलवा आवश्यक आहे.</p>\n<p>शॉर्ट पुटसाठी समान क्षय इतर मार्गाने चालते. तेथे निळी T+0 लाईन नारंगी शेल्फच्या खाली बसते आणि दिवस निघून गेल्याने त्याकडे वाढतात, कारण तुम्ही विकलेला प्रीमियम वितळतो तो नफ्यात. खरेदीदार घड्याळ लढतो. त्याद्वारे विक्रेत्याला पैसे दिले जातात. हा एकच फरक हा आहे की बरेच व्यापारी शेवटी खरेदीपासून विक्रीकडे का जातात, त्यांच्या बाजूने वेळेच्या बदल्यात शेपूट स्वीकारतात.</p>\n<h2 id=\"buyer-against-seller-both-bullish\">विक्रेता विरुद्ध खरेदीदार, दोन्ही तेजी</h2>\n<p>दोन ट्रेड शेजारी शेजारी ठेवल्याने या संपूर्ण कोर्सचा मध्यवर्ती सौदा शिकवला जातो.</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>लांब कॉल</th>\n<th>शॉर्ट पुट</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>तुम्ही पैसे द्या किंवा प्राप्त करा</td>\n<td>27,677 रुपये भरा</td>\n<td>19,182 रुपये मिळवा</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>रु 27,677</td>\n<td>सुमारे रु 1,544,068</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>अमर्यादित</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>24,476</td>\n<td>23,755</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>सुमारे 31 टक्के</td>\n<td>सुमारे 62 टक्के</td>\n</tr>\n<tr>\n<td>समास</td>\n<td>रु 27,677</td>\n<td>रु. 165,042</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>या दोन अंतःप्रेरणा एकत्र करून जवळपास प्रत्येक रणनीती तयार केली जाते. पुढील प्रकरणांमध्ये परिभाषित-जोखीम स्प्रेड्स एकाच वेळी लांब कॉलची किंमत आणि शॉर्ट पुटची शेपटी नियंत्रित करतात, दुसरा पाय जोडून जो एकासाठी पैसे देतो आणि दुसऱ्याचे संरक्षण करतो. येथे एकच पाय हे कच्चे पदार्थ आहेत.</p>\n</div></div>\n<p>नवशिक्यासाठी परिभाषित-जोखीम लांब कॉल, किंवा अजून चांगले स्प्रेड्स अगदी पुढे, हे सुरू करण्यासाठी अधिक सुरक्षित ठिकाण आहे. शॉर्ट पुट काळजीपूर्वक अभ्यासण्यासारखे आहे आणि केवळ नकारात्मक बाजूंचा पूर्ण आदर ठेवून विक्री करणे योग्य आहे, आघाडीवर नाही.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>ए <strong>लांब कॉल</strong> 24,476 च्या ब्रेकईव्हनच्या वर अमर्यादित वाढीच्या बदल्यात एक निश्चित प्रीमियम (येथे रु. 27,677) भरतो जो त्याचा जास्तीत जास्त तोटा देखील आहे.</li>\n<li>ए <strong>शॉर्ट पुट</strong> त्याचा जास्तीत जास्त नफा म्हणून निश्चित क्रेडिट (रु. 19,182) गोळा करते, परंतु 23,755 च्या ब्रेकईव्हनच्या खाली रु. 1,544,068 पर्यंत मोठे नुकसान होते आणि मोठ्या मार्जिनची मागणी करते.</li>\n<li>लांब कॉल कमी शक्यता आहे, सुमारे 31 टक्के, आणि <strong>वेळ क्षय त्याच्या विरुद्ध कार्य करते</strong>. शॉर्ट पुटमध्ये उच्च शक्यता आहे, सुमारे 62 टक्के, आणि <strong>वेळ क्षय त्यासाठी कार्य करते</strong>.</li>\n<li>लांब कॉल <strong>मार्जिन त्याच्या डेबिट बरोबर आहे</strong>, अभ्यासक्रमातील सर्वात स्वच्छ. शॉर्ट पुट नग्न डाउनसाइडसाठी सुमारे 165,042 रुपये बांधतो.</li>\n<li>प्रत्येक वाचा <strong>POP त्याच्या कमाल तोट्याच्या बाजूला</strong>: जड शेपटीसह उच्च शक्यता आणि लहान जोखमीसह कमी शक्यता एकाच प्रकारची पैज नाही.</li>\n<li>खरेदीदार त्यांना क्वचितच मिळणाऱ्या मोठ्या विजयाच्या संधीसाठी पैसे देतात. विक्रेते वारंवार लहान विजय आणि क्वचित मोठे नुकसान घेतात. दोन्हीपैकी काहीही चुकीचे नाही, परंतु परिभाषित करा.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"लांबलचक कॉल, रुपयाने रुपया","id":"the-long-call-rupee-by-rupee"},{"level":2,"text":"लांब कॉलचे तीन नंबर","id":"the-long-call-s-three-numbers"},{"level":2,"text":"कालबाह्य होण्यासाठी लांब कॉल चालणे","id":"walking-the-long-call-to-expiry"},{"level":2,"text":"शॉर्ट पुट, रुपया दर रुपया","id":"the-short-put-rupee-by-rupee"},{"level":2,"text":"शॉर्ट पुटचे तीन आकडे","id":"the-short-put-s-three-numbers"},{"level":2,"text":"एक्सपायरी करण्यासाठी शॉर्ट पुट चालणे","id":"walking-the-short-put-to-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"मार्जिन आणि परतावा","id":"margin-and-return"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"विक्रेता विरुद्ध खरेदीदार, दोन्ही तेजी","id":"buyer-against-seller-both-bullish"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"4":{"html":"<p>गेल्या प्रकरणातील लांब कॉल एक समस्या होती. 24,050 कॉल खरेदी करण्यासाठी तुम्ही सुमारे 27,677 रुपये दिले आणिNIFTY′ नंतर तुम्ही एक रुपया कमावण्यापूर्वी 24,476 वर चढावे लागले, तेथे पोहोचण्याची तीनपैकी फक्त एक शक्यता होती. हे खूप पैसे द्यावे लागेल, आणि प्रवास करण्यासाठी लांबचा मार्ग आहे, अशा दृश्यासाठी जे कदाचित सौम्यपणे उत्साही असेल. रॉकेट दूर करण्याऐवजीNIFTY′ 24,150 पर्यंत वाहण्याची तुमची अपेक्षा असेल, तर त्या मताचे अचूक समर्थन करण्याचा एक स्वस्त, स्मार्ट मार्ग आहे. तुम्ही विकत घेतलेल्या एकाच्या विरुद्ध तुम्ही जास्त कॉल विकता आणि तुमच्या सट्टेचा बहुतांश भाग मार्केटला देऊ द्या. हे आहे <strong>बैल कॉल पसरला</strong>, प्रत्येक पर्याय व्यापाऱ्याने शिकले पाहिजे अशी पहिली खरी दोन पायांची रणनीती आणि परिभाषित जोखमीचे सर्वात स्वच्छ उदाहरण आहे. सर्व आकडे 26 जून 2026, स्पॉट 24,056, लॉट 65, 28 जुलै 2026 ची मुदत 32 दिवसांनंतर कॅप्चर केलेला वास्तविक NIFTY डेटा वापरतात.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>बैल कॉल पसरला</strong> एकाच मुदतीत दोन कॉल्स आहेत. आपण <strong>लोअर-स्ट्राइक कॉल खरेदी करा</strong> उदय कॅप्चर करण्यासाठी, आणि आपण <strong>उच्च-स्ट्राइक कॉल विक्री</strong> प्रीमियम परत करण्यासाठी त्या लहान खर्च, द <strong>निव्वळ डेबिट</strong>, तुम्ही कधीही गमावू शकता ते सर्वात जास्त आहे.</p>\n<p>तुमचा दृष्टिकोन असेल तेव्हा तुम्ही ते वापरता <strong>माफक प्रमाणात तेजी</strong>: तुम्हीNIFTY′ पातळीच्या दिशेने वाढण्याची अपेक्षा करता, त्यापेक्षा जास्त पुढे जाणार नाही. तुम्ही खूप कमी पैसे देऊन आणि अगदी छोट्या हालचालीवरही खंडित होण्याच्या बदल्यात अमर्यादित वाढीचे स्वप्न दूर करता.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बुल कॉल स्प्रेड कमी कॉल खरेदी करतो आणि निव्वळ डेबिटसाठी उच्च कॉल विकतो. विकले गेलेले कॉल बहुतेक खरेदी केलेल्या कॉलला निधी देतात, त्यामुळे व्यापारासाठी कमी खर्च येतो. ते निव्वळ डेबिट, येथे रु. 3,624, तुमची एकूण किंमत आणि तुमचा कमाल तोटा दोन्ही आहे. तुम्ही जेवढी रक्कम ठेवता त्यापेक्षा जास्त तुम्ही कधीही तोटा करू शकत नाही आणि एकाकी कॉलच्या गरजेपेक्षा खूप कमी चालीवर तुम्ही नफा मिळवता.</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">खरा व्यापार, रुपयाने रुपया</h2>\n<p>येथे वास्तविक NIFTY किमतींवरील अचूक व्यापार, 24,056 वर निर्देशांक आहे. आम्ही 24,050 कॉल एट-द-मनी खरेदी करतो आणि 24,150 कॉल एक स्ट्राइक जास्त विकतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल विक्री</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>अधिक रु 24,053 मध्ये</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>3,624 रु</strong></td>\n</tr>\n</tbody></table>\n<p>एका कॉलसाठी तुमच्याकडे २७,६७७ रुपये आहेत. विकल्या गेलेल्या 24,150 कॉलचा परतावा सुमारे 24,053 रुपये होतो, त्यामुळे तुमचा खरा खर्च कमी होतो <strong>3,624 रुपये निव्वळ डेबिट</strong> एका लॉटसाठी. तुम्ही ते पैसे आगाऊ भरल्यामुळे आणि त्यापेक्षा जास्त कधीही मागितले जाऊ शकत नाही, निव्वळ डेबिट देखील तुम्ही गमावू शकता. त्यामुळेच बैल हाक पसरते अ <strong>परिभाषित-जोखीम</strong> व्यापार</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-call-spread.png\" alt=\"NIFTY बुल कॉल पसरला, 24,050 कॉल विकत घेतला आणि 24,150 कॉल विकला. ऑरेंज ॲट-एक्सपायरी लाइन 24,050 च्या खाली 3,624 रुपयांच्या फ्लॅट लॉस फ्लोअरवर टिकून आहे, 24,106 च्या ब्रेकईव्हनवर शून्य ओलांडते आणि 24,150 च्या वर 2,876 च्या मर्यादित नफ्यावर सपाट होते. निळ्या डॅशची T+0 रेषा त्याच्या अगदी वरती स्पॉटजवळ बसते, वेळ निघून गेल्यावर स्थिर होते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY बुल कॉल पसरला, 24,050 कॉल विकत घेतला आणि 24,150 कॉल विकला. ऑरेंज ॲट-एक्सपायरी लाइन 24,050 च्या खाली 3,624 रुपयांच्या फ्लॅट लॉस फ्लोअरवर टिकून आहे, 24,106 च्या ब्रेकईव्हनवर शून्य ओलांडते आणि 24,150 च्या वर 2,876 च्या मर्यादित नफ्यावर सपाट होते. निळ्या डॅशची T+0 रेषा त्याच्या अगदी वरती स्पॉटजवळ बसते, वेळ निघून गेल्यावर स्थिर होते.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p>प्रत्येक बुल कॉल स्प्रेडचे वर्णन तीन क्रमांकांद्वारे केले जाते आणि प्रत्येक वरील ट्रेडमधून थेट बाहेर पडतो.</p>\n<p><strong>जास्तीत जास्त नुकसान निव्वळ डेबिट आहे, रु. 3,624.</strong> जर NIFTY 24,050 वर किंवा खाली बंद होत असेल, तर दोन्ही कॉल निरुपयोगी कालबाह्य होतात आणि तुमचा संपूर्ण खर्च निघून जातो. चार्टच्या डावीकडील सपाट मजला आहे.</p>\n<p><strong>कमाल नफा म्हणजे स्ट्राइक रुंदी वजा डेबिट, रु 2,876.</strong> स्ट्राइकमधील अंतर 100 गुणांचे आहे, 100 गुणिले 65 किंवा 6,500 रुपये. एकदा NIFTY 24,150 वर किंवा वर बंद झाल्यावर, विकत घेतलेला कॉल पूर्ण 100 पॉइंट्स मिळवतो तर विकलेला कॉल त्यापलीकडे काहीही रद्द करतो, म्हणून तुम्ही ते 6,500 रुपये तुम्ही दिलेले 3,624 रुपये कमी ठेवा, जे रुपये 2,876 आहे.</p>\n<p><strong>ब्रेकइव्हन हा कमी स्ट्राइक अधिक डेबिट प्रति शेअर, 24,106 आहे.</strong> तुम्ही प्रति शेअर निव्वळ डेबिटचे 55.75 पॉइंट दिले आहेत, त्यामुळे तुम्ही नफ्यात जाण्यापूर्वीNIFTY′ खरेदी केलेल्या स्ट्राइकपेक्षा खूप वर जाणे आवश्यक आहे. ते 24,050 अधिक 55.75 किंवा 24,106 वर येते, एकाकी कॉलच्या 24,476 पेक्षा स्पॉटच्या खूप जवळ आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>निव्वळ डेबिट</td>\n<td>3,624 रु</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>स्ट्राइक रुंदी वजा निव्वळ डेबिट</td>\n<td>रु. 6,500 वजा रु 3,624 म्हणजे रु. 2,876</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>कमी स्ट्राइक अधिक डेबिट प्रति शेअर</td>\n<td>24,050 अधिक 55.75 बरोबर 24,106</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>कमाल नफा रु 2,876 आणि कमाल तोटा रु 3,624 नेहमी रु. 6,500 च्या पूर्ण स्ट्राइक रुंदीला जोडतात. स्प्रेड फक्त ती रुंदी तुम्ही आणि मार्केटमध्ये विभाजित करतो. स्ट्राइक हलवा आणि दोन संख्या बदलतात, परंतु त्यांची बेरीज रुंदीवर पिन केलेली राहते.</p>\n</div></div>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>मुठभर बंद किंमतींवर स्प्रेड सेटल करा आणि आकार दिसेल. खरेदी केलेल्या कॉलची किंमत कमाल आहे (NIFTY′ उणे 24,050, 0); विकलेल्या कॉलची किंमत कमाल आहे(NIFTY वजा 24,150, 0); तुमचा नफा म्हणजे खरेदी केलेले मूल्य वजा विक्री मूल्य, 65 पट, रु. 3,624 डेबिटपेक्षा कमी.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>तुम्ही विकत घेतलेला २४,०५० कॉल</th>\n<th>24,150 कॉल तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,900</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 3,624 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 3,624 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,106</td>\n<td>56 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 2,876 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,300</td>\n<td>250 किमतीची</td>\n<td>150 किमतीची</td>\n<td>अधिक रु 2,876 (कमाल नफा)</td>\n</tr>\n</tbody></table>\n<p>टेबल खाली वाचा आणि व्यापार स्वतः स्पष्ट करते. 24,050 वर किंवा त्यापेक्षा कमी कुठेही तुम्ही पूर्ण 3,624 रुपये गमावाल. 24,150 किंवा त्याहून अधिक कुठेही तुम्ही पूर्ण रु. 2,876 ठेवा. स्ट्राइक दरम्यान निकाल एका शेल्फमधून दुसऱ्या शेल्फवर सरकतो, शून्यातून 24,106 वर जातो. खालच्या पंक्तीकडे लक्ष द्या: 24,300 ला विकत घेतलेल्या कॉलची किंमत 250 आहे आणि विकलेल्या कॉलची किंमत 150 आहे, निव्वळ 100 पॉइंट्स, तीच रुंदी 6,500 रु, त्यामुळे कितीही उच्च NIFTY धावला तरीही नफा मर्यादित केला जातो.</p>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>तुम्ही जिंकू शकता आणि गमावू शकता हे जाणून घेणे ही अर्धी गोष्ट आहे. दुसरा अर्धा आहे <strong>नफा होण्याची शक्यता</strong>, बाजार-निहित संधी व्यापार हिरवा समाप्त.</p>\n<p>यासाठी पसरले <strong>POP सुमारे 47 टक्के आहे</strong>. 24,106 चा ब्रेकइव्हन चार्टवरील प्लस वन सिग्मा बँडच्या अगदी आत बसतो, पर्याय बाजाराची किंमत निश्चित आहे, म्हणूनNIFTY′ ला पैसे भरण्यासाठी फक्त स्पॉटच्या वर एक लहान पुश आवश्यक आहे. ते एकाकी कॉलच्या 31 टक्क्यांपेक्षा खूप आरोग्यदायी आहे, कारण ब्रेकइव्हन 24,476 वरून 24,106 पर्यंत कमी करणे म्हणजे खूप लहान चाल जिंकणे म्हणून मोजले जाते.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>रिवॉर्डच्या जोखमीच्या पुढीलPOP′ वाचा, येथे 1 ते 0.79. तुम्ही रु. 2,876 कमवण्यासाठी 3,624 रुपयांची जोखीम पत्करता, अगदी पैशांपेक्षा थोडे कमी, पण तुम्ही जवळपास अर्धा वेळ आणि फक्त छोट्या चालीवर जिंकता. एकाकी कॉल मोठ्या रनवर अधिक पैसे देतो, तरीही तो खूप कमी वेळा नफ्यात जातो. स्प्रेड भौतिकदृष्ट्या चांगल्या शक्यतांसाठी वरच्या भागाचा व्यापार करतो.</p>\n</div></div>\n<h2 id=\"margin\">समास</h2>\n<p>येथे बिल्डर ब्लॉक्सचे मार्जिन आहे <strong>35,378 रु</strong>, 3,624 रुपयांपेक्षा मोठे तुम्ही प्रत्यक्षात गमावू शकता. विकत घेतलेल्या कॉल लेगवर एक्स्पोजर रक्कम आकारते हे लक्षात येईपर्यंत ते विचित्र दिसते, जरी विकत घेतलेला कॉल पूर्णपणे कॅप करतो. खरोखर धोक्यात असलेली रोकड अद्याप फक्त निव्वळ डेबिट आहे, परंतु व्यापार सुरू असताना बाजूला ठेवण्यासाठी मोठ्या रकमेसाठी तयार रहा.</p>\n<p>ते मार्जिन तुम्हाला त्याच्या व्यापाराचा न्याय करू देते <strong>मार्जिन वर परत</strong>: सुमारे महिनाभर ब्लॉक केलेल्या रु. 35,378 विरुद्ध रु. 2,876 नफा <strong>8 टक्के</strong> जर ते कार्य करते. कल्पनांमध्ये तुलना करण्यासाठी हेच खरे उत्पन्न आहे, कच्च्या नफ्याचा आकडा नाही.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>पहा <strong>निळ्या डॅशची T+0 रेखा</strong> स्पॉट जवळ घन नारिंगी एक्सपायरी लाईन विरुद्ध. ते एकत्र बसतात, कारण एका पर्यायापेक्षा स्प्रेडमध्ये कच्च्या वेळेचे मूल्य खूपच कमी असते: तुम्ही विकत घेतलेल्या कॉलमधील रक्तस्राव मोठ्या प्रमाणात तुम्ही विकलेल्या कॉलच्या मूल्याच्या रक्तस्रावाने ऑफसेट केला जातो. बुल कॉल स्प्रेड म्हणजे ए <strong>डेबिट</strong> व्यापार करा, त्यामुळे शिल्लक वेळ तुमच्या विरुद्ध हळूवारपणे कार्य करते, परंतु स्थिर निचरा सारखे काहीही एकटे कॉल सहन करत नाही. घड्याळाच्या काट्यापेक्षा स्थितीला दिशेची जास्त काळजी असते.</p>\n<h2 id=\"choosing-your-strikes\">तुमचे स्ट्राइक निवडत आहे</h2>\n<p>100-पॉइंट स्प्रेड ही अनेकांमध्ये एक निवड आहे. स्पॉटच्या जवळ स्ट्राइकची विक्री करा आणि तुम्ही अधिक प्रीमियम गोळा कराल, खर्च आणि ब्रेकइव्हन कमी करा पण नफा लवकर मर्यादित करा. पुढे स्ट्राइक विकून टाका आणि तुम्ही जास्त पैसे द्याल, ब्रेकइव्हन वाढवून, हलवा मोठा असल्यास मोठ्या जास्तीत जास्त नफ्याच्या बदल्यात. अंगठ्याचा नियम साधा आहे.</p>\n<p>तुमची विक्री स्ट्राइक निवडा ज्या किमतीत तुम्हालाNIFTY′ पोहोचण्याची खरोखर अपेक्षा आहे, येथे 24,150, आशेने जास्त नाही. जास्तीत जास्त नफा त्या स्ट्राइकवर बसतो, म्हणून एक NIFTY विक्री केल्याने केवळ प्रीमियम फेकून देण्याची शक्यता नाही आणि तुमची किंमत विनाकारण वाढेल, तर हलविण्याआधी एक खूप जवळची विक्री केल्यास नफा वाढेल.</p>\n<h2 id=\"bull-call-spread-or-bull-put-spread\">बुल कॉल स्प्रेड की बुल पुट स्प्रेड?</h2>\n<p>पुढील अध्याय तयार करतो <strong>बैल पसरला</strong>, जे जवळपास-समान पेऑफ आकारासह अगदी समान मध्यम तेजीचे दृश्य व्यक्त करते. तर तुम्ही कोणते निवडता? बाजार तुम्हाला काय पैसे देत आहे यावर ते अवलंबून आहे.</p>\n<ul>\n<li>द <strong>बैल कॉल पसरला</strong> आहे <strong>डेबिट</strong> व्यापार तुम्ही आगाऊ पैसे भरता आणि योग्य असण्याची आशा आहे. NIFTY वाढल्यावर तुम्हाला फायदा होतो.</li>\n<li>द <strong>बैल पसरला</strong> आहे <strong>क्रेडिट</strong> व्यापार तुम्हाला आगाऊ पैसे दिले जातात आणि एकटे राहण्याची आशा आहे. जेव्हा NIFTY फक्त पडत नाही तेव्हा तुम्हाला फायदा होतो.</li>\n</ul>\n<p>जेव्हा बाजार घसरतो आणि भीतीने पुट प्रिमियम कमी होतो, तेव्हा तो महागडा विमा बुल पुट स्प्रेडद्वारे विकणे हा अधिक श्रीमंत सौदा असतो. जेव्हा प्रीमियम स्वस्त असतात आणि बाजार शांत असतो, तेव्हा बुल कॉल स्प्रेड खरेदी करणे अधिक चांगले मूल्य असू शकते. ते एकाच टेकडीवर जाणारे दोन मार्ग आहेत; क्रेडिट आवृत्ती तुमच्या बाजूने वेळ क्षय ठेवते, डेबिट आवृत्ती बाजाराला तुमच्या मार्गावर जाण्यास सांगते.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>परिभाषित जोखीम याचा अर्थ लहान धोका नाही. 3,624 रुपये प्रति लॉट हा खरा पैसा आहे, आणि जर NIFTY कालबाह्य झाल्यावर 24,050 वर किंवा खाली बंद झाला तर तुम्ही ते सर्व गमावाल, जे आज 24,056 च्या जवळ असलेल्या निर्देशांकासह पूर्णपणे शक्य आहे. नेहमी जास्तीत जास्त तोट्याने आकार द्या, जास्तीत जास्त नफ्याने कधीही नाही आणि लक्षात ठेवा की या दरम्यान मोठे मार्जिन बद्ध राहते. दोन लॉटची जोखीम रु. 7,248, तीन जोखीम रु. 10,872, इत्यादी.</p>\n</div></div>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>कोणताही धोका न पत्करता त्याची तालीम करा. OpenAlgo स्ट्रॅटेजी बिल्डर उघडा, NIFTY वर बुल कॉल स्प्रेड टेम्प्लेट निवडा आणि तुम्ही विकलेला स्ट्राइक स्लाइड करताना नऊ-मेट्रिक पॅनल अपडेट पहा. निव्वळ डेबिट आणि ब्रेकइव्हन एकत्रितपणे पाहा, त्यानंतर तुम्ही कधीही निधी देण्यापूर्वी सँडबॉक्स ट्रेडिंगमधील संपूर्ण ट्रेडची पुष्टी करा. हा अध्याय आपल्या हाताखाली उद्धृत केलेला समान अंक पाहणे म्हणजे रेसिपी समजून घेणे होय.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>ए <strong>बैल कॉल पसरला</strong> NIFTY वरच्या स्ट्राइकच्या दिशेने वाढल्यावर नफा मिळवून, निव्वळ डेबिटसाठी कमी कॉल खरेदी करतो आणि उच्च कॉल विकतो.</li>\n<li><strong>कमाल तोटा म्हणजे निव्वळ डेबिट</strong> (येथे ३,६२४ रुपये), <strong>कमाल नफा म्हणजे स्ट्राइक रुंदी वजा डेबिट</strong> (रु. 2,876), आणि दोन्ही नेहमी 6,500 च्या पूर्ण रुंदीच्या बेरीज करतात.</li>\n<li><strong>ब्रेकईव्हन हा कमी स्ट्राइक आणि प्रति शेअर डेबिट आहे</strong> (24,106), एकाकी कॉलच्या 24,476 पेक्षा स्पॉटच्या खूप जवळ आहे, त्यामुळे तुम्हाला खूप कमी चालीवर फायदा होतो.</li>\n<li>एकट्या कॉल पेक्षा चांगले शक्यता, बद्दल <strong>47 टक्के विरुद्ध 31 टक्के</strong>, विकल्या गेलेल्या स्ट्राइकच्या वर अमर्यादित वरचा भाग सोडून देण्याच्या बदल्यात.</li>\n<li>ते बद्दल अवरोधित करते <strong>35,378 रु</strong> मार्जिन आणि अंदाजे परतावा <strong>8 टक्के</strong> जर ते चालले तर त्या भांडवलावर. कमाल तोट्याने आकार, कमाल नफा नाही.</li>\n<li>वर प्राधान्य द्या <strong>बैल पसरला</strong> जेव्हा प्रीमियम स्वस्त असतात आणि बाजार शांत असतो, तेव्हा ते विकण्यापेक्षा मूव्ह खरेदी करणे चांगले असते.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"खरा व्यापार, रुपयाने रुपया","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"समास","id":"margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"तुमचे स्ट्राइक निवडत आहे","id":"choosing-your-strikes"},{"level":2,"text":"बुल कॉल स्प्रेड की बुल पुट स्प्रेड?","id":"bull-call-spread-or-bull-put-spread"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"5":{"html":"<p>बहुतेक नवशिक्या लॉटरी तिकीट म्हणून पर्याय भेटतात. तुम्ही एक छोटा प्रीमियम भरता, तुम्ही मोठ्या हालचालीसाठी प्रार्थना करता आणि बहुतेक दिवस तिकीट व्यर्थ संपते. बैल पुट स्प्रेड स्क्रिप्ट संपूर्णपणे flips. येथे तुम्ही तिकीट विकणारे, प्रीमियम गोळा करणारे आणि जोपर्यंत NIFTY पडत नाहीत तोपर्यंत शांतपणे ठेवणारे आहात. तुम्ही रॅलीवर पैज लावत नाही. तुम्ही क्रॅश विरुद्ध पैज लावत आहात, जी जिंकण्यासाठी खूप वेगळी आणि बऱ्याचदा खूप सोपी पैज आहे. हा धडा खऱ्या NIFTY किमतींवर व्यापार तयार करतो, तुम्हाला प्रत्येक रुपया नेमका कुठून येतो हे दाखवतो आणि तुम्हाला तीन आयाम देतो जे बहुतेक स्पष्टीकरणकर्त्यांनी सोडले आहेत: शक्यता, मार्जिन आणि वेळ स्वतःच तुमच्या बाजूने कसा काम करतो.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>बैल पसरला</strong> एकाच कालबाह्यतेवर दोन पुट पर्याय आहेत. आपण <strong>उच्च-स्ट्राइक पुट विक्री</strong> फॅट प्रीमियम गोळा करण्यासाठी आणि तुम्ही <strong>लोअर-स्ट्राइक पुट खरेदी करा</strong> वास्तविक अपघाताविरूद्ध स्वस्त विमा म्हणून. तुम्ही फरक ठेवा अ <strong>निव्वळ क्रेडिट</strong>, आणि ते क्रेडिट तुम्ही सर्वात जास्त कमवू शकता. खरेदी केलेले पुट तुमची नकारात्मक बाजू दर्शवत असल्याने, तुम्ही सर्वात जास्त गमावू शकता ते निश्चित केले जाते आणि तुम्ही बटणावर क्लिक करण्यापूर्वी ओळखले जाते.</p>\n<p>तुमचा दृष्टिकोन असेल तेव्हा तुम्ही ते वापरता <strong>माफक प्रमाणात तेजी</strong>, म्हणजे तुम्हाला वाटते की NIFTY वाढेल, सपाट राहील, किंवा सर्वात वाईट म्हणजे थोडेसे कमी होईल. तुम्हाला रॅलीची गरज नाही. कठीण पडू नये यासाठी तुम्हाला फक्त NIFTY आवश्यक आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बुल पुट स्प्रेड जास्त पुट विकतो आणि निव्वळ क्रेडिटसाठी कमी पुट खरेदी करतो. NIFTY तुमच्या उच्च स्ट्राइकच्या वर राहिल्यास तुम्हाला नफा होतो, तो तुमच्या खालच्या स्ट्राइकच्या खाली आला तरच तुमचे नुकसान होते आणि नफा आणि तोटा दोन्ही मर्यादित आहेत. मार्केट क्रॅश होणार नाही ही पैज आहे, ती चढेल अशी पैज नाही.</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">खरा व्यापार, रुपयाने रुपया</h2>\n<p>येथे 26 जून 2026 रोजी इंडेक्ससह कॅप्चर केलेल्या वास्तविक NIFTY किमतींवरील अचूक व्यापार येथे आहे <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत जवळपास 32 दिवसांनी संपेल. आम्ही 24,050 पुट एट-द-मनी विकतो आणि 23,950 पुट वन स्ट्राइक खाली विकत घेतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>24,050</td>\n<td>295 मिळाले</td>\n<td>अधिक 19,175 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>पुट खरेदी करा</td>\n<td>23,950</td>\n<td>257 भरले</td>\n<td>16,669 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु 2,506 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>24,050 पुटसाठी तुम्हाला मिळणारा प्रीमियम तुम्ही 23,950 पुटसाठी भरलेल्या प्रीमियमपेक्षा मोठा आहे, कारण जास्त स्ट्राइक अधिक मूल्यवान आहे. ते अंतर तुमचे आहे <strong>2,506 रुपये निव्वळ क्रेडिट</strong>, आणि तुम्ही व्यापार उघडताच ते तुमच्या खात्यात येते. म्हणूनच बुल पुट स्प्रेडला अ म्हणतात <strong>क्रेडिट प्रसार</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-put-spread.png\" alt=\"वास्तविक NIFTY बुल पुट स्प्रेड: 24,050 च्या वर 2,506 रुपयांचा फ्लॅट प्रॉफिट शेल्फ, 23,950 च्या खाली 3,994 रुपयांचा फ्लॅट लॉस शेल्फ, 24,011 वर सिंगल ब्रेकइव्हन, आणि ऑरेंज ॲट-एक्सपायरी लाइन स्पॉटच्या अगदी खाली नफ्यात बदलते. निळी डॅश केलेली रेषा आज आहे, नारंगी रेषेच्या वर बसली आहे कारण वेळेचा क्षय अद्याप त्याचे कार्य पूर्ण करू शकलेला नाही.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>वास्तविक NIFTY बुल पुट स्प्रेड: 24,050 च्या वर 2,506 रुपयांचा फ्लॅट प्रॉफिट शेल्फ, 23,950 च्या खाली रु. 3,994 चा फ्लॅट लॉस शेल्फ, 24,011 वर सिंगल ब्रेकईव्हन आणि स्पॉटच्या अगदी खाली ऑरेंज ॲट-एक्सपायरी लाईन नफ्यात. निळी डॅश केलेली रेषा आज आहे, नारंगी रेषेच्या वर बसली आहे कारण वेळेचा क्षय अद्याप त्याचे कार्य पूर्ण करू शकलेला नाही.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p>प्रत्येक बुल पुट स्प्रेडचे वर्णन तीन संख्येने केले जाते आणि प्रत्येक वरील ट्रेडमधून थेट बाहेर पडतो. एकदा तुम्ही लॉजिक पाहिल्यानंतर लक्षात ठेवण्याची गरज नाही.</p>\n<p><strong>जास्तीत जास्त नफा निव्वळ क्रेडिट, रु 2,506 आहे.</strong> NIFTY 24,050 स्ट्राइकवर किंवा त्याहून अधिक कुठेही समाप्त झाल्यास, दोन्ही पुट निरर्थक कालबाह्य होतात. जेव्हा निर्देशांक स्ट्राइकच्या वर असतो तेव्हा कोणीही पुट व्यायाम करत नाही. तुमचे काहीही देणे घेणे नाही, तुम्ही पूर्ण श्रेय ठेवता आणि हेच व्यापार करू शकणारे सर्वोत्तम आहे.</p>\n<p><strong>जास्तीत जास्त नुकसान स्प्रेड वजा क्रेडिट, रु 3,994 आहे.</strong> स्प्रेड म्हणजे दोन स्ट्राइकमधील अंतर, 100 गुण, 100 गुणिले 65, जे 6,500 रुपये आहे. जर NIFTY 23,950 च्या खाली कोसळले तर, दोन्ही पुट पैशात खोलवर आहेत आणि त्यांच्यामधील पूर्ण 100-बिंदू अंतर तुमच्या विरूद्ध लॉक केले आहे. तुम्ही ते 6,500 रुपये गमावले, परंतु तुम्ही आधीच 2,506 रुपये खिशात टाकले आहेत, त्यामुळे तुमचे खरे नुकसान 6,500 उणे 2,506 आहे, जे आहे <strong>3,994 रु</strong>. विकत घेतलेले पुट हे या पूर्वीचे नुकसान थांबवते. त्याशिवाय तुम्ही लाखोंच्या घसरणीला तोंड देणारे नग्न विक्रेते व्हाल.</p>\n<p><strong>ब्रेकइव्हन हा उच्च स्ट्राइक वजा क्रेडिट प्रति शेअर, 24,011 आहे.</strong> तुम्ही प्रति शेअर 38.55 पॉइंट क्रेडिट गोळा केले. NIFTY 24,050 स्ट्राइक पेक्षा 38.55 पॉइंट खाली जाऊ शकते, <strong>24,011</strong>, तुमच्या शॉर्ट पुटवरील तोटा पूर्ण क्रेडिट खाण्यापूर्वी. 24,011 च्या वर तुम्ही नफ्यात पूर्ण करता. त्या खाली तुम्ही तोट्यात पूर्ण करता.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>निव्वळ क्रेडिट</td>\n<td>2,506 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>स्प्रेड वजा निव्वळ क्रेडिट</td>\n<td>रु. 6,500 वजा रु 2,506 = रु. 3,994</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>उच्च स्ट्राइक वजा क्रेडिट प्रति शेअर</td>\n<td>24,050 वजा 38.55 = 24,011</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>रणनीतीवर विश्वास ठेवण्याचा सर्वात स्वच्छ मार्ग म्हणजे मूठभर बंद किंमतींवर त्याचे निराकरण करणे आणि पैशावर लक्ष ठेवणे. येथे वळू पुट स्प्रेड आहे पाच स्तरांवर NIFTY कालबाह्य दिवशी, प्रति लॉट 65.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 ला तुम्ही विकले</th>\n<th>23,950 ला तुम्ही विकत घेतले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>250 किमतीची</td>\n<td>150 किमतीची</td>\n<td>उणे रु ३,९९४ (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>उणे रु ३,९९४ (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,011</td>\n<td>39 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 2,506 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,300</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 2,506 (कमाल नफा)</td>\n</tr>\n</tbody></table>\n<p>टेबल खाली वाचा आणि व्यापाराचा आकार स्वतःच दिसून येईल. 24,050 वरून कुठेही तुम्ही पूर्ण 2,506 रुपये गोळा करता. 23,950 वरून कुठेही खाली तुम्ही पूर्ण 3,994 रुपये गमावाल. दोन स्ट्राइक दरम्यान परिणाम 24,011 वर शून्यातून पुढे सरकत एका शेल्फमधून दुसऱ्या शेल्फवर सहजतेने सरकतो. ते संपूर्ण मोबदला आहे आणि ते चार्टवरील केशरी रेषेशी तंतोतंत जुळते.</p>\n<h2 id=\"the-dimension-most-explainers-skip-your-odds\">बहुतेक स्पष्टीकरण करणारे परिमाण वगळतात: तुमची शक्यता</h2>\n<p>तुम्ही जिंकू शकता आणि गमावू शकता हे जाणून घेणे ही केवळ अर्धी गोष्ट आहे. व्यापार स्मार्ट आहे की नाही हे ठरवणारा प्रश्न हा आहे की, प्रत्येक परिणामाची किती शक्यता आहे? ते म्हणजे <strong>नफ्याची शक्यता</strong>, किंवा POP, आणि बिल्डर ते थेट पॅनेलवर ठेवतो.</p>\n<p>यासाठी पसरले <strong>POP सुमारे 51 टक्के आहे</strong>. तो क्रमांक ऑप्शन मार्केटमधूनच येतो. अंदाजे 12.7 टक्के आणि 32 दिवस शिल्लक असलेल्याNIFTY′ पर्यायांमध्ये किंमत असलेल्या अस्थिरतेचा वापर करून, बाजार 51 टक्के शक्यता सूचित करतो की NIFTY कालबाह्यतेनुसार 24,011 ब्रेकइव्हनच्या वर पूर्ण होईल. पुन्हा चार्ट पहा. फिकट छायांकित <strong>सिग्मा बँड</strong> बाजाराला अपेक्षित असलेली हालचाल दाखवा आणि 24,011 चे ब्रेकइव्हन स्पॉटच्या अगदी खाली बसते, आरामात आतील बँडमध्ये. NIFTY ला काही विशेष करण्याची गरज नाही. तो फक्त आधीपासून आहे तेथे अंदाजे धरून ठेवणे आवश्यक आहे.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>POP च्या शेजारी जास्तीत जास्त नुकसान नेहमी वाचा, कधीही एकटे नाही. हा स्प्रेड रु. 2,506 करण्यासाठी रु. 3,994 जोखीम घेतो, जो एक-टू-वन पेआउटपेक्षा वाईट आहे, तरीही ते अर्थपूर्ण आहे कारण शक्यता, 51 टक्के, तुमचा मार्ग आणि वेळ तुम्हाला मदत करेल. क्रेडिट स्प्रेड ही एक डील आहे जिथे तुम्ही अधिक वेळा जिंकण्याच्या बदल्यात एक लहान बक्षीस स्वीकारता. POP हे तुम्ही कसे तपासता की ट्रेड-ऑफ खरोखर तुमच्या बाजूने आहे.</p>\n</div></div>\n<h2 id=\"the-other-dimension-most-explainers-skip-margin\">दुसरे परिमाण बहुतेक स्पष्टीकरण करणारे वगळतात: समास</h2>\n<p>कारण तुम्ही निव्वळ विक्रेता आहात, एक्सचेंज ब्लॉक करते <strong>समास</strong> सुरक्षा म्हणून, येथे <strong>35,358 रु</strong>, SPAN घटक तसेच एक्सपोजर बफरपासून बनविलेले. खरेदी केलेले 23,950 पुट ही संख्या कमी ठेवते. त्याशिवाय नग्न शॉर्ट पुट रु. 1.6 लाखांवर बांधला जाईल. संरक्षणात्मक पाय केवळ तुमचे नुकसान भरून काढत नाही, तर ते व्यापारासाठी आवश्यक भांडवल कमी करते.</p>\n<p>ते मार्जिन तुम्हाला व्यापाराचा प्रामाणिकपणे न्याय करू देते <strong>मार्जिन वर परत</strong>. तुम्ही सुमारे महिनाभर ब्लॉक केलेल्या रु. 35,358 विरुद्ध रु. 2,506 गोळा करता, जे साधारणतः <strong>भांडवलावर 7 टक्के जोखीम</strong> व्यापार चालतो तर. हेच पोझिशनचे खरे उत्पन्न आहे आणि एक गंभीर ट्रेडर कच्च्या प्रीमियमशी नव्हे तर कल्पनांमध्ये तुलना करतो.</p>\n<h2 id=\"time-is-on-your-side\">वेळ तुमच्या बाजूने आहे</h2>\n<p>चार्ट वर पुन्हा एकदा पहा <strong>निळ्या डॅशची T+0 रेखा</strong> सध्याच्या किमतीच्या जवळ घन नारंगी ॲट-एक्सपायरी लाईनच्या वर बसणे. ते अंतर आहे <strong>वेळेचे मूल्य</strong>, आणि निव्वळ विक्रेत्यासाठी ही एक भेट आहे. प्रत्येक शांत दिवसात तुम्ही ज्या पर्यायांमध्ये कमी आहात त्यातील थोडा प्रीमियम वितळतो आणि निळी रेषा केशरीकडे जाते. तुम्ही समोर क्रेडिट गोळा केले आहे आणि जोपर्यंत NIFTY वर्तन करत आहे तोपर्यंत वेळ शांतपणे त्याचे वास्तविक नफ्यात रूपांतर करते. एक लांब पर्याय खरेदीदार दररोज या किडणे लढा. क्रेडिट-स्प्रेड विक्रेता म्हणून, तुम्हाला त्याद्वारे पैसे दिले जातात.</p>\n<h2 id=\"choosing-your-strikes\">तुमचे स्ट्राइक निवडत आहे</h2>\n<p>वरील 100-पॉइंट स्प्रेड ही अनेकांमध्ये एक निवड आहे. स्ट्राइकमधील अंतर वाढवा किंवा कमी करा आणि तुम्ही संपूर्ण व्यापाराला आकार द्या. येथे एकाच NIFTY, समान एक्सपायरी वर चार रिअल बुल पुट स्प्रेड आहेत, त्यामुळे तुम्ही ट्रेड-ऑफ स्वच्छपणे पाहू शकता.</p>\n<table>\n<thead>\n<tr>\n<th>प्रसार</th>\n<th>विक्री / खरेदी</th>\n<th>क्रेडिट (कमाल नफा)</th>\n<th>कमाल नुकसान</th>\n<th>ब्रेकवेन</th>\n<th>POP</th>\n<th>समास</th>\n<th>मार्जिनवर परत या</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>50 गुण</td>\n<td>24,050 विक्री करा / 24,000 खरेदी करा</td>\n<td>1,173 रु</td>\n<td>रु. 2,077</td>\n<td>24,032</td>\n<td>50%</td>\n<td>33,633 रु</td>\n<td>3.5%</td>\n</tr>\n<tr>\n<td>100 गुण</td>\n<td>विक्री 24,050 / खरेदी 23,950</td>\n<td>2,506 रु</td>\n<td>3,994 रु</td>\n<td>24,011</td>\n<td>51%</td>\n<td>35,358 रु</td>\n<td>7.1%</td>\n</tr>\n<tr>\n<td>200 गुण</td>\n<td>विक्री 24,050 / खरेदी 23,850</td>\n<td>४,६१८ रु</td>\n<td>8,382 रु</td>\n<td>23,979</td>\n<td>53%</td>\n<td>39,246 रु</td>\n<td>11.8%</td>\n</tr>\n<tr>\n<td>200 गुण, अधिक खोल</td>\n<td>विक्री 24,150 / खरेदी 23,950</td>\n<td>५,३७२ रु</td>\n<td>७,६२८ रु</td>\n<td>24,067</td>\n<td>48%</td>\n<td>38,553 रु</td>\n<td>13.9%</td>\n</tr>\n</tbody></table>\n<p>नमुना स्पष्ट आहे. ए <strong>व्यापक प्रसार</strong> अधिक क्रेडिट गोळा करते आणि मार्जिनवर जास्त परतावा मिळवते, परंतु जर तुम्ही चुकीचे असाल तर ते अधिक रुपये जोखीम देखील घेते. उच्च, इन-द-मनी स्ट्राइक, शेवटची पंक्ती, विक्री केल्याने, सर्वात जास्त क्रेडिट गोळा केले जाते, परंतु हे ब्रेकइव्हनला 24,067 पर्यंत, वर्तमान स्थानापेक्षा वर ढकलते, त्यामुळे तुम्हाला आता थोडेसे वाढण्यासाठीNIFTY′ आवश्यक आहे, फक्त धरून नाही. टेबलमध्ये कोणतेही मोफत जेवण नाही, फक्त एक डायल जो तुम्ही तुमच्या खात्रीशी जुळण्यासाठी सेट केला आहे. मजबूत माफक प्रमाणात तेजी दृश्य, प्रसार रुंद करा. सावध, अरुंद ठेवा.</p>\n<h2 id=\"bull-put-spread-or-bull-call-spread\">बुल पुट स्प्रेड की बुल कॉल स्प्रेड?</h2>\n<p>तुम्ही बुल कॉल स्प्रेड शेवटच्या अध्यायात भेटलात आणि ते अगदी समान मध्यम स्वरूपाचे तेज दृश्य व्यक्त करते आणि जवळपास एकसारखे पेऑफ आकार आहे. तर तुम्ही कोणते निवडता? प्रामाणिक उत्तर आहे, हे बाजार तुम्हाला काय पैसे देत आहे यावर अवलंबून आहे.</p>\n<ul>\n<li>द <strong>बैल कॉल पसरला</strong> आहे <strong>डेबिट</strong> व्यापार तुम्ही समोर पैसे भरता आणि बरोबर असण्याची आशा आहे.</li>\n<li>द <strong>बैल पसरला</strong> आहे <strong>क्रेडिट</strong> व्यापार तुम्हाला समोर पैसे दिले जातात आणि एकटे राहण्याची आशा आहे.</li>\n</ul>\n<p>जेव्हा बाजार घसरतात, भीती जास्त असते आणि पुट प्रीमियम्स सुजलेले असतात, तेव्हा बुल पुट स्प्रेडद्वारे महाग पुट विमा विकणे हा अधिक श्रीमंत सौदा आहे. जेव्हा प्रीमियम स्वस्त असतात आणि बाजार शांत असतो, तेव्हा बुल कॉल स्प्रेड ही चांगली खरेदी असू शकते. बरेच अनुभवी व्यापारी फक्त क्रेडिट आवृत्ती पसंत करतात, कारण त्यांच्या बाजूने वेळ क्षय झाल्यामुळे प्रतीक्षा करण्यासाठी पैसे दिले जाणे, पैसे देणे आणि घड्याळ त्यांच्या विरूद्ध चालत पाहण्यापेक्षा स्थितीत राहण्याचा अधिक सोयीस्कर मार्ग आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>बुल पुट स्प्रेड परिभाषित-जोखीम आहे, परंतु जोखीम वास्तविक आहे आणि ती पुरस्कारापेक्षा मोठी आहे. येथे तुम्ही रु. 2,506 कमविण्यासाठी 3,994 रु. शांततापूर्ण विजयी महिन्यांची धावपळ तुम्हाला ओव्हरसाइजिंगमध्ये कमी करू शकते आणि नंतर तुमच्या खालच्या स्ट्राइकद्वारे एकाच वेळी अनेक महिन्यांची क्रेडिट्स परत मिळू शकतात. पसरलेल्या प्रत्येक क्रेडिटला त्याच्या कमाल तोट्याने आकार द्या, तुम्ही गोळा केलेल्या क्रेडिटनुसार कधीही नाही आणि कधीही तुटलेली पाहून घाबरून जातील अशा स्तराखाली पुट स्प्रेड कधीही विकू नका.</p>\n</div></div>\n<h2 id=\"when-it-shines-and-when-to-stay-out\">ते कधी चमकते आणि कधी बाहेर राहायचे</h2>\n<p>जेव्हा अनेक गोष्टी रांगेत असतात तेव्हा बुल पुट स्प्रेड सर्वोत्तम असतो.</p>\n<ul>\n<li>तुमचा दृष्टिकोन आहे <strong>मध्यम तेजी ते तटस्थ</strong>. तुम्हीNIFTY′ धारण करण्याची किंवा उगवण्याची अपेक्षा करतो, उंचावण्याची नाही.</li>\n<li><strong>ठेवा प्रीमियम श्रीमंत आहेत</strong>, सहसा घसरण झाल्यानंतर, जेव्हा तुम्ही विकू इच्छित असलेले पर्याय घाबरून जातील.</li>\n<li><strong>गर्भित अस्थिरता भारदस्त आहे</strong>, त्यामुळे तुम्हाला पॅनीकची दुसरी बाजू घेण्यासाठी अधिक पैसे दिले जातात.</li>\n<li>आहे <strong>कालबाह्य होण्यासाठी पुरेसा वेळ</strong> काम करण्यासाठी क्षय होण्यासाठी, परंतु इतके नाही की स्थिती अनेक आठवड्यांपर्यंत अनियंत्रित राहते.</li>\n</ul>\n<p>जेव्हा तुम्हाला ब्रेकडाउनची खरी चिंता वाटत असेल, प्रिमियम कमी असेल आणि गोळा करण्यासाठी थोडे क्रेडिट असेल किंवा जेव्हा एखादी मोठी घटना तुमच्या खालच्या स्ट्राइकमधून रात्रभरNIFTY′ अंतर करू शकते, कारण परिभाषित जोखीम केवळ तुमच्या मुदत संपल्यावर तुमचे रक्षण करते, इंट्राडे मार्जिन कॉल ट्रिगर करणाऱ्या हिंसक अंतरापासून नाही.</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>जोखीम नसलेल्या पैशांशिवाय याचे रिहर्सल करण्याचा एक स्वच्छ मार्ग: OpenAlgo स्ट्रॅटेजी बिल्डर उघडा, NIFTY वर बुल पुट स्प्रेड टेम्प्लेट निवडा आणि तुम्ही स्ट्राइक अलग पाडत असताना नऊ-मेट्रिक पॅनल अपडेट पहा. क्रेडिट आणि मार्जिन एकत्रितपणे पहा, ब्रेकइव्हन शिफ्ट पहा आणि सँडबॉक्स ट्रेडिंगमधील ट्रेडची पुष्टी करा (Analyser मोड OpenAlgo मध्ये) तुम्ही कधीही निधी देण्यापूर्वी. आपल्या स्वत: च्या हातांनी व्यापार तयार करणे, आणि या अध्यायात उद्धृत केलेले समान संख्या पाहणे, हेच रेसिपीला वास्तविक समज बनवते.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>बुल पुट स्प्रेड जास्त पुट विकतो आणि कमी पुट a साठी विकत घेतो <strong>निव्वळ क्रेडिट</strong>, NIFTY उच्च स्ट्राइकपेक्षा वर धारण केल्यास नफा.</li>\n<li><strong>कमाल नफा हे निव्वळ क्रेडिट आहे</strong> (येथे रु 2,506), <strong>कमाल तोटा म्हणजे स्प्रेड वजा क्रेडिट</strong> (रु. ३,९९४), आणि <strong>ब्रेकईव्हन हा उच्च स्ट्राइक वजा क्रेडिट आहे</strong> (24,011).</li>\n<li>बक्षीस जोखमीपेक्षा लहान आहे, म्हणून व्यापार त्याचे स्थान a द्वारे कमावतो <strong>फायद्याची अनुकूल शक्यता</strong> (51 टक्के) आणि <strong>वेळ क्षय आपल्यासाठी काम करत आहे</strong>.</li>\n<li>ते ब्लॉक करते <strong>समास</strong> (सुमारे 35,358 रुपये), आणि खरेदी केलेला पुट हा मार्जिन आणि तोटा दोन्ही कमी ठेवतो. व्यापाराचा न्याय करा <strong>मार्जिन वर परत</strong>, अंदाजे 7 टक्के येथे.</li>\n<li><strong>विस्तृत पसरते</strong> अधिक जोखमीसाठी अधिक क्रेडिट आणि अधिक परतावा गोळा करा. तुमच्या खात्रीशी रुंदी जुळवा.</li>\n<li>जेव्हा बुल कॉल स्प्रेडवर ते निवडा <strong>प्रीमियम समृद्ध आहेत आणि अस्थिरता जास्त आहे</strong>, त्यामुळे तुम्हाला प्रतीक्षा करण्यासाठी चांगले पैसे दिले जातात.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"खरा व्यापार, रुपयाने रुपया","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"बहुतेक स्पष्टीकरण करणारे परिमाण वगळतात: तुमची शक्यता","id":"the-dimension-most-explainers-skip-your-odds"},{"level":2,"text":"दुसरे परिमाण बहुतेक स्पष्टीकरण करणारे वगळतात: समास","id":"the-other-dimension-most-explainers-skip-margin"},{"level":2,"text":"वेळ तुमच्या बाजूने आहे","id":"time-is-on-your-side"},{"level":2,"text":"तुमचे स्ट्राइक निवडत आहे","id":"choosing-your-strikes"},{"level":2,"text":"बुल पुट स्प्रेड की बुल कॉल स्प्रेड?","id":"bull-put-spread-or-bull-call-spread"},{"level":2,"text":"ते कधी चमकते आणि कधी बाहेर राहायचे","id":"when-it-shines-and-when-to-stay-out"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"6":{"html":"<p>आतापर्यंत प्रत्येक तेजीच्या व्यापाराला एक व्यवस्थित, मर्यादित स्वरूप आले आहे. आता आम्ही महत्वाकांक्षेमध्ये तीन संरचनांसह पाऊल टाकतो जे त्या नीटनेटके टोप्यांचा व्यापार मोठ्या आणि अधिक मुक्त गोष्टींसाठी करतात आणि दोन प्रकरणांमध्ये खूप धोकादायक असतात. ते सर्व उत्साही आहेत, परंतु प्रत्येकजण वेगळ्या पद्धतीने मत व्यक्त करतो. द <strong>कॉल रेशो बॅक स्प्रेड</strong> वरची बाजू मोकळी सोडताना तुमची डाउनसाइड लहान ठेवते. द <strong>दीर्घ कृत्रिम भविष्य</strong> दोन पर्यायांना सरळ रेषेत वळवते जे अगदी NIFTY भविष्य खरेदी करण्यासारखे वागते. द <strong>श्रेणी पुढे</strong> एक बुलिश कॉलर आहे जो NIFTY प्रत्यक्ष हालचाल करेपर्यंत झोपतो. हे असे ट्रेड आहेत जिथे स्ट्रॅटेजी बिल्डरच्या नंबर्सची कमाई होते, कारण आकार आता नावावरून स्पष्ट होत नाहीत. सर्व आकडे 26 जून 2026, स्पॉट 24,056, लॉट 65, 28 जुलै 2026 ची मुदत 32 दिवसांनंतर कॅप्चर केलेला वास्तविक NIFTY डेटा वापरतात.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>तिन्ही रचना एक साठी पोहोचतात <strong>अमर्यादित वरची बाजू</strong>, परंतु ते पूर्णपणे भिन्न मार्गांनी त्यासाठी पैसे देतात. एक त्याचे नुकसान घट्टपणे कॅप करतो आणि केवळ माफक रकमेचा धोका असतो. इतर दोन पर्यायांमधून फ्युचर्स पोझिशनची पुनर्बांधणी करतात, त्यामुळे त्यांची डाउनसाइड खुली आहे आणि त्यांचे मार्जिन भारी आहे. हा धडा शिकविणारे कौशल्य म्हणजे तक्त्याची कोणती बाजू अमर्यादित, किंवा जवळपास अमर्यादित, नुकसान लपवते ते वाचणे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>अमर्यादित नफा पाहणे सोपे भाग आहे. दुसऱ्या बाजूला काय बसते हा नेहमीच प्रामाणिक प्रश्न असतो. कॉल रेशो बॅक स्प्रेड 26,930 रु. सिंथेटिक भविष्य आणि श्रेणी पुढे प्रत्येक धोक्यात पंधरा लाखांहून अधिक कोलमडते, कारण विकलेला पाय हा नकारात्मक बाजू उघडतो. एकच स्वप्न, तीन अगदी भिन्न किंमती.</p>\n</div></div>\n<h2 id=\"strategy-one-the-call-ratio-back-spread\">धोरण एक: कॉल रेशो बॅक स्प्रेड</h2>\n<p>बॅक स्प्रेड असमान पायांचा वापर करतो. येथे तुम्ही एक ॲट-द-मनी कॉल विकता आणि दोन कॉल एक स्ट्राइक जास्त खरेदी करता.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 कॉल विक्री करा</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td>अधिक रु 27,677 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>2 कॉल खरेदी करा</td>\n<td>24,150</td>\n<td>370.1 प्रत्येकी दिले</td>\n<td>४८,१०७ रुपये (२ लॉट)</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>20,430 रु</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही खरेदी करता त्या दोनपैकी सिंगल सेल्ड कॉल फंड भाग, परंतु जोडीची एकूण किंमत जास्त आहे, म्हणून तुम्ही ए <strong>20,430 रुपये निव्वळ डेबिट</strong>. त्या बदल्यात तुमच्याकडे स्ट्राइकच्या वर एक अतिरिक्त लांब कॉल आहे आणि तो अतिरिक्त कॉल स्ट्रक्चरला मजबूत रॅलीमध्ये अमर्यादित वाढ देतो.</p>\n<p>तीन संख्या खालील प्रमाणे पडतात.</p>\n<p><strong>जास्तीत जास्त तोटा रु. 26,930 आहे आणि तो शेपटी नव्हे तर मध्यभागी राहतो.</strong> 24,050 च्या खाली प्रत्येक कॉल निरुपयोगी कालबाह्य होतो आणि तुम्ही निव्वळ डेबिट गमावता. खरी वेदना 24,150 स्ट्राइकवर बसते, जिथे विकलेला कॉल 100 पॉईंट्सने पूर्णपणे पैशांमध्ये असतो परंतु दोन विकत घेतलेले कॉल जेमतेम जागे झाले आहेत. हे शॉर्टवर 100-पॉइंटचे नुकसान आहे, 6,500 रुपये, तसेच रुपये 20,430 डेबिट, जे एकत्रितपणे 26,930 रुपये बनवतात.</p>\n<p><strong>ब्रेकईव्हन 24,564 आहे.</strong> 24,150 च्या वर दोन लाँग कॉल्स सिंगल शॉर्ट हरवल्यापेक्षा दुप्पट वेगाने वाढतात, प्रति शेअर निव्वळ एक पॉइंट, त्यामुळे पोझिशन त्याच्या दरीतून बाहेर पडते आणि एकदा तो फायदा प्रति शेअर डेबिट पुनर्प्राप्त झाल्यावर शून्य ओलांडतो. <strong>जास्तीत जास्त नफा अमर्यादित आहे</strong> तेथे वर.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>24,150 अधिक निव्वळ डेबिटवर शॉर्ट कॉल तोटा</td>\n<td>रु. 6,500 अधिक रु. 20,430 म्हणजे रु. 26,930</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>एक सुटे लांब कॉल विनामूल्य चालू आहे</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>अप्पर क्रॉसिंग जेथे दोन लाँग डेबिट वसूल करतात</td>\n<td>24,564</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-ratio-back-spread.png\" alt=\"NIFTY कॉल रेशो बॅक स्प्रेड, एक 24,050 कॉल विकून आणि दोन 24,150 कॉल खरेदी केले. ऑरेंज लाइन 24,150 स्ट्राइकवर रु. 26,930 च्या सर्वात वाईट तोट्यात बुडते, ब्रेकइव्हन 24,564 वर चढते, नंतर कोणत्याही कमाल मर्यादेशिवाय हिरव्या रंगात वाढते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY कॉल रेशो बॅक स्प्रेड, एक 24,050 कॉल विकून आणि दोन 24,150 कॉल खरेदी केले. ऑरेंज लाइन 24,150 स्ट्राइकवर रु. 26,930 च्या सर्वात वाईट तोट्यात बुडते, ब्रेकइव्हन 24,564 वर चढते, नंतर कोणत्याही कमाल मर्यादेशिवाय हिरव्या रंगात वाढते.</figcaption></figure>\n<p>आता एक्सपायरी वर सेटल करा. विकल्या गेलेल्या कॉलची किंमत कमाल आहे(NIFTY′ उणे 24,050, 0); दोन खरेदी केलेले कॉल प्रत्येकी कमाल (NIFTY वजा 24,150, 0) किमतीचे आहेत.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल विकले</th>\n<th>24,150 कॉल खरेदी केले (प्रत्येक)</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,900</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 20,430 (डेबिट)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>उणे रु 26,930 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,564</td>\n<td>514 किमतीची</td>\n<td>414 किमतीची</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,800</td>\n<td>750 किमतीची</td>\n<td>650 किमतीची</td>\n<td>अधिक रु. 15,320</td>\n</tr>\n<tr>\n<td>25,050</td>\n<td>1,000 किमतीचे</td>\n<td>900 किमतीची</td>\n<td>अधिक रु. 31,570 (आणि वाढत)</td>\n</tr>\n</tbody></table>\n<p>खाली वाचा आणि दरी स्वतः दर्शवते. सर्वात वाईट स्थिती म्हणजे क्रॅश नसून, 24,150 वर विकल्या गेलेल्या स्ट्राइकला पिन करणारा सौम्य प्रवाह. ही अशी दुर्मिळ रचना आहे जिथे अमर्यादित म्हणजे अमर्यादित नफा, अमर्यादित जोखीम नाही आणि तोटा 26,930 रुपये आहे.</p>\n<h2 id=\"strategy-two-the-long-synthetic-future\">रणनीती दोन: दीर्घ सिंथेटिक भविष्य</h2>\n<p>पुढील रचना वक्र पूर्णपणे सोडून देते. एकाच स्ट्राइकवर एक खरेदी केलेला कॉल आणि एक विकलेला पुट एकत्र करून, तुम्ही एक सरळ कर्णरेषा तयार करता जी उगवते आणि पडते ती अगदी NIFTY भविष्याच्या मालकीप्रमाणे.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>24,050</td>\n<td>295.1 मिळाले</td>\n<td>अधिक 19,182 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>8,496 रु</strong></td>\n</tr>\n</tbody></table>\n<p>विकत घेतलेला कॉल तुम्हाला भविष्यातील सर्व वरवरचा हात देतो; विकलेले त्याचे सर्व नुकसान तुम्हाला हात लावतात. एकत्रितपणे त्यांची थोडीशी किंमत आहे <strong>8,496 रुपये निव्वळ डेबिट</strong>, आणि स्थिती नंतर दोन्ही दिशांच्या बिंदूसाठीNIFTYबिंदू ट्रॅक करते. कुठेही संरक्षक पाय नाही, त्यामुळे सपाट मजला नाही. हे संपूर्ण भविष्य आहे, दोन पर्यायांमधून पुनर्निर्मित.</p>\n<p><strong>जास्तीत जास्त नफा अमर्यादित आहे</strong> ब्रेकईव्हनच्या वर. <strong>जास्तीत जास्त तोटा शून्याकडे जातो, सुमारे रु 1,571,746</strong>, कारण ब्रेकइव्हनच्या खाली स्थिती दीर्घ भविष्याप्रमाणेच रुपयासाठी रुपयाची घसरण होते. <strong>ब्रेकईव्हन 24,181 आहे</strong>, स्ट्राइक आणि प्रति शेअर निव्वळ डेबिट 130.7, जी तुम्हीNIFTYखरेदी केलेली प्रभावी किंमत आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>भविष्याप्रमाणे, ब्रेकईव्हनच्या वर कमाल मर्यादा नाही</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>भविष्यासारखी शून्याकडे घसरण</td>\n<td>सुमारे रु 1,571,746</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>स्ट्राइक अधिक प्रति शेअर निव्वळ डेबिट</td>\n<td>24,050 अधिक 130.7 बरोबर 24,181</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-synthetic.png\" alt=\"NIFTY दीर्घ सिंथेटिक भविष्य, 24,050 कॉल खरेदी करणे आणि 24,050 पुट विकणे. केशरी रेषा ही एक सरळ कर्णरेषा आहे, जी 24,181 च्या ब्रेकईव्हनच्या वर मर्यादेशिवाय वाढत आहे आणि त्याच्या खाली रुपयासाठी रुपया घसरत आहे, अगदी दीर्घ भविष्याप्रमाणे. निळी T+0 रेषा जवळजवळ त्याच्या वर आहे, कारण सिंथेटिक भविष्यकाळाला जवळजवळ कोणतेही मूल्य नसते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY दीर्घ सिंथेटिक भविष्य, 24,050 कॉल खरेदी करणे आणि 24,050 पुट विकणे. केशरी रेषा ही एक सरळ कर्णरेषा आहे, जी 24,181 च्या ब्रेकईव्हनच्या वर मर्यादेशिवाय वाढत आहे आणि त्याच्या खाली रुपयासाठी रुपया घसरत आहे, अगदी दीर्घ भविष्याप्रमाणे. निळी T+0 रेषा जवळजवळ त्याच्या वर आहे, कारण सिंथेटिक भविष्यकाळाला जवळजवळ कोणतेही मूल्य नसते.</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल खरेदी केले</th>\n<th>24,050 पुट विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>मूल्य 0</td>\n<td>1,050 किमतीची</td>\n<td>उणे रु 76,746 (आणि घसरण)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 8,496</td>\n</tr>\n<tr>\n<td>24,181</td>\n<td>131 किमतीची</td>\n<td>मूल्य 0</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,500</td>\n<td>450 किमतीची</td>\n<td>मूल्य 0</td>\n<td>अधिक 20,755 रु</td>\n</tr>\n<tr>\n<td>25,000</td>\n<td>950 किमतीची</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 53,255 (आणि वाढत)</td>\n</tr>\n</tbody></table>\n<p>ओळीत अर्थ लावण्यासारखे काहीही नाही, जो मुद्दा आहे. 24,181 च्या वर तुम्ही कमाल मर्यादा नसलेल्या पॉइंटसाठी पॉइंट मिळवाल; याच्या खाली तुम्ही बिंदूसाठी बिंदू गमावता, फक्तNIFTY′ शून्यावर घसरल्याने.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>दीर्घ सिंथेटिक भविष्यकाळ अगदी दीर्घ NIFTY भविष्याप्रमाणे वागतो, त्यामुळे त्याचा धोका द्वि-बाजूचा आणि प्रचंड आहे. NIFTY कोसळल्यास, विकले जाणारे पुट नग्न शॉर्ट लेग असल्यास, आणि एक्सचेंज रु. 173,537 च्या जवळ जास्त मार्जिन अवरोधित केल्यास सुमारे 1,571,746 रुपयांचे नुकसान होते. येथे कोणताही परिभाषित मजला नाही. ही दोन पर्यायांची वेशभूषा केलेली फ्युचर्स-ग्रेड पोझिशन आहे आणि नवशिक्याने त्यास फ्युचर्स-ग्रेड आदराने वागवले पाहिजे, ते भविष्यापेक्षा अधिक सुरक्षित नसावे.</p>\n</div></div>\n<h2 id=\"strategy-three-the-range-forward\">रणनीती तीन: श्रेणी पुढे</h2>\n<p>तिसरी रचना सौम्य आहे. ए <strong>श्रेणी पुढे</strong>, ज्याला कधीकधी बुलिश कॉलर म्हणतात, त्याच्या वरच्या आउट-ऑफ-द-मनी कॉलला निधी देण्यासाठी बाजाराच्या खाली ठेवलेला आउट-ऑफ-द-मनी विकतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>अधिक रु 16,679 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल खरेदी करा</td>\n<td>24,150</td>\n<td>370.1 भरले</td>\n<td>24,057 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>7,378 रु</strong></td>\n</tr>\n</tbody></table>\n<p>विकलेला पुट बहुतेक खरेदी केलेल्या कॉलसाठी पैसे देतो, एक छोटासा सोडून <strong>7,378 रुपये निव्वळ डेबिट</strong>. दोन स्ट्राइक दरम्यान, 23,950 ते 24,150 पर्यंत, कोणत्याही पर्यायाचे आंतरिक मूल्य नाही, म्हणून स्थिती त्या लहान डेबिटवर अवलंबून असते, एक सपाट डेड झोन जेथे थोडेसे घडते. स्ट्राइकच्या बाहेर ते जिवंत होते: 24,150 च्या वर खरेदी केलेला कॉल अमर्यादित वरची बाजू देतो, 23,950 च्या खाली विकलेला कॉल तुम्हाला भविष्यासारखी नकारात्मक बाजू देतो.</p>\n<p><strong>जास्तीत जास्त नफा अमर्यादित आहे</strong> ब्रेकईव्हनच्या वर. <strong>जास्तीत जास्त तोटा शून्याकडे जातो, सुमारे रु 1,564,128</strong>, नग्न पुट वर. <strong>ब्रेकईव्हन 24,264 आहे</strong>, 24,150 चा वरचा स्ट्राइक अधिक निव्वळ डेबिट प्रति शेअर 113.5.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>वरच्या स्ट्राइकच्या वर विनामूल्य चालू असलेले कॉल खरेदी केले</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>विक्री शून्य दिशेने घसरण</td>\n<td>सुमारे रु 1,564,128</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>अप्पर स्ट्राइक अधिक प्रति शेअर निव्वळ डेबिट</td>\n<td>24,150 अधिक 113.5 बरोबर 24,264</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-range-forward.png\" alt=\"NIFTY श्रेणी फॉरवर्ड, 23,950 पुट विकून आणि 24,150 कॉल खरेदी. स्ट्राइक दरम्यान एक लहान सपाट डेड झोन, 24,264 च्या ब्रेकईव्हनच्या वर अमर्यादित आणि 23,950 च्या खाली सखोल भविष्यासारखा तोटा असलेली केशरी रेषा जवळजवळ दीर्घ भविष्य आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY श्रेणी फॉरवर्ड, 23,950 पुट विकून आणि 24,150 कॉल खरेदी. स्ट्राइक दरम्यान एक लहान सपाट डेड झोन, 24,264 च्या ब्रेकईव्हनच्या वर अमर्यादित आणि 23,950 च्या खाली सखोल भविष्यासारखा तोटा असलेली केशरी रेषा जवळजवळ दीर्घ भविष्य आहे.</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>23,950 पुट विकले</th>\n<th>24,150 कॉल खरेदी केले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>950 किमतीची</td>\n<td>मूल्य 0</td>\n<td>उणे ६९,१२८ रुपये (आणि घसरण)</td>\n</tr>\n<tr>\n<td>24,000</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे ७,३७८ रुपये (डेड झोन)</td>\n</tr>\n<tr>\n<td>24,264</td>\n<td>मूल्य 0</td>\n<td>114 किमतीची</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,600</td>\n<td>मूल्य 0</td>\n<td>450 किमतीची</td>\n<td>अधिक 21,873 रु</td>\n</tr>\n<tr>\n<td>25,100</td>\n<td>मूल्य 0</td>\n<td>950 किमतीची</td>\n<td>अधिक रु 54,373 (आणि वाढत)</td>\n</tr>\n</tbody></table>\n<p>स्ट्राइक दरम्यानचा डेड झोन व्यापाराला शांत वाटतो, परंतु त्या शांततेमुळे 23,950 पर्यंत झटपट NIFTY घसरते, जेथे विकले गेलेले पुट रुपयाला रुपया गमावण्यास सुरुवात करते, फक्तNIFTY′ शून्यावर घसरल्याने.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>श्रेणी फॉरवर्ड नग्न पुट विकून त्याची किंमत मिटवते, त्यामुळे नकारात्मक बाजू भविष्यासारखी आणि खूप मोठी आहे, 1,564,128 रुपयांच्या जवळ कमाल तोटा, 166,553 रुपयांच्या जवळ मार्जिनसह. तुम्ही थोडक्यात सांगाल तसे ते नकारात्मक बाजू हाताळा. सपाट मधला भाग आत्मसंतुष्टतेला आमंत्रण देतो, परंतु खालच्या स्ट्राइकद्वारे खरी घसरण हे एका लहान भविष्यासारखे वागते, परिभाषित-जोखीम पसरत नाही.</p>\n</div></div>\n<h2 id=\"your-odds-across-the-three\">तिन्ही ओलांडून तुमची शक्यता</h2>\n<p>द <strong>नफ्याची शक्यता</strong> या स्वच्छपणे क्रमवारीत: सुमारे <strong>28 टक्के</strong> कॉल रेशो बॅक स्प्रेडसाठी, <strong>44 टक्के</strong> कृत्रिम भविष्यासाठी, आणि <strong>40 टक्के</strong> पुढे श्रेणीसाठी. बॅक स्प्रेड सर्वात कमी बसतो कारण ओपन-एंडेड अपसाइड देय होण्यापूर्वी NIFTY ने त्याच्या चार्टवरील प्लस वन सिग्मा बँडच्या पलीकडे, 24,564 साफ करणे आवश्यक आहे. सिंथेटिक आणि श्रेणी फॉरवर्ड सम जवळ आहेत कारण ते भविष्यासारखे वागतात, ब्रेकईव्हनच्या अगदी थोड्या वरच्या स्थानानंतरच्या कोणत्याही हालचालीवर नफा मिळवतात.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>कमी POP हा आपोआप वाईट व्यापार नसतो आणि उच्चतर आपोआप चांगला नसतो. कॉल रेशो बॅक स्प्रेड वेळेच्या केवळ 28 टक्के जिंकतो, तरीही त्याचे नुकसान रु. 26,930 इतके मर्यादित आहे आणि त्याचे विजय ओपन एंडेड असू शकतात. सिंथेटिकचे 44 टक्के तुम्ही त्याच्या रु. 1,571,746 शेपटाच्या बाजूला सेट करेपर्यंत चांगले दिसते. नेहमी जास्तीत जास्त नुकसानापुढील POP वाचा, स्वतःहून कधीही नाही.</p>\n</div></div>\n<h2 id=\"margin\">समास</h2>\n<p>मार्जिन इतर कोणत्याही संख्येपेक्षा अधिक प्रामाणिकपणे धोक्यानुसार या तिघांची क्रमवारी लावते. द <strong>कॉल रेशो बॅक स्प्रेड</strong> बद्दल संबंध <strong>52,256 रु</strong>, विनम्र, कारण त्याचे नुकसान परिभाषित केले आहे आणि लांब कॉल्स मोठ्या प्रमाणावर शॉर्ट कव्हर करतात. द <strong>दीर्घ कृत्रिम भविष्य</strong> बद्दल अवरोध <strong>रु. 173,537</strong> आणि <strong>श्रेणी पुढे</strong> बद्दल <strong>रु. 166,553</strong>, दोन्ही जड, कारण प्रत्येकामध्ये उघड्या डाउनसाइडसह नग्न लहान पाय आहे ज्यात एक्सचेंज कव्हर करणे आवश्यक आहे.</p>\n<p>मार्जिनवर परतावा तेव्हाच अर्थपूर्ण होतो जेव्हा नफा मर्यादित असतो आणि यापैकी दोनची कमाल मर्यादा नसते, त्यामुळे कोट करण्यासाठी कोणतेही निश्चित उत्पन्न नसते. टेकअवे हाच कॉन्ट्रास्ट आहे: परिभाषित-जोखीम आकारासाठी अंदाजे 52,000 मार्जिन, वेशातील भविष्यासाठी अंदाजे रु. 1.7 लाख.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>तिघे घड्याळाच्या विरुद्ध बसतात. द <strong>कॉल रेशो बॅक स्प्रेड</strong> पर्यायांचा निव्वळ खरेदीदार आहे, एक अतिरिक्त कॉल लांब आहे, त्यामुळे वेळ क्षय त्याच्या विरूद्ध हळूवारपणे कार्य करते: तिची निळी T+0 रेषा केशरी एक्स्पायरी रेषेच्या वर तरंगते आणि 28 जुलै जवळ आल्यावर दरी थोडीशी खोल होते. द <strong>दीर्घ कृत्रिम भविष्य</strong> जवळजवळ वेळेचे मूल्य अजिबात धारण करत नाही, म्हणून तिची T+0 रेषा कालबाह्य रेषेवर आहे; ते मूलत: वेळ-तटस्थ आहे, भविष्याप्रमाणे. द <strong>श्रेणी पुढे</strong> त्याच्या लांब कॉलवर फक्त एक लहान रक्तस्त्राव सह, तटस्थ देखील जवळ बसते. यापैकी काहीही हा क्षय व्यापार नाही. ते दिशाने जगतात किंवा मरतात.</p>\n<h2 id=\"three-shapes-one-bullish-family\">तीन आकार, एक तेजस्वी कुटुंब</h2>\n<table>\n<thead>\n<tr>\n<th>रणनीती</th>\n<th>कमाल नुकसान</th>\n<th>जास्तीत जास्त नफा</th>\n<th>ब्रेकवेन</th>\n<th>समास</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कॉल रेशो बॅक स्प्रेड</td>\n<td>26,930 रु</td>\n<td>अमर्यादित</td>\n<td>24,564</td>\n<td>52,256 रु</td>\n</tr>\n<tr>\n<td>लांब सिंथेटिक भविष्य</td>\n<td>सुमारे रु 1,571,746</td>\n<td>अमर्यादित</td>\n<td>24,181</td>\n<td>रु. 173,537</td>\n</tr>\n<tr>\n<td>पुढे श्रेणी</td>\n<td>सुमारे रु 1,564,128</td>\n<td>अमर्यादित</td>\n<td>24,264</td>\n<td>रु. 166,553</td>\n</tr>\n</tbody></table>\n<p>जास्तीत जास्त नुकसान स्तंभ काळजीपूर्वक वाचा, कारण ते धोक्यांनुसार क्रमवारी लावते. कॉल रेशो बॅक स्प्रेड हा एकच आहे ज्यासाठी नवशिक्याने पोहोचले पाहिजे: त्याची सर्वात वाईट स्थिती म्हणजे परिभाषित केलेले रु 26,930 आणि ते माफक मार्जिन मागते. सिंथेटिक भविष्य आणि श्रेणी फॉरवर्ड प्रत्येकामध्ये नग्न लहान पाय, पंधरा लाखांहून अधिक डाउनसाईड आणि भारी मार्जिन आहे, कारण प्रत्येक खरोखर पर्यायी पोशाख परिधान केलेले भविष्य आहे.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>तिघेही एक सह उत्साही आहेत <strong>अमर्यादित वरची बाजू</strong>, परंतु त्यांच्यापर्यंत पोहोचण्याचा धोका त्यांच्यात पूर्णपणे भिन्न आहे.</li>\n<li>द <strong>कॉल रेशो बॅक स्प्रेड</strong> रु. 26,930 चा परिभाषित कमाल तोटा आहे जो 24,150 स्ट्राइकच्या मध्यभागी बसतो, टेलमध्ये नाही आणि 24,564 च्या ब्रेकईव्हनच्या वर विनामूल्य चालतो. ही येथे नवशिक्या-सुरक्षित निवड आहे.</li>\n<li>द <strong>दीर्घ कृत्रिम भविष्य</strong> दीर्घ NIFTY भविष्यकाळाच्या बरोबरीचे: ब्रेकइव्हन 24,181, रु. 1,571,746 कडे जवळपास सहा-आकड्या-गुणपट-दहा डाउनसाइड, भारी मार्जिन, आणि जवळजवळ कोणताही क्षय नाही.</li>\n<li>द <strong>श्रेणी पुढे</strong> स्ट्राइक दरम्यान एक सपाट डेड झोन असलेला एक तेजीचा कॉलर आहे, परंतु विकले गेलेले पुट 23,950 च्या खाली रु. 1,564,128 च्या जवळ भविष्यासारखे उतार सोडते.</li>\n<li><strong>मार्जिन सत्य सांगतो</strong>: परिभाषित-जोखीम परत स्प्रेडसाठी सुमारे रु 52,000, दोन भविष्यासारख्या संरचनांसाठी अंदाजे रु. 1.7 लाख.</li>\n<li>नेहमी तपासा <strong>तक्त्याची कोणती बाजू अमर्यादित, किंवा जवळपास अमर्यादित, नुकसान लपवते</strong> अमर्यादित नफा मिळवण्याआधी.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"धोरण एक: कॉल रेशो बॅक स्प्रेड","id":"strategy-one-the-call-ratio-back-spread"},{"level":2,"text":"रणनीती दोन: दीर्घ सिंथेटिक भविष्य","id":"strategy-two-the-long-synthetic-future"},{"level":2,"text":"रणनीती तीन: श्रेणी पुढे","id":"strategy-three-the-range-forward"},{"level":2,"text":"तिन्ही ओलांडून तुमची शक्यता","id":"your-odds-across-the-three"},{"level":2,"text":"समास","id":"margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"तीन आकार, एक तेजस्वी कुटुंब","id":"three-shapes-one-bullish-family"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"7":{"html":"<p>आत्तापर्यंतच्या प्रत्येक ट्रेडनेNIFTY′ ची व्यापक बाजू मागितली आहे: कृपया उठ, कृपया क्रॅश होऊ नका, कृपया येथेच थांबा. या प्रकरणातील दोन रचना अधिक अचूक काहीतरी विचारतात. द <strong>तेजस्वी फुलपाखरू</strong> आणि <strong>तेजीचा कंडोर</strong> लहान, सर्जिकल बेट्स आहेत जेNIFTY′ एका विशिष्ट लँडिंग स्पॉटवर वाहतात आणि एक्सपायरी झाल्यावर तिथे बसतात. त्यांना जवळजवळ काहीही लागत नाही, जेमतेम शंभर रुपये जोखीम, आणि ते त्यापेक्षा कितीतरी पटीने परत देऊ शकतात. कॅच, प्रामाणिकपणे समोर सांगितले, ते दहापैकी फक्त एक वेळा जिंकतात, कारण निर्देशांक एका अरुंद खिडकीत संपला पाहिजे. हा धडा 26 जून 2026, स्पॉट 24,056, लॉट 65, एक्सपायरी 28 जुलै 2026 रोजी कॅप्चर केलेल्या वास्तविक NIFTY डेटावर दोन्ही तयार करतो आणि ते नेमके काय आहेत हे शिकवते: अचूक दृश्यावर स्वस्त तिकिटे, कमाईचा कधीही स्थिर मार्ग नाही.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>दोन्ही स्ट्रक्चर्स संपूर्णपणे कॉल ऑप्शन्समधून तयार केल्या आहेत आणि दोन्ही खरेदी आणि विक्री केलेल्या स्ट्राइकचा संच स्टॅक करतात जेणेकरून प्रत्येक बाजूला आपल्या जोखमीला पंख लावले जातील. ए <strong>तेजस्वी फुलपाखरू</strong> एक लोअर कॉल विकत घेतो, दोन मिडल कॉल विकतो आणि एक उच्च कॉल खरेदी करतो, बॉडी पैशाच्या अगदी वर नज केली जाते जेणेकरून ते एकाच टार्गेटवर सर्वोत्तम पैसे देते. ए <strong>तेजीचा कंडोर</strong> त्या बॉडीला दोन वेगळ्या विकलेल्या स्ट्राइकमध्ये पसरवते, एका बिंदूऐवजी लहान लँडिंग झोनसाठी खालच्या शिखरावर व्यापार करते. दोन्हीमध्ये, तुम्ही विकल्या गेलेल्या कॉल्समधून गोळा केलेले प्रीमियम तुम्ही खरेदी केलेल्या कॉलसाठी जवळजवळ तंतोतंत अदा करतात, त्यामुळे तुम्ही एका लहान निव्वळ डेबिटसाठी प्रवेश करता आणि ते लहान डेबिट ही तुमची संपूर्ण जोखीम असते.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>एक बुलिश बटरफ्लाय आणि एक बुलिश कंडोर हे स्वस्त, परिभाषित-जोखीम बेट्स आहेत जेNIFTY′ एक्स्पायरीनंतर अचूक लक्ष्यावर चढतात आणि तिथेच थांबतात. तुम्ही एक लहान डेबिट भरता, ते डेबिट तुम्ही सर्वात जास्त गमावू शकता आणि दोन्ही बाजूंच्या व्यापाराला विंग कॅप करतात. जोखीम घेण्याचे बक्षीस नेत्रदीपक आहे, परंतु खिडकीत उतरण्याची शक्यता कमी आहे. हे लक्ष्यित लांब शॉट्स आहेत, कोर पोझिशन्स नाहीत.</p>\n</div></div>\n<h2 id=\"the-bullish-butterfly-rupee-by-rupee\">तेजस्वी फुलपाखरू, रुपयाने रुपया</h2>\n<p>हे फुलपाखरू वास्तविक NIFTY किंमतींवर आहे, तीन स्ट्राइक आणि चार पाय, शरीर दोनदा 24,150 ला विकले गेले आणि पंख 24,050 आणि 24,250 ला विकत घेतले गेले.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>2</td>\n<td>दोन कॉल विक्री</td>\n<td>24,150</td>\n<td>740.2 प्राप्त झाले</td>\n<td>अधिक रु 48,113 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल खरेदी करा</td>\n<td>24,250</td>\n<td>316.1 भरले</td>\n<td>20,547 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>सुमारे 120 रु</strong></td>\n</tr>\n</tbody></table>\n<p>खरेदी केलेले दोन पंख एकत्र जोडा आणि त्यांची किंमत 48,224 रुपये आहे. दोन विकल्या गेलेल्या बॉडी कॉल्स 48,113 रुपये परत आणतात. त्यांच्यातील अंतर फक्त आहे <strong>120 रु</strong>, आणि ती व्यापाराची संपूर्ण किंमत आहे. कारण विंग बॉक्समध्ये रचना वर आणि खाली आहे, तुम्हाला कधीही एक रुपया जास्त मागितला जाऊ शकत नाही, म्हणून हे 120 रुपये देखील सर्वात जास्त नुकसान आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bullish-butterfly.png\" alt=\"NIFTY बुलिश बटरफ्लाय, 24,050 आणि 24,250 कॉल्स खरेदी करतो आणि दोन 24,150 कॉल्स विकतो. ऑरेंज ॲट-एक्सपायरी लाईन हा एक तीक्ष्ण तंबू आहे जो 6,380 रुपये 24,150 वर पोहोचतो, बाहेरील पंखांजवळ ब्रेकवेव्हन्स आणि जवळपास सपाट मजल्यासह इतर सर्वत्र फक्त 120 रुपयांचे कमाल नुकसान होते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY बुलिश बटरफ्लाय, 24,050 आणि 24,250 कॉल्स खरेदी करतो आणि दोन 24,150 कॉल्स विकतो. ऑरेंज ॲट-एक्सपायरी लाईन हा एक तीक्ष्ण तंबू आहे जो 6,380 रुपये 24,150 वर पोहोचतो, बाहेरील पंखांजवळ ब्रेकवेव्हन्स आणि जवळपास सपाट मजल्यासह इतर सर्वत्र फक्त 120 रुपयांचे कमाल नुकसान होते.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p>प्रत्येक संख्या थेट व्यापाराच्या बाहेर पडते. शिखर शरीराच्या स्ट्राइकवर बसते, मजला डेबिट आहे आणि ब्रेकेव्हन्स पंखांना मिठी मारतात.</p>\n<p><strong>कमाल नफा 6,380 रुपये आहे.</strong> जर NIFTY 24,150 च्या बॉडी स्ट्राइकवर तंतोतंत पूर्ण झाले, तर तुमचा खरेदी केलेला 24,050 कॉल पैशात 100 पॉइंट्स आहे तर दोन विकलेले कॉल आणि वरचे विंग सर्व व्यर्थ आहेत. ते आंतरिक मूल्य 100 गुणिले 65 आहे, जे 6,500 रुपये आहे आणि तुम्ही दिलेले 120 रुपये वजा केल्यानंतर तुम्ही 6,380 रुपये ठेवाल. ती तंबूची एकच तीक्ष्ण टोक आहे.</p>\n<p><strong>कमाल तोटा रु. 120 आहे, निव्वळ डेबिट.</strong> पंखांच्या बाहेर कुठेही स्ट्रक्चर कालबाह्य होते, प्रत्येक कॉल एकतर रद्द होतो किंवा निरुपयोगी असतो आणि आपण प्रविष्ट करण्यासाठी दिलेली तुटपुंजी रक्कम आपण गमावतो.</p>\n<p><strong>ब्रेकेव्हन्स 24,042 आणि 24,254 वर बसतात, मूलत: बाह्य पंख.</strong> डेबिट इतके लहान आहे, दोन पॉइंट्सच्या शेअरच्या खाली, की तंबू शून्य ओलांडत असलेल्या पॉईंटला क्वचितच हलवते, त्यामुळे ते थेट पंखांवर उतरतात.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>विंगपासून शरीरापर्यंतचे अंतर, पटसंख्या, वजा डेबिट</td>\n<td>100 गुण गुणिले 65, जे रुपये 6,500, उणे रुपये 120, बरोबरीचे रुपये 6,380</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>तुम्ही भरलेले निव्वळ डेबिट</td>\n<td>120 रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>बाह्य पंख, अगदी लहान डेबिटने हलवले</td>\n<td>सुमारे 24,042 आणि 24,254</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>फुलपाखराला पाच NIFTY स्तरांवर सेट करा आणि तंबू स्वतःच काढेल. प्रत्येक कॉल कालबाह्य होण्याच्या वेळेस त्याचे आंतरिक मूल्य आहे, कॉल त्याच्या स्ट्राइकच्या वर जेवढे संपेल ते कितीही मूल्यवान आहे आणि बॉडी लेग दुप्पट आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल (विकत घेतले)</th>\n<th>24,150 कॉल्स (विकलेले, दोन)</th>\n<th>२४,२५० कॉल (खरेदी)</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,900</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 120 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 120 (मजला)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 6,380 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,250</td>\n<td>200 किमतीचे</td>\n<td>2 पट 100 थकबाकी</td>\n<td>मूल्य 0</td>\n<td>उणे रु 120 (मागे मजल्यावर)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>350 किमतीची</td>\n<td>2 पट 250 थकबाकी</td>\n<td>150 किमतीची</td>\n<td>उणे रु 120 (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>ते पृष्ठ खाली वाचा. अगदी डावीकडे आणि उजवीकडे 120 रुपयांच्या तोट्यात रेषा सपाट आहे, इतकी लहान ती जवळजवळ शून्याला स्पर्श करते. केवळ 24,150 च्या आसपास ते एका उंच, पातळ शिखरावर पोहोचते. 24,400 वरच्या पंक्तीकडे लक्ष द्या: विकत घेतलेले 24,250 विंग जिवंत होते आणि दोन विकल्या गेलेल्या कॉलची परतफेड करते, त्यामुळेच तोटा रु. 120 च्या पुढे कधीच वाढत नाही, कितीही पुढे धावले तरीही.</p>\n<h2 id=\"the-bullish-condor-rupee-by-rupee\">तेजीचा कंडर, रुपयाने रुपया</h2>\n<p>कंडोर हीच कल्पना घेते आणि शिखर एका पठारावर पसरवते. एक स्ट्राइक दोनदा विकण्याऐवजी, तुम्ही 24,100 आणि 24,200 असे दोन भिन्न मध्यम स्ट्राइक विकता, त्यामुळे तंबूचा वरचा भाग एका बिंदूऐवजी एक लहान सपाट शेल्फ बनतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल विक्री</td>\n<td>24,100</td>\n<td>397.6 प्राप्त झाले</td>\n<td>अधिक रु 25,844 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल विक्री</td>\n<td>24,200</td>\n<td>342.9 मिळाले</td>\n<td>अधिक रु 22,289 मध्ये</td>\n</tr>\n<tr>\n<td>4</td>\n<td>कॉल खरेदी करा</td>\n<td>24,250</td>\n<td>316.1 भरले</td>\n<td>20,547 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>सुमारे 88 रु</strong></td>\n</tr>\n</tbody></table>\n<p>पुन्हा एकदा दोन विकले गेलेले कॉल दोन विकत घेतलेल्या पंखांसाठी जवळजवळ पैसे देतात, फक्त निव्वळ डेबिट सोडून <strong>रु 88</strong>, जे संपूर्ण कमाल नुकसान आहे. दोन विकले गेलेले स्ट्राइक त्यांच्या दरम्यान सपाट नफ्याच्या पठाराच्या कडा चिन्हांकित करतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bullish-condor.png\" alt=\"NIFTY बुलिश कंडोर, 24,050 आणि 24,250 कॉल्स खरेदी करतो आणि 24,100 आणि 24,200 कॉल्स विकतो. ऑरेंज लाईन सुमारे 24,100 आणि 24,200 च्या दरम्यान 3,162 रुपयांच्या कमाल नफ्यावर फ्लॅट टॉप केलेला तंबू बनवते, स्ट्रक्चरच्या अगदी बाहेर ब्रेकवेन्स आणि फक्त 88 रुपयांच्या कमाल तोट्यात फ्लॅट फ्लोअर.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY बुलिश कंडोर, 24,050 आणि 24,250 कॉल्स खरेदी करतो आणि 24,100 आणि 24,200 कॉल्स विकतो. ऑरेंज लाईन सुमारे 24,100 आणि 24,200 च्या दरम्यान 3,162 रुपयांच्या कमाल नफ्यावर फ्लॅट टॉप केलेला तंबू बनवते, स्ट्रक्चरच्या अगदी बाहेर ब्रेकवेन्स आणि फक्त 88 रुपयांच्या कमाल तोट्यात फ्लॅट फ्लोअर.</figcaption></figure>\n<p>त्याचे तीन आकडे त्याच प्रकारे तयार केले आहेत. द <strong>कमाल नफा 3,162 रुपये आहे</strong>: पठारावर कुठेही विकत घेतलेला 24,050 कॉल पहिल्या विकल्या गेलेल्या स्ट्राइकच्या 50 गुणांनी पुढे बसतो, 50 गुणा 65, म्हणजे 3,250 रुपये, आणि 88 रुपये डेबिटनंतर तुम्ही 3,162 रुपये ठेवा. द <strong>कमाल नुकसान रु 88 आहे</strong>, डेबिट. द <strong>breakevens सुमारे 24,040 आणि 24,254 वर बसतात</strong>, पुन्हा मूलत: संरचनेच्या बाह्य कडा. आता ते पाच पातळ्यांवर चाला.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल (विकत घेतले)</th>\n<th>24,100 कॉल (विक्री)</th>\n<th>24,200 कॉल (विकलेला)</th>\n<th>२४,२५० कॉल (खरेदी)</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,950</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु ८८ (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,100</td>\n<td>50 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,162 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 किमतीचे</td>\n<td>50 देणे बाकी आहे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,162 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,200</td>\n<td>150 किमतीची</td>\n<td>100 देणे बाकी आहे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,162 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,350</td>\n<td>300 किमतीचे</td>\n<td>250 थकबाकी आहे</td>\n<td>150 थकबाकी आहे</td>\n<td>100 किमतीचे</td>\n<td>उणे रु ८८ (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>तीन मधली पंक्ती कथा सांगतात: 24,100 ते 24,200 पर्यंत कुठेही व्यापार समान 3,162 रुपये देतो, फुलपाखराच्या सिंगल स्पाइकपेक्षा एक सपाट शेल्फ. तुम्ही जमिनीच्या विस्तीर्ण जागेसाठी फुलपाखराच्या 6,380 रुपयांच्या तुलनेत शिखर उंची, रु. 3,162 असा व्यवहार केला.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>या दोघांमधील खरा फरक म्हणजे बुलसीची रुंदी. फुलपाखरू सर्वात जास्त पैसे देते परंतु केवळ एका अचूक स्ट्राइकवर, 24,150. कंडोर कमी पैसे देते परंतु स्ट्राइकच्या छोट्या बँडमध्ये, 24,100 ते 24,200. जेव्हा तुमच्याकडे रफ टार्गेट झोन असेल तेव्हा कंडोर निवडा, तंतोतंत लँडिंग पॉइंटबद्दल तुमचा विश्वास मजबूत असेल तेव्हा फुलपाखरू निवडा.</p>\n</div></div>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>इथेच प्रामाणिकपणा सर्वात महत्त्वाचा असतो. दोन्ही संरचना जोखमीसाठी चमकदार बक्षीस दर्शवितात, फुलपाखरू 1 ते 53 आणि कंडोर 1 ते 36, परंतु <strong>प्रत्येकावर नफा मिळण्याची शक्यता फक्त 10 टक्के आहे</strong>. हा आकडा ऑप्शन मार्केटमधूनच आला आहे: NIFTY, सुमारे 12.7 टक्के, आणि 32 दिवस शिल्लक असलेली अस्थिरता वापरून, बाजार दहापैकी फक्त एक शक्यता सूचित करतो की निर्देशांक तुमच्या अरुंद विंडोमध्ये वळतो आणि तिथेच राहतो. चार्ट पहा आणि कारण स्पष्ट आहे. अशक्त सिग्मा बँड NIFTY श्रेणी एका महिन्यात प्रवास करणे अपेक्षित आहे, आणि फायदेशीर क्षेत्र त्याच्या आत एक पातळ स्लिव्हर आहे. दहापैकी नऊ वेळा NIFTY खिडकीच्या बाहेर पूर्ण होते आणि तुम्ही तुमचे छोटे डेबिट गमावता. दहापैकी एक वेळा ते झोनमध्ये येते आणि तुम्ही त्यातील एक गुणाकार गोळा करता.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>1 ते 53 रिवॉर्ड स्वतः जोखीम घेण्यासाठी कधीही वाचू नका. नेहमी त्याच्या बाजूला बसलेल्या नफ्याच्या 10 टक्के संभाव्यतेसह ते जोडा. सर्वात संभाव्य एकल परिणाम, आतापर्यंत, लहान नुकसान आहे. हे व्यवहार अगदी स्वस्त असतात कारण ते क्वचितच पैसे देतात आणि स्वस्तपणा म्हणजे तुम्हाला शक्यता सांगणारी बाजारपेठ.</p>\n</div></div>\n<h2 id=\"margin-and-what-you-really-tie-up\">मार्जिन, आणि आपण खरोखर काय बांधले</h2>\n<p>येथे एक प्रामाणिक सुरकुत्या आहे जी लहान डेबिट लपवते. तुम्ही गमावू शकणारी रोख रक्कम 88 ते 120 रुपये असली तरी, एक्सचेंज ब्लॉक्सचे मार्जिन खूपच मोठे आहे. <strong>फुलपाखरासाठी 63,628 रुपये आणि कंडोरसाठी 63,757 रुपये</strong>, कारण प्रत्येक संरचनेत विक्री केलेले कॉल लेग असतात जे एक्सपोजरवर मार्जिन केलेले असतात. त्यामुळे तुमची खरी जोखीम क्षुल्लक आहे, परंतु तरीही तुम्ही स्थान धारण करण्यासाठी अर्थपूर्ण भांडवल बांधता.</p>\n<p>हे अंतर तुम्ही परतावा कसा ठरवता याचा आकार बदलतो. बटरफ्लायचे सर्वोत्कृष्ट केस, रु. 6,380 विरुद्ध रु. 63,628 ब्लॉक केलेले भांडवल, सुमारे मार्जिनवर परतावा आहे <strong>10 टक्के</strong> जर ते उत्तम प्रकारे उतरले, आणि कंडोरचे रु. 3,162 विरुद्ध रु. 63,757 <strong>5 टक्के</strong>. ते चांगले रिटर्न आहेत, परंतु लक्षात ठेवा की ते दहापैकी फक्त एकदाच येतात, म्हणूनच ते खात्याच्या एका लहान कोपऱ्यात असतात, लहान किंवा पूर्ण गुंतवणूक केलेल्या खात्यासाठी कधीही कोर होल्डिंग नाही.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>घन नारंगी ॲट-एक्सपायरी रेषेच्या विरूद्ध निळ्या डॅश केलेल्या T+0 रेषा पहा. आज निळी रेषा एक सौम्य, गोलाकार कुबड आहे; केवळ कालबाह्य झाल्यावर केशरी रेषा उंच तंबूमध्ये तीक्ष्ण होते. हा फरक म्हणजे वेळेचे मूल्य, आणि या संरचनांसाठी वेळ एका विशिष्ट मार्गाने शांत मित्र आहे. जर NIFTY आधीच तुमच्या टार्गेटच्या जवळ बसला असेल तर एक्सपायरी जवळ येत असेल, तर सेल बॉडी कॉल्स त्यांच्या उर्वरित वेळेचे मूल्य कमी करतात आणि पोझिशन फर्म त्याच्या शिखराकडे जाते. NIFTY लक्ष्याजवळ कुठेही नसल्यास, वेळ फक्त लहान डेबिट कालबाह्य होऊ देतो, ज्यासाठी तुम्हाला जवळजवळ काहीही लागत नाही. जेव्हा किंमत बुलसीवर असते तेव्हाच क्षय आपल्यासाठी कार्य करते.</p>\n<h2 id=\"butterfly-or-condor-and-when-to-use-either\">बटरफ्लाय किंवा कंडोर आणि एकतर कधी वापरायचे</h2>\n<p>हे दोन भिन्न रुंदींवर सेट केलेले समान साधन आहेत, म्हणून निवड ही आपण लँडिंगच्या जागेबद्दल किती खात्रीपूर्वक आहात याबद्दल आहे.</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>बुलिश फुलपाखरू</th>\n<th>बुलिश कंडर</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>निव्वळ डेबिट आणि कमाल तोटा</td>\n<td>120 रु</td>\n<td>रु 88</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>6,380 रु</td>\n<td>3,162 रु</td>\n</tr>\n<tr>\n<td>जोखमीसाठी बक्षीस</td>\n<td>1 ते 53</td>\n<td>1 ते 36</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>सुमारे 10 टक्के</td>\n<td>सुमारे 10 टक्के</td>\n</tr>\n<tr>\n<td>सर्वोत्तम तेव्हा</td>\n<td>तुमच्याकडे एकच अचूक लक्ष्य आहे</td>\n<td>तुमच्याकडे एक लहान लक्ष्य क्षेत्र आहे</td>\n</tr>\n</tbody></table>\n<p>जेव्हा तुम्ही स्पष्ट लक्ष्य किंमत आणि स्पष्ट कालबाह्यता ठेवता तेव्हाच एकतर मिळवा, उदाहरणार्थ तुम्हीNIFTY′ सुमारे 24,150 पर्यंत पीसण्याची आणि महिन्याच्या शेवटी थांबण्याची अपेक्षा करता. शरीराला त्या लक्ष्यावर ठेवा, भागीदारी लहान ठेवा कारण शक्यता तुमच्या विरुद्ध आहे आणि दुर्मिळ मोठ्या मोबदल्याला योजनेऐवजी बोनस म्हणून हाताळा. तुमच्याकडे कोणतेही अचूक लक्ष्य नसल्यास, पूर्वीच्या अध्यायांमधून एक परिभाषित-जोखीम पसरवणे हे अधिक चांगले आणि अधिक विश्वासार्ह तेजीचे साधन आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>एकाकीपणात धोका पत्करण्यासाठी 1 ते 53 पुरस्काराने मोहात पडू नका. नफ्याची संभाव्यता फक्त 10 टक्के आहे, त्यामुळे मोठ्या फरकाने सर्वात संभाव्य परिणाम म्हणजे NIFTY विंडो चुकते आणि तुम्ही लहान डेबिट गमावाल. हे बेट स्वस्त आहेत कारण ते क्वचितच पैसे देतात. त्यांना अधूनमधून, कमी-स्टेक पंट्स म्हणून त्याच्या अचूक दृष्टीने समजा, पैसे कमाण्याचा विश्वासार्ह मार्ग म्हणून कधीही म्हणून घ्या आणि त्यांना आकार द्या जेणेकरुन लहान नुकसानाची स्ट्रिंग कधीही महत्त्वाची नाही.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>एक तेजस्वी फुलपाखरू एक लोअर कॉल विकत घेते, दोन बॉडी कॉल विकते आणि एक उच्च कॉल खरेदी करते, हे सर्व एका छोट्यासाठी <strong>सुमारे 120 रुपये निव्वळ डेबिट</strong>, जे संपूर्ण कमाल नुकसान आहे.</li>\n<li>एक बुलिश कंडर शरीराला दोन विकल्या गेलेल्या स्ट्राइकमध्ये पसरवतो <strong>सुमारे 88 रुपये निव्वळ डेबिट</strong>, एकल शिखर एका लहान पठारात बदलत आहे.</li>\n<li>जास्तीत जास्त नफा शरीरावर किंवा पठारावर उतरतो, <strong>फुलपाखरासाठी ६,३८० रुपये आणि कंडोरसाठी ३,१६२ रुपये</strong>, 1 ते 53 आणि 1 ते 36 च्या जोखमीसाठी नेत्रदीपक बक्षीस दिले.</li>\n<li>द <strong>नफा मिळण्याची शक्यता फक्त 10 टक्के आहे</strong> प्रत्येकावर, कारण NIFTY एका अरुंद खिडकीत संपले पाहिजे; स्वस्तपणा म्हणजे त्या दीर्घ शक्यतांची बाजारातील किंमत.</li>\n<li>रोख तोटा लहान असला तरी, द <strong>ब्लॉक केलेले मार्जिन सुमारे 63,000 रुपये आहे</strong> विकलेल्या पायांमुळे प्रत्येकावर, त्यामुळे हे दहापैकी एका मोबदल्यासाठी वास्तविक भांडवल बांधतात.</li>\n<li>तुमच्याजवळ अचूक टार्गेट आणि स्पष्ट एक्सपायरी असताना त्यांचा वापर करा, स्टेक लहान ठेवा आणि उत्पन्न रणनीतीसाठी कधीही स्वस्त लांब शॉट चुकवू नका.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"तेजस्वी फुलपाखरू, रुपयाने रुपया","id":"the-bullish-butterfly-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"तेजीचा कंडर, रुपयाने रुपया","id":"the-bullish-condor-rupee-by-rupee"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"मार्जिन, आणि आपण खरोखर काय बांधले","id":"margin-and-what-you-really-tie-up"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"बटरफ्लाय किंवा कंडोर आणि एकतर कधी वापरायचे","id":"butterfly-or-condor-and-when-to-use-either"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"8":{"html":"<p>तुम्ही सात अध्याय तेजीत घालवले आहेत. आता दुर्बीण फिरवा. 24,056 वर चित्रNIFTY′ आणि कल्पना करा की तुम्हाला वाटते की ते थकले आहे, की पुढचा महिना कमी होईल, कदाचित 23,500 च्या दिशेने. त्या दृश्यावर कृती करण्याचे दोन शुद्ध सिंगल-लेग मार्ग आहेत, आणि ते त्याच बाजीच्या विरुद्ध बाजूंना बसतात. आपण करू शकता <strong>एक पुट खरेदी करा</strong>, NIFTY कमी झाल्यामुळे नफ्याच्या अधिकारासाठी प्रीमियम भरणे. किंवा तुम्ही करू शकता <strong>एक कॉल विक्री</strong>, प्रीमियम गोळा करणे आणि सट्टा लावणे की NIFTY चढत नाही. तुम्ही पूर्वी भेटलेल्या लाँग कॉल आणि शॉर्ट पुटचे हे अचूक मंदीचे मिरर आहेत. एक नवशिक्या करू शकणारा सर्वात स्वच्छ, सुरक्षित मंदीचा व्यापार आहे. या संपूर्ण अभ्यासक्रमातील सर्वात धोकादायक पदांपैकी दुसरी आहे. हा धडा 26 जून 2026 रोजी कॅप्चर केलेल्या वास्तविकNIFTY′ डेटावर दोन्ही बाजूने शिकवतो आणि कोणता आहे याबद्दल स्पष्ट आहे.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>लांब ठेवले</strong> NIFTY एका निश्चित स्ट्राइकवर विकण्याचा अधिकार विकत घेतो, त्यामुळे निर्देशांक जितका अधिक घसरतो तितका तो अधिक मौल्यवान होतो. तुम्ही प्रीमियम भरता, तो प्रीमियम तुम्ही सर्वाधिक गमावू शकता आणि तुमचा नफा वाढतो कारण NIFTY स्ट्राइकच्या खाली घसरतो. ए <strong>लहान कॉल</strong> उलट व्यापार आहे: तुम्ही स्ट्राइकवर NIFTY विकत घेण्याचा अधिकार दुसऱ्याला विकता, आज प्रीमियम गोळा करा आणि जोपर्यंत निर्देशांक त्या स्ट्राइकच्या पुढे वाढू शकत नाही तोपर्यंत तो ठेवा. पुट खरेदीदार खूप पाठलाग करण्यासाठी थोडा धोका पत्करतो. पुष्कळ उघड करताना कॉलचा विक्रेता थोडासा गोळा करतो.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>लाँग पुट घसरणीपासून नफा मिळवण्याच्या अधिकारासाठी प्रीमियम भरतो, प्रीमियममध्ये तोटा मर्यादित असतो. जर बाजार वाढला नाही तर एक लहान कॉल प्रीमियम गोळा करतो आणि नफा मिळवतो, परंतु तोट्याची कमाल मर्यादा नसते. एक परिभाषित-जोखीम आणि नवशिक्या-सुरक्षित आहे; दुसरा नग्न आणि धोकादायक आहे. ते व्यापाराच्या विरुद्ध बाजूंनी समान मंदीचे मत व्यक्त करतात.</p>\n</div></div>\n<h2 id=\"the-long-put-rupee-by-rupee\">लाँग पुट, रुपयाने रुपया</h2>\n<p>28 जुलै 2026 रोजी एक्स्पायर होणारे 24,050 पुट तुम्ही एट-द-मनी खरेदी करा. हे एकच पाय आहे, त्यामुळे तुम्ही भरलेला प्रीमियम ही संपूर्ण कथा आहे.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td><strong>19,182 रु</strong></td>\n</tr>\n</tbody></table>\n<p>295.1 प्रति शेअरचा प्रीमियम आहे <strong>19,182 रु</strong> 65 च्या एका लॉटसाठी, आणि ते डेबिट तुम्ही खरेदी करताच बाजारात उतरते. कारण तुमच्याकडे कधीही एक रुपया जास्त मागितला जाऊ शकत नाही, डेबिट हा देखील जास्तीत जास्त तोटा आहे, ज्यामुळे लाँग पुट एक परिभाषित-जोखीम व्यापार होतो. एक्सचेंज ब्लॉक्सचे मार्जिन म्हणजे फक्त प्रीमियम स्वतःच आहे, रु. 19,182, आणि त्यापलीकडे काहीही नाही.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-put.png\" alt=\"लाँग पुट पेऑफ: 24,050 स्ट्राइकच्या वर रु. 19,182 चा सपाट तोटा, 23,755 वर ब्रेकईव्हन, आणिNIFTY′ घसरत असताना नफ्याची रेषा, ओए 26X0′ घसरत असताना, अस्पष्ट सिग्मा बँड्स हे दर्शविते की ऑप्शन मार्केटची किंमत किती आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>लाँग पुट पेऑफ: 24,050 स्ट्राइकच्या वर रु. 19,182 चा सपाट तोटा, 23,755 वर ब्रेकईव्हन आणिNIFTY′ घसरत असताना नफ्याची रेषा, ओए 28X0′ घसरत असताना, फिकट सिग्मा बँड्स हे दर्शविते की ऑप्शन मार्केटची किंमत किती आहे.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p><strong>कमाल तोटा रु. 19,182 आहे, तुम्ही भरलेला प्रीमियम.</strong> जर पुट एक्सपायरीच्या वेळी 24,050 वर किंवा त्याहून अधिक बंद झाला तरच तुम्ही ते पूर्णपणे जप्त कराल, जेथे पुट निरर्थक आहे.</p>\n<p><strong>कमाल नफा रु 1,544,068, सैद्धांतिक मर्यादा आहे.</strong> जर NIFTY शून्यावर आले तर, 24,050 पुट 24,050 गुणांचे असेल, म्हणजे 24,050 गुणिले 65, जे 1,563,250 रुपये आहे आणि प्रीमियम वजा केल्यावर तुम्ही 1,544,068 रुपये क्लिअर कराल. NIFTY कधीही शून्यावर पोहोचणार नाही, म्हणून ही संख्या \"अस्सल घसरणीवर खूप मोठी\" साठी लेबल म्हणून वाचा, लक्ष्य नाही.</p>\n<p><strong>ब्रेकइव्हन 23,755 आहे, स्ट्राइक वजा प्रीमियम प्रति शेअर.</strong> तुम्ही शेअरसाठी 295 पॉइंट दिले आहेत, त्यामुळे पुट तुमच्या खिशात पैसे टाकणे सुरू होण्यापूर्वी NIFTY 24,050 स्ट्राइकच्या खाली 23,755 वर 295 बंद करणे आवश्यक आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>प्रीमियम भरला</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>स्ट्राइक पॉइंट्सच्या गुणाकार, वजा प्रीमियम</td>\n<td>24,050 गुणिले 65, जे रुपये 1,563,250, उणे रुपये 19,182, 1,544,068 रुपये</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>प्रति शेअर वजा प्रीमियम</td>\n<td>24,050 वजा 295 बरोबर 23,755</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-long-put-to-expiry\">एक्सपायरी करण्यासाठी लांब ठेवले चालणे</h2>\n<p>पाच बंद स्तरांवर पुट सेटल करा आणि क्लाइंबिंग पेऑफ दिसून येईल. पुट 24,050 च्या खाली जे काही संपेल ते मूल्य आहे आणि जर NIFTY त्याच्या वर असेल तर काहीही नाही.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 ला तुम्ही विकत घेतले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,200</td>\n<td>मूल्य 0</td>\n<td>उणे रु 19,182 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>उणे रु 19,182 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>23,755</td>\n<td>295 किमतीची</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>23,500</td>\n<td>550 किमतीची</td>\n<td>अधिक रु. 16,568</td>\n</tr>\n<tr>\n<td>23,000</td>\n<td>1,050 किमतीची</td>\n<td>अधिक रु 49,068</td>\n</tr>\n</tbody></table>\n<p>स्ट्राइकच्या वर तुम्ही फ्लॅट कमाल तोटा, प्रीमियम आणि आणखी काही नाही. 23,755 ब्रेकइव्हनवर तुम्ही जे भरले होते ते पुटने वसूल केले आहे. त्याखाली, प्रत्येक पॉइंट NIFTY फॉल्स तुमच्या नफ्यात 65 रुपये जोडतो आणि ते कठीण NIFTY थेंब चढत राहते. जोखीम घेण्याचे बक्षीस एक नेत्रदीपक 1 ते 80 वाचते, परंतु ते एक लहान, विशिष्ट जोखीम मोठ्या, अत्यंत संभव नसलेल्या बक्षीसाच्या विरूद्ध जोडते. तुम्हाला ग्राउंड ठेवणारी प्रामाणिक संख्या आहे <strong>नफा संभाव्यता, सुमारे 38 टक्के</strong>: बहुतेक महिने NIFTY पुरेशी पडत नाही, आणि पुट शांतपणे कुजतो.</p>\n<h2 id=\"the-short-call-rupee-by-rupee\">लहान कॉल, रुपयाने रुपया</h2>\n<p>आता दुसरी बाजू. घसरणीतून नफा मिळवण्यासाठी पुट विकत घेण्याऐवजी, तुम्ही <strong>24,050 कॉल विक्री करा</strong> आणि तुम्ही ट्रेड उघडताच त्याचा प्रीमियम गोळा करा.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल विक्री</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td><strong>अधिक रु 27,677 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही आत घ्या <strong>रु 27,677</strong> भरपूर साठी, आणि ते क्रेडिट तुम्ही कधीही बनवू शकता. NIFTY 24,050 वर किंवा खाली बंद झाल्यास तुम्ही ते सर्व ठेवाल, जेथे तुम्ही विकलेला कॉल कालबाह्य होईल. द <strong>breakeven 24,476 आहे</strong>, स्ट्राइक अधिक 426 पॉइंट्स एक शेअर, आणि द <strong>नफ्याची संभाव्यता आरामदायक 69 टक्के आहे</strong>, कारण NIFTY ला फक्त त्या ब्रेकईव्हनच्या पुढे जाणे टाळायचे आहे. तो उच्च विजय दर प्रलोभन आहे. येथे श्रेय लपवतो पकडणे आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>एका शॉर्ट कॉलमध्ये कमाल नफा रु. 27,677 आणि कमाल तोटा UNLIMITED आहे. तुम्ही एक अनकव्हर्ड कॉल विकला आहे, त्यामुळे कोणतीही कमाल मर्यादा नसताना एका तीव्र रॅलीसाठी तुम्हाला ब्रेकइव्हनच्या वर रुपयासाठी रुपये मोजावे लागतात. एक्सचेंजला हे माहित आहे, म्हणूनच ते सुमारे रु. 177,541 चे मार्जिन ब्लॉक करते, तुम्ही जमा केलेल्या क्रेडिटच्या जवळपास सात पट. हा एक नग्न शॉर्ट आहे आणि एकच अंतर एका सकाळी अनेक विजयी ट्रेड मिटवू शकतो. नवशिक्याने मुख्यतः त्याचा आदर करण्यासाठी ते समजून घेतले पाहिजे.</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-call.png\" alt=\"शॉर्ट कॉल पेऑफ: 24,050 स्ट्राइकच्या खाली रु. 27,677 चा सपाट नफा, 24,476 वर ब्रेकईव्हन आणि NIFTY वाढल्याने मर्यादेशिवाय कमी होणारी तोटा, लांब कॉलची अचूक उलटी प्रतिमा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>शॉर्ट कॉल पेऑफ: 24,050 स्ट्राइकच्या खाली रु. 27,677 चा सपाट नफा, 24,476 वर ब्रेकवेन आणि NIFTY वाढल्याने मर्यादेशिवाय कमी होणारी तोटा, लांब कॉलची अचूक उलटी प्रतिमा.</figcaption></figure>\n<h2 id=\"walking-the-short-call-to-expiry\">कालबाह्य होण्यासाठी शॉर्ट कॉल चालणे</h2>\n<p>पाच स्तरांवर शॉर्ट कॉल सेटल करा आणि तळहीन शेपूट उघडून पहा. तुम्ही विकलेल्या कॉलचे मूल्य 24,050 पेक्षा जास्त असेल आणि ते मूल्य तुमच्याकडे आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 27,677 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 27,677 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,476</td>\n<td>426 थकबाकी आहे</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,700</td>\n<td>650 थकबाकी आहे</td>\n<td>उणे रु. 14,573</td>\n</tr>\n<tr>\n<td>25,000</td>\n<td>950 थकबाकी आहे</td>\n<td>उणे रु. 34,073</td>\n</tr>\n</tbody></table>\n<p>स्ट्राइकच्या खाली तुम्ही तुमच्या फ्लॅट कमाल नफ्यावर रु. 27,677 बसता. 24,476 ब्रेकईव्हन ओलांडून रेषा तोट्यात जाते आणि तिथून ती कायमची घसरत राहते. टेबलमध्ये कोणताही मजला नाही कारण प्रत्यक्षात कोणताही मजला नाही: 25,000 वर तुम्ही 34,073 रुपये खाली आहात, 25,500 वर खूप जास्त आहे, आणि तोटा प्रत्येक पॉईंटNIFTY′ वर चढत असताना वाढतो. असा अर्थ अमर्यादित आहे.</p>\n<h2 id=\"your-odds-side-by-side\">आपल्या शक्यता, बाजूला</h2>\n<p>दोन व्यवहार खरेदीदार विरुद्ध विक्रेता सौदाच्या विरुद्ध टोकाला बसतात आणि त्यांच्या शक्यता स्पष्टपणे सांगतात.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>लांब ठेवले</th>\n<th>शॉर्ट कॉल</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>रु 1,544,068</td>\n<td>रु 27,677</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>19,182 रु</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>23,755</td>\n<td>24,476</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>38 टक्के</td>\n<td>६९ टक्के</td>\n</tr>\n<tr>\n<td>जोखमीसाठी बक्षीस</td>\n<td>1 ते 80</td>\n<td>NA</td>\n</tr>\n<tr>\n<td>निव्वळ क्रेडिट किंवा डेबिट</td>\n<td>डेबिट रु. 19,182</td>\n<td>क्रेडिट रु 27,677</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>19,182 रु</td>\n<td>रु. 177,541</td>\n</tr>\n</tbody></table>\n<p>लाँग पुटमध्ये नफा मिळण्याची शक्यता कमी असते परंतु ज्ञात, माफक खर्च आणि जर NIFTY खरोखरच घसरला तर एक मोठा वरचा भाग असतो. शॉर्ट कॉलमध्ये फायद्याची उच्च संभाव्यता असते परंतु मोठ्या फरकाने होल्ड करण्याची मागणी करून मर्यादेशिवाय पळून जाणाऱ्या नुकसानाविरुद्ध मर्यादित बक्षीस असते. एखाद्याचा खूप पाठलाग करण्यासाठी थोडासा धोका असतो. दुसरा खूप काही उघड करताना थोडे गोळा करतो.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>जास्तीत जास्त तोट्याच्या पुढे नफ्याची संभाव्यता नेहमी वाचा, स्वतःहून कधीही नाही. शॉर्ट कॉलचे 69 टक्के लाँग पुटच्या 38 टक्क्यांपेक्षा चांगले दिसते, तरीही ते अमर्यादित नुकसान आणि रु. 177,541 मार्जिन ब्लॉकच्या बाजूला बसते, तर पुटची सर्वात वाईट स्थिती तिकिटावर छापलेले रु. 19,182 आहे. उच्च विजयाचा दर अनकॅप्ड लॉससह जोडलेला आहे की शिस्तबद्ध खाती एकाच सकाळी कशी पुसली जातात.</p>\n</div></div>\n<h2 id=\"margin-and-return\">मार्जिन आणि परतावा</h2>\n<p>भांडवलावर दोन्ही बाजू अधिक भिन्न दिसू शकत नाहीत. लाँग पुट फक्त स्वतःचा प्रीमियम ब्लॉक करतो, <strong>19,182 रु</strong>, कारण तुम्ही भरलेल्या रकमेपेक्षा जास्त तोटा करू शकत नाही, त्यामुळे मार्जिन जास्तीत जास्त तोट्याइतकेच आहे. लहान कॉल अवरोध <strong>रु. 177,541</strong> SPAN अधिक एक्सपोजर, कारण एक्सचेंजने ओपन-एंडेड नुकसान कव्हर केले पाहिजे. त्या ब्लॉकच्या विरूद्ध मोजले तर, शॉर्ट कॉलचा सर्वात चांगला रु. 27,677 हा सुमारे मार्जिनवर परतावा आहे <strong>16 टक्के</strong>, जोपर्यंत तुम्हाला जुळणारी जोखीम अमर्याद आहे हे लक्षात येईपर्यंत आकर्षक वाटते. पुट फारच कमी आहे, परंतु खरेदीदार म्हणून तुम्हाला कोट करण्यासाठी मार्जिनवर परतावा मिळत नाही, मोठ्या संभाव्य रिवॉर्डच्या विरोधात केवळ प्रीमियमचा धोका असतो.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>वेळ दोन व्यापारांना विरुद्ध दिशेने खेचते आणि निळ्या रंगाची T+0 रेषा ती दर्शवते. लाँग पुटवर, निळी रेषा नारंगी ॲट-एक्सपायरी रेषेच्या वर बसते, म्हणजे आजच्या स्थितीत वेळेचे मूल्य आहे जे कालबाह्यता जवळ आल्यावर रक्तस्त्राव होतो. प्रत्येक शांत दिवसासाठी खरेदीदाराला थोडासा खर्च येतो, त्यामुळे दीर्घ पुट घड्याळाशी लढा देतो आणि प्रीमियम कमी होण्याआधी NIFTY आवश्यक आहे. शॉर्ट कॉलवर, नफ्याच्या बाजूने निळी रेषा केशरी रेषेच्या खाली बसते, कारण तुम्ही विकलेले वेळेचे मूल्य अद्याप तुमच्या बाजूने कमी झालेले नाही. प्रत्येक शांत दिवस विक्रेत्याला शिखराकडे खेचतो. क्षय हा खरेदीदाराचा शत्रू आणि विक्रेत्याचा मित्र आहे, म्हणूनच धोकादायक व्यापार देखील मोहक आहे.</p>\n<h2 id=\"which-one-a-beginner-should-reach-for\">ज्यासाठी नवशिक्याने पोहोचले पाहिजे</h2>\n<p>जर तुमचे प्रामाणिक मत असे आहे की NIFTY पडतो, तर पोहोचा <strong>लांब ठेवले</strong>. तुमची सर्वात वाईट केस तुम्ही ऑर्डर देण्यापूर्वी तिकीटावर छापली जाते, रु. 19,182 आणि एक रुपया जास्त नाही आणि मार्जिन त्याच लहान आकड्याइतके आहे. तुम्ही चुकीचे असू शकता, प्रीमियम गमावू शकता आणि तुमचे खाते अबाधित ठेवू शकता. शिकणाऱ्याने नेमकी अशीच जोखीम घ्यावी.</p>\n<p>द <strong>लहान कॉल</strong> हे व्यावसायिकांचे साधन आहे, नवशिक्याचे नाही. 69 टक्के विजयाचा दर त्याची प्रशंसा करतो, परंतु तो अमर्यादित नुकसान आणि मोठ्या फरकाच्या ब्लॉकच्या विरूद्ध एक लहान, मर्यादित बक्षीस जोडतो. अनुभवी व्यापाऱ्यांनी संरक्षण म्हणून स्वस्त, उच्च कॉल विकत घेण्याचा मार्ग आहे, जो नग्न शॉर्टला परिभाषित-जोखीम अस्वल कॉल स्प्रेडमध्ये रूपांतरित करतो, पुढील प्रकरणाचा विषय. तो एकल विकत घेतलेला विंग \"अमर्यादित\" ज्ञात संख्येमध्ये बदलतो. तुम्ही सँडबॉक्स ट्रेडिंगमध्ये दोन्ही ट्रेड्सची पूर्वाभ्यास करू शकता ( OpenAlgo मध्ये विश्लेषक मोड), प्रत्येक एक पाय ठेवून आणि तुम्ही मॉडेल केलेल्या किमतीला धक्का देताना नारिंगी रेषा तिरपा पहा.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>घसरणीपासून नफा मिळवण्याच्या अधिकारासाठी दीर्घ पुट प्रीमियम भरतो; द <strong>प्रीमियम, रु. 19,182, संपूर्ण कमाल तोटा आहे</strong>, आणि समास त्याच्या बरोबरीचे आहे.</li>\n<li>लाँग पुटचे ब्रेकईव्हन आहे <strong>स्ट्राइक वजा प्रीमियम, 23,755</strong>, आणि त्याची नफ्याची संभाव्यता सुमारे 38 टक्के आहे, म्हणून त्याला देय देण्यासाठी वास्तविक घट आवश्यक आहे.</li>\n<li>एक लहान कॉल गोळा a <strong>रु. 27,677 चे कमाल नफा म्हणून क्रेडिट</strong> आणि NIFTY स्ट्राइकवर किंवा खाली राहिल्यास, 69 टक्के लाभाच्या संभाव्यतेसह ते ठेवते.</li>\n<li>लहान कॉल एक वाहून <strong>UNLIMITED तोटा</strong> आणि बद्दल ब्लॉक <strong>रु. 177,541</strong> फरकाने; एकच अंतर अनेक विजयी व्यापार पूर्ववत करू शकतो.</li>\n<li>वेळेचा क्षय हा लांबचा शत्रू आणि लहान कॉलचा मित्र आहे, म्हणूनच धोकादायक व्यापार देखील मोहक आहे.</li>\n<li>तुम्ही अजूनही शिकत असताना, कॉल विकण्याऐवजी पुट विकत घ्या: तुम्ही उच्च विजयाचा दर सोडता परंतु निश्चित, टिकून राहण्यायोग्य सर्वात वाईट स्थिती मिळवता.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"लाँग पुट, रुपयाने रुपया","id":"the-long-put-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी करण्यासाठी लांब ठेवले चालणे","id":"walking-the-long-put-to-expiry"},{"level":2,"text":"लहान कॉल, रुपयाने रुपया","id":"the-short-call-rupee-by-rupee"},{"level":2,"text":"कालबाह्य होण्यासाठी शॉर्ट कॉल चालणे","id":"walking-the-short-call-to-expiry"},{"level":2,"text":"आपल्या शक्यता, बाजूला","id":"your-odds-side-by-side"},{"level":2,"text":"मार्जिन आणि परतावा","id":"margin-and-return"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"ज्यासाठी नवशिक्याने पोहोचले पाहिजे","id":"which-one-a-beginner-should-reach-for"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"9":{"html":"<p>शेवटच्या प्रकरणाने तुम्हाला एक समस्या सोडवली आहे. शॉर्ट कॉल हा एक आकर्षक मंदीचा व्यापार आहे, नफ्याची 69 टक्के शक्यता आणि एक फॅट क्रेडिट आहे, परंतु यात अमर्यादित तोटा आहे आणि रु. 177,541 मार्जिन ब्लॉकची मागणी आहे. घराचा सट्टा न लावता तुम्हाला मंदीचे वातावरण हवे होते. द <strong>अस्वल कॉल पसरला</strong> उत्तर आहे. हे विकले गेलेला कॉल ठेवते जे तुम्हाला NIFTY शांत राहते किंवा पडते तेव्हा तुम्हाला पैसे देते आणि ते एक सेकंद जोडते, थोड्या जास्त वर विकत घेतलेला स्वस्त कॉल जो ज्ञात नंबरवर आपत्ती कॅप करतो. तुम्ही तुमच्या तोट्यावर कठोर कमाल मर्यादेच्या बदल्यात क्रेडिटचा एक तुकडा परत देता. तुम्हाला आधी भेटलेल्या बुल पुट स्प्रेडचा हा मंदीचा क्रेडिट-स्प्रेड चुलत भाऊ आहे: समान परिभाषित-जोखीम, क्रेडिट-संकलन आकार, फक्त कॉल्समधून तयार केलेला आणि जेव्हा बाजार वाढू शकत नाही तेव्हा नफ्याकडे झुकलेला. एका नवशिक्यासाठी ज्याला मंदीच्या दृश्यावर प्रीमियम गोळा करायचा आहे, हा असा ट्रेड आहे जो नेकेड शॉर्टमध्ये असायला हवा होता.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>अस्वल कॉल पसरला</strong> एकाच कालबाह्यतेवर दोन कॉल पर्याय आहेत. आपण <strong>लोअर-स्ट्राइक कॉल विक्री करा</strong> फॅट प्रीमियम गोळा करण्यासाठी, जो पाय तुम्हाला पैसे देतो जर NIFTY स्ट्राइकवर किंवा खाली राहिल्यास, आणि तुम्ही <strong>उच्च-स्ट्राइक कॉल खरेदी करा</strong> वास्तविक रॅली विरुद्ध स्वस्त विमा म्हणून. तुम्ही फरक निव्वळ क्रेडिट म्हणून ठेवता आणि ते क्रेडिट तुम्ही सर्वात जास्त मिळवू शकता. विकत घेतलेल्या कॉल कॅप्समुळे विकले गेलेले कॉल तुम्हाला किती हानी पोहोचवू शकतात, तुम्ही सर्वात जास्त गमावू शकता हे तुम्ही कधीही बटण क्लिक करण्यापूर्वी निश्चित केले आहे आणि ज्ञात आहे.</p>\n<p>तुमचा दृष्टिकोन असेल तेव्हा तुम्ही ते वापरता <strong>मध्यम मंदीचा ते तटस्थ</strong>, म्हणजे तुम्हाला वाटते की NIFTY पडेल, सपाट राहील, किंवा सर्वात वाईट स्थितीत फक्त थोडेसे वाढेल. तुम्हाला क्रॅशची गरज नाही. कठीण चढाई टाळण्यासाठी तुम्हाला फक्त NIFTY आवश्यक आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बेअर कॉल स्प्रेड कमी कॉल विकतो आणि निव्वळ क्रेडिटसाठी उच्च कॉल खरेदी करतो. तुमच्या खालच्या स्ट्राइकवर किंवा खाली राहिल्यास तुम्हाला नफा होतो, तुमच्या उच्च स्ट्राइकच्या पुढे तो वाढला तरच तुम्हाला तोटा होतो आणि नफा आणि तोटा दोन्ही मर्यादित केले जातात. बाजारात तेजी येणार नाही ही पैज आहे, पडेल अशी पैज नाही.</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">खरा व्यापार, रुपयाने रुपया</h2>\n<p>26 जून 2026 रोजी 24,056 इंडेक्ससह कॅप्चर केलेला वास्तविक NIFTY किमतींवरील तंतोतंत व्यापार येथे आहे आणि 28 जुलै 2026 ची मुदत जवळपास 32 दिवसांवर आहे. आम्ही 24,050 कॉल एट-द-मनी विकतो आणि वरील 24,150 कॉल वन स्ट्राइक विकत घेतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल विक्री</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td>अधिक रु 27,677 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल खरेदी करा</td>\n<td>24,150</td>\n<td>370.1 भरले</td>\n<td>24,057 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु. 3,624 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>24,050 कॉलसाठी तुम्हाला मिळणारा प्रीमियम तुम्ही 24,150 कॉलसाठी भरलेल्या प्रीमियमपेक्षा मोठा आहे, कारण खालच्या स्ट्राइकची किंमत जास्त आहे. ते अंतर तुमचे आहे <strong>सुमारे 3,624 रुपये निव्वळ क्रेडिट</strong>, आणि तुम्ही व्यापार उघडताच ते तुमच्या खात्यात येते. म्हणूनच बेअर कॉल स्प्रेडला क्रेडिट स्प्रेड म्हणतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bear-call-spread.png\" alt=\"NIFTY बेअर कॉल स्प्रेड: 24,050 च्या खाली 3,624 रुपयांची सपाट नफा कमाल मर्यादा, 24,106 वर ब्रेकइव्हन आणि 24,150 च्या वर 2,876 रुपयांचा मर्यादित तोटा, नारंगी एक्सपायरी लाइनच्या खाली बसलेल्या निळ्या डॅश T+0 लाईनसह, कारण विक्रीची वेळ संपली आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY बेअर कॉल स्प्रेड: 24,050 च्या खाली 3,624 रुपयांची सपाट नफा कमाल मर्यादा, 24,106 वर ब्रेकइव्हन आणि 24,150 च्या वर 2,876 रुपयांचा मर्यादित तोटा, नारंगी एक्सपायरी लाईनच्या खाली बसलेल्या निळ्या डॅश T+0 लाईनसह, कारण विक्रीची वेळ संपली आहे.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p>प्रत्येक क्रमांक वरील ट्रेडमधून सरळ येतो, लक्षात ठेवण्याची आवश्यकता नाही.</p>\n<p><strong>कमाल नफा निव्वळ क्रेडिट, रु 3,624 आहे.</strong> NIFTY 24,050 स्ट्राइकवर किंवा त्यापेक्षा कमी असल्यास, दोन्ही कॉल निरुपयोगी कालबाह्य होतात, जेव्हा निर्देशांक स्ट्राइकच्या खाली असतो तेव्हा कोणीही कॉल करत नाही, तुमच्याकडे काहीही देणे नाही आणि तुम्ही संपूर्ण क्रेडिट ठेवता.</p>\n<p><strong>जास्तीत जास्त नुकसान स्प्रेड वजा क्रेडिट, रु 2,876 आहे.</strong> स्प्रेड म्हणजे दोन स्ट्राइकमधील अंतर, 100 गुण, 100 गुणिले 65, जे 6,500 रुपये आहे. जर NIFTY 24,150 च्या वर रॅली करत असेल, तर दोन्ही कॉल पैशांमध्ये असतील आणि पूर्ण 100-पॉइंट गॅप तुमच्या विरूद्ध लॉक केले जाईल. तुम्ही ते 6,500 रुपये गमावले, परंतु तुम्ही आधीच 3,624 रुपये खिशात टाकले आहेत, त्यामुळे तुमचे खरे नुकसान 6,500 उणे 3,624 आहे, जे आहे <strong>रु. 2,876</strong>. विकत घेतलेला कॉल हा पूर्वीचा तोटा थांबवतो.</p>\n<p><strong>ब्रेकईव्हन हा कमी स्ट्राइक आणि प्रति शेअर क्रेडिट, 24,106 आहे.</strong> तुम्ही एका शेअरचे सुमारे 56 पॉइंट क्रेडिट गोळा केले. NIFTY 24,050 स्ट्राइकच्या वर 56 पॉइंट्सने पुढे जाऊ शकते, <strong>24,106</strong>, तुमच्या शॉर्ट कॉलवरील तोटा संपूर्ण क्रेडिट खाण्यापूर्वी.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>निव्वळ क्रेडिट</td>\n<td>3,624 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>स्प्रेड वजा निव्वळ क्रेडिट</td>\n<td>रु. 6,500 वजा रु 3,624 म्हणजे रु. 2,876</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>कमी स्ट्राइक अधिक क्रेडिट प्रति शेअर</td>\n<td>24,050 अधिक 56 बरोबर 24,106</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>पाच बंद किंमतींवर स्प्रेड सेटल करा आणि आकार स्वतःच दिसून येईल. प्रत्येक कॉल त्याच्या स्ट्राइकच्या वर जे काहीNIFTY′ पूर्ण करतो त्याचे मूल्य आहे आणि तुम्ही जे विकले आहे ते तुमच्याकडे आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल तुम्ही विकले</th>\n<th>तुम्ही विकत घेतलेला २४,१५० कॉल</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,624 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,624 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,106</td>\n<td>56 देणे बाकी आहे</td>\n<td>मूल्य 0</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 देणे बाकी आहे</td>\n<td>मूल्य 0</td>\n<td>उणे रु 2,876 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>350 थकबाकी आहे</td>\n<td>250 किमतीची</td>\n<td>उणे रु 2,876 (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>ते पृष्ठ खाली वाचा. 24,050 खाली कोठेही तुम्ही पूर्ण रु. 3,624 गोळा कराल आणि लक्षात घ्या कीNIFTY′ फक्त स्थिर बसले तरी चालते, इतकेच नाही तर ते पडले तरी चालते. 24,150 वरून कुठेही तुम्ही पूर्ण 2,876 रुपये गमावाल. दोन स्ट्राइक दरम्यान निकाल एका शेल्फवरून दुसऱ्या शेल्फवर सरकतो, 24,106 वर शून्य ओलांडतो. खालच्या पंक्तीकडे पहा: 24,400 ला विकलेला कॉल 350 आहे, तर खरेदी केलेला कॉल 250 परत करतो, निव्वळ 100 पॉइंट्स, पूर्ण रुंदी सोडतो, त्यामुळेच तोटा 2,876 रुपयांच्या पुढे कधीच वाढत नाही, कितीही उच्च NIFTY धावला तरीही.</p>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>तुम्ही जिंकू शकता आणि गमावू शकता हे जाणून घेणे ही केवळ अर्धी गोष्ट आहे. व्यापार स्मार्ट आहे की नाही हे ठरवणारा प्रश्न प्रत्येक परिणामाची किती शक्यता आहे. यासाठी पसरले <strong>नफ्याची शक्यता सुमारे 53 टक्के आहे</strong>, नाणे फ्लिप पेक्षा एक स्पर्श चांगला. हा आकडा ऑप्शन मार्केटमधूनच आला आहे: NIFTY, सुमारे 12.7 टक्के, आणि 32 दिवस शिल्लक असलेल्या अस्थिरतेचा वापर करून, बाजार 53 टक्के शक्यता सूचित करतो NIFTY कालबाह्यतेनुसार 24,106 ब्रेकइव्हनच्या खाली पूर्ण होईल. पुन्हा चार्ट पहा. फिकट सिग्मा बँड बाजाराला अपेक्षित असलेली हालचाल दाखवतात आणि 24,106 वर ब्रेकईव्हन जागेच्या अगदी वर बसते, आरामात आतील बँडमध्ये. NIFTY पडण्याची गरज नाही. फक्त खरी रॅली टाळण्याची गरज आहे.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>नेहमी नफ्याच्या संभाव्यतेच्या पुढे जास्तीत जास्त तोटा वाचा, कधीही एकटे राहू नका. हे स्प्रेड रु. 3,624 करण्यासाठी रु. 2,876 जोखीम घेते, म्हणून येथे कॅप्ड रिवॉर्ड प्रत्यक्षात कॅप केलेल्या जोखमीपेक्षा किंचित मोठे आहे, 1 ते 1.26 च्या जोखमीचे बक्षीस आहे आणि शक्यता 53 टक्के आहे. हे संयोजन, एक अनुकूल पेआउट आणि तुमच्या बाजूने असलेल्या वेळेसह अगदी शक्यतांपेक्षाही चांगले, हेच क्रेडिट स्प्रेड ठेवण्यास योग्य बनवते.</p>\n</div></div>\n<h2 id=\"margin\">समास</h2>\n<p>तुम्ही निव्वळ विक्रेते असल्यामुळे, एक्स्चेंज मार्जिनला सुरक्षितता म्हणून ब्लॉक करते, येथे <strong>34,789 रु</strong>, SPAN घटक तसेच एक्सपोजर बफरपासून बनविलेले. विकत घेतलेला 24,150 कॉल हा नंबर लहान ठेवतो. शेवटच्या अध्यायातील नग्न शॉर्ट कॉलने रु. 177,541 बांधले; हा प्रसार, त्याच मंदीच्या स्थितीसह, त्याच्या अंदाजे पाचव्या भागाला ब्लॉक करतो, कारण संरक्षणात्मक शाखा एक्सचेंजसाठी सर्वात वाईट परिस्थिती परिभाषित करते. तो एकच विकत घेतलेला पाय दुहेरी कर्तव्य करतो: तो तुमचा तोटा रु. 2,876 पर्यंत कमी करतो आणि व्यापारासाठी आवश्यक भांडवल कमी करतो.</p>\n<p>ते मार्जिन तुम्हाला मार्जिनवर परताव्याद्वारे प्रामाणिकपणे व्यापाराचा न्याय करू देते. तुम्ही जवळपास एका महिन्यासाठी ब्लॉक केलेल्या रु. 34,789 विरुद्ध रु. 3,624 कमवू शकता, जे अंदाजे आहे <strong>जोखीम असलेल्या भांडवलावर 10 टक्के</strong> व्यापार चालतो तर. ते उत्पन्न, कच्चा क्रेडिट नाही, एक गंभीर व्यापारी कल्पनांमध्ये तुलना करतो.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>नफ्याच्या बाजूला घन नारंगी ॲट-एक्सपायरी रेषेच्या खाली बसलेल्या निळ्या डॅश केलेल्या T+0 रेषेकडे, चार्टकडे आणखी एकदा पहा. हे अंतर हे वेळेचे मूल्य आहे आणि निव्वळ विक्रेत्यासाठी ते एक भेट आहे. प्रत्येक शांत दिवशी तुम्ही ज्या कॉलमध्ये आहात त्यामधील थोडासा प्रीमियम वितळतो आणि निळी रेषा केशरीकडे स्थिर होते. तुम्ही समोर क्रेडिट गोळा केले आहे आणि जोपर्यंत NIFTY वागेल तोपर्यंत वेळ शांतपणे त्याचे वास्तविक नफ्यात रूपांतर करते. एक लांब पर्याय खरेदीदार दररोज या क्षय लढा. क्रेडिट-स्प्रेड विक्रेता म्हणून, तुम्हाला त्याद्वारे पैसे दिले जातात.</p>\n<h2 id=\"bear-call-spread-or-long-put\">अस्वल कॉल स्प्रेड किंवा लांब पुट?</h2>\n<p>तुम्ही लाँग पुट लास्ट चॅप्टर भेटलात, आणि जेव्हा NIFTY पडतो तेव्हा त्याचा फायदा होतो, मग तुम्ही कोणता निवडाल? प्रामाणिक उत्तर असे आहे की ते भिन्न दृश्यांना अनुरूप आहेत. लाँग पुट हा एक डेबिट ट्रेड आहे जो कठोर, जलद घसरणीवर चांगला मोबदला देतो, कारण त्याचा नफा पुढील NIFTY थेंबांवर चढत राहतो. बेअर कॉल स्प्रेड तुमच्या रिवॉर्डला माफक रु. 3,624 क्रेडिटवर मर्यादित ठेवते, जरी NIFTY कितीही दूर गेले तरीही ते तुम्हाला पैसे देते, जरी निर्देशांक फक्त कुठेही गेला नाही, आणि वेळेचा क्षय संपूर्ण वेळ तुमच्या बाजूने काम करतो.</p>\n<p>साठी पोहोचा <strong>अस्वल कॉल पसरला</strong> जेव्हा तुम्हाला वाटते की वरची बाजू संपली आहे परंतु तुम्हाला फटाके कमी होण्याची अपेक्षा नाही आणि तुम्हाला तुमच्या बाजूने वेळ हवा आहे. साठी पोहोचा <strong>लांब ठेवले</strong> जेव्हा तुम्हाला अस्सल, तीव्र घसरण अपेक्षित असते आणि तुम्हाला त्यासोबत मिळणारा मोकळा मोबदला हवा असतो. प्रसार म्हणतो \"रॅली संपली\"; पुट म्हणते \"पतन येत आहे\".</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>परिभाषित जोखीम लहान जोखीम सारखी नसते. रु. 2,876 प्रति लॉट हे खरे पैसे आहेत आणि जर NIFTY 24,150 वर किंवा त्यापेक्षा जास्त बंद झाला तर तुम्ही ते सर्व गमावाल, जे एक मजबूत अप दिवस वितरित करू शकते. नेहमी जास्तीत जास्त नुकसानापर्यंत आकार द्या, कधीही क्रेडिट नाही. निर्देशांक तुमच्या विरोधात वाढल्यास तुम्हाला किती तोटा सहन करावा लागेल ते ठरवा, त्यानंतर किती लॉटला परवानगी मिळेल ते मोजा.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>बेअर कॉल स्प्रेड कमी कॉल विकतो आणि उच्च कॉल खरेदी करतो <strong>निव्वळ क्रेडिट</strong>, NIFTY खालच्या स्ट्राइकवर किंवा खाली राहिल्यास नफा.</li>\n<li><strong>कमाल नफा हे निव्वळ क्रेडिट आहे</strong> (येथे ३,६२४ रुपये), <strong>कमाल तोटा म्हणजे स्प्रेड वजा क्रेडिट</strong> (रु. 2,876), आणि <strong>ब्रेकईव्हन हा लोअर स्ट्राइक अधिक क्रेडिट आहे</strong> (24,106).</li>\n<li>येथे कॅप्ड रिवॉर्ड कॅप्ड जोखमीपेक्षा किंचित मोठे आहे, अ <strong>1 ते 1.26 च्या जोखमीसाठी बक्षीस</strong>, सह <strong>53 टक्के नफा होण्याची शक्यता</strong> आणि आपल्या बाजूला वेळ क्षय.</li>\n<li>ते ब्लॉक करते <strong>सुमारे 34,789 रुपये मार्जिन</strong>, साधारणपणे नग्न शॉर्ट कॉलच्या ब्लॉकचा पाचवा भाग, कारण खरेदी केलेले विंग सर्वात वाईट केस परिभाषित करते. त्याचा न्याय करा <strong>मार्जिनवर परतावा, सुमारे 10 टक्के</strong>.</li>\n<li>हा बुल पुट स्प्रेडचा बेअरिश क्रेडिट-स्प्रेड चुलत भाऊ आहे: समान परिभाषित-जोखीम, क्रेडिट-कलेक्शन आकार, कॉल्समधून तयार केलेला.</li>\n<li>जेव्हा तुम्ही NIFTY क्रॅश होण्याऐवजी थांबण्याची अपेक्षा करता आणि तुम्हाला प्रतीक्षा करण्यासाठी पैसे दिले जावेत अशी तुमची अपेक्षा असते तेव्हा ते दीर्घकाळापर्यंत निवडा.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"खरा व्यापार, रुपयाने रुपया","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"समास","id":"margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"अस्वल कॉल स्प्रेड किंवा लांब पुट?","id":"bear-call-spread-or-long-put"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"10":{"html":"<p>NIFTY वर मंदीचे वळण घेणारे बहुतेक लोक थेट पुटसाठी पोहोचतात, फॅट प्रीमियम भरतात आणि नंतर ब्रेकइव्हनपर्यंत पोहोचण्यासाठी खरी उडी आवश्यक असते. अस्वल पुट स्प्रेड ही त्याच प्रवृत्तीची शिस्तबद्ध आवृत्ती आहे. तुम्ही अजूनही घसरणीपासून फायद्यासाठी पुट खरेदी करता, परंतु तुम्ही बहुतेक खर्च परत करण्यासाठी सेकंद, कमी पुट विकता, त्यामुळे तुमचे तिकीट स्वस्त होते आणि तुमचे ब्रेकईव्हन आजच्या किमतीच्या अगदी जवळ बसते. तुम्ही एखाद्या क्रॅशमध्ये अमर्यादित विंडफॉलचे स्वप्न सोडून देता आणि त्या बदल्यात तुम्हाला सामान्य घसरणीवर परिभाषित, परवडणारे आणि अधिक संभाव्य मोबदला मिळेल. हा धडा खऱ्या NIFTY किमतींवर ट्रेड तयार करतो, प्रत्येक रुपया कुठून येतो हे दाखवतो आणि तुम्हाला सर्वात स्पष्टीकरण देणारे तीन आयाम देतात: डेबिट ट्रेडवर शक्यता, मार्जिन आणि वेळ कसा दाबतो.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>अस्वल पसरले</strong> एकाच कालबाह्यतेवर दोन पुट पर्याय आहेत. आपण <strong>उच्च-स्ट्राइक पुट खरेदी करा</strong> NIFTY कमी होताना वाढण्यासाठी, आणि तुम्ही <strong>लोअर-स्ट्राइक पुट विक्री करा</strong> बहुतेक खर्च परत करण्यासाठी. तुम्ही शिल्लक रकमेवर जे भरता ते अ <strong>निव्वळ डेबिट</strong>, आणि तुम्ही भरलेल्या रकमेपेक्षा तुम्ही कधीही कर्ज देऊ शकत नसल्यामुळे, ते डेबिट देखील तुम्ही गमावू शकता. तुम्ही दिलेले स्ट्राइक वजा मधील अंतरावर, रिवॉर्ड देखील मर्यादित आहे.</p>\n<p>तुमचा दृष्टिकोन असेल तेव्हा तुम्ही ते वापरता <strong>मध्यम मंदीचा</strong>, याचा अर्थ तुम्ही NIFTY पडण्याची अपेक्षा करता, परंतु कड्यावरून पडण्याऐवजी समजूतदार पातळीवर. आपण संकुचित होण्यासाठी पैसे देत नाही. आपल्याला फक्त मोजलेल्या स्लाइडची आवश्यकता आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बेअर पुट स्प्रेड जास्त पुट खरेदी करतो आणि निव्वळ डेबिटसाठी कमी पुट विकतो. NIFTY तुमच्या उच्च स्ट्राइकच्या खाली आल्यास तुम्हाला नफा होतो, तुमचा नफा तुमच्या खालच्या स्ट्राइकच्या पुढे गेल्यावर मर्यादित केला जातो आणि तुमचा तोटा तुम्ही भरलेल्या डेबिटवर मर्यादित केला जातो. हा क्रेडिट-अँड-सेल बेअर कॉल स्प्रेडचा डेबिट-आणि-बाय मिरर आहे, जो शांत वाहून जाण्याऐवजी सक्रिय घसरणीपर्यंत पोहोचतो.</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">खरा व्यापार, रुपयाने रुपया</h2>\n<p>येथे 26 जून 2026 रोजी इंडेक्ससह कॅप्चर केलेल्या वास्तविक NIFTY किमतींवरील अचूक व्यापार येथे आहे <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत जवळपास 32 दिवसांनी संपेल. आम्ही 24,050 पुट एट-द-मनी खरेदी करतो आणि 23,950 पुट वन स्ट्राइक खाली विकतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>अधिक रु. 16,676 मध्ये</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>2,506 रु</strong></td>\n</tr>\n</tbody></table>\n<p>एकट्या 24,050 पुटसाठी संपूर्ण 19,182 रुपये मोजावे लागतील. 23,950 पुट वन स्ट्राइक लोअरवर विकल्यास 16,676 रुपये मिळतात, जे त्या बिलातील बहुतांश पैसे भरतात आणि <strong>2,506 रुपये निव्वळ डेबिट</strong>. तुम्ही ट्रेड उघडता त्या क्षणी ते तुम्ही खिशातून भरता आणि तुमच्याकडून कधीही दुसरा रुपया मागितला जाऊ शकत नाही. त्यामुळे अस्वलाला स्प्रेड म्हणतात <strong>डेबिट प्रसार</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bear-put-spread.png\" alt=\"वास्तविक NIFTY बेअर पुट स्प्रेड: 23,950 च्या खाली 3,994 रुपयांचा फ्लॅट प्रॉफिट शेल्फ, 24,050 च्या वर 2,506 रुपयांचा फ्लॅट लॉस शेल्फ आणि स्पॉटच्या अगदी खाली 24,011 वर सिंगल ब्रेकवेन. NIFTY घसरल्याने केशरी ॲट-एक्सपायरी लाइन नफ्यात चढते; निळ्या डॅशची T+0 रेषा आजच्या किमतीच्या वर बसलेली आहे कारण विकत घेतलेल्या पुटमध्ये अजूनही वेळेचे मूल्य आहे जे अद्याप कमी झालेले नाही.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>रिअल NIFTY बेअर पुट स्प्रेड: 23,950 च्या खाली रु. 3,994 चा फ्लॅट प्रॉफिट शेल्फ, 24,050 च्या वर रु. 2,506 चा फ्लॅट लॉस शेल्फ आणि स्पॉटच्या अगदी खाली 24,011 वर सिंगल ब्रेकवेन. NIFTY घसरल्याने केशरी ॲट-एक्सपायरी लाइन नफ्यात चढते; निळ्या डॅशची T+0 रेषा आजच्या किमतीच्या वर बसलेली आहे कारण विकत घेतलेल्या पुटमध्ये अजूनही वेळेचे मूल्य आहे जे अद्याप कमी झालेले नाही.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p>प्रत्येक बेअर पुट स्प्रेड तीन अंकांनी पिन केलेला असतो आणि प्रत्येक वरील ट्रेडमधून सरळ बाहेर पडतो. तर्कशास्त्र एकदा वाचा आणि तुम्हाला ते कधीही लक्षात ठेवण्याची गरज नाही.</p>\n<p><strong>जास्तीत जास्त नुकसान निव्वळ डेबिट आहे, रु. 2,506.</strong> NIFTY 24,050 स्ट्राइकवर किंवा त्याहून अधिक कुठेही समाप्त झाल्यास, दोन्ही पुट निरर्थक कालबाह्य होतात. जेव्हा निर्देशांक स्ट्राइकच्या वर बसतो तेव्हा कोणीही पुट व्यायाम करत नाही. तुम्ही जे पैसे दिले ते तुम्ही गमावता आणि हे व्यापार सर्वात वाईट आहे.</p>\n<p><strong>जास्तीत जास्त नफा म्हणजे स्प्रेड वजा डेबिट, रु. 3,994.</strong> स्प्रेड म्हणजे दोन स्ट्राइकमधील अंतर, 100 गुण, 100 गुणिले 65, जे 6,500 रुपये आहे. जर NIFTY 23,950 च्या खाली आला, तर दोन्ही पुट पैशांमध्ये खोलवर असतील आणि पूर्ण 100-पॉइंट गॅप तुमच्या बाजूने लॉक होईल. तुम्ही ते रु. 6,500 गोळा करता, परंतु तुम्ही आत जाण्यासाठी आधीच 2,506 रुपये दिले आहेत, त्यामुळे तुमचा निव्वळ नफा 6,500 वजा 2,506 आहे, म्हणजे <strong>3,994 रु</strong>. विकले गेलेले पुट हे येथे बक्षीस वाढवते आणि नेहमीप्रमाणे उभ्या स्प्रेडसह, जास्तीत जास्त नफा आणि कमाल तोटा पूर्ण स्ट्राइक रुंदीपर्यंत जोडतो.</p>\n<p><strong>ब्रेकइव्हन हा उच्च स्ट्राइक वजा डेबिट प्रति शेअर, 24,011 आहे.</strong> तुम्ही प्रति शेअर ३८.५५ गुण दिले. NIFTY 24,050 स्ट्राइकपेक्षा 38.55 अंकांनी खाली घसरले आहे. <strong>24,011</strong>, खरेदी केलेल्या पुटने आपण पोझिशनसाठी जे पैसे दिले ते परत मिळण्यापूर्वी. 24,011 च्या खाली तुम्ही नफा पूर्ण करता. याच्या वर तुम्ही तोट्यात पूर्ण करता.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>निव्वळ डेबिट</td>\n<td>2,506 रु</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>स्प्रेड वजा निव्वळ डेबिट</td>\n<td>रु. 6,500 वजा रु 2,506 = रु. 3,994</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>उच्च स्ट्राइक वजा डेबिट प्रति शेअर</td>\n<td>24,050 वजा 38.55 = 24,011</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>एखाद्या रणनीतीवर विश्वास ठेवण्याचा सर्वात खात्रीचा मार्ग म्हणजे काही मोजक्या किंमतींवर त्याचा निपटारा करणे आणि पैशांची हालचाल पाहणे. येथे एक्सपायरी दिवशी, प्रति लॉट 65 च्या पाच स्तरांवर बेअर पुट स्प्रेड आहे. एक्स्पायरीच्या वेळी एक पुट कमाल (स्ट्राइक वजा NIFTY, 0) आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 ला तुम्ही विकत घेतले</th>\n<th>23,950 ला तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>250 किमतीची</td>\n<td>150 किमतीची</td>\n<td>अधिक रु 3,994 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,994 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,011</td>\n<td>39 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 2,506 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,300</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 2,506 (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>टेबल खाली वाचा आणि आकार स्वतः काढतो. 23,950 वरून कोठूनही तुम्ही पूर्ण रु. 3,994 गोळा करता, कारण खरेदी केलेला प्रत्येक अतिरिक्त पॉइंट तुम्ही विकलेल्या पुटद्वारे थेट परत केला जातो. 24,050 वरून कुठेही तुम्ही पूर्ण 2,506 रुपये गमावाल. दोन स्ट्राइक दरम्यान परिणाम एका शेल्फमधून दुसऱ्या शेल्फवर सहजतेने सरकतो, 24,011 वर शून्य ओलांडतो. ते संपूर्ण मोबदला आहे आणि ते चार्टवरील केशरी रेषेशी तंतोतंत जुळते.</p>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>तुम्ही जिंकू शकता आणि गमावू शकता हे जाणून घेणे ही केवळ अर्धी गोष्ट आहे. व्यापार स्मार्ट आहे की नाही हे ठरवणारा प्रश्न हा आहे की प्रत्येक परिणामाची शक्यता किती आहे? ते म्हणजे <strong>नफ्याची शक्यता</strong>, किंवा POP, आणि बिल्डर ते थेट पॅनेलवर प्रिंट करतो.</p>\n<p>यासाठी पसरले <strong>POP सुमारे 49 टक्के आहे</strong>, नाणे फ्लिप जवळ. हा आकडा ऑप्शन मार्केटमधूनच आला आहे. अंदाजे 12.7 टक्के आणि 32 दिवस शिल्लक असलेल्याNIFTY′ पर्यायांमध्ये किंमत असलेल्या अस्थिरतेचा वापर करून, बाजार 49 टक्के शक्यता दर्शवितो की NIFTY कालबाह्यतेनुसार 24,011 ब्रेकइव्हनच्या खाली पूर्ण होईल. पुन्हा चार्ट पहा. फिकट छायांकित <strong>सिग्मा बँड</strong> बाजाराला अपेक्षित असलेली हालचाल दाखवा आणि 24,011 वर ब्रेकइव्हन 24,056 च्या स्पॉटपेक्षा फक्त 45 पॉइंट्स खाली बसते, आरामात इनर बँडमध्ये. तुम्ही चमत्कार मागत नाही. आपण एक लहान पाऊल खाली विचारत आहात.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>नेहमी जास्तीत जास्त नुकसानापुढील POP वाचा, कधीही एकटे नाही. हे स्प्रेड रु. 3,994 करण्यासाठी 2,506 जोखीम घेते, जो जोखमीपेक्षा मोठे बक्षीस आहे, परंतु ते फक्त अर्ध्या वेळेतच जिंकते कारण प्रत्यक्षात पडण्यासाठी NIFTY आवश्यक आहे. डेबिट स्प्रेड हा क्रेडिट स्प्रेडच्या विरुद्ध सौदा आहे: तुम्ही जे काही करता त्यापेक्षा जास्त मोबदल्याच्या बदल्यात तुम्ही वाईट शक्यता स्वीकारता. POP हा ट्रेड घेण्यासारखा आहे याची तुम्ही पुष्टी कशी करता.</p>\n</div></div>\n<h2 id=\"margin\">समास</h2>\n<p>कारण प्रत्येक पाय परिभाषित केला आहे आणि तुमचा तोटा डेबिटवर मर्यादित आहे, एक्सचेंज फक्त माफक प्रमाणात अवरोधित करते <strong>समास</strong> सुमारे <strong>34,113 रु</strong> हे पद धारण करण्यासाठी. विकले गेलेले पुट ही संख्या कमी ठेवते. लोन लाँग पुट त्याच्या प्रीमियमला ​​तंतोतंत जोडतो, परंतु एका स्प्रेडमध्ये जोडणे, एक विकत घेतलेले आणि एक विकलेले लेग एक्स्चेंज एकमेकांच्या विरूद्ध नेट करू शकते, भांडवल व्यवस्थित ठेवते.</p>\n<p>ते मार्जिन तुम्हाला व्यापाराचा प्रामाणिकपणे न्याय करू देते <strong>मार्जिन वर परत</strong>. तुम्ही जवळपास एका महिन्यासाठी ब्लॉक केलेल्या रु. 34,113 विरुद्ध रु. 3,994 कमवू शकता, जे अंदाजे आहे <strong>जोखीम असलेल्या भांडवलावर 11.7 टक्के</strong> व्यापार चालतो तर. तो परतावा, कच्च्या रुपयाचा आकडा नव्हे, तर एक गंभीर व्यापारी समान भांडवलासाठी स्पर्धा करणाऱ्या प्रत्येक कल्पनेच्या विरोधात उभा राहतो.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>चार्ट वर पुन्हा एकदा पहा <strong>निळ्या डॅशची T+0 रेखा</strong> सध्याच्या किमतीच्या जवळ घन नारंगी ॲट-एक्सपायरी लाईनच्या वर बसणे. ते अंतर आहे <strong>वेळेचे मूल्य</strong>, आणि निव्वळ खरेदीदारासाठी हे भेटवस्तूऐवजी हळू गळती आहे. आजच्या 24,056 च्या स्पॉटवर ट्रेड एक्सपायरीच्या वेळी त्याच्या कमाल-तोट्याच्या शेल्फवर बसला आहे, तरीही ब्लू लाइन आत्ता कमी तोटा दाखवते, कारण विकत घेतलेल्या 24,050 पुटमध्ये अजूनही टाइम प्रीमियम आहे. जसजसे शांत दिवस जातात, तसतसे प्रीमियम वितळते आणि निळी रेषा नारिंगी मजल्याकडे बुडते.</p>\n<p>सोप्या भाषेत, काहीही न केल्याने तुम्हाला किंमत नाही. NIFTY पडण्यास नकार देणारा प्रत्येक शांत दिवस तुमच्या मालकीच्या पुटमधून थोडेसे रक्तस्त्राव करतो आणि वेळ क्षय स्थितीला त्याच्या कमाल नुकसानाकडे हळूवारपणे खेचते. क्रेडिट-स्प्रेड विक्रेत्याला घड्याळानुसार पैसे दिले जातात. डेबिट-स्प्रेड खरेदीदार म्हणून, तुम्ही ते चालवत आहात, त्यामुळे तुमचा पतन अंतिम दिवशी नव्हे तर चांगल्या वेळेत यावा अशी तुमची इच्छा आहे.</p>\n<h2 id=\"choosing-your-strikes\">तुमचे स्ट्राइक निवडत आहे</h2>\n<p>वरील 100-पॉइंट स्प्रेड ही अनेकांमध्ये एक निवड आहे. स्ट्राइकमधील अंतर वाढवा किंवा कमी करा आणि तुम्ही संपूर्ण व्यापाराला आकार द्या. येथे समान NIFTY आणि समान एक्सपायरी वर तीन बेअर पुट स्प्रेड आहेत, प्रत्येक क्रमांकाची गणना समान पर्याय शृंखलेतून केली जाते, जेणेकरून तुम्ही ट्रेड-ऑफ स्वच्छपणे पाहू शकता.</p>\n<table>\n<thead>\n<tr>\n<th>प्रसार</th>\n<th>खरेदी/विक्री</th>\n<th>निव्वळ डेबिट</th>\n<th>जास्तीत जास्त नफा</th>\n<th>ब्रेकवेन</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>50 गुण</td>\n<td>24,050 खरेदी करा / 24,000 विक्री करा</td>\n<td>1,170 रु</td>\n<td>2,080 रु</td>\n<td>24,032</td>\n</tr>\n<tr>\n<td>100 गुण</td>\n<td>24,050 खरेदी करा / 23,950 विक्री करा</td>\n<td>2,506 रु</td>\n<td>3,994 रु</td>\n<td>24,011</td>\n</tr>\n<tr>\n<td>200 गुण</td>\n<td>24,050 खरेदी करा / 23,850 विक्री करा</td>\n<td>४,६१५ रु</td>\n<td>8,385 रु</td>\n<td>23,979</td>\n</tr>\n</tbody></table>\n<p>नमुना स्पष्ट आहे. ए <strong>अरुंद पसरला</strong> स्वस्त आहे आणि त्याचे ब्रेकईव्हन स्पॉटच्या सर्वात जवळ बसते, म्हणून ते सर्वात कमी पडल्यावर पैसे देण्यास सुरुवात करते, परंतु त्याचे बक्षीस कमी असते. ए <strong>व्यापक प्रसार</strong> अधिक खर्च येतो आणि ब्रेकईव्हनपर्यंत पोहोचण्यासाठी थोडा पुढे प्रवास करण्यासाठी NIFTY आवश्यक आहे, तरीही तुम्हाला अपेक्षित घट प्रत्यक्षात उतरली तर ते जास्त पैसे देते. तुमचा विकला गेलेला स्ट्राइक तुम्हाला ज्या स्तरावर पोहोचू शकेल असे वाटते त्या पातळीवर सेट करा, कारण जास्तीत जास्त नफा तिथेच पोहोचतो. टेबलमध्ये कोणतेही विनामूल्य जेवण नाही, फक्त एक डायल तुम्ही तुमच्या खात्रीशी जुळण्यासाठी चालू करता.</p>\n<h2 id=\"bear-put-spread-or-bear-call-spread\">बेअर पुट स्प्रेड की बेअर कॉल स्प्रेड?</h2>\n<p>तुम्ही मागील प्रकरणामध्ये पसरलेल्या अस्वल कॉलला भेटलात आणि ते बांधकामात फ्लिप केलेल्या जवळपास-समान पेऑफ आकारासह समान मंदीचे दृश्य व्यक्त करते. तर तुम्ही कोणते निवडता? प्रामाणिक उत्तर आहे, ते तुम्हाला NIFTY काय करायचे आहे यावर अवलंबून आहे.</p>\n<ul>\n<li>द <strong>अस्वल कॉल पसरला</strong> आहे <strong>क्रेडिट</strong> व्यापार तुम्हाला 3,624 रुपये अगोदर दिले जातात आणि जर तुमच्या बाजूने वेळ क्षय होऊन NIFTY फक्त वाढण्यात अपयशी ठरला तर तुम्ही जिंकता. तुम्हाला शांतता हवी आहे.</li>\n<li>द <strong>अस्वल पसरले</strong> आहे <strong>डेबिट</strong> व्यापार तुम्ही आधी 2,506 रुपये भरता आणि NIFTY सक्रियपणे 24,011 च्या खाली आल्यावरच तुम्ही जिंकता, वेळ तुमच्या विरुद्ध हळूवारपणे क्षय होईल. तुम्हाला चळवळ हवी आहे.</li>\n</ul>\n<p>अस्वल पुट स्प्रेडपर्यंत पोहोचा जेव्हा तुम्हाला अस्सल, बऱ्यापैकी तत्पर घट अपेक्षित असते, कदाचित एखाद्या ज्ञात समर्थनापर्यंत किंवा उत्प्रेरकाच्या पुढे तुम्हाला वाटते की बाजार कमी होईल. रु. 2,506 च्या जोखमीच्या विरुद्ध रु. 3,994 चे बक्षीस, सुमारे 1 ते 1.59 चे गुणोत्तर, बेअर कॉल स्प्रेडपेक्षा अधिक उदार आहे, आणि जेव्हाNIFTY′ तुमच्या खालच्या स्ट्राइकवर पोहोचतो तेव्हा ते तुम्हाला सर्वात अचूकपणे पैसे देते. त्याऐवजी बेअर कॉल स्प्रेडसाठी पोहोचा जेव्हा तुम्हाला विश्वास असेल की वरची बाजू मर्यादित आहे, पडणार आहे असे नाही. बरेच व्यापारी दोन्ही हातात ठेवतात आणि मार्केटचा मूड शांत करू देतात की ब्रेकिंग, कोणता बसेल ते ठरवतात.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>अस्वल पुट स्प्रेड परिभाषित-जोखीम आहे, परंतु जोखीम वास्तविक आहे आणि त्याचे संपूर्ण पैसे दिले जातात. जरNIFTY′ 24,050 वर किंवा त्यापेक्षा वर बंद झाला तर संपूर्ण रु. 2,506 निघून जाईल, जे ते आजच्या 24,056 वरून स्थिर राहून करू शकते. डेबिट ट्रेडमध्ये घसरण कधीच झाली नाही तर वेळ निघून गेल्याने त्या नुकसानाकडे शांतपणे रक्तस्त्राव होतो. प्रत्येक पोझिशनला त्याच्या जास्तीत जास्त तोट्याने आकार द्या, रिवॉर्डने कधीही नाही आणि तुमचा मंदीचा कॉल लवकर किंवा सरळ चुकीचा असल्यास तुमचे खाते शोषून घेऊ शकतील इतकेच लॉट ठेवा.</p>\n</div></div>\n<p>तुम्ही हा स्प्रेड लेग बाय लेग इन एकत्र करू शकता <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong>, स्वस्त, जवळ ब्रेकइव्हन दिसल्यावर तुम्ही विकलेल्या पुटला लोन लाँग पुटमध्ये जोडता. सिंगल पुटची सखोल नफ्याची रेषा 3,994 रुपयांच्या कमाल मर्यादेत सपाट झाली आहे आणि त्याच हालचालीत किंमत 19,182 रुपयांवरून 2,506 रुपयांपर्यंत घसरली आहे. तो व्यापार, मर्यादित पुरस्कारासाठी स्वस्त प्रवेश, प्रत्येक प्रसाराचे हृदय आहे. पुढे आम्ही विनम्र दोन-पायांचे स्प्रेड मागे सोडतो आणि तीन ठळक मंदीचे आकार एक्सप्लोर करतो: पुट रेशो बॅक स्प्रेड, शॉर्ट सिंथेटिक भविष्य आणि जोखीम उलटणे.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>बेअर पुट स्प्रेड जास्त पुट विकत घेतो आणि कमी पुट a साठी विकतो <strong>निव्वळ डेबिट</strong>, NIFTY उच्च स्ट्राइकच्या खाली आल्यास नफा.</li>\n<li><strong>कमाल तोटा म्हणजे निव्वळ डेबिट</strong> (येथे रु 2,506), <strong>जास्तीत जास्त नफा म्हणजे स्प्रेड वजा डेबिट</strong> (रु. ३,९९४), आणि <strong>ब्रेकईव्हन हा उच्च स्ट्राइक वजा डेबिट आहे</strong> (24,011).</li>\n<li>बक्षीस जोखीम पेक्षा मोठे आहे, पण <strong>POP फक्त 49 टक्के आहे</strong>, कारण व्यापाराला प्रत्यक्षात पडण्यासाठी NIFTY आवश्यक आहे, आणि <strong>काळाचा क्षय तुमच्या विरुद्ध हळूवारपणे कार्य करतो</strong> निव्वळ खरेदीदार म्हणून.</li>\n<li>हे एक लहान अवरोधित करते <strong>समास</strong> सुमारे रु. 34,113, आणि विकलेला पुट तोटा आणि मार्जिन दोन्ही व्यवस्थित ठेवतो. त्याचा न्याय करा <strong>मार्जिन वर परत</strong>, अंदाजे 11.7 टक्के येथे.</li>\n<li><strong>अरुंद पसरतो</strong> जवळच्या ब्रेकइव्हन आणि लहान बक्षीससह स्वस्त आहेत; <strong>व्यापक प्रसार</strong> अधिक खर्च करा आणि अधिक पैसे द्या. विकलेला स्ट्राइक सेट करा जिथे तुम्हाला NIFTY उतरण्याची अपेक्षा आहे.</li>\n<li>जेव्हा तुम्ही अपेक्षा करता तेव्हा ते बेअर कॉल स्प्रेडवर निवडा <strong>अस्सल, त्वरित घट</strong>, आणि जेव्हा तुम्हाला पैशाच्या जवळ ब्रेकइव्हनसह स्वस्त तिकीट हवे असेल तेव्हा एकट्याने लांब ठेवा.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"खरा व्यापार, रुपयाने रुपया","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"समास","id":"margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"तुमचे स्ट्राइक निवडत आहे","id":"choosing-your-strikes"},{"level":2,"text":"बेअर पुट स्प्रेड की बेअर कॉल स्प्रेड?","id":"bear-put-spread-or-bear-call-spread"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"11":{"html":"<p>तुम्ही नुकतेच बनवलेले दोन बेअर स्प्रेड दोन्ही बाजूंना मर्यादित रिवॉर्डसह सभ्य, परिभाषित-जोखमीचे व्यवहार होते. हा धडा तीन ठळक मंदीच्या आकारांपर्यंत पोहोचतो, प्रत्येक घसरणीच्या वेळी खूप मोठ्या मोबदल्याचा पाठलाग करतो आणि त्यापैकी दोन नुकसानीची शेपटी घेऊन जातात जे कधीही वरच्या बाजूला बंद होत नाहीत. आपण भेटू <strong>गुणोत्तर परत पसरवा</strong>, ज्याची किंमत कमी आहे आणि वास्तविक ब्रेक लोअरवर प्रचंड पैसे देतात; द <strong>लहान कृत्रिम भविष्य</strong>, जिथे एक कॉल आणि एक पुट अगदी NIFTY भविष्य विकल्यासारखे वागतात; आणि <strong>धोका उलटणे</strong>, एक मंदीचा कॉलर जो क्रेडिटसाठी उघडतो. प्रत्येकाला तुम्हाला आधीच माहित असलेल्या पायांपासून एकत्र केले जाते आणि प्रत्येक वेगळ्या प्रकारे डाउनसाइडवर कठोरपणे झुकते.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>तिन्ही ट्रेड्समध्ये मंदीचा कल आहे, परंतु जोखीम कोठे राहते यावर ते झपाट्याने विभाजित होतात. द <strong>गुणोत्तर परत पसरवा</strong> तिकीटावर सर्वात वाईट केस छापून ठेवते आणि क्रॅशच्या मर्यादेशिवाय पैसे देते. द <strong>लहान कृत्रिम भविष्य</strong> आणि <strong>धोका उलटणे</strong> दोन्ही क्रेडिटसाठी उघडतात आणि अधिक वेळा फायदेशीर समाप्त करतात, परंतु प्रत्येक कॉल विकतो ज्याच्या वर काहीही नसतो, त्यामुळे रॅलीची किंमत अंतहीन असते. त्याचे नुकसान कुठे मर्यादित आहे आणि कुठे नाही हे प्रत्येकाने वाचा.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>पुट रेशो बॅक स्प्रेड ही एक स्वस्त, परिभाषित-जोखमीची पैज आहे जी कठोर पडल्यावर खूप पैसे देते. लहान सिंथेटिक भविष्य हे दोन पर्याय आहेत जे लहान NIFTY भविष्यासारखे आहेत, अनकॅप्ड अपसाइड जोखीम. रिस्क रिव्हर्सल म्हणजे क्रेडिटसाठी उघडलेली मंदीची कॉलर, अनकॅप्ड अपसाइड रिस्कसह. प्रथम नवशिक्या-सुरक्षित आहे; इतर दोन लीव्हरेज्ड शॉर्ट्स आहेत जे आदर आणि मोठ्या फरकाची मागणी करतात.</p>\n</div></div>\n<h2 id=\"the-put-ratio-back-spread\">पुट रेशो बॅक स्प्रेड</h2>\n<p>एक गुणोत्तर बॅक स्प्रेड जाणूनबुजून एका सामान्य स्प्रेडचा एक-एक संतुलन तोडतो. तुम्ही एक ऐट-द-मनी पुट विकता आणि दोन पुट स्ट्राइक लोअर विकत घेता, त्यामुळे तुम्ही एक अतिरिक्त पुट धारण कराल, याचा अर्थ NIFTY कठोर पडल्यास तुम्हाला शक्तिशाली नफा होतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>24,050</td>\n<td>295.1 मिळाले</td>\n<td>अधिक 19,182 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>पुट खरेदी करा (x2)</td>\n<td>23,950</td>\n<td>प्रत्येकी २५६.६, देय</td>\n<td>33,352 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>14,170 रु</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही जे पुट विकता ते 19,182 रुपये आणते, आणि तुम्ही खरेदी केलेल्या दोन पुटची किंमत 33,352 रुपये मिळून मिळते, त्यामुळे पोझिशन थोड्या प्रमाणात उघडते <strong>14,170 रुपये निव्वळ डेबिट</strong>. तुम्ही विकल्यापेक्षा एक अधिक पुट तुमच्या मालकीचा असल्याने, खोल घसरण त्या अतिरिक्त पुटला पूर्णतः ए <strong>कमाल नफा 1,536,080 रु</strong> जर NIFTY शून्याकडे कोसळले. त्या आकृतीला \"क्रॅशवर खूप मोठा\" साठी लघुलेख म्हणून हाताळा.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>NIFTY शून्यावर आल्याने अतिरिक्त लाँग पुट मर्यादेशिवाय वाढतो</td>\n<td>रु. 1,536,080</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>23,950 वर विकलेला पुट तुमच्या विरुद्ध 100 पॉइंट्स आणि डेबिट आहे</td>\n<td>रु. 6,500 अधिक रु. 14,170 = रु. 20,670</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>शॉर्ट स्ट्राइक वजा व्हॅली लॉस एका जाळ्यावर पसरला</td>\n<td>23,950 वजा 318 = 23,632</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-ratio-back-spread.png\" alt=\"NIFTY पुट रेशो बॅक स्प्रेड: 23,950 शॉर्ट स्ट्राइकवर 20,670 वर उथळ नुकसान व्हॅली, 23,632 वर ब्रेकइव्हन, आणि नफ्याची रेषा जी त्याच्या खाली वेग वाढवते कारण तुम्ही एक अतिरिक्त लांब पुट धरला आहे. 24,050 वरील तिन्ही पुट निरर्थक कालबाह्य होतात आणि तुम्ही फक्त रु. 14,170 डेबिट गमावाल.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY पुट रेशो बॅक स्प्रेड: 23,950 शॉर्ट स्ट्राइकवर 20,670 वर उथळ नुकसान व्हॅली, 23,632 वर एक ब्रेकइव्हन आणि एक नफा रेषा जी त्याच्या खाली वेग वाढवते कारण तुम्ही एक अतिरिक्त लांब पुट धरला आहे. 24,050 वरील तिन्ही पुट निरर्थक कालबाह्य होतात आणि तुम्ही फक्त रु. 14,170 डेबिट गमावाल.</figcaption></figure>\n<p>इथला धोका वरवरचा नाही, तो मध्यभागी आहे. तुमची सर्वात वाईट स्थिती मोठ्या हालचालीवर नाही तर एका लहानशी आहे, अगदी 23,950 शॉर्ट स्ट्राइकवर, जिथे तुम्ही विकलेल्या पुटचे 100 पॉइंट्स तुमच्या विरुद्ध पैसे आहेत, तर तुम्ही विकत घेतलेले दोन्ही पुट अजूनही निरुपयोगी आहेत. येथे प्रति लॉट, NIFTY च्या पाच स्तरांवर स्थायिक झालेला व्यापार आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 ला तुम्ही विकले</th>\n<th>तुम्ही खरेदी केलेले २३,९५० पुट (दोन)</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,200</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 14,170 (केवळ डेबिट)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>उणे रु 20,670 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>23,632</td>\n<td>418 किमतीची</td>\n<td>636 किमतीची</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>23,300</td>\n<td>750 किमतीची</td>\n<td>1,300 किमतीची</td>\n<td>अधिक 21,580 रु</td>\n</tr>\n<tr>\n<td>23,000</td>\n<td>1,050 किमतीची</td>\n<td>1,900 किमतीची</td>\n<td>अधिक रु 41,080</td>\n</tr>\n</tbody></table>\n<p>ते वाचा आणि विचित्र आकार अर्थ प्राप्त होतो. स्ट्राइकच्या वर तुम्ही फक्त डेबिट गमावाल आणि 23,950 ची एक छोटी स्लाइड हे उतरण्यासाठी सर्वात वाईट ठिकाण आहे. 23,632 च्या ब्रेकईव्हनच्या खाली दुसऱ्या लाँग पुटने सर्व काही परत केले आहे आणि तेथून नफा पुढील NIFTY थेंबांना गती देतो. नफ्याची 32 टक्के संभाव्यता ही त्या भूमितीची प्रामाणिक किंमत आहे: या व्यापारामुळे खरी घसरण होते, सौम्य प्रवाह नाही.</p>\n<h2 id=\"the-short-synthetic-future\">लहान कृत्रिम भविष्य</h2>\n<p>पुढील आकार दोन पर्यायांपैकी फ्युचर्स पोझिशन कॉपी करतो. एट-द-मनी कॉलची विक्री करा आणि त्याच 24,050 स्ट्राइकवर ठेवलेले पैसे खरेदी करा आणि जोडी अगदी लहान NIFTY भविष्याप्रमाणे वागते, नफा आणि तोट्याची एकल सरळ कर्णरेषा.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल विक्री</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td>अधिक रु 27,677 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु 8,496 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही विकत घेतलेल्या कॉलमध्ये तुम्ही खरेदी केलेल्या पुटपेक्षा जास्त खर्च येतो, त्यामुळे पोझिशन अल्पसाठी उघडते <strong>8,496 रुपये निव्वळ क्रेडिट</strong>. तिथून सरळ रेषा आहे. प्रत्येक पॉइंट NIFTY कमी झाला की तुम्हाला 65 रुपये फायदा होतो. प्रत्येक पॉइंट वाढला की तुमचे 65 रुपये कमी होतात.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>NIFTY शून्यावर आल्याने लाँग पुट नफा, तसेच क्रेडिट</td>\n<td>रु 1,571,746</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>विकलेल्या कॉलमध्ये त्याच्या वर काहीही नाही</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>स्ट्राइक आणि प्रति शेअर क्रेडिट</td>\n<td>24,050 अधिक 130.7 = 24,181</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-synthetic.png\" alt=\"NIFTY लहान सिंथेटिक भविष्य: 24,181 वर शून्य ओलांडणारी एकल सरळ कर्णरेषा, प्रत्येक बिंदूसाठी 65 रुपये मिळवणे NIFTY पडणे आणि प्रत्येक बिंदूसाठी 65 रुपये गमावणे, भविष्य विकण्यासारखेच आहे. निळी T+0 रेषा जवळजवळ नारंगी ऍट-एक्सपायरी रेषेच्या वर असते कारण सिंथेटिक भविष्यात अक्षरशः वेळेचे मूल्य नसते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY लघु सिंथेटिक भविष्य: 24,181 वर शून्य ओलांडणारी एकल सरळ कर्णरेषा, प्रत्येक बिंदूसाठी 65 रुपये मिळवते NIFTY पडते आणि प्रत्येक बिंदूसाठी 65 रुपये गमावतात, भविष्य विकण्यासारखेच. निळी T+0 रेषा जवळजवळ नारंगी ऍट-एक्सपायरी रेषेच्या वर असते कारण सिंथेटिक भविष्यात अक्षरशः वेळेचे मूल्य नसते.</figcaption></figure>\n<p>येथे ब्रेकईव्हन <strong>24,181</strong> ही सिंथेटिक भविष्यातील किंमत आहे, अगदी वर बसलेली आहे कारण कॅरीची किंमत पर्यायांमध्ये बेक केली जाते. येथे सरळ रेषा चार स्तरांवर स्थिरावली आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल तुम्ही विकले</th>\n<th>24,050 ला तुम्ही विकत घेतले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,550</td>\n<td>मूल्य 0</td>\n<td>500 किमतीचे</td>\n<td>अधिक रु 40,996</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 8,496</td>\n</tr>\n<tr>\n<td>24,181</td>\n<td>131 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,550</td>\n<td>500 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>उणे 24,004 रु</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>लहान सिंथेटिक भविष्यात जास्तीत जास्त तोटा आहे जो UNLIMITED आहे. तुम्ही वरील कोणत्याही संरक्षणाशिवाय कॉल विक्री केल्यामुळे, कोणत्याही कमाल मर्यादाशिवाय, प्रत्येक पॉइंट NIFTY वाढीसाठी पोझिशन 65 रुपये गमावते. हा इंडेक्सवर एक लीव्हरेज्ड शॉर्ट आहे, त्यामुळेच एक्सचेंज सुमारे रु. 1.69 लाख मार्जिन ब्लॉक करते. नफ्याची 56 टक्के संभाव्यता त्या अनकॅप्ड शेपटीला मऊ करत नाही. एक तीक्ष्ण रॅली आपण गोळा केलेल्या कोणत्याही गोष्टीपेक्षा जास्त नुकसान करू शकते.</p>\n</div></div>\n<p>सिंथेटिक भविष्य हा नवशिक्याचा पहिला व्यापार नाही. त्याचे खरे मूल्य वैचारिक आहे: एका स्ट्राइकवर पुट विकत घेताना कॉल विकणे हे भविष्यात लहान असण्यासारखे आहे, कॉल आणि पुट हे एकाच साधनाचे दोन भाग आहेत याचा पुरावा.</p>\n<h2 id=\"the-risk-reversal\">जोखीम उलटणे</h2>\n<p>शेवटचा आकार सिंथेटिकला मंदीच्या कॉलरमध्ये मऊ करतो. तुम्ही डाउनसाइड नफ्यासाठी पैशाच्या खाली एक पुट विकत घेता आणि ते भरण्यासाठी पैशाच्या वर कॉल विकता, त्यामध्ये थोडा उतार असतो.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>23,950</td>\n<td>२५६.६ भरले</td>\n<td>16,679 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल विक्री</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>अधिक रु 24,057 मध्ये</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु 7,378 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही विकत असलेला कॉल तुम्ही खरेदी करता त्यापेक्षा जास्त खर्च येतो, त्यामुळे <strong>धोका उलटणे</strong> a साठी उघडते <strong>7,378 रुपये निव्वळ क्रेडिट</strong>. 23,950 च्या खाली लाँग पुट प्रॉफिट आणि नफा वाढतो पुढे NIFTY कमी होतो. दोन स्ट्राइक दरम्यान तुम्ही फक्त क्रेडिट ठेवा. 24,150 च्या वर विकलेला कॉल तुमच्या विरुद्ध होतो आणि तोटा मर्यादेशिवाय चालतो.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>NIFTY शून्यावर आल्याने लाँग पुट नफा, तसेच क्रेडिट</td>\n<td>रु 1,564,128</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>विकल्या गेलेल्या 24,150 कॉलच्या वर काहीही नाही</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>कॉल स्ट्राइक आणि प्रति शेअर क्रेडिट</td>\n<td>24,150 अधिक 113.5 = 24,264</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-risk-reversal.png\" alt=\"NIFTY मंदीचा जोखीम रिव्हर्सल: 23,950 च्या खाली लाँग-पुट प्रॉफिट झोन, दोन स्ट्राइक दरम्यान रु. 7,378 चे अंदाजे फ्लॅट क्रेडिट आणि विकलेल्या कॉलमुळे 24,264 वर ब्रेकईव्हन वर अमर्यादित तोटा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY मंदीचा जोखीम रिव्हर्सल: 23,950 च्या खाली लाँग-पुट प्रॉफिट झोन, दोन स्ट्राइक दरम्यान रु. 7,378 चे अंदाजे सपाट क्रेडिट आणि विकलेल्या कॉलमुळे 24,264 वर ब्रेकइव्हनच्या वर अमर्यादित तोटा.</figcaption></figure>\n<p>येथे प्रति लॉट, NIFTY च्या पाच स्तरांवर कॉलर सेटल आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>23,950 ला तुम्ही विकत घेतले</th>\n<th>24,150 कॉल तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,450</td>\n<td>500 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>अधिक रु. 39,878</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 7,378</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 7,378</td>\n</tr>\n<tr>\n<td>24,264</td>\n<td>मूल्य 0</td>\n<td>114 किमतीची</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,550</td>\n<td>मूल्य 0</td>\n<td>400 किमतीची</td>\n<td>उणे रु. 18,622</td>\n</tr>\n</tbody></table>\n<p>23,950 ते 24,150 पर्यंतच्या संपूर्ण अंतरावर रु. 7,378 चा फ्लॅट शेल्फ पहा. तो विस्तृत शांत बँड आहे जिथून नफ्याची 60 टक्के संभाव्यता येते, परंतु ती त्याच्या वरची शेपटी कॅप करण्यासाठी काहीही करत नाही.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>मंदीच्या जोखीम रिव्हर्सलमध्ये जास्तीत जास्त तोटा असतो जो UNLIMITED असतो. विकल्या गेलेल्या 24,150 कॉलला त्याच्या वर कोणतेही संरक्षण नाही, त्यामुळे 24,264 च्या ब्रेकईव्हनच्या पुढे गेल्यास तुमची मर्यादा न लागता, आणि एक्सचेंज ते ठेवण्यासाठी सुमारे रु. 1.64 लाख मार्जिन ब्लॉक करते. नफ्याची 60 टक्के संभाव्यता संपूर्णपणे तोटा सुरू होण्यापूर्वीच्या विस्तीर्ण अंतरातून येते, त्यावरील कोणत्याही कमाल मर्यादेपासून नाही. सुरक्षित उत्पन्न व्यापार म्हणून कधीही याला लाभदायक मंदीची स्थिती मानू नका.</p>\n</div></div>\n<h2 id=\"your-odds-across-the-three\">तिन्ही ओलांडून तुमची शक्यता</h2>\n<p>फायद्याची संभाव्यता आकारांप्रमाणेच कथा सांगते. द <strong>गुणोत्तर परत पसरवा</strong> फक्त प्रिंट <strong>32 टक्के</strong>, कारण त्याची दरी साफ करण्यासाठी आणि प्रवेगक नफ्याच्या रेषेपर्यंत पोहोचण्यासाठी त्याला खऱ्या अर्थाने घसरण आवश्यक आहे. द <strong>लहान कृत्रिम भविष्य</strong> येथे बसतो <strong>56 टक्के</strong> आणि <strong>धोका उलटणे</strong> येथे <strong>60 टक्के</strong>, दोन्ही अर्ध्या वर, कारण प्रत्येक क्रेडिटने सुरू होतो आणि किंमतीच्या विस्तृत विस्ताराने जिथे तो फक्त जिंकतो. परंतु अनकॅप्ड शेपटीने विकत घेतलेल्या उच्च शक्यता म्हणजे सुरक्षितता नाही: ते दोघे अधिक वेळा जिंकतात आणि ज्या दुर्मिळ दिवशी ते हरतात त्या दिवशी ते खूपच वाईट हरतात.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तोटा कुठे मर्यादित आहे त्यापुढील फायद्याची संभाव्यता नेहमी वाचा. जोपर्यंत रिव्हर्सलवर नफा मिळण्याची 60 टक्के संधी तुम्हाला इतर 40 टक्क्यांवर मजला नाही हे लक्षात येईपर्यंत दिलासादायक वाटतो. पुट रेशो बॅक स्प्रेडवर 32 टक्के संधी तिकिटावर मुद्रित केलेली 20,670 रूपये परिभाषित केली आहे. तोट्याचा आकार हेडलाइनच्या शक्यतांपेक्षा अधिक महत्त्वाचा आहे.</p>\n</div></div>\n<h2 id=\"margin-the-cost-of-an-open-tail\">मार्जिन, खुल्या शेपटीची किंमत</h2>\n<p>तीन मार्जिन शेजारी बघा आणि एक्स्चेंज तुम्हाला सांगते की, नेमके कोणते व्यवहार धोकादायक आहेत.</p>\n<table>\n<thead>\n<tr>\n<th>रणनीती</th>\n<th>नेट</th>\n<th>कमाल नुकसान</th>\n<th>समास</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>गुणोत्तर परत स्प्रेड ठेवा</td>\n<td>डेबिट रु. 14,170</td>\n<td>20,670 रु</td>\n<td>46,304 रु</td>\n</tr>\n<tr>\n<td>लघु कृत्रिम भविष्य</td>\n<td>क्रेडिट रु 8,496</td>\n<td>अमर्यादित</td>\n<td>रु. 169,046</td>\n</tr>\n<tr>\n<td>जोखीम उलटणे</td>\n<td>क्रेडिट रु 7,378</td>\n<td>अमर्यादित</td>\n<td>रु. 163,941</td>\n</tr>\n</tbody></table>\n<p>परिभाषित-रिस्क पुट रेशो बॅक स्प्रेड ब्लॉक्स रु. 46,304, त्याच्या स्वतःच्या सर्वात वाईट नुकसानापेक्षा दुप्पट. दोन अपरिभाषित-जोखीम प्रत्येक ब्लॉकला रु. 1.6 लाखापेक्षा जास्त व्यापार करतात, कारण एक्सचेंज एका शेपटीच्या विरूद्ध संपार्श्विक ठेवत आहे ज्याला अंत नाही. जेव्हा जेव्हा एखादी रचना अशा प्रकारचे भांडवल बांधते, तेव्हा तुम्ही ती ठेवण्यापूर्वी अमर्यादित बाजू कुठे राहते हे शोधण्यासाठी सिग्नल म्हणून घ्या.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>वेळ तिन्ही व्यवहारांना वेगळ्या पद्धतीने हाताळते. द <strong>गुणोत्तर परत पसरवा</strong> निव्वळ लाँग वन पुट आहे, म्हणून घड्याळ त्याच्या विरुद्ध कार्य करते: शॉर्ट स्ट्राइकच्या जवळ बसल्याने लांब पुटला रक्तस्त्राव होऊ शकतो, 23,950 पर्यंत शांतपणे वाहणे हा त्याचा सर्वात वाईट परिणाम आहे. द <strong>लहान कृत्रिम भविष्य</strong> जवळजवळ वेळेचे मूल्य नसते, म्हणून तिची निळी T+0 रेषा आणि नारिंगी एट-एक्सपायरी रेषा जवळजवळ एकमेकांच्या वर असते, वास्तविक भविष्यापेक्षा अधिक क्षय होत नाही. द <strong>धोका उलटणे</strong> NIFTY त्याच्या सपाट बँडमध्ये ठेवत असताना क्षयातून थोडेसे कमावते, कारण विकले गेलेले कॉल विकत घेतलेल्या पुटपेक्षा वेगाने वाया जातात, परंतु ती छोटी मदत दोन्ही बाजूंच्या दिशात्मक जोखमीमुळे कमी होते.</p>\n<h2 id=\"how-the-three-compare\">तिघांची तुलना कशी होते</h2>\n<p>पुट रेशो बॅक स्प्रेड हा त्रिकूटाचा एकमेव सदस्य आहे ज्याची सर्वात वाईट स्थिती आहे, 20,670 रुपये 23,950 वर, ज्यामुळे ते प्रथम स्थानावर पोहोचले आहे. शॉर्ट सिंथेटिक फ्युचर हे शुद्ध लीव्हरेज्ड शॉर्ट आहे, 24,181 च्या वर अमर्यादित आहे आणि जोखीम रिव्हर्सल हे विस्तीर्ण कुशनसह मंदीचे झुकते आहे परंतु 24,264 वरील समान अनकॅप्ड शेपटी आहे.</p>\n<p>जर तुम्ही मंदीशी संबंधित असाल आणि अजूनही शिकत असाल, तर या त्रिकूटातील पुट रेशो बॅक स्प्रेडला प्राधान्य द्या किंवा शेवटच्या अध्यायापासून प्लेन बेअर पुट स्प्रेडला अधिक चांगले द्या. दोघेही तुमची सर्वात वाईट केस तिकीटावर ठेवतात जिथे तुम्ही त्याच्या विरुद्ध आकार घेऊ शकता. जोपर्यंत तुम्ही अनकॅप्ड शॉर्ट मॅनेज करू शकत नाही तोपर्यंत शॉर्ट सिंथेटिक आणि रिस्क रिव्हर्सल सोडा आणि प्रथम अपसाइड कॅप करण्याच्या योजनेशिवाय एखाद्या ज्ञात इव्हेंटमध्ये कधीही होल्ड करू नका.</p>\n<p>आपण तिन्ही मध्ये तयार करू शकता <strong>सँडबॉक्स ट्रेडिंग (OpenAlgoमधील विश्लेषक मोड)</strong>, पाय ठेवून आणि पुट रेशो बॅक स्प्रेड पाहणे त्याची लॉस व्हॅली कोरते, सिंथेटिक पूर्णपणे सरळ रेषा काढते आणि त्याच्या स्ट्राइक दरम्यान जोखीम उलटा उतार. दोन क्रेडिट ट्रेड्सवर मॉडेल केलेली किंमत वरच्या दिशेने ड्रॅग करा आणि तोटा रेषा न संपता घसरताना पहा. ती एकच दृष्टी संपूर्ण धडा आहे. पुढे आम्ही मंदीच्या बटरफ्लाय आणि कंडोरसह परिभाषित-जोखमीच्या जमिनीवर परत येऊ, दोन स्वस्त, लक्ष्यित बेट पैशाच्या खाली अचूक लँडिंगवर.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>द <strong>गुणोत्तर परत पसरवा</strong> एक पुट विकतो आणि छोट्या डेबिटसाठी दोन लोअर पुट खरेदी करतो. त्याची सर्वात वाईट स्थिती म्हणजे 23,950 वर 20,670 रूपये परिभाषित, त्याचे ब्रेकईव्हन 23,632 आहे आणि ते 32 टक्के नफ्याच्या संधीसह, वास्तविक घसरणीवर खूप पैसे देते.</li>\n<li>द <strong>लहान कृत्रिम भविष्य</strong> 24,050 कॉल विकतो आणि 24,050 पुट विकत घेतो, लहान भविष्याशी बरोबरी करतो: एक सरळ रेषा, ब्रेकइव्हन 24,181, UNLIMITED तोटा.</li>\n<li>द <strong>धोका उलटणे</strong> 23,950 पुट विकत घेतो आणि क्रेडिटसाठी 24,150 कॉल विकतो, स्ट्राइक आणि 24,264 च्या पुढे UNLIMITED नुकसान दरम्यान 7,378 रु.च्या शेल्फसह एक मंदीचा कॉलर.</li>\n<li>दोन क्रेडिट ट्रेड्स 56 आणि 60 टक्के जास्त शक्यता दर्शवतात, परंतु या शक्यता मजल्याशिवाय शेपटीच्या वर बसतात आणि एक्स्चेंज प्रत्येकी 1.6 लाख रुपयांपेक्षा जास्त मार्जिन अवरोधित करते.</li>\n<li>नवशिक्यासाठी, परिभाषित-जोखीम पुट रेशो बॅक स्प्रेड हा त्रिकूटांपैकी फक्त एकच आहे जे पहिल्या स्थानावर पोहोचले आहे, आणि फक्त स्थितीत सर्वात वाईट केस आहे.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"पुट रेशो बॅक स्प्रेड","id":"the-put-ratio-back-spread"},{"level":2,"text":"लहान कृत्रिम भविष्य","id":"the-short-synthetic-future"},{"level":2,"text":"जोखीम उलटणे","id":"the-risk-reversal"},{"level":2,"text":"तिन्ही ओलांडून तुमची शक्यता","id":"your-odds-across-the-three"},{"level":2,"text":"मार्जिन, खुल्या शेपटीची किंमत","id":"margin-the-cost-of-an-open-tail"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"तिघांची तुलना कशी होते","id":"how-the-three-compare"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"12":{"html":"<p>आतापर्यंतच्या प्रत्येक मंदीच्या व्यापारात घसरण झाली आहे आणि घसरण जितकी मोठी होईल तितके चांगले. हा अध्याय विरुद्ध प्रवृत्ती शिकवतो. जर तुम्हाला वाटत असेल की NIFTY खाली पडेल, परंतु ते एका विशिष्ट ठिकाणी पडेल आणि थांबेल आणि आता जिथे बसले आहे त्या खाली एका अरुंद पट्ट्यात स्थिर होईल असे वाटत असेल तर? जेव्हा तुमचा दृष्टिकोन अगदी अचूक असेल, तेव्हा तुम्ही अशी रचना खरेदी करू शकता ज्याची किंमत जवळजवळ काहीही नाही आणि जर तुम्ही अंदाज लावला असेल तर निर्देशांक त्याच्या कितीतरी पटीने जास्त खर्च करेल. हे आहेत <strong>मंदीचे फुलपाखरू</strong> आणि <strong>मंदीचा कंडोर</strong>, पूर्णपणे पुट्सपासून बनवलेले, फक्त पैशाच्या खाली बसलेले. ते स्वस्त आहेत, ते परिभाषित-जोखीम आहेत आणि ते एका लहान खर्चाविरूद्ध चमकदार बक्षीस देतात. प्रामाणिक झेल, जो हा धडा लपवणार नाही, तो म्हणजे जिंकण्याची शक्यता कमी आहे, कारण किंमतीला सुई थ्रेड करावी लागेल.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>एक मंदीचे फुलपाखरू आणि एक मंदीचा कंडर दोन्ही आहेत <strong>सध्याच्या स्पॉटच्या खाली ठेवलेल्या रेंज बेट्स</strong>. तुम्ही चार पुट पाय एकत्र करता त्यामुळे संरचनेची किंमत अरुंद झोनच्या बाहेर जवळजवळ काहीच नसते आणि जर NIFTY खाली वाहून गेले तर ते खूप मोलाचे ठरते. प्रवेश करण्यासाठी तुम्ही एक लहान निव्वळ डेबिट भरता आणि ते डेबिट तुम्ही गमावू शकता. बक्षीस, काही शंभरांच्या तुलनेत हजार रुपये, नेत्रदीपक दिसते आणि ते गोळा करण्याची संभाव्यता हा भाग आहे जो तुम्ही प्रामाणिक ठेवला पाहिजे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>एक मंदीचे फुलपाखरू आणि कंडोर हे स्वस्त, परिभाषित-जोखमीचे बेट आहेत जेNIFTY′ एका विशिष्ट स्तरावर कमी होतील आणि तिथेच थांबतील. तुम्ही भरलेले छोटे डेबिट तुमचे जास्तीत जास्त नुकसान आहे, पेऑफ डेबिटच्या अनेक पट आहे आणि नफ्याची शक्यता दहापैकी फक्त एक आहे. ते लँडिंग स्पॉटवर अचूक, कमी शक्यता असलेली तिकिटे आहेत, मोठ्या हालचालीवर पैज लावत नाहीत.</p>\n</div></div>\n<h2 id=\"the-bearish-butterfly\">मंदीचे फुलपाखरू</h2>\n<p>फुलपाखराला तीन वार आणि चार पाय असतात. तुम्ही वर एक पुट विकत घ्या, दोन मध्यभागी विकता आणि खाली एक विकत घ्या, म्हणून दोघांनी बॉडीवर विकलेल्या दोन पुटमध्ये पंखांचे कुंपण विकत घेतले. स्पॉटच्या खाली ठेवलेले, जर NIFTY मधल्या स्ट्राइकवर खाली वाहून गेले तर संपूर्ण रचना शिखरावर येते.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री पुट (x2)</td>\n<td>23,950</td>\n<td>प्रत्येकी २५६.६ प्राप्त झाले</td>\n<td>अधिक रु. 33,358 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>पुट खरेदी करा</td>\n<td>23,850</td>\n<td>224.1 भरले</td>\n<td>14,567 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>सुमारे 393 रु</strong></td>\n</tr>\n</tbody></table>\n<p>शरीरावर विकले गेलेले दोन पुट बहुतेक प्रीमियम आणतात आणि दोन विकत घेतलेल्या पंखांची किंमत थोडी जास्त असते <strong>सुमारे 393 रुपये निव्वळ डेबिट</strong> संपूर्ण भरपूर साठी. ते डेबिट तुमचे जास्तीत जास्त नुकसान आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>निव्वळ डेबिट, पंखांच्या बाहेर हरवले</td>\n<td>393 रु</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>विंग रुंदी 6,500 रुपये डेबिट वजा, शरीर स्ट्राइक येथे</td>\n<td>रु. 6,500 वजा रु 393 = रु. 6,107</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>प्रत्येक विंगच्या आत काही बिंदू</td>\n<td>23,856 आणि 24,047</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bearish-butterfly.png\" alt=\"NIFTY मंदीचे बटरफ्लाय इन पुट्स: 23,950 च्या बॉडीवर 6,107 रुपयांवर एक तीव्र नफा तंबू, 23,856 आणि 24,047 वर ब्रेकव्हेन्स आणि पंखांच्या बाहेर सर्वत्र 393 रुपयांचे लहान नुकसान. 24,056 वरील गुलाबी स्पॉट लाइन तंबूच्या उजवीकडे बसते, म्हणून NIFTY पेमेंट करण्यासाठी बँडमध्ये खाली यावे लागेल.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY मंदीचे बटरफ्लाय इन पुट्स: 23,950 च्या बॉडीवर 6,107 रुपयांपर्यंत पोहोचणारा तीव्र नफा टेंट, 23,856 आणि 24,047 वर ब्रेकवेन्स आणि पंखांच्या बाहेर सर्वत्र 393 रुपयांचे छोटे नुकसान. 24,056 वरील गुलाबी स्पॉट लाइन तंबूच्या उजवीकडे बसते, म्हणून NIFTY पेमेंट करण्यासाठी बँडमध्ये खाली यावे लागते.</figcaption></figure>\n<p>पाच बंद पातळी ओलांडून व्यापार चाला आणि तंबू स्वतः काढतो. एक पुट एक्सपायरीच्या वेळी कमाल (स्ट्राइक वजा NIFTY, 0) मूल्य आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 PE विकत घेतले</th>\n<th>23,950 PE विकले (प्रत्येक)</th>\n<th>23,850 PE विकत घेतले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>250 किमतीची</td>\n<td>150 किमतीची</td>\n<td>50 किमतीचे</td>\n<td>उणे ३९३ रुपये (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>23,856</td>\n<td>194 किमतीची</td>\n<td>94 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 6,107 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,000</td>\n<td>50 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु. 2,857</td>\n</tr>\n<tr>\n<td>24,100</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे ३९३ रुपये (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>23,850 च्या खाली आणि 24,050 च्या वर चार पाय रद्द करा आणि तुम्ही Rs 393 च्या छोट्या तोट्यावर बसता. च्या breakevens दरम्यान <strong>23,856 आणि 24,047</strong> संरचना शून्याच्या वर पोकस करते, फक्त NIFTY ने 23,950 बॉडीला अचूकपणे पिन केले तरच पूर्ण रु. 6,107 च्या शिखरावर चढते. कोणत्याही मार्गाने पन्नास गुणही घसरतात आणि बक्षीस वेगाने कमी होते. ती धारदारपणा फुलपाखराचा स्वभाव आहे: एकच बिंदू सर्वात जास्त पैसे देतो.</p>\n<h2 id=\"the-bearish-condor\">मंदीचा कंडर</h2>\n<p>कंडोर हे फुलपाखरू असून त्याचे शिखर पठारावर पसरलेले आहे. एका बॉडी स्ट्राइकवर दोन पुट विकण्याऐवजी, तुम्ही ते दोन समीप स्ट्राइकवर विकता, ज्यामुळे जास्तीत जास्त नफा एका बिंदूऐवजी लहान श्रेणीमध्ये पसरतो. कमी शिखराच्या किमतीत NIFTY नेमके कुठे उतरते हे थोडे अधिक क्षमाशील आहे.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>24,000</td>\n<td>277.1 प्राप्त झाले</td>\n<td>अधिक रु 18,012 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>विक्री ठेवा</td>\n<td>23,900</td>\n<td>241.6 प्राप्त झाले</td>\n<td>अधिक रु 15,704 मध्ये</td>\n</tr>\n<tr>\n<td>4</td>\n<td>पुट खरेदी करा</td>\n<td>23,850</td>\n<td>224.1 भरले</td>\n<td>14,567 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>सुमारे 36 रु</strong></td>\n</tr>\n</tbody></table>\n<p>दोन विकले गेलेले आतील पुट पुन्हा बहुतेक प्रीमियम आणतात, अ <strong>फक्त 36 रुपये निव्वळ डेबिट</strong> लॉटसाठी, या संपूर्ण कोर्समध्ये सर्वात स्वस्त प्रवेश. ते 36 रुपये सर्वाधिक नुकसान आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>निव्वळ डेबिट, पंखांच्या बाहेर हरवले</td>\n<td>36 रु</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>50-पॉइंट अप्पर स्प्रेड (रु. 3,250) वजा डेबिट, संपूर्ण पठारावर</td>\n<td>रु. 3,250 वजा रु 36 = रु. 3,214</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>प्रत्येक बाहेरील पंखाच्या आत एक केस</td>\n<td>सुमारे 23,851 आणि 24,049</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bearish-condor.png\" alt=\"NIFTY मंदीचा कंडोर इन पुट्स: 23,900 आणि 24,000 अंतर्गत स्ट्राइक दरम्यान 3,214 रुपयांचा सपाट नफा पठार, बाहेरील पंखांच्या अगदी आत ब्रेकवेव्हन्स आणि त्यांच्या बाहेर सर्वत्र जवळपास-शून्य रुपये 36 नुकसान. फुलपाखराचा तंबू टेबलटॉप बनला आहे, खालचा पण रुंद आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY मंदीचा कंडोर इन पुट्स: 23,900 आणि 24,000 अंतर्गत स्ट्राइक दरम्यान 3,214 रुपयांचा सपाट नफा पठार, बाहेरील पंखांच्या अगदी आत ब्रेकवेव्हन्स आणि त्यांच्या बाहेर सर्वत्र जवळपास शून्य रुपये 36 नुकसान. फुलपाखराचा तंबू टेबलटॉप बनला आहे, खालचा पण रुंद आहे.</figcaption></figure>\n<p>येथे प्रति लॉट, NIFTY च्या पाच स्तरांवर कॉन्डोर सेटल आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 PE विकत घेतले</th>\n<th>24,000 PE विकले</th>\n<th>23,900 PE विकले</th>\n<th>23,850 PE विकत घेतले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,100</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे ३६ रुपये (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,000</td>\n<td>50 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,214 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>23,900</td>\n<td>150 किमतीची</td>\n<td>100 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 3,214 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>23,851</td>\n<td>199 किमतीची</td>\n<td>149 किमतीची</td>\n<td>49 किमतीचे</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>23,800</td>\n<td>250 किमतीची</td>\n<td>200 किमतीचे</td>\n<td>100 किमतीचे</td>\n<td>50 किमतीचे</td>\n<td>उणे ३६ रुपये (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>नारिंगी रेषा दोन आतील स्ट्राइक दरम्यान पठारावर सपाट चालते, 23,900 ते 24,000 पर्यंत कुठेही तेच 3,214 रुपये भरते, नंतर पंखांच्या बाहेर 36 रुपयांच्या तोट्यात येते. बटरफ्लायच्या तुलनेत, तंबू टेबलटॉप बनला आहे: 6,107 रुपयांऐवजी 3,214 रुपयांची कमी कमाल मर्यादा, परंतु एका पॉइंटऐवजी विस्तीर्ण लँडिंग झोनमध्ये कमाई केली.</p>\n<h2 id=\"your-odds-told-honestly\">तुमची शक्यता, प्रामाणिकपणे सांगितले</h2>\n<p>कमी खर्चात चमकदार बक्षीस दोन्ही रचना जवळजवळ खूप छान दिसतात. पकड म्हणजे भूमिती. जिंकण्यासाठी, NIFTY बँडमध्ये फक्त दोनशे पॉइंट्स रुंद झाले पाहिजे आणि जास्तीत जास्त जिंकण्यासाठी ते अगदी अरुंद स्लाइसमध्ये पूर्ण केले पाहिजे. कालबाह्य होण्यासाठी सुमारे 32 दिवस आणि चार्टवरील सिग्मा बँड किती अंतरावर फिरू शकतात हे दर्शविते, ते पैशाच्या खाली असलेल्या अचूक खिशात जाण्याची शक्यता खरोखरच कमी आहे. तेच आहे <strong>फुलपाखरावर 9 टक्के आणि कंडोरवर 10 टक्के संभाव्यता</strong> मोजत आहेत.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>जोखमीसाठी बक्षीस पहा. फुलपाखरू 1 ते 16 वाचते आणि कॉन्डोर आश्चर्यकारक 1 ते 90, कारण 36 रुपये डेबिट हे 3,214 रुपयांच्या तुलनेत खूपच कमी आहे. हे कोर्समधील सर्वोत्तम ट्रेडसारखे दिसतात. तुम्हाला प्रामाणिक ठेवणारी संख्या म्हणजे नफा मिळण्याची शक्यता, फक्त 9 ते 10 टक्के. दहापैकी एकदा जिंकणारा 1 ते 90 पेऑफ हे लॉटरी तिकीट आहे, किनार नाही.</p>\n</div></div>\n<p>कमी शक्यता हा व्यापारात दोष नाही. ते प्रचंड मोबदल्याची किंमत आहेत. बाजार संभाव्य घटनांवर 1 ते 90 शक्यता देत नाही. तर स्वस्तपणा हे एक वैशिष्ट्य आहे आणि एकाच वेळी एक सापळा आहे आणि तो सापळा कुठे चावतो तो पुढील भाग आहे.</p>\n<h2 id=\"margin-and-what-you-actually-risk\">मार्जिन आणि आपण प्रत्यक्षात काय धोका</h2>\n<p>दोन्ही रचना दाखवतात अ <strong>सुमारे 63,000 रुपयांचे मार्जिन</strong>, फुलपाखरासाठी सुमारे 63,606 रुपये आणि कॉन्डोरसाठी 63,256 रुपये. ही आकृती एक्सचेंजने ट्रॅक केलेले चार स्वतंत्र पाय प्रतिबिंबित करते, तुमचे खरे प्रदर्शन नाही. तुमची जोखीम असलेली खरी रोख रक्कम ही फक्त लहान निव्वळ डेबिट आहे, रु 393 किंवा रु. रिटर्न-ऑन-मार्जिन लेन्स जे साध्या स्प्रेड्ससाठी अनुकूल आहेत ते येथे बसत नाहीत, कारण मार्जिन बुककीपिंग कारणांसाठी मोठा आहे तर खरा धोका हा एक गोलाकार त्रुटी आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>तुम्ही आकार वाढवल्यानंतर जवळपास-शून्य खर्च हा जवळपास-शून्य धोका नसतो. मंदीच्या कंडोरच्या दहा लॉटमध्ये रु. 360 आणि बटरफ्लायच्या दहा लॉटमध्ये रु. 3,930 जोखीम आहे आणि तुम्ही ती पूर्ण रक्कम दहापैकी नऊ किंवा दहा वेळा गमावाल, कारण नफा मिळण्याची शक्यता फक्त 10 टक्के आहे. काही-शंभर रुपयांचे तिकीट फुकटचे पैसे मानून अनेक लॉट रचण्याचा मोह कमी शक्यता असलेल्या पैजचे खरे नुकसान कसे होते. हे लहान, मुद्दाम लावलेल्या बेटांसारखे आकार द्या, लोड करण्यासाठी स्वस्त लॉटरी पट्ट्यांसारखे नाही.</p>\n</div></div>\n<h2 id=\"time-decay-and-why-to-place-these-late\">वेळेचा क्षय आणि हे उशीरा का ठेवायचे</h2>\n<p>या नेट-डेबिट संरचना आहेत, परंतु त्यांचा काळाशी संबंध असामान्य आहे. फुलपाखरू किंवा कंडोर केवळ त्याच्या पूर्ण तंबूत पोहोचते जेव्हा प्रत्येक पर्याय शुद्ध आंतरिक मूल्यावर स्थिरावतो. सध्या निळ्या रंगाची T+0 लाईन ऑरेंज एट-एक्सपायरी लाईनपेक्षा खूप चपटा आहे, कारण विकल्या गेलेल्या बॉडी पुटमध्ये अजूनही टाइम प्रिमियम आहे ज्याचा अद्याप निचरा झालेला नाही. घड्याळाचे काटे जसजसे खाली धावते तसतसे रचना त्याचा आकार मिळवते, परंतु जेव्हा ते घडते तेव्हा NIFTY खिशात बसले असते.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>ते कालबाह्य होण्याच्या जवळ ठेवा, त्यापासून लांब नाही. फुलपाखरू किंवा कंडोर आठवडे लवकर पिन केलेले NIFTY अरुंद पट्ट्यातून बाहेर भटकण्यासाठी खूप वेळ देते आणि तंबू अगदीच तयार झाला आहे. शेवटच्या आठवड्यात तीच रचना ठेवली जाते, जेव्हा सिग्मा बँड्स कमी होतात आणि निर्देशांक कुठे स्थिरावतो याविषयी तुम्हाला जोरदार वाचन असते, तेव्हा खिशात उतरण्याची आणि पूर्ण शिखर भरण्याची अधिक चांगली संधी असते.</p>\n</div></div>\n<h2 id=\"butterfly-or-condor\">फुलपाखरू किंवा कंडोर</h2>\n<p>स्पष्ट डोळ्यांनी वापरलेले, दोघांची खरी भूमिका आहे. जेव्हा तुम्ही विशिष्ट, कालबद्ध दृष्टिकोन ठेवता तेव्हा ते योग्य साधन आहे NIFTY एका विशिष्ट पातळीपर्यंत खाली जाईल आणि तेथे थांबेल, कदाचित एखाद्या ज्ञात समर्थनामध्ये किंवा तुम्ही निर्देशांक पिन करण्याची अपेक्षा करत असलेल्या इव्हेंटच्या आधी. त्या अचूक परिणामावर तुम्ही परिभाषित-जोखीम तिकिटासाठी काही शंभर रुपये देत आहात आणि जर तुम्ही योग्य असाल तर किंमत कमी होईल.</p>\n<ul>\n<li>निवडा <strong>फुलपाखरू</strong> जेव्हा तुमचा लँडिंग स्पॉटचा दृष्टीकोन तीव्र असेल आणि तुम्हाला 23,950 बॉडी अचूकपणे पिन करण्यासाठी सर्वात जास्त मोबदला हवा असेल. ते त्याच्या शिखरावर 6,107 रुपये देते.</li>\n<li>निवडा <strong>कॉन्डोर</strong> जेव्हा तुम्हाला थोडी अधिक खोली हवी असेल तेव्हा 23,900 ते 24,000 पर्यंत कुठेही देय असलेल्या पठाराच्या बदल्यात रु. 3,214 ची कमी मर्यादा स्वीकारा.</li>\n</ul>\n<p>दोन्ही तिकिटावर तुमची सर्वात वाईट केस छापून ठेवा, रु 393 किंवा रु.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>या ट्रेड्सवरील अंदाजे प्रीमियम हा चारही पायांवर उलाढालीचा आकडा आहे आणि तो मोठा दिसतो, परंतु तो तुमचा धोका नाही. तुमची जोखीम म्हणजे लहान निव्वळ डेबिट, रु 393 किंवा रु. 36, कारण खरेदी केलेले विंग प्रत्येक निकालावर अवलंबून असतात. तुम्ही गमावू शकता त्या रकमेप्रमाणे एकूण प्रीमियम कधीही वाचू नका. निव्वळ डेबिट वाचा, जे बिल्डरने जास्तीत जास्त नुकसान म्हणून नोंदवले आहे.</p>\n</div></div>\n<p>तुम्ही दोन्ही मध्ये बांधू शकता <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong>, एका वेळी एक पाय जोडणे आणि फुलपाखराचा तीक्ष्ण तंबू कंडोरच्या टेबलटॉपमध्ये मऊ होताना पाहणे जेव्हा आपण शरीराचे दोन स्ट्राइकमध्ये विभाजन करता. मॉडेल केलेली किंमत संपूर्ण चार्टवर स्लाइड करा आणि ती नफ्याच्या बँडमध्ये किती क्वचितच येते आणि काही प्रसंगी ती किती भरभरून देते ते पहा. ती भावना, स्वस्त आणि तेजस्वी परंतु क्वचितच योग्य, दिशात्मक फुलपाखरू आणि कंडोरचा प्रामाणिक धडा आहे. या प्रकरणासह मंदीचे कुटुंब पूर्ण झाले आहे, आणि पुढे आम्ही अशा ट्रेड्सकडे वळतो ज्यांना दिशेची अजिबात पर्वा नाही, त्याऐवजी NIFTY किती पुढे जाईल यावर सट्टा लावतो.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>एक मंदीचे फुलपाखरू वर एक पुट विकत घेते, शरीरावर दोन विकते आणि खाली एक पुट विकत घेते, सर्व काही जागेच्या खाली. लहान <strong>393 रुपये डेबिट हा जास्तीत जास्त तोटा आहे</strong>, द <strong>कमाल नफा 6,107 रुपये आहे</strong> 23,950 बॉडीवर, आणि ब्रेकेव्हन्स 23,856 आणि 24,047 आहेत.</li>\n<li>एक मंदीचा कंडर शरीराला दोन विकल्या गेलेल्या स्ट्राइकमध्ये विभाजित करतो, एक फ्लॅट देतो <strong>रु. 3,214 पठार</strong> साठी 23,900 आणि 24,000 दरम्यान <strong>कमाल नुकसान फक्त 36 रुपये</strong>.</li>\n<li>दोन्ही जोखमीसाठी चित्तथरारक बक्षीस दाखवतात, 1 ते 16 आणि 1 ते 90, परंतु द <strong>नफा मिळण्याची शक्यता फक्त 9 ते 10 टक्के आहे</strong>, कारण NIFTY अरुंद खिशात उतरणे आवश्यक आहे.</li>\n<li>63,000 रु.चे मोठे मार्जिन हे बुककीपिंगचे चार पाय प्रतिबिंबित करते, वास्तविक एक्सपोजर नाही. तुमची खरी जोखीम ही लहान निव्वळ डेबिट आहे आणि खरेदी केलेले पंख प्रत्येक निकालावर अवलंबून असतात.</li>\n<li>एक्सपायरी जवळ आल्यावर वेळ तंबू बांधतो, त्यामुळे हे उत्तम काम करतात <strong>सायकल मध्ये उशीरा ठेवले</strong>, जेव्हा अपेक्षित श्रेणी कमी होते आणि लँडिंग स्पॉटवर तुमचे वाचन मजबूत असते.</li>\n<li>तंतोतंत लँडिंगवर त्यांना लहान, मुद्दाम, कमी-विषम बेट समजा, अनेक लॉटमध्ये स्टॅक करण्यासाठी स्वस्त पैसे कधीही नाहीत.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"मंदीचे फुलपाखरू","id":"the-bearish-butterfly"},{"level":2,"text":"मंदीचा कंडर","id":"the-bearish-condor"},{"level":2,"text":"तुमची शक्यता, प्रामाणिकपणे सांगितले","id":"your-odds-told-honestly"},{"level":2,"text":"मार्जिन आणि आपण प्रत्यक्षात काय धोका","id":"margin-and-what-you-actually-risk"},{"level":2,"text":"वेळेचा क्षय आणि हे उशीरा का ठेवायचे","id":"time-decay-and-why-to-place-these-late"},{"level":2,"text":"फुलपाखरू किंवा कंडोर","id":"butterfly-or-condor"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"13":{"html":"<p>आतापर्यंतच्या प्रत्येक रणनीतीला एक दिशा आवश्यक आहे. तुम्ही बुलिशकडे झुकले आहात किंवा तुम्ही मंदीकडे झुकले आहात आणि तुम्ही जुळण्यासाठी एक रचना निवडली आहे. आता पहिल्या ट्रेड्सला भेटा जे कोणत्या मार्गाने NIFTY जाते याकडे लक्ष देत नाही, फक्त किती अंतरावर आहे. कॅलेंडरवर एक मोठी घटना, धोरणात्मक निर्णय किंवा परिणाम जे सर्वांना माहीत आहे ते 24,056 वर बसलेले निर्देशांक चित्रित करा परंतु कोणीही आगाऊ कॉल करू शकत नाही. तुम्हाला खात्री आहे की NIFTY कठोरपणे हलवणार आहे. तुम्हाला फक्त वर किंवा खाली माहित नाही. द <strong>लांब पट्टा</strong> आणि <strong>लांब गळा दाबणे</strong> नेमक्या त्या क्षणासाठी बांधल्या जातात. तुम्ही कॉल आणि पुट दोन्ही खरेदी करता, त्यामुळे मोठ्या हालचाली कोणत्याही प्रकारे पैसे देतात आणि तुमचा एकमेव खरा शत्रू हा बाजार आहे जो कुठेही जात नाही.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>लांब पट्टा</strong> एकाच स्ट्राइक आणि एक्सपायरी वर, एट-द-मनी कॉल आणि एट-द-मनी एकत्र खरेदी करते. ए <strong>लांब गळा दाबणे</strong> स्वस्त-बाहेरील स्ट्राइक, बाजाराच्या खाली पुट आणि त्याच्या वर कॉलसह समान गोष्ट करते. एकतर दोन्ही बाजू तुमच्या मालकीच्या आहेत, त्यामुळे NIFTY चढला तर एका पायाला फायदा होतो आणि दुसरा पडला तर. तुम्ही अ <strong>निव्वळ डेबिट</strong> व्यापार चालू ठेवण्यासाठी, आणि ते डेबिट, एकाच वेळी दोन पर्यायांसाठी प्रीमियम, तुमची संपूर्ण जोखीम आहे.</p>\n<p>तुमचा व्ह्यू बद्दल असेल तेव्हा तुम्ही हे वापरता <strong>अस्थिरता, दिशा नाही</strong>. तुम्हाला लवकरच एक तीव्र हालचाल अपेक्षित आहे आणि तुम्हाला तो खंडित होईल अशा प्रकारे पैसे मिळायचे आहेत. तुम्ही जे टाळले पाहिजे ते म्हणजे शांत, वाहून जाणारे बाजार, कारण हाच एक परिणाम आहे जो शांतपणे तुमचे जास्तीत जास्त नुकसान करून देतो.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>एक लांब स्ट्रॅडल किंवा स्ट्रॅगल दोन्ही दिशेने मोठ्या हालचालीतून नफा मिळवण्यासाठी कॉल आणि पुट एकत्र खरेदी करतो. तुम्ही जो प्रीमियम भरता तो संपूर्ण जोखीम असतो, नफा प्रत्यक्ष हालचालीवर उघडला जातो आणि शांत बाजार हा लॉट गमावण्याचा एकमेव मार्ग आहे. हा बाजार कोणत्या मार्गावर जातो यावर नव्हे तर गतीवर पैज आहे.</p>\n</div></div>\n<h2 id=\"the-straddle-rupee-by-rupee\">स्ट्रॅडल, रुपयाने रुपया</h2>\n<p>येथे 26 जून 2026 रोजी इंडेक्ससह कॅप्चर केलेल्या वास्तविकNIFTY′ किमतींवरील स्ट्रॅडल आहे <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत सुमारे 32 दिवस संपत आहे. तुम्ही ॲट-द-मनी 24,050 कॉल आणि ॲट-द-मनी 24,050 पुट खरेदी करता.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>2</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>46,858 रु</strong></td>\n</tr>\n</tbody></table>\n<p>दोन्ही पाय पैशावर बरोबर बसतात, जेथे वेळेचे मूल्य सर्वात श्रीमंत आहे, त्यामुळे बिल खूप जास्त आहे. तुम्ही दोन पर्यायांमध्ये सुमारे 720.9 पॉइंट प्रति शेअर भरता, जे आहे <strong>46,858 रु</strong> 65 च्या एका लॉटसाठी. कारण तुम्ही ते अगोदर दिले आहे आणि एक रुपया जास्त मागितला जाऊ शकत नाही, तो देखील तुम्ही गमावू शकता.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-straddle.png\" alt=\"NIFTY वर लांबलचक स्ट्रॅडल: 24,050 च्या स्ट्राइकवर एक तीक्ष्ण V ज्यामध्ये पूर्ण रु. 46,858 गमावले जातात, 23,329 आणि 24,771 वर ब्रेकवेन्स आणि निर्देशांक दोन्ही दिशेने लांब जात असताना मर्यादेशिवाय वाढणारी नफा रेषा. निळ्या डॅशची T+0 रेषा केंद्राजवळील नारिंगी V च्या वर तरंगते, तुम्ही लढत असलेल्या वेळेचे मूल्य.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वर लांबलचक स्ट्रॅडल: 24,050 च्या स्ट्राइकवर एक तीक्ष्ण V ज्यामध्ये पूर्ण रु. 46,858 गमावले जातात, 23,329 आणि 24,771 वर ब्रेकवेव्हन्स आणि निर्देशांक दोन्ही दिशेने लांब जात असताना मर्यादेशिवाय वाढणारी नफा रेषा. निळ्या डॅशची T+0 रेषा केंद्राजवळील नारिंगी V च्या वर तरंगते, तुम्ही लढत असलेल्या वेळेचे मूल्य.</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-straddle\">स्ट्रॅडलची तीन संख्या</h2>\n<p>प्रत्येक संख्या थेट वरील व्यापाराच्या बाहेर पडते. प्रति शेअर एकूण प्रीमियम, 425.8 अधिक 295.1, 720.9 आहे आणि तो एकच आकडा सर्वकाही चालवतो.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>निव्वळ डेबिट भरले</td>\n<td>46,858 रु</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>प्रत्यक्ष हालचालीवर ओपन एंडेड</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>स्ट्राइक वजा, नंतर अधिक, प्रति शेअर एकूण प्रीमियम</td>\n<td>24,050 वजा 720.9 बरोबर 23,329; 24,050 अधिक 720.9 बरोबर 24,771</td>\n</tr>\n</tbody></table>\n<p><strong>जास्तीत जास्त नुकसान डेबिट आहे, रु 46,858.</strong> तुम्हाला फक्त एका अचूक बिंदूवर, 24,050 वर जवळचा अधिकार आहे, जेथे दोन्ही पर्याय एकत्र व्यर्थ कालबाह्य होतात. <strong>जास्तीत जास्त नफा अमर्यादित आहे.</strong> वरच्या ब्रेकइव्हनच्या वर कॉल कमाल मर्यादाशिवाय चालतो, आणि कमी झाल्यावर पुटचा फायदा शून्याच्या दिशेने होतो, ही खूप मोठी पण मर्यादित रक्कम, ज्याला बिल्डर प्रामाणिकपणे अमर्यादित लेबल लावतो. <strong>ब्रेकवेन्स 23,329 आणि 24,771 आहेत</strong>, दोन गुण जेथे हलवल्याने शेवटी तुम्ही खर्च केलेल्या प्रीमियमच्या 720.9 पॉइंट्सची परतफेड केली आहे.</p>\n<h2 id=\"walking-the-straddle-outcomes-at-expiry\">स्ट्रॅडल चालणे एक्सपायरी येथे परिणाम</h2>\n<p>पाच बंद किंमतींवर व्यापार सेटल करा आणि V स्वतःच दिसून येईल. कॉल एक्सपायरीच्या वेळी जास्तीत जास्त (NIFTY′ उणे 24,050, 0) मूल्याचा आहे, पुट कमाल (24,050 वजा NIFTY, 0) मूल्याचा आहे, आणि नेट म्हणजे ते दोन जोडले गेलेले गुण 65, तुम्ही दिलेले 46,858 रुपये वजा.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>तुम्ही विकत घेतलेला २४,०५० कॉल</th>\n<th>24,050 ला तुम्ही विकत घेतले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>मूल्य 0</td>\n<td>1,050 किमतीची</td>\n<td>अधिक 21,392 रु</td>\n</tr>\n<tr>\n<td>23,329</td>\n<td>मूल्य 0</td>\n<td>721 किमतीची</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 46,858 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,771</td>\n<td>721 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>1,250 किमतीची</td>\n<td>मूल्य 0</td>\n<td>अधिक रु. 34,392</td>\n</tr>\n</tbody></table>\n<p>स्तंभ खाली वाचा आणि धडा अगदी स्पष्ट आहे. उतरण्यासाठी सर्वात वाईट ठिकाण म्हणजे डेड सेंटर, तुम्ही खरेदी केलेल्या स्ट्राइकवर, जिथे तुम्ही सर्व काही गमावता. बाहेरच्या दिशेने दोन्ही दिशेने चालत जा आणि एक पाय जिवंत होतो, तोटा कमी होतो, तुम्ही ब्रेकईव्हनवर शून्य ओलांडता आणि त्यापलीकडे नफा मर्यादेशिवाय चढतो. तुम्ही दरीच्या अगदी तळाशी प्रवेश केला आहे आणि बाहेर जाण्यासाठी तुम्हाला NIFTY आवश्यक आहे.</p>\n<h2 id=\"the-strangle-rupee-by-rupee\">गळा घोटला, रुपयाने रुपया</h2>\n<p>स्ट्रॅडल चालते परंतु ते महाग आहे, कारण वेळेचे मूल्य सर्वात प्रिय असलेल्या ठिकाणी दोन्ही पाय बसतात. द <strong>लांब गळा दाबणे</strong> त्याऐवजी पैसे नसलेले पर्याय खरेदी करून कमी पैशात समान आकार ठेवते. तुम्ही बाजाराच्या खाली 23,950 पुट दोन स्ट्राइक खरेदी करा आणि 24,150 वर दोन स्ट्राइक कॉल करा.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>23,950</td>\n<td>२५६.६ भरले</td>\n<td>16,679 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल खरेदी करा</td>\n<td>24,150</td>\n<td>370.1 भरले</td>\n<td>24,057 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>40,729 रु</strong></td>\n</tr>\n</tbody></table>\n<p>दोन्ही पाय पैसे बाहेर आहेत कारण, प्रत्येक कमी खर्च, आणि <strong>निव्वळ डेबिट रु. 40,729 वर घसरले</strong>, स्ट्रॅडलपेक्षा सुमारे 6,000 रुपये स्वस्त. पकड अशी आहे की स्वस्त प्रवेश अधिक वाईट ब्रेकवेन विकत घेते, अधिक चांगले नाही, कारण आता मध्यभागी एक मृत बँड आहे जिथे एकही पाय पैसे देत नाही.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-strangle.png\" alt=\"NIFTY वर लांब गळा: एक सपाट तळाची बादली 23,950 आणि 24,150 च्या दरम्यान कुठेही पूर्ण 40,729 रुपये गमावते, 23,323 आणि 24,777 वर ब्रेकइव्हन्स आणि एकदा निर्देशांक एकतर पलीकडे गेला की अमर्यादित नफा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वर लांब गळा: एक सपाट तळाची बादली 23,950 आणि 24,150 च्या दरम्यान कुठेही पूर्ण 40,729 रुपये गमावते, 23,323 आणि 24,777 वर ब्रेकइव्हन्स आणि एकदा निर्देशांक एकतर पलीकडे गेला की अमर्यादित नफा.</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-strangle\">गळा घोटण्याची तीन संख्या</h2>\n<p>प्रति शेअर एकूण प्रीमियम, 256.6 अधिक 370.1, 626.7 आहे आणि ते तुम्ही विकत घेतलेल्या दोन स्ट्राइकचे ब्रेकवेव्हन्स सेट करते.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कमाल नुकसान</td>\n<td>निव्वळ डेबिट भरले</td>\n<td>40,729 रु</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>प्रत्यक्ष हालचालीवर ओपन एंडेड</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>लोअर स्ट्राइक मायनस, अप्पर स्ट्राइक अधिक, प्रति शेअर एकूण प्रीमियम</td>\n<td>23,950 वजा 626.7 बरोबर 23,323; 24,150 अधिक 626.7 बरोबर 24,777</td>\n</tr>\n</tbody></table>\n<p>गळ्यात मधेच काही परत देत नाही. 23,950 आणि 24,150 दरम्यान कुठेही दोन्ही पर्याय एक्सपायरीच्या वेळी निरुपयोगी ठरतात, त्यामुळे त्या संपूर्ण मध्यवर्ती बँडमध्ये तुम्ही पूर्ण 40,729 रुपये गमावाल. त्याचे ब्रेकवेव्हन्स, <strong>23,323 आणि 24,777</strong>, स्ट्रॅडलपेक्षा थोडेसे विस्तीर्ण बसा. तुम्ही एंटर करण्यासाठी कमी पैसे दिले आणि त्या बदल्यात NIFTY तुम्हाला पैसे देण्यापूर्वी आणखी एक टच हलवणे आवश्यक आहे.</p>\n<h2 id=\"walking-the-strangle-outcomes-at-expiry\">एक्सपायरी येथे गळा परिणाम चालणे</h2>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>23,950 ला तुम्ही विकत घेतले</th>\n<th>तुम्ही विकत घेतलेला २४,१५० कॉल</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>950 किमतीची</td>\n<td>मूल्य 0</td>\n<td>अधिक 21,021 रु</td>\n</tr>\n<tr>\n<td>23,323</td>\n<td>627 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु ४०,७२९ (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,777</td>\n<td>मूल्य 0</td>\n<td>627 किमतीची</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>मूल्य 0</td>\n<td>1,150 किमतीची</td>\n<td>अधिक रु. 34,021</td>\n</tr>\n</tbody></table>\n<p>स्ट्रॅडलची तीक्ष्ण व्ही एक सपाट तळाची बादली बनली आहे. एका हौदाऐवजी, स्ट्राइक दरम्यानच्या संपूर्ण अंतरामध्ये तोटा 40,729 रुपये इतका आहे, त्यानंतर लाइन फक्त पंखांच्या बाहेर वळते. समान आकार, ठेवण्यासाठी स्वस्त, परंतु तुम्हाला पैसे मिळण्यापूर्वी प्रवास करण्यासाठी विस्तीर्ण अंतर.</p>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>तुम्ही जिंकू शकता आणि गमावू शकता हे जाणून घेणे ही केवळ अर्धी गोष्ट आहे. व्यापार स्मार्ट आहे की नाही हे ठरवणारा प्रश्न नफा किती शक्यता आहे, आणि तो आहे <strong>नफ्याची शक्यता</strong>, पॅनेलवर उजवीकडे दर्शविले आहे. साठी <strong>straddle ते 42 टक्के आहे</strong>, साठी <strong>गळा दाबणे 41 टक्के</strong>. दोघेही अर्ध्या खाली बसतात आणि कारण प्रामाणिक आहे: NIFTY ला स्ट्रॅडल परत करण्यासाठी 720 पॉइंट्सपेक्षा जास्त प्रवास करावा लागतो आणि स्ट्रॅडल परत करण्यासाठी 626 पॉइंट्सपेक्षा जास्त प्रवास करावा लागतो, एका महिन्यात निर्देशांकाच्या अंदाजे तीन टक्के, जे मागण्यासाठी खरे अंतर आहे.</p>\n<p>बेहोश पहा <strong>सिग्मा बँड</strong> प्रत्येक चार्टवर, मूव्ह द ऑप्शन मार्केट प्रत्यक्षात किंमत ठरते. ब्रेकेव्हन्स आत नसून आतील बँडच्या काठाजवळ बसतात. हेच बाजार तुम्हाला सांगत आहे की या मोठ्या हालचालीवर अंदाजे सम-पैशाच्या बेट आहेत, यापुढे नाही.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>नेहमी खर्चाच्या बाजूला नफ्याची संभाव्यता वाचा, कधीही एकटे राहू नका. 42 टक्के नफ्याच्या संधीसह 46,858 रुपयांची जोखीम असलेली स्ट्रॅडल केवळ तेव्हाच खरेदी करणे योग्य आहे जेव्हा तुम्ही त्या फॅट प्रीमियम्समध्ये बाजाराने आधीच दिलेल्या किंमतीपेक्षा मोठ्या वाटचालीची अपेक्षा करता. सर्वोत्तम एंट्री म्हणजे जेव्हा गर्भित अस्थिरता कमी असते आणि तुम्ही ती वाढण्याची अपेक्षा करता, एखाद्या ज्ञात इव्हेंटने आधीच पर्याय सुजल्यानंतर नाही. गर्दीने त्याची किंमत वाढवण्याआधी हलवा खरेदी करा, नंतर नाही.</p>\n</div></div>\n<h2 id=\"margin\">समास</h2>\n<p>कारण तुम्ही शुद्ध खरेदीदार आहात, एक्सचेंज ब्लॉक करते <strong>डेबिटच्या समान मार्जिन</strong>, बद्दल <strong>स्ट्रॅडलसाठी 46,858 रु</strong> आणि <strong>गळा दाबण्यासाठी 40,729 रु</strong>, आणि एक रुपया जास्त नाही. कोणताही SPAN पेनल्टी नाही आणि एक्सपोजर बफर नाही, कारण तुम्ही गमावू शकता ते तुम्ही आधीच दिले आहे. लांब पर्याय असण्याची ही शांत भेट आहे: तुम्ही ऑर्डर देण्यापूर्वी तुमची सर्वात वाईट केस तिकीटावर छापली जाते आणि मार्जिन त्याच्या बरोबरीचे असते.</p>\n<p>येथे कोट करण्यासाठी मार्जिनवर कोणताही निश्चित परतावा नाही, कारण नफा मर्यादित न होता ओपन एंडेड आहे. या ट्रेड्सला तुम्ही अपेक्षित असलेल्या हालचालींच्या किंमतीनुसार त्यांच्या किंमतीवर न्याय द्या: मोठ्या स्विंगवर परिभाषित-जोखमीच्या तिकिटासाठी तुम्ही रु 46,858 किंवा रु 40,729 अदा करत आहात आणि मोबदला आणखी वाढतोNIFTY′ ब्रेकइव्हनच्या पुढे.</p>\n<h2 id=\"time-decay-is-the-enemy\">काळाचा क्षय हा शत्रू आहे</h2>\n<p>वर पुन्हा पहा <strong>निळ्या डॅशची T+0 रेखा</strong> प्रत्येक चार्टच्या मध्यभागी एक्सपायरी V नारिंगी वर तरंगत आहे. ते अंतर आहे <strong>वेळेचे मूल्य</strong>, आणि खरेदीदारासाठी तो रोजचा कर आहे. तुम्ही एकाच वेळी दोन पर्याय लांब आहात, त्यामुळे दोन्ही पायांवरून क्षय तुमच्याविरुद्ध चालतो. प्रत्येक शांत दिवशी निळी रेषा केशरी रेषेकडे झुकते आणि NIFTY क्वचितच हालचाल करत असतानाही स्थिती पैसे गमावते. निव्वळ विक्रेत्याला याच क्षयने पैसे दिले जातात. स्ट्रॅडल किंवा स्ट्रँगल खरेदीदार प्रत्येक सत्रात लढतो.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>एक लांब स्ट्रॅडल किंवा गळा दाबल्याने प्रत्येक शांत दिवशी वेळेचे मूल्य कमी होते आणि दोन पायांमधून एकाच वेळी रक्तस्त्राव होतो. तुम्ही दिलेले रु 46,858 किंवा रु. 40,729 जर NIFTY स्थिर राहिल्यासच नाही तर ते हळूहळू वाहून गेले तर देखील धोक्यात आहे, कारण क्षय रोखण्यासाठी हालचाली मोठ्या आणि वाजवीरीत्या जलद दोन्ही असणे आवश्यक आहे. त्यांना कधीही धारण करण्याची आणि विसरण्याची स्थिती मानू नका. लवकरच काहीतरी घडेल अशी त्यांची पैज आहे आणि एक्सपायरी येण्यापूर्वीच खरे नुकसान करण्यासाठी शांत पंधरवडा पुरेसा आहे.</p>\n</div></div>\n<h2 id=\"straddle-or-strangle\">स्ट्रॅडल की गळा दाबून?</h2>\n<p>दोन्ही बाजू बाजूला ठेवा आणि निवड हा अंतराच्या तुलनेत खर्चाचा एक सोपा सौदा आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>लांब स्ट्रॅडल</th>\n<th>लांब गळा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>अमर्यादित</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>46,858 रु</td>\n<td>40,729 रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>23,329 आणि 24,771</td>\n<td>23,323 आणि 24,777</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>42 टक्के</td>\n<td>41 टक्के</td>\n</tr>\n<tr>\n<td>निव्वळ डेबिट</td>\n<td>46,858 रु</td>\n<td>40,729 रु</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>46,858 रु</td>\n<td>40,729 रु</td>\n</tr>\n</tbody></table>\n<p>स्ट्रॅडलची किंमत जास्त आहे परंतु काही पॉइंट लवकर काम करण्यास सुरवात करते, कारण त्याचे पाय आधीच पैशावर आहेत. गळा दाबण्याची किंमत सुमारे 6,000 रुपये कमी आहे परंतु पैसे देण्यापूर्वी थोडा मोठा हलवा मागतो. जेव्हा तुम्हाला शक्य तितक्या घट्ट ब्रेकइव्हन्स हवे असतील आणि हिंसक, त्वरित हालचालीची अपेक्षा असेल तेव्हा स्ट्रॅडल निवडा. जेव्हा तुम्हाला कमी जोखीम घ्यायची असेल आणि मोठ्या स्विंगची वाट पाहण्यात आनंद वाटत असेल तेव्हा गळा घोटणे निवडा.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>आपण दोन्ही तयार करू शकता <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong>, एका वेळी कॉल आणि पुट एक पाय जोडणे आणि लांब पर्यायाची एकच ओळ एका स्ट्रॅडलच्या V मध्ये दुमडलेली पाहणे, नंतर आपण स्ट्राइक अलग पाडत असताना गळा दाबण्याच्या बादलीमध्ये पसरवा. संपूर्ण चार्टवर मॉडेल केलेली किंमत स्लाइड करा आणि अनुभवा की शांत दिवस तुम्हाला किती क्वचितच मदत करतो आणि वास्तविक हालचाल किती मोठ्या प्रमाणात देते. ती प्रवृत्ती, तुम्ही गती विकत घेत आहात आणि घड्याळाशी लढत आहात, हे प्रत्येक दीर्घ-अस्थिर व्यापाराचे हृदय आहे.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>एक लांब स्ट्रॅडल ॲट-द-मनी कॉल आणि पुट विकत घेते, एक लांब स्ट्रॅडल पैशाच्या बाहेर स्वस्त स्ट्राइक खरेदी करते आणि मोठ्या हालचालीतून दोन्ही नफा मिळवतात <strong>दोन्ही दिशा</strong>.</li>\n<li>द <strong>निव्वळ डेबिट हा संपूर्ण धोका आहे</strong>, स्ट्रॅडलसाठी रु 46,858 आणि स्ट्रॅगलसाठी रु 40,729, आणि मार्जिन फक्त त्याच्या बरोबरीचे आहे कारण व्यापार परिभाषित-जोखीम आहे.</li>\n<li><strong>नफा अमर्यादित आहे</strong> वास्तविक चालीवर, परंतु ब्रेकइव्हन्स स्पॉटपासून दूर बसतात, स्ट्रॅडलसाठी 23,329 आणि 24,771 आणि स्ट्रॅडलसाठी 23,323 आणि 24,777 वर.</li>\n<li>द <strong>नफ्याची शक्यता निम्म्यापेक्षा कमी आहे</strong>, 42 आणि 41 टक्के, कारण बाजाराने आधीच त्या प्रीमियम्समध्ये वाजवी-आकाराच्या हालचालीची किंमत ठरवली आहे.</li>\n<li><strong>काळाचा क्षय हा शत्रू आहे</strong>: तुम्ही लांब दोन पर्याय आहात, मूल्य दुप्पट वेगाने रक्तस्त्राव होतो आणि शांत बाजार हा एक परिणाम आहे जो तुमचे सर्व काही गमावतो.</li>\n<li>स्ट्रॅडल कडक ब्रेकवेन्ससाठी जास्त किंमत देते; गळा दाबण्याची किंमत कमी आहे परंतु मोठ्या हालचालीची आवश्यकता आहे. पुढील प्रकरणामध्ये तुम्ही दोन्हीची दुसरी बाजू घेता, प्रीमियम विकणे आणि विरुद्ध जोखीम वारसा मिळवणे.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"स्ट्रॅडल, रुपयाने रुपया","id":"the-straddle-rupee-by-rupee"},{"level":2,"text":"स्ट्रॅडलची तीन संख्या","id":"the-three-numbers-of-the-straddle"},{"level":2,"text":"स्ट्रॅडल चालणे एक्सपायरी येथे परिणाम","id":"walking-the-straddle-outcomes-at-expiry"},{"level":2,"text":"गळा घोटला, रुपयाने रुपया","id":"the-strangle-rupee-by-rupee"},{"level":2,"text":"गळा घोटण्याची तीन संख्या","id":"the-three-numbers-of-the-strangle"},{"level":2,"text":"एक्सपायरी येथे गळा परिणाम चालणे","id":"walking-the-strangle-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"समास","id":"margin"},{"level":2,"text":"काळाचा क्षय हा शत्रू आहे","id":"time-decay-is-the-enemy"},{"level":2,"text":"स्ट्रॅडल की गळा दाबून?","id":"straddle-or-strangle"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"14":{"html":"<p>शेवटच्या अध्यायात तुम्ही खरेदीदार होता, भरपूर प्रीमियम भरून आणि मोठ्या हालचालीसाठी प्रार्थना करत होता. आता त्याच व्यापाराच्या दुसऱ्या बाजूला उभे रहा. कोणीतरी स्ट्रॅडल खरेदीदारास त्यांचे कॉल आणि त्यांचे पुट विकले पाहिजे, ते फॅट प्रीमियम घ्यावे लागेल आणि उलट बाजूने पैज लावावी लागेल की NIFTY कुठेही जात नाही. तो विक्रेता या अध्यायात तुम्ही आहात. द <strong>लहान स्ट्रॅडल</strong> आणि <strong>लहान गळा</strong> शांत बाजाराचे उत्पन्नाचे व्यवहार आहेत. तुम्ही आधी प्रीमियम गोळा करता आणि प्रत्येक शांत दिवस नफ्याच्या दिशेने पोझिशन खेचतो. आकार मोहक आहे आणि विजय दर जास्त आहे. धोका असा आहे की तुम्हाला खरेदीदाराचे अमर्यादित बक्षीस तुमचे स्वतःचे अमर्याद नुकसान म्हणून मिळाले आहे आणि तुम्ही येथे करत असलेल्या प्रत्येक गोष्टीवर एक तथ्य आहे.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>लहान स्ट्रॅडल</strong> एट-द-मनी कॉल आणि ॲट-द-मनी एकत्र विकतो. ए <strong>लहान गळा</strong> स्वस्त विकतो आउट-ऑफ-द मनी स्ट्राइक, बाजाराच्या खाली पुट आणि त्याच्या वर कॉल. कोणत्याही प्रकारे तुम्ही ए मध्ये घ्या <strong>निव्वळ क्रेडिट</strong> समोर, आणि जोपर्यंत NIFTY बँडमध्ये राहतो तोपर्यंत तुम्ही ते ठेवता. स्ट्रॅडल खरेदीदार ज्या मूव्हसाठी पैसे देत आहे ते तुम्ही विकत आहात, प्रिमियमच्या पर्यायापेक्षा मार्केट शांत होईल अशी पैज लावत आहात.</p>\n<p>क्रेडिट हा तुमचा जास्तीत जास्त नफा आहे. पकडलेला, आणि तो एक गंभीर आहे, दोन्ही पाय नग्न आहेत. लहान कॉलला त्याच्या वर कमाल मर्यादा नसते आणि शॉर्ट पुट शून्याच्या दिशेने खूप खाली जातो, त्यामुळे तोटा वरच्या बाजूने उघडलेला असतो आणि खाली बांधलेला असला तरी तो खूप मोठा असतो.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>एक लहान स्ट्रॅडल किंवा स्ट्रॅगल शांत बाजारातून प्रीमियम गोळा करण्यासाठी कॉल आणि पुट एकत्र विकतो. तुम्ही जास्तीत जास्त श्रेय मिळवू शकता, वेळ क्षय तुमच्यासाठी कार्य करते आणि तुम्ही बहुतेक महिने जिंकता. पण दोन्ही विकले गेलेले पाय नग्न आहेत, तोट्याला वरची कमाल मर्यादा नाही आणि खाली खूप मोठ्या पण बांधलेल्या आकृतीपर्यंत धावते आणि त्या खुल्या शेपटामुळे एक्सचेंज तंतोतंत मोठ्या फरकाने अवरोधित करते.</p>\n</div></div>\n<h2 id=\"the-short-straddle-rupee-by-rupee\">लहान स्ट्रॅडल, रुपयाने रुपया</h2>\n<p>येथे 26 जून 2026 रोजी इंडेक्ससह कॅप्चर केलेल्या वास्तविक NIFTY किमतींवरील लहान स्ट्रॅडल आहे <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत सुमारे 32 दिवस संपत आहे. तुम्ही एट-द-मनी 24,050 कॉल आणि ॲट-द-मनी 24,050 पुट विकता, दोन्ही प्रीमियम एकाच वेळी गोळा करा.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल विक्री</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td>रु 27,677 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>24,050</td>\n<td>295.1 मिळाले</td>\n<td>मध्ये 19,182 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>46,858 रु</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही दोन पर्यायांमध्ये सुमारे 720.9 पॉइंट्स एक शेअर घेता, <strong>46,858 रु</strong> 65 च्या एका लॉटसाठी, आणि तुम्ही ट्रेड उघडताच ते तुमच्या खात्यात येते. ते श्रेय तुमचे आहे <strong>जास्तीत जास्त नफा</strong>, फक्त 24,050 रोजी पूर्ण झाले तरच पूर्ण ठेवले जाते, जेथे तुम्ही विकलेले दोन्ही पर्याय निरर्थक कालबाह्य होतात आणि तुमचे काहीही देणे लागत नाही.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-straddle.png\" alt=\"NIFTY वरील शॉर्ट स्ट्रॅडल: 24,050 वर पूर्ण रु. 46,858 क्रेडिट वर एक उलटा व्ही शिखर, 23,329 आणि 24,771 वर ब्रेकेव्हन्स आणि निर्देशांक स्ट्राइकपासून दूर गेल्यावर दोन्ही बाजूंनी मर्यादेशिवाय खाली येणारी नुकसान रेषा. निळ्या डॅशची T+0 रेषा नारिंगी शिखराच्या खाली बसते, वेळेचे मूल्य अद्याप तुमच्या बाजूने क्षीण होणार आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वरील शॉर्ट स्ट्रॅडल: 24,050 वर पूर्ण रु. 46,858 क्रेडिट वर एक उलटा व्ही शिखर, 23,329 आणि 24,771 वर ब्रेकेव्हन्स आणि निर्देशांक स्ट्राइकपासून दूर जात असताना दोन्ही बाजूंनी मर्यादेशिवाय खाली येणारी नुकसान रेषा. निळ्या डॅशची T+0 रेषा नारिंगी शिखराच्या खाली बसलेली आहे, वेळेचे मूल्य अद्याप तुमच्या बाजूने क्षीण होणार आहे.</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-short-straddle\">लहान स्ट्रॅडलच्या तीन संख्या</h2>\n<p>प्रति शेअर एकूण प्रीमियम, 425.8 अधिक 295.1, 720.9 आहे, हाच आकडा ज्याने लांब पल्ला गाठला, कारण तुम्ही फक्त दुसरी बाजू घेतली आहे.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>निव्वळ क्रेडिट गोळा केले</td>\n<td>46,858 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>मोठ्या हालचालीवर उघडले</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>स्ट्राइक वजा, नंतर अधिक, प्रति शेअर एकूण प्रीमियम</td>\n<td>24,050 वजा 720.9 बरोबर 23,329; 24,050 अधिक 720.9 बरोबर 24,771</td>\n</tr>\n</tbody></table>\n<p>NIFTY ब्रेकवेन्स दरम्यान 1,442-पॉइंट बँडमध्ये कुठेही भटकू शकते आणि तरीही तुम्ही काळ्या रंगात पूर्ण करता. 24,771 च्या पलीकडे नग्न कॉलसाठी तुम्हाला कोणत्याही कमाल मर्यादा नसलेल्या रुपयासाठी रुपये मोजावे लागतील आणि 23,329 च्या खाली नग्न पुट संपूर्णपणे खाली NIFTY खरेदी करत राहण्याच्या बंधनासारखे वागते.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>शॉर्ट स्ट्रॅडलचा कमाल नफा 46,858 रुपये आहे आणि तोटा दोन्ही बाजूंनी ओपन एंडेड आहे. तुम्ही नग्न कॉल विकला आहे, त्यामुळे 24,771 वरील कोणत्याही कमाल मर्यादेशिवाय आणि नग्न पुटशिवाय मजबूत रॅलीची किंमत आहे, त्यामुळे क्रॅश 23,329 वरून खाली मजल्यापर्यंत पोहोचेल जेथे निर्देशांक शून्यावर पोहोचेल. वरचे नुकसान खरोखर अमर्यादित आहे; डाउनसाइड फक्त त्या मजल्याने बांधलेला आहे, ज्याचा अर्थ निर्देशांकावर अजूनही इतका मोठा आकृती आहे की तो कोणत्याही व्यावहारिक हेतूसाठी खराब आहे. हे एकाच स्ट्राइकवर स्टॅक केलेले दोन न उघडलेले छोटे पाय आहेत आणि एकच अंतर, वर किंवा खाली, एका सकाळी अनेक महिन्यांचे शांत क्रेडिट मिटवू शकते.</p>\n</div></div>\n<h2 id=\"walking-the-short-straddle-outcomes-at-expiry\">एक्सपायरी येथे शॉर्ट स्ट्रॅडल परिणाम चालणे</h2>\n<p>पाच बंद भावांवर व्यापार सेटल करा. कॉल एक्सपायरीच्या वेळी कमाल (NIFTY′ वजा 24,050, 0) मूल्याचा आहे, पुट कमाल (24,050 वजा NIFTY, 0) मूल्याचा आहे, आणि तुमचे नेट 46,858 रुपये क्रेडिट आहे त्या दोन मूल्यांच्या 65 गुणा वजा.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>24,050 कॉल तुम्ही विकले</th>\n<th>24,050 ला तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>मूल्य 0</td>\n<td>1,050 किमतीची</td>\n<td>उणे २१,३९२ रु</td>\n</tr>\n<tr>\n<td>23,329</td>\n<td>मूल्य 0</td>\n<td>721 किमतीची</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 46,858 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,771</td>\n<td>721 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>1,250 किमतीची</td>\n<td>मूल्य 0</td>\n<td>उणे २१,३९२ रु</td>\n</tr>\n</tbody></table>\n<p>उतरण्यासाठी एकमेव सर्वोत्तम ठिकाण म्हणजे डेड सेंटर, तुम्ही विकलेल्या स्ट्राइकवर, जिथे तुम्ही संपूर्ण क्रेडिट ठेवता. बाहेरून चालत जा आणि नफा कमी होतो, ब्रेकईव्हनवर शून्य ओलांडतो आणि नंतर तोटा कमी होतो, वर कमाल मर्यादा नसते आणि फक्त खाली शून्यावर मजला असतो. लक्षात घ्या की टेबल फक्त 25,300 पर्यंत पोहोचते, जिथे तोटा आधीच 21,392 रुपये आहे आणि अजूनही वाढत आहे. शेवटची पंक्ती नाही, कारण वरच्या बाजूला कमाल नाही.</p>\n<h2 id=\"the-short-strangle-rupee-by-rupee\">लहान गळा घोटणे, रुपयाने रुपया</h2>\n<p>लहान स्ट्रॅडल सर्वात जास्त पैसे देते, परंतु त्याचे ब्रेकइव्हन्स अस्वस्थपणे स्पॉटच्या जवळ बसतात. द <strong>लहान गळा</strong> त्याऐवजी पैसेबाह्य पर्याय विकून त्रुटीसाठी विस्तीर्ण मार्जिन खरेदी करते. तुम्ही 23,950 पुट आणि 24,150 कॉल विकता, दोन्ही पाय जिवंत होण्याआधी प्रत्येक बाजूला एक उशी ठेवा.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>रु. 16,679 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल विक्री</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>रु 24,057 मध्ये</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>40,729 रु</strong></td>\n</tr>\n</tbody></table>\n<p>कारण दोन्ही पाय पैसे बाहेर आहेत, प्रत्येक कमी मिळवते, त्यामुळे <strong>निव्वळ क्रेडिट 40,729 रुपयांपर्यंत घसरले</strong>, स्ट्रॅडलपेक्षा सुमारे 6,000 रुपये कमी. त्या बदल्यात तुम्हाला एकाच शिखराऐवजी मध्यभागी एक सपाट नफ्याचे पठार मिळेल आणि दोन्ही बाजूंनी तुम्हाला त्रास होण्याआधी एक व्यापक सुरक्षित क्षेत्र मिळेल.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-strangle.png\" alt=\"NIFTY वरील लहान गळा: 23,950 आणि 24,150 च्या दरम्यान कुठेही 40,729 रुपयांचे सपाट नफ्याचे पठार, 23,323 आणि 24,777 वर ब्रेकवेव्हन्स आणि एकदा निर्देशांक दोन्ही पंखांच्या पलीकडे गेल्यावर अमर्यादित नुकसान.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वरील लहान गळा: 23,950 आणि 24,150 च्या दरम्यान कुठेही 40,729 रुपयांचे सपाट नफ्याचे पठार, 23,323 आणि 24,777 वर ब्रेकव्हेन्स आणि एकदा निर्देशांक दोन्ही पंखांच्या पलीकडे गेल्यावर अमर्यादित नुकसान.</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-short-strangle\">लघु गळा च्या तीन संख्या</h2>\n<p>प्रति शेअर एकूण प्रीमियम, 256.6 अधिक 370.1, 626.7 आहे आणि ते तुम्ही विकलेल्या दोन स्ट्राइकचे ब्रेकवेव्हन्स सेट करते.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>निव्वळ क्रेडिट गोळा केले</td>\n<td>40,729 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>पंखांच्या पलीकडे अमर्यादित</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>लोअर स्ट्राइक मायनस, अप्पर स्ट्राइक अधिक, प्रति शेअर एकूण प्रीमियम</td>\n<td>23,950 वजा 626.7 बरोबर 23,323; 24,150 अधिक 626.7 बरोबर 24,777</td>\n</tr>\n</tbody></table>\n<p>23,950 आणि 24,150 दरम्यान तुम्ही संपूर्ण क्रेडिट ठेवता, कारण दोन्ही पर्याय त्या बँडमध्ये निरर्थक कालबाह्य होतात. ब्रेकवेन्स, <strong>23,323 आणि 24,777</strong>, स्ट्रॅडलपेक्षा विस्तीर्ण बसा, म्हणूनच ही आवृत्ती अधिक सुरक्षित वाटते. तो नाही. विस्तीर्ण क्षेत्र केवळ धोक्याला उशीर करतो, तो कॅप करत नाही.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>शॉर्ट स्ट्रॅन्गलचा जास्तीत जास्त नफा रु. 40,729 आणि कमाल तोटा आहे जो अजूनही ओपन एंडेड आहे. विस्तीर्ण ब्रेकइव्हन्समुळे ते अधिक सुरक्षित वाटते आणि नफ्याची उच्च संभाव्यता अधिक चापलूस करते, परंतु विकलेले दोन्ही पाय नग्न असतात. 24,777 च्या वर शॉर्ट कॉल कमाल मर्यादेशिवाय रक्तस्त्राव होतो आणि 23,323 च्या खाली शॉर्ट पुट शून्यावर मजल्याकडे धावतो. बंधनाशिवाय पराभूत होऊ शकणाऱ्या व्यापारावरील उच्च विजयाचा दर म्हणजे सुरक्षितता नाही, तो एक धीमा फ्यूज आहे.</p>\n</div></div>\n<h2 id=\"walking-the-short-strangle-outcomes-at-expiry\">एक्सपायरी येथे लहान गळा परिणाम चालणे</h2>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>23,950 ला तुम्ही विकले</th>\n<th>24,150 कॉल तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>950 किमतीची</td>\n<td>मूल्य 0</td>\n<td>उणे रु 21,021</td>\n</tr>\n<tr>\n<td>23,323</td>\n<td>627 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 40,729 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,777</td>\n<td>मूल्य 0</td>\n<td>627 किमतीची</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>मूल्य 0</td>\n<td>1,150 किमतीची</td>\n<td>उणे रु. 34,021</td>\n</tr>\n</tbody></table>\n<p>स्ट्रॅडलचा उलटा V टेबलटॉपमध्ये सपाट झाला आहे. संपूर्ण श्रेय मध्यवर्ती बँडमध्ये कुठेही तुमचेच आहे, नंतर ओळ पंखांच्या बाहेर खाली वळते आणि दोन्ही बाजूंनी खाली पडते, वर कमाल मर्यादा नाही आणि खाली फक्त शून्यावर मजला आहे. पठार म्हणजे आराम, पडणाऱ्या शेपट्या धोक्याची असतात आणि शेपटी कधीच थांबत नाहीत.</p>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>द <strong>नफ्याची संभाव्यता स्ट्रॅडलसाठी 58 टक्के आणि स्ट्रॅगलसाठी 59 टक्के आहे</strong>, दोन्ही आरामात अर्ध्यापेक्षा जास्त, कारण बहुतेक महिने NIFTY कोणत्याही प्रकारे 720 गुणांचा प्रवास करत नाही. हा उच्च विजयाचा दर हा प्रीमियम विक्रीचा संपूर्ण मोह आहे आणि हेच हे व्यवहार अविचारी लोकांसाठी धोकादायक बनवते.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>58 किंवा 59 टक्के जिंकण्याचा दर म्हणजे तुम्ही पुन्हा पुन्हा क्रेडिट गोळा कराल, शांत आत्मविश्वास निर्माण कराल आणि शेवटी येणारा दुर्मिळ तोटा आधीच्या प्रत्येक नफ्यापेक्षा कितीतरी पटीने मोठा असू शकतो. नेहमी त्या खुशामत करणाऱ्या संभाव्यतेच्या पुढे अमर्यादित कमाल तोटा वाचा, कधीही एकटे नाही. बाजार-निहित शक्यता देखील कालबाह्य होण्यासाठी एकच होल्ड गृहीत धरतात, परंतु बहुतेक विक्रेते कधीही तितकी प्रतीक्षा करत नाहीत: क्रेडिटचा मोठा भाग क्षय झाला की ते व्यापार बंद करतात किंवा अमर्यादित धोका पत्करण्याऐवजी लहान नुकसान स्वीकारून, ब्रेकवेनचा धोका पत्करून बाहेर पडतात. या कोर्समधील कोणत्याही परिभाषित-जोखीम व्यापारापेक्षा येथे निर्गमन योजना अधिक महत्त्वाची आहे.</p>\n</div></div>\n<h2 id=\"margin\">समास</h2>\n<p>येथेच नग्न विक्रीची प्रामाणिक किंमत दिसून येते. एक्सचेंज ब्लॉक्स् बद्दल <strong>शॉर्ट स्ट्रॅडलसाठी रुपये 162,339 आणि शॉर्ट स्ट्रॅडलसाठी 162,195 रुपये</strong>, जड SPAN घटक अधिक एक्सपोजर बफर बनलेले, तंतोतंत कारण तोटा ओपन एंडेड आहे. काही लाखो रुपयांचे प्रीमियम गोळा करण्यासाठी तुम्ही दीड लाखाहून अधिक भांडवल लावत आहात.</p>\n<p>ते तुम्हाला त्याच्या व्यापाराचा न्याय करू देते <strong>मार्जिन वर परत</strong>. स्ट्रॅडल रु. 162,339 विरुद्ध रु. 46,858 जमा करते, सुमारे <strong>29 टक्के</strong> जर ते कार्य करते. सुमारे 162,195 रुपयांच्या तुलनेत गळा दाबून 40,729 रुपये जमा होतात <strong>25 टक्के</strong>. ते श्रीमंत दिसतात, परंतु आकृती अशा स्थितीची प्रशंसा करते ज्याची नकारात्मक बाजू अमर्यादित आहे. एका खराब महिन्यासाठी तुमचा 29 टक्के खर्च होत नाही, तो संपूर्ण मार्जिनच्या पटीत खर्च करू शकतो.</p>\n<h2 id=\"time-decay-is-your-ally\">वेळेचा क्षय हा तुमचा सहयोगी आहे</h2>\n<p>वर पुन्हा पहा <strong>निळ्या डॅशची T+0 रेखा</strong> प्रत्येक चार्टच्या मध्यभागी नारिंगी ॲट-एक्सपायरी शिखराच्या खाली बसणे. हे अंतर अद्याप वितळले जाणारे वेळेचे मूल्य आहे आणि विक्रेता म्हणून तुम्हाला त्याचे पैसे दिले जातात. प्रत्येक शांत दिवशी निळी रेषा केशरी रेषेकडे वळते कारण तुम्ही गोळा केलेला प्रीमियम तुमच्या बाजूने खराब होतो. वेळेचा क्षय, शेवटच्या अध्यायातील खरेदीदाराचा शत्रू, आता तुमचा सहयोगी आहे. संपूर्ण व्यापार हा एक खेळी आहे ज्याचा क्षय तुम्हाला दुखावणाऱ्या कोणत्याही हालचालीपेक्षा वेगाने येतो.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>जर तुम्ही अशा प्रकारे प्रीमियम विकत असाल, तर तोटा भरून काढण्याच्या योजनेशिवाय कधीही नग्न शॉर्ट स्ट्रॅडल धरू नका किंवा गळा दाबू नका. व्यावसायिक निराकरण म्हणजे एक स्वस्त, अधिक पैसे नसलेला कॉल खरेदी करणे आणि विमा म्हणून ठेवणे, जे अमर्यादित शेपटी ज्ञात संख्यांमध्ये बदलते आणि व्यापाराचे रूपांतर लोखंडी माशी किंवा लोखंडी कंडरमध्ये करते. या अचूक कल्पनेच्या त्या परिभाषित-जोखीम आवृत्त्या आहेत आणि त्या पुढील अध्यायात जातात. नवशिक्याने लहान स्ट्रॅडल आणि गळा दाबणे शिकले पाहिजे मुख्यतः त्यांचा आदर करण्यासाठी, त्यांना नग्न ठेवण्यासाठी नाही.</p>\n</div></div>\n<h2 id=\"the-two-trades-side-by-side\">दोघे शेजारी शेजारी व्यवहार करतात</h2>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>लहान स्ट्रॅडल</th>\n<th>लहान गळा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>46,858 रु</td>\n<td>40,729 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>अमर्यादित</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>23,329 आणि 24,771</td>\n<td>23,323 आणि 24,777</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>58 टक्के</td>\n<td>59 टक्के</td>\n</tr>\n<tr>\n<td>निव्वळ क्रेडिट</td>\n<td>46,858 रु</td>\n<td>40,729 रु</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>रु. 162,339</td>\n<td>रु. 162,195</td>\n</tr>\n</tbody></table>\n<p>स्तंभ वाचा आणि सौदा स्पष्ट आहे. स्ट्रॅडल अधिक घट्ट सुरक्षित क्षेत्रासह मोठे क्रेडिट गोळा करते, स्ट्रॅडल चुकीचे असण्यासाठी अधिक जागा देऊन कमी गोळा करते आणि दोघेही बहुतेक वेळा जिंकतात. ते एक वैशिष्ट्य देखील सामायिक करतात ज्याने नवशिक्या विराम द्यावा: नुकसानास मर्यादा नाही आणि फरक मोठा आहे. तुम्ही काही हजार रुपये गोळा करता आणि स्वत:ला अशा शेपटीत उघडे पाडता जे तुम्ही कधीही घेतलेल्यापेक्षा कितीतरी जास्त घेऊ शकतात.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>तुम्ही दोन्हीमध्ये रिहर्सल करू शकता <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong>, कॉल आणि पुट विकणे आणि स्ट्रॅडलचा उलटा व्ही पाहणे स्ट्रॅगलच्या टेबलटॉपमध्ये पसरत असताना तुम्ही स्ट्राइक अलग पाडता. मॉडेल केलेली किंमत ब्रेकईव्हनच्या दिशेने सरकवा आणि खाली पडणारी शेपटी चालूच राहते, कमाल मर्यादा नसलेली वरची बाजू आणि डाउनसाइड फक्त शून्याने बांधलेली पहा. दोन्ही भाग एकाच वेळी अनुभवा: तुमच्या बाजूने होणारा क्षय दररोजचा शांत खेचणे, आणि दोन्ही बाजूंनी एक हिंसक सत्र तुम्हाला पाठवू शकते. हा ताण, अनकॅप्ड शेपटी विरुद्ध स्थिर उत्पन्न, प्रत्येक प्रीमियम विक्रेता यासह जगतो.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>एक लहान स्ट्रॅडल ॲट-द-मनी कॉल आणि पुट विकतो, एक लहान स्ट्रॅडल स्वस्त आउट-ऑफ-द-मनी स्ट्राइक विकतो आणि दोन्ही गोळा करतात <strong>निव्वळ क्रेडिट</strong> तो जास्तीत जास्त नफा आहे.</li>\n<li>स्ट्रॅडल आत घेते <strong>46,858 रु</strong> 23,329 आणि 24,771 वर breakevens सह; गळा आत घेते <strong>40,729 रु</strong> 23,323 ते 24,777 च्या विस्तृत सुरक्षित क्षेत्रासह.</li>\n<li>द <strong>जास्तीत जास्त नुकसान दोन्ही बाजूंनी ओपन-एंडेड आहे</strong> प्रत्येक व्यापाराचा, वरच्या बाजूने खरोखर अमर्यादित आणि नकारात्मक बाजूने बांधलेला असला तरी खूप मोठा आहे, कारण प्रत्येक विकलेला पाय नग्न आहे, आणि ही वस्तुस्थिती आहे जी प्रत्येक गोष्टीवर नियंत्रण ठेवते.</li>\n<li>द <strong>नफा होण्याची शक्यता जास्त आहे</strong>, 58 आणि 59 टक्के, जे प्रलोभन आहे; एकच दुर्मिळ पराभव लहान विजयांच्या दीर्घ रनला कमी करू शकतो.</li>\n<li><strong>मार्जिन मोठा आहे</strong>, प्रत्येकासाठी सुमारे रु 1.62 लाख, आणि वेळेचा क्षय तुमच्या बाजूने काम करतो, परंतु मार्जिनवर श्रीमंत दिसणारा परतावा मोकळ्या शेपटीच्या स्थितीची चापलूस करतो.</li>\n<li>नवशिक्याने त्यांचा आदर करण्यासाठी हे शिकले पाहिजे, नंतर शेपटीला कुंपण घालावे. पुढचा अध्याय हा अचूक उत्पन्न आकार परिभाषित-जोखमीच्या लोह कंडोरमध्ये बदलतो.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"लहान स्ट्रॅडल, रुपयाने रुपया","id":"the-short-straddle-rupee-by-rupee"},{"level":2,"text":"लहान स्ट्रॅडलच्या तीन संख्या","id":"the-three-numbers-of-the-short-straddle"},{"level":2,"text":"एक्सपायरी येथे शॉर्ट स्ट्रॅडल परिणाम चालणे","id":"walking-the-short-straddle-outcomes-at-expiry"},{"level":2,"text":"लहान गळा घोटणे, रुपयाने रुपया","id":"the-short-strangle-rupee-by-rupee"},{"level":2,"text":"लघु गळा च्या तीन संख्या","id":"the-three-numbers-of-the-short-strangle"},{"level":2,"text":"एक्सपायरी येथे लहान गळा परिणाम चालणे","id":"walking-the-short-strangle-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"समास","id":"margin"},{"level":2,"text":"वेळेचा क्षय हा तुमचा सहयोगी आहे","id":"time-decay-is-your-ally"},{"level":2,"text":"दोघे शेजारी शेजारी व्यवहार करतात","id":"the-two-trades-side-by-side"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"15":{"html":"<p>शेवटच्या प्रकरणातील लहान गळा मध्ये एक सुंदर उत्पन्न आकार आणि एक जीवघेणा दोष होता, शेपूट जे कायमचे पडले. तोटा अंतर्गत कठोर मजला टाकताना तुम्ही स्थिर प्रीमियम ठेवू शकता का हा स्पष्ट प्रश्न आहे. आपण हे करू शकता, आणि ते करणारी रचना आहे <strong>लोखंडी कंडर</strong>, पर्यायांच्या जगात सर्वात लोकप्रिय परिभाषित-जोखीम उत्पन्न व्यापार. विकले गेलेले गळफास घ्या आणि एक स्वस्त विकत घ्या, पुढे पैसे नसलेले कॉल आणि विमा म्हणून ठेवा. ते दोन विकत घेतलेले पंख अमर्यादित शेपटीला ज्ञात संख्येत बदलतात, चार पायांची रचना सोडतात जी एका मर्यादेत नफा मिळवते आणि निश्चित, माफक रकमेपेक्षा जास्त कधीही गमावू शकत नाही. NIFTY, देशातील सर्वात खोल निर्देशांक पर्याय बाजार, त्याचे नैसर्गिक घर आहे.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>लोखंडी कंडर हे दोन उभ्या स्प्रेड असतात ज्यात एक एक्सपायरी सामायिक होते, अ <strong>बैल पसरला</strong> downside वर आणि a <strong>अस्वल कॉल पसरला</strong> वरच्या बाजूस, वर्तमान किंमतीच्या आसपास ठेवलेले आहे. दोन आतील स्ट्राइक प्रीमियम गोळा करण्यासाठी विकले जातात आणि प्रत्येक शेपटीला टोपी देण्यासाठी दोन बाह्य पंख विकत घेतले जातात. या संपूर्ण गोष्टीला ज्ञात जास्तीत जास्त नफा आणि ज्ञात कमाल तोटा आहे, दोन्ही बाजूंना कोणताही खुला खडक नाही.</p>\n<p>तुम्हाला समजलेच पाहिजे असा एक ट्विस्ट आहे आणि तो या धड्याच्या केंद्रस्थानी आहे. OpenAlgo बिल्डर समान चार स्ट्राइकचे दोन चेहरे ऑफर करतो, a <strong>लांब लोखंडी कंडोर</strong> आणि अ <strong>लहान लोह कंडोर</strong>, आणि कोणता तुम्हाला बसेल हे पूर्णपणे तुम्हाला हव्या असलेल्या शक्यतांवर अवलंबून आहे, बटणावरील शब्दांवर नाही.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>लोखंडी कंडोर म्हणजे बुल पुट स्प्रेड आणि एक एक्स्पायरी शेअरिंग बेअर कॉल स्प्रेड. आतील विकले गेलेले स्ट्राइक प्रीमियम गोळा करतात, बाहेरील विकत घेतलेल्या पंख दोन्ही शेपटीला टोपी देतात. ही शॉर्ट स्ट्रॅन्गलची परिभाषित-जोखीम आवृत्ती आहे, समान श्रेणी-बद्ध उत्पन्न आकार आहे, परंतु उघड्या शेपटीच्या ऐवजी ज्ञात, लहान कमाल तोटा आहे.</p>\n</div></div>\n<h2 id=\"the-long-iron-condor-rupee-by-rupee\">लांबलचक लोखंडी कंडोर, रुपयाने रुपया</h2>\n<p>बिल्डरने कॉल केलेली आवृत्ती येथे आहे <strong>लांब लोखंडी कंडोर</strong>, रिअल NIFTY वर 26 जून 2026 रोजी निर्देशांकासह किमती पकडल्या गेल्या <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत सुमारे 32 दिवस संपत आहे. हे पैशाला घट्ट बांधलेले आहे, आतील स्ट्राइक स्पॉटपासून फक्त दोन पावले आणि पंख त्यांच्या पलीकडे शंभर पॉइंट्सवर आहेत.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>23,850</td>\n<td>224.1 भरले</td>\n<td>14,567 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>रु. 16,679 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल विक्री</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>रु 24,057 मध्ये</td>\n</tr>\n<tr>\n<td>4</td>\n<td>कॉल खरेदी करा</td>\n<td>24,250</td>\n<td>316.1 भरले</td>\n<td>20,547 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>रु. 5,616 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>23,950 पुट आणि 24,150 कॉल हे दोन आतील विकले जाणारे पर्याय शॉर्ट स्ट्रँगल सारखेच आहेत आणि बहुतेक प्रीमियम आणतात. 23,850 पुट आणि 24,250 कॉल या दोन बाह्य खरेदी पर्यायांची किंमत थोडीशी आहे आणि विमा म्हणून कार्य करते, प्रत्येक शेपटीला शंभर गुणांची मर्यादा घालते. निव्वळ ए <strong>5,616 रुपये क्रेडिट</strong> जेव्हा तुम्ही व्यापार उघडता तेव्हा ते तुमच्या खात्यात येते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-iron-condor.png\" alt=\"NIFTY वरील लाँग आयर्न कंडोर: 23,950 आणि 24,150 शॉर्ट स्ट्राइक दरम्यान 5,616 रुपयांचे सपाट नफ्याचे पठार, 23,864 आणि 24,236 वर ब्रेकइव्हन्स आणि एकदा निर्देशांकाने दोन्ही बाजूंना धक्का दिला की फक्त रु. 884 चा मर्यादित तोटा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वरील लाँग आयर्न कंडोर: 23,950 आणि 24,150 शॉर्ट स्ट्राइक दरम्यान 5,616 रुपयांचा सपाट नफ्याचा पठार, 23,864 आणि 24,236 वर ब्रेकइव्हन्स आणि एकदा निर्देशांकाने दोन्ही बाजूंना धक्का दिला की फक्त रु. 884 चा मर्यादित तोटा.</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-long-iron-condor\">लांब लोखंडी कंडोरच्या तीन संख्या</h2>\n<p>प्रति शेअर क्रेडिट 5,616 रुपये आहे भागिले 65, सुमारे 86.4 गुण, आणि हा एकच आकडा दोन आतील शॉर्ट स्ट्राइकच्या ब्रेकवेव्हन्स सेट करतो.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>निव्वळ क्रेडिट गोळा केले</td>\n<td>५,६१६ रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>विंग रुंदी वजा क्रेडिट</td>\n<td>रु. 6,500 वजा रु 5,616 म्हणजे रु. 884</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>अंतर्गत शॉर्ट स्ट्राइक वजा, नंतर अधिक, प्रति शेअर क्रेडिट</td>\n<td>23,950 वजा 86.4 बरोबर 23,864; 24,150 अधिक 86.4 बरोबर 24,236</td>\n</tr>\n</tbody></table>\n<p><strong>कमाल नफा क्रेडिट आहे, रु 5,616</strong>, 23,950 आणि 24,150 च्या अंतर्गत स्ट्राइक दरम्यान NIFTY पूर्ण झाल्यास पूर्ण ठेवली जाईल. <strong>कमाल नुकसान रु 884 वर कुंपण केले आहे.</strong> प्रत्येक विंग 100 पॉइंट रुंद आहे, 65 च्या लॉटवर 6,500 रुपये किमतीची आहे आणि तुम्ही त्यातील 5,616 रुपये आधीच गोळा केले आहेत, त्यामुळे तुम्ही सर्वात जास्त गमावू शकता ते अंतर आहे. सर्वात वाईट केस अमर्यादित, नग्न गळा दाबून, ज्ञात 884 रुपयांपर्यंत गेली आहे.</p>\n<h2 id=\"walking-the-long-iron-condor-outcomes-at-expiry\">लांब लोखंडी कंडर चालणे समाप्ती वेळी परिणाम</h2>\n<p>एक्सपायरीच्या वेळी प्रत्येक पाय त्याच्या अंतर्गत मूल्याप्रमाणे घेऊन, पाच बंद किंमतींवर व्यापार सेटल करा. लांब पाय तुम्हाला मदत करतात, लहान पाय तुमची किंमत मोजतात, आणि निव्वळ रु 5,616 क्रेडिट अधिक लांब मूल्य वजा लहान मूल्ये, गुणा 65.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>23,850 पुट (लांब)</th>\n<th>23,950 पुट (लहान)</th>\n<th>24,150 कॉल (लहान)</th>\n<th>24,250 कॉल (लांब)</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,700</td>\n<td>150 किमतीची</td>\n<td>250 किमतीची</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 884 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>23,864</td>\n<td>मूल्य 0</td>\n<td>86 किमतीची</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 5,616 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,236</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>86 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>250 किमतीची</td>\n<td>150 किमतीची</td>\n<td>उणे रु 884 (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>पंक्तींमध्ये वाचा आणि आकार एक सपाट-टॉप केलेला टेबल आहे. अंतर्गत स्ट्राइक दरम्यान आपण संपूर्ण क्रेडिट ठेवा. एका पंखातून पुढे जा आणि तोटा रु. 884 वर मर्यादित आहे, कारण विकत घेतलेला पाय त्याच्या पलीकडे असलेल्या पॉइंटसाठी विकलेल्या लेग पॉइंटशी जुळतो. 24,056 वरील गुलाबी स्पॉट लाइन पठाराच्या आत बसते, म्हणून आज तुम्ही फायदेशीर झोनमध्ये आहात.</p>\n<h2 id=\"the-honest-catch-a-narrow-band-and-low-odds\">प्रामाणिक झेल: एक अरुंद बँड आणि कमी शक्यता</h2>\n<p>परंतु नफ्याचा पट्टा किती संकुचित आहे ते पहा. ब्रेकइव्हन्स स्पॉटच्या प्रत्येक बाजूला फक्त 190 पॉइंट्स आहेत आणि चार्ट शो NIFTY वर सिग्मा बँड एक्स्पायरीपर्यंत तीन किंवा चार वेळा सहज प्रवास करू शकतात. म्हणूनच द <strong>नफ्याची शक्यता फक्त 17 टक्के आहे</strong>. रचना त्याच्या जोखमीच्या विरूद्ध सुंदरपणे पैसे देते, अ <strong>सुमारे 1 ते 6.4 च्या जोखमीसाठी बक्षीस</strong>, कारण आतील स्ट्राइक पैसे मिठी मारतात आणि एक श्रीमंत क्रेडिट गोळा करतात. त्या रिच क्रेडिटची किंमत एक घट्ट, कमी शक्यता नसलेला नफा क्षेत्र आहे, त्यामुळे तुम्हाला रु. 884 च्या छोट्या तोट्यासह आणि कधी कधी पूर्ण रु. 5,616 सह दूर जाण्याची शक्यता आहे.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>1 ते 6.4 च्या जोखमीचे बक्षीस जोपर्यंत तुम्ही त्याच्या बाजूला नफ्याची 17 टक्के संभाव्यता वाचत नाही तोपर्यंत ते आश्चर्यकारक दिसते. बाजार संभाव्य इव्हेंटवर सहा-ते-एक मोबदला देत नाही. मोठे क्रेडिट आणि लहान जोखीम एका अरुंद बँडसह दिले जाते जे NIFTY सहसा सुटते.</p>\n</div></div>\n<h2 id=\"the-short-iron-condor-the-high-probability-inverse\">लहान लोखंडी कंडर, उच्च संभाव्यता व्युत्क्रम</h2>\n<p>बिल्डर अचूक आरसा देखील देतो, ज्याला तो म्हणतात <strong>लहान लोह कंडोर</strong>. तुम्ही चारही पायांची दुसरी बाजू घ्या, आतील स्ट्राइक विकत घ्या आणि बाहेरील पंख विकता आणि क्रेडिट गोळा करण्याऐवजी डेबिट भरा.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>23,850</td>\n<td>224.1 प्राप्त झाले</td>\n<td>14,567 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>पुट खरेदी करा</td>\n<td>23,950</td>\n<td>२५६.६ भरले</td>\n<td>16,679 रु</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल खरेदी करा</td>\n<td>24,150</td>\n<td>370.1 भरले</td>\n<td>24,057 रु</td>\n</tr>\n<tr>\n<td>4</td>\n<td>कॉल विक्री</td>\n<td>24,250</td>\n<td>316.1 प्राप्त झाले</td>\n<td>20,547 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>5,616 रु</strong></td>\n</tr>\n</tbody></table>\n<p>कारण ते व्यस्त आहे, प्रत्येक संख्या पलटते. तुम्ही आता प्रवेश करण्यासाठी रु. 5,616 अदा करा आणि जेव्हाहीNIFTY′ डेड सेंटरपासून दूर जाल तेव्हा नफा द्या.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>विंग रुंदी वजा डेबिट</td>\n<td>रु. 6,500 वजा रु 5,616 म्हणजे रु. 884</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>डेबिट भरले</td>\n<td>५,६१६ रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>लांब आवृत्ती प्रमाणेच</td>\n<td>23,864 आणि 24,236</td>\n</tr>\n</tbody></table>\n<p>द <strong>कमाल नफा रु 884 आहे</strong>, जेव्हा जेव्हा NIFTY ब्रेकवेन्सच्या बाहेर पूर्ण होते, तेव्हा अरुंद मध्यवर्ती बँडमध्ये पिन केलेले वगळता कुठेही मिळवले जाते. द <strong>कमाल तोटा रु 5,616 आहे</strong>, NIFTY आतील स्ट्राइक दरम्यान सेटल झाल्यासच त्रास सहन करावा लागतो. मथळा आहे <strong>83 टक्के नफा मिळण्याची शक्यता</strong>, कारण NIFTY जवळजवळ नेहमीच 32 दिवसांमध्ये मृत केंद्रापासून दूर जाते आणि अशा कोणत्याही ड्रिफ्ट या आवृत्तीला त्याचा छोटासा विजय मिळतो.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-iron-condor.png\" alt=\"NIFTY वरील शॉर्ट आयर्न कंडोर: व्यस्त आकार, 23,864 ते 24,236 बँडच्या बाहेर कुठेही 884 रुपयांचा लहान नफा, परंतु 83 टक्के नफ्याच्या संभाव्यतेसह निर्देशांक कालबाह्यतेच्या वेळी सेंट्रल झोनला पिन केल्यास रु. 5,616 नुकसान.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वरील शॉर्ट आयर्न कंडोर: व्यस्त आकार, 23,864 ते 24,236 बँडच्या बाहेर कुठेही 884 रुपयांचा लहान नफा, परंतु 83 टक्के नफ्याच्या संभाव्यतेसह निर्देशांक कालबाह्यतेच्या वेळी सेंट्रल झोनला पिन केल्यास रु. 5,616 नुकसान.</figcaption></figure>\n<h2 id=\"walking-the-short-iron-condor-outcomes-at-expiry\">लहान लोह कंडोर चालणे कालबाह्यतेवर परिणाम</h2>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>23,850 पुट (लहान)</th>\n<th>23,950 पुट (लांब)</th>\n<th>24,150 कॉल (लांब)</th>\n<th>२४,२५० कॉल (लहान)</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,700</td>\n<td>150 किमतीची</td>\n<td>250 किमतीची</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>अधिक रु 884 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>23,864</td>\n<td>मूल्य 0</td>\n<td>86 किमतीची</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>उणे रु 5,616 (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,236</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>86 किमतीची</td>\n<td>मूल्य 0</td>\n<td>रु 0 (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>मूल्य 0</td>\n<td>मूल्य 0</td>\n<td>250 किमतीची</td>\n<td>150 किमतीची</td>\n<td>अधिक रु 884 (कमाल नफा)</td>\n</tr>\n</tbody></table>\n<p>तर तुमच्याकडे एक रचना आणि दोन चेहरे आहेत. एक मोठा क्रेडिट गोळा करतो आणि क्वचितच ठेवतो; दुसरा डेबिट भरतो, बहुतेक वेळा थोडा जिंकतो, आणि क्वचित प्रसंगी बरेच काही गमावतो NIFTY मध्यभागी पिन करतो, जेथे लांब लोखंडी कंडर सर्वात आनंदी असतो.</p>\n<h2 id=\"your-odds-and-choosing-strikes-to-match-them\">तुमची शक्यता आणि त्यांच्याशी जुळण्यासाठी स्ट्राइक निवडणे</h2>\n<p>ही जोडी प्रामाणिकपणे शक्यता वाचण्याबद्दल अभ्यासक्रमातील सर्वात स्पष्ट धडा आहे. पाठलाग करणारा व्यापारी <strong>उत्पन्न</strong> अनेकदा योग्य होऊ इच्छित आहे, त्यामुळे <strong>उच्च संभाव्यता बाजू</strong>, 83 टक्के शॉर्ट आयर्न कॉन्डर, अभ्यास करण्यासाठी आहे. पाठलाग करणाऱ्या व्यापाऱ्याने ए <strong>शांत कालबाह्यतेवर मोठा मोबदला</strong> 17 टक्के लाँग आयर्न कॉन्डोर हवा आहे, जे NIFTY रेंज पिन करते तेव्हा सहा ते एक देते.</p>\n<p>पण एक सखोल मुद्दा आहे. हे घट्ट स्ट्राइक केवळ तुम्ही तयार करू शकतील असे नाही. ए <strong>क्लासिक इन्कम आयरन कंडोर पैशातून पुढे स्ट्राइक विकतो</strong>, शॉर्ट पुट आणि शॉर्ट कॉल स्पॉटपासून दूर ढकलणे. यामुळे नफ्याचा बँड रुंदावतो, नफ्याची शक्यता वाढते आणि क्रेडिट कमी होते. तुम्ही चांगल्या शक्यता आणि शांत रात्रीसाठी एक लहान बक्षीस खरेदी करता.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तुम्हाला हव्या असलेल्या नफ्याच्या संभाव्यतेशी जुळण्यासाठी तुम्ही सेट केलेल्या डायलप्रमाणे स्ट्राइकचा उपचार करा. मोठ्या क्रेडिटसाठी आणि कमी शक्यतांसाठी आतील स्ट्राइक पैशाच्या जवळ विका, जसे की येथे घट्ट लाँग आयर्न कॉन्डोर. त्यांना अधिक विस्तीर्ण बँडसाठी, नफ्याची उच्च संभाव्यता आणि कमी क्रेडिटसाठी विक्री करा. प्रत्येक वेळी जास्तीत जास्त तोट्याच्या बाजूला फायद्याची संभाव्यता वाचा आणि तुम्ही जगू शकणाऱ्या शक्यता देणारे स्ट्राइक निवडा.</p>\n</div></div>\n<h2 id=\"margin\">समास</h2>\n<p>एकतर तो बांधलेल्या उघड्या गळा पेक्षा खूपच कमी फेस ब्लॉक्स्, कारण विकत घेतलेले पंख नुकसान भरून काढतात. द <strong>लाँग आयर्न कॉन्डोरला सुमारे 64,319 रुपये लागतात</strong>, द <strong>शॉर्ट आयर्न कॉन्डोर सुमारे 68,864 रु</strong>, चार पाय प्रतिबिंबित करून एक्सचेंजने ट्रॅक करणे आवश्यक आहे. तुमची खरी रोकड धोक्यात असली तरी, केवळ परिभाषित कमाल तोटा आहे, लांब आवृत्तीवर रु. 884 किंवा लहान आवृत्तीवर रु. 5,616.</p>\n<p>चालू <strong>मार्जिन वर परत</strong>, लाँग आयर्न कंडोर रु. 64,319 च्या तुलनेत 5,616 रु. <strong>9 टक्के</strong> जर तो जिंकला, परंतु तो फक्त 17 टक्के वेळा जिंकतो. शॉर्ट आयर्न कंडोर 68,864 रुपयांच्या तुलनेत 884 रुपये देते, फक्त <strong>1.3 टक्के</strong> जेव्हा तो जिंकतो, परंतु तो 83 टक्के वेळा जिंकतो. कोणत्याही आकृतीचा अर्थ त्याच्या बाजूच्या संभाव्यतेशिवाय जास्त नाही.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>दोन चेहरे घड्याळाच्या विरुद्ध बाजूला बसतात. द <strong>लाँग आयर्न कॉन्डोर हे निव्वळ क्रेडिट आहे</strong>, त्यामुळे तुम्ही बँडमध्ये प्रीमियमचे निव्वळ विक्रेता आहात आणि <strong>वेळ क्षय आपल्यासाठी कार्य करते</strong>: प्रत्येक शांत दिवशी निळ्या रंगाची T+0 रेषा नारिंगी पठाराकडे जाते कारण तुम्ही गोळा केलेला प्रीमियम वितळतो. द <strong>शॉर्ट आयर्न कॉन्डोर हे निव्वळ डेबिट आहे</strong>, म्हणून तुम्ही निव्वळ खरेदीदार आहात आणि <strong>वेळ क्षय आपल्या विरुद्ध कार्य करते</strong>: घड्याळाची स्थिती खराब होण्यापूर्वी बँडमधून बाहेर पडण्यासाठी तुम्हाला NIFTY आवश्यक आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>बिल्डरच्या लाँग आणि शॉर्ट या शब्दांवर विश्वास ठेवू नका आणि क्रेडिट म्हणजे चांगला ट्रेड किंवा डेबिट म्हणजे वाईट असे समजू नका. येथे लाँग आयर्न कंडोर ही क्रेडिट आवृत्ती आहे आणि शॉर्ट आयर्न कॉन्डोर ही डेबिट आवृत्ती आहे, जी बहुतेक लोकांच्या अंतर्ज्ञानाविरुद्ध चालते. कोणत्याही संरचनेचा न्याय करण्याचा एकमेव प्रामाणिक मार्ग म्हणजे त्याचे नऊ आकडे वाचणे आणि क्रेडिट किंवा डेबिट तुम्हाला अपेक्षित असलेल्या निकालाशी जुळतात की नाही. लेबल तुमची दिशाभूल करू शकते. संख्या शक्य नाही.</p>\n</div></div>\n<h2 id=\"the-two-faces-side-by-side\">दोन्ही तोंडे शेजारी</h2>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>लांब लोखंडी कंडोर</th>\n<th>लहान लोह कंडोर</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>५,६१६ रु</td>\n<td>रु 884</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>रु 884</td>\n<td>५,६१६ रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>23,864 आणि 24,236</td>\n<td>23,864 आणि 24,236</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>17 टक्के</td>\n<td>83 टक्के</td>\n</tr>\n<tr>\n<td>निव्वळ क्रेडिट किंवा डेबिट</td>\n<td>क्रेडिट रु 5,616</td>\n<td>डेबिट रु 5,616</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>64,319 रु</td>\n<td>68,864 रु</td>\n</tr>\n</tbody></table>\n<p>कोणत्याही प्रकारे स्थिती परिभाषित-जोखीम, तिकिटावर छापलेली सर्वात वाईट केस, एका बाजूला 884 रुपये किंवा दुसरीकडे 5,616 रुपये. केवळ तेच लोखंडी कंडर ज्यापासून ते बांधले गेले आहे त्याहून अधिक सुरक्षित बनवते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>दोन्ही चेहरे तयार करा <strong>सँडबॉक्स ट्रेडिंग (Analyser मोड OpenAlgo मध्ये)</strong>, चार पाय जोडणे आणि पठाराचे स्वरूप पाहणे, नंतर परतफेड उलथापालथ पाहण्यासाठी प्रत्येक पाय फ्लिप करणे. लहान स्ट्राइक बाहेरून ड्रॅग करा आणि बँड रुंद होताना आणि नफा वाढण्याची शक्यता पहा.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>एक लोखंडी कंडर आहे a <strong>बुल पुट स्प्रेड प्लस अ बेअर कॉल स्प्रेड</strong> एका कालबाह्यतेवर; आतील विकले जाणारे स्ट्राइक प्रीमियम गोळा करतात आणि बाहेरील पंख दोन्ही शेपटी एका निश्चित कमाल तोट्यात ठेवतात.</li>\n<li>बिल्डरचे <strong>लाँग आयर्न कॉन्डोर ही क्रेडिट आवृत्ती आहे</strong>: ते रु. 5,616 मध्ये घेते, फक्त रु. 884 जोखीम घेते, परंतु त्याची घट्ट बँड फक्त नफा होण्याची शक्यता देते <strong>17 टक्के</strong>.</li>\n<li>द <strong>शॉर्ट आयर्न कॉन्डोर ही डेबिट आवृत्ती आहे</strong>: ते 5,616 रुपये देते, फक्त 884 रुपये कमावते, पण जिंकते <strong>83 टक्के</strong> त्या वेळेचे कारण NIFTY सहसा मध्यभागी वाहून जाते.</li>\n<li>कमाल नुकसान आहे <strong>विंग रुंदी वजा क्रेडिट</strong> लांब आवृत्तीवर (रु. 6,500 वजा 5,616 रु. 884 च्या बरोबरीचे) आणि फक्त <strong>डेबिट</strong> लहान आवृत्तीवर, दोन्हीसाठी 23,864 आणि 24,236 वर breakevens सह.</li>\n<li>संप हे ए <strong>शक्यतांसाठी डायल करा</strong>: क्लासिक इन्कम कंडोर विस्तीर्ण बँड, उच्च शक्यता आणि लहान क्रेडिटसाठी पैशातून पुढे विकतो. दोन्ही चेहरे माफक फरकाने परिभाषित-जोखीम आहेत, आणि वेळेचा क्षय क्रेडिट आवृत्तीला मदत करते आणि डेबिटला दुखापत करते. प्रत्येकाला त्याच्या नऊ संख्येने न्याय द्या, त्याच्या लेबलवर कधीही.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"लांबलचक लोखंडी कंडोर, रुपयाने रुपया","id":"the-long-iron-condor-rupee-by-rupee"},{"level":2,"text":"लांब लोखंडी कंडोरच्या तीन संख्या","id":"the-three-numbers-of-the-long-iron-condor"},{"level":2,"text":"लांब लोखंडी कंडर चालणे समाप्ती वेळी परिणाम","id":"walking-the-long-iron-condor-outcomes-at-expiry"},{"level":2,"text":"प्रामाणिक झेल: एक अरुंद बँड आणि कमी शक्यता","id":"the-honest-catch-a-narrow-band-and-low-odds"},{"level":2,"text":"लहान लोखंडी कंडर, उच्च संभाव्यता व्युत्क्रम","id":"the-short-iron-condor-the-high-probability-inverse"},{"level":2,"text":"लहान लोह कंडोर चालणे कालबाह्यतेवर परिणाम","id":"walking-the-short-iron-condor-outcomes-at-expiry"},{"level":2,"text":"तुमची शक्यता आणि त्यांच्याशी जुळण्यासाठी स्ट्राइक निवडणे","id":"your-odds-and-choosing-strikes-to-match-them"},{"level":2,"text":"समास","id":"margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"दोन्ही तोंडे शेजारी","id":"the-two-faces-side-by-side"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"16":{"html":"<p>लोखंडी कंडोरने तुम्हाला रुंद खोलीतNIFTY′ ठेवण्यासाठी पैसे दिले. हा धडा एकच दरवाजा होईपर्यंत ती खोली संकुचित करतो. जर तुमचा दृष्टिकोन असा असेल की निर्देशांक आज जिथे बसला आहे तिथे जवळपास 24,050 च्या जवळपास स्थिर होईल, तर तुम्ही अशी रचना तयार करू शकता जी त्या एका स्ट्राइकवर तीव्रतेने शिखरावर जाईल आणि दोन्ही बाजूंनी उतार असेल. हे आहेत <strong>लोखंडी माशी</strong> आणि <strong>फुलपाखरू</strong>, पिन-द-स्ट्राइक व्यापार. ते पूर्णपणे परिभाषित-जोखीम आहेत, काही शंभर रुपये खर्च करतात किंवा भरपूर क्रेडिट गोळा करतात आणि जर NIFTY खिळ्यावर उतरले तर त्यांची किंमत कितीतरी पटीने भरावी लागते. प्रामाणिक कॅच असा आहे की एक स्ट्राइक पिन करणे ही कमी-विषम घटना आहे, येथे समान शिखरावर जाण्याचे तीन मार्ग दाखवले आहेत.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>पिन-द-स्ट्राइक</strong> व्यापार त्यांच्या फॅट प्रीमियमची कापणी करण्यासाठी पैशावर पर्याय विकतो, नंतर प्रत्येक बाजूला एक स्वस्त विंग विकत घेतो त्यामुळे नुकसान कुंपण केले जाते. परिणाम म्हणजे एक तंबू: मध्यवर्ती स्ट्राइकवर एक उंच नफा शिखर जो NIFTY दोन्ही बाजूंनी वळला की तीव्रपणे खाली पडतो. तुम्ही एकच तंबू तीन प्रकारे बांधता, लोखंडी माशी, कॉल बटरफ्लाय किंवा पुट बटरफ्लाय, आणि तिन्ही एकच गोष्ट सांगतात की NIFTY आता जिथे आहे त्याच्या अगदी जवळ संपेल.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>पिन-द-स्ट्राइक ट्रेड म्हणजे लोखंडी कंडोअर ज्यामध्ये कोणतेही पठार नाही. हे एकाच मध्यवर्ती स्ट्राइकवर शिखरावर पोहोचते, त्याचे बहुतेक मूल्य ॲट-द-मनी पर्यायांमधून गोळा करते आणि विकत घेतलेल्या पंखांसह थोड्या ज्ञात रकमेवर नुकसान कमी करते. NIFTY एक्सपायरीच्या वेळी बॉडी स्ट्राइकवर जवळजवळ पूर्ण झाले तरच ते सर्वात जास्त पैसे देते.</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">खरा व्यापार, रुपयाने रुपया</h2>\n<p>येथे आहे <strong>लांब लोखंडी माशी</strong> वास्तविक NIFTY किमतींवर, 26 जून 2026 रोजी निर्देशांकासह कॅप्चर केले <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत जवळपास 32 दिवसांनी संपेल. तुम्ही एट-द-मनी 24,050 पुट आणि 24,050 कॉल एकत्र विकता, एक लहान स्ट्रॅडल, नंतर 23,950 पुट आणि 24,150 कॉल विंग्स म्हणून प्रत्येक बाजूला शंभर पॉइंट्स विकत घ्या. OpenAlgo बिल्डर या क्रेडिट आवृत्तीला म्हणतात <strong>लांब लोखंडी माशी</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>23,950</td>\n<td>२५६.६ भरले</td>\n<td>16,679 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>24,050</td>\n<td>295.1 मिळाले</td>\n<td>अधिक 19,182 रु</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल विक्री</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td>अधिक रु 27,677 मध्ये</td>\n</tr>\n<tr>\n<td>4</td>\n<td>कॉल खरेदी करा</td>\n<td>24,150</td>\n<td>370.1 भरले</td>\n<td>24,057 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु 6,130 इंच</strong></td>\n</tr>\n</tbody></table>\n<p>दोन विकल्या गेलेल्या पैशाच्या पर्यायांचा सिंहाचा वाटा आहे, तर दोन विकत घेतलेल्या पंखांची किंमत थोडी कमी आहे. अंतर आहे तुमचे <strong>6,130 रुपये निव्वळ क्रेडिट</strong>, जे तुम्ही ट्रेड उघडता त्या क्षणी तुमच्या खात्यात येते आणि ही स्थिती आजपर्यंतची सर्वात जास्त आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-iron-fly.png\" alt=\"NIFTY वर लांब लोखंडी माशी: 24,050 बॉडी स्ट्राइकवर 6,130 रुपयांचा नफ्याचा उच्चांक, 23,956 आणि 24,148 वर अरुंद ब्रेकवेव्हन्स आणि एकदा निर्देशांक दोन्ही बाजूंच्या मागे गेल्यावर केवळ रु. 370 चा मर्यादित तोटा. 24,056 वरील गुलाबी स्पॉट लाइन जवळजवळ शिखरावर बसते, जी आकर्षक आणि सापळा दोन्ही आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वरील लांब लोखंडी माशी: 24,050 बॉडी स्ट्राइकवर 6,130 रुपयांचा नफ्याचा उच्चांक, 23,956 आणि 24,148 वर अरुंद ब्रेकवेव्हन्स आणि एकदा निर्देशांक दोन्ही बाजूंच्या मागे गेल्यावर केवळ रु. 370 चा मर्यादित तोटा. 24,056 वरील गुलाबी स्पॉट लाइन जवळजवळ शिखरावर बसते, जी आकर्षक आणि सापळा दोन्ही आहे.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p><strong>कमाल नफा म्हणजे निव्वळ क्रेडिट, रु 6,130.</strong> जर NIFTY 24,050 वर पूर्ण झाले तर, सर्व चार पर्याय निरर्थक कालबाह्य होतात, पंखांची कधीही गरज नव्हती आणि तुम्ही संपूर्ण क्रेडिट ठेवता.</p>\n<p><strong>कमाल नुकसान विंग रुंदी वजा क्रेडिट, रु 370 आहे.</strong> प्रत्येक पंख शरीरापासून शंभर बिंदूंवर बसतो, 6,500 रुपयांचे अंतर. मागील एकतर विंग ज्याने तुमच्या विरुद्ध संपूर्ण रु. 6,500 मध्ये लॉक केले होते, परंतु तुम्ही आधीच 6,130 रुपये जमा केले होते, त्यामुळे खरे नुकसान 6,500 उणे 6,130 आहे, जे आहे <strong>370 रु</strong>.</p>\n<p><strong>ब्रेकेव्हन्स 23,956 आणि 24,148 वर, प्रत्येक विंगच्या अगदी आत बसतात.</strong> तुम्ही प्रति शेअर सुमारे 94 पॉइंट क्रेडिट गोळा केले आहेत, त्यामुळे चाचणी केलेल्या बाजूचे नुकसान क्रेडिट खाण्यापूर्वी NIFTY शरीराच्या खाली 94 पॉइंट्स खाली येऊ शकते किंवा त्यापेक्षा 98 पॉइंट वर जाऊ शकते.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>निव्वळ क्रेडिट</td>\n<td>6,130 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>विंग रुंदी वजा निव्वळ क्रेडिट</td>\n<td>रु. 6,500 वजा रु 6,130 = रु. 370</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>बॉडी स्ट्राइक, कमी किंवा अधिक क्रेडिट प्रति शेअर</td>\n<td>24,050 वजा 94 = 23,956; 24,050 अधिक 98 = 24,148</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>पाच बंद किंमतींवर व्यापार सेटल करा आणि तंबू स्वतःच दिसून येईल. एक्सपायरीच्या वेळी पुट कमाल (स्ट्राइक मायनस NIFTY, 0) आणि कॉलचे मूल्य कमाल (NIFTY वजा स्ट्राइक, 0) प्रति शेअर आहे, नेट प्रति लॉट 65 सह.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>लांब 23,950 PE</th>\n<th>शॉर्ट 24,050 PE</th>\n<th>शॉर्ट 24,050 CE</th>\n<th>लांब 24,150 CE</th>\n<th>निव्वळ पी आणि एल प्रति लॉट</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,850</td>\n<td>100</td>\n<td>200</td>\n<td>0</td>\n<td>0</td>\n<td>उणे ३७० रुपये (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>23,956</td>\n<td>0</td>\n<td>94</td>\n<td>0</td>\n<td>0</td>\n<td>सुमारे रु. (लोअर ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु 6,130 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>0</td>\n<td>0</td>\n<td>100</td>\n<td>0</td>\n<td>उणे ३७० रुपये (कमाल तोटा)</td>\n</tr>\n<tr>\n<td>24,250</td>\n<td>0</td>\n<td>0</td>\n<td>200</td>\n<td>100</td>\n<td>उणे ३७० रुपये (कमाल तोटा)</td>\n</tr>\n</tbody></table>\n<p>चित्र ठळक आहे. संपूर्ण 6,130 रुपये फक्त एका किमतीत, 24,050 गोळा केले जातात. दोन्ही बाजूंनी व्हिस्कर आणि क्रेडिट झपाट्याने कमी होते, NIFTY एका पंखाला स्पर्श करेपर्यंत, 24,148 वर कॉल-साइड ब्रेकइव्हनसह रु. 370 लॉस शेल्फवर पोहोचते. हे ऑरेंज लाईनशी तंतोतंत जुळते.</p>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>व्यापार स्मार्ट आहे की नाही हे ठरवणारी संख्या, तो एकल शिखर किती आहे? ते म्हणजे <strong>नफ्याची शक्यता</strong>, आणि लांब लोखंडी माशीसाठी ते फक्त आहे <strong>9 टक्के</strong>. NIFTY, सुमारे 12.7 टक्के, आणि 32 दिवस शिल्लक असलेली अस्थिरता वापरून, बाजार 23,956 ते 24,148 बँडमध्ये निर्देशांक पूर्ण होण्याची केवळ 9 टक्के शक्यता दर्शवते. चार्टवर, नफा क्षेत्र अगदी आतील सिग्मा बँडपेक्षा खूपच घट्ट आहे. तुम्ही NIFTY ला शांत राहण्यास सांगत नाही, तुम्ही ते गोठवण्यास सांगत आहात.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>नेहमी रिवॉर्डच्या पुढे नफ्याची संभाव्यता आणि कमाल तोटा एकत्र वाचा. लांब लोखंडी माशी 6,130 रुपये करण्यासाठी केवळ 370 रुपयांची जोखीम घेते, सुमारे 1 ते 16.5 च्या जोखमीसाठी एक चमकदार बक्षीस आहे, परंतु ते केवळ 9 टक्के वेळेत पूर्ण देते. चकचकीत पेआउट मल्टिपल म्हणजे जर तुम्ही ते जवळजवळ कधीच गोळा केले नाही तर थोडेच.</p>\n</div></div>\n<h2 id=\"margin-and-return-on-margin\">मार्जिन आणि मार्जिनवर परतावा</h2>\n<p>कारण व्यापार पूर्णपणे कुंपण आहे, एक्सचेंज एक माफक अवरोधित करते <strong>सुमारे 63,940 रुपयांचे मार्जिन</strong>, लाखांहून खूप खाली एक नग्न स्ट्रॅडल मागणी करेल. खरेदी केलेले पंख व्यापारासाठी आवश्यक भांडवल कमी करतात. चालू <strong>मार्जिन वर परत</strong>, रु. 6,130 विरुद्ध रु. 63,940 ब्लॉक केलेले आहे <strong>९.६ टक्के</strong> पिन उतरल्यास, पण वजन आधी 9 टक्के शक्यतांनी.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>द <strong>निळ्या डॅशची T+0 रेखा</strong> शरीरावर एक्सपायरी पीकच्या नारंगीच्या अगदी खाली बसते. ते अंतर हे वेळेचे मूल्य आहे, आणि लांब लोखंडी माशीसाठी ते मित्र आहे, परंतु जर 24,050 वर पार्क केले असेल तरच. जसजसे एक्सपायरी जवळ येते आणि निर्देशांक स्थिर राहतो, तसतसे तुमच्याकडे असलेले श्रीमंत पर्याय वितळतात आणि निळी रेषा तीक्ष्ण नारिंगी शिखराकडे जाते. जर NIFTY एका पंखापर्यंत भटकले असेल, तर वेळ तुम्हाला त्याऐवजी रु. 370 च्या शेल्फपर्यंत घेऊन जाईल. क्षय शांततेला बक्षीस देते आणि वाहून जाण्याची शिक्षा देते.</p>\n<h2 id=\"the-short-iron-fly-the-high-probability-inverse\">लहान लोखंडी माशी: उच्च संभाव्यता व्युत्क्रम</h2>\n<p>बिल्डर मिरर ऑफर करतो, द <strong>लहान लोखंडी माशी</strong>. तुम्ही चारही पायांची दुसरी बाजू घ्या, पैसे देऊन <strong>6,130 रुपये निव्वळ डेबिट</strong> ते गोळा करण्याऐवजी.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>अधिक रु 16,679 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>4</td>\n<td>कॉल विक्री</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>अधिक रु 24,057 मध्ये</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>6,130 रु</strong></td>\n</tr>\n</tbody></table>\n<p>प्रत्येक आकडा उलटतो. द <strong>कमाल नफा 370 रुपये आहे</strong>, जवळजवळ कोठेही जिंकले NIFTY चालते. द <strong>कमाल नुकसान रु. 6,130 आहे</strong>, 24,050 वर निर्देशांक गोठला तरच त्रास सहन करावा लागतो. द <strong>नफ्याची शक्यता 91 टक्क्यांपर्यंत वाढली</strong>, ब्रेकइव्हन्स 23,956 आणि 24,148 वर राहतात आणि मार्जिन सुमारे 69,490 रुपये आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-iron-fly.png\" alt=\"NIFTY वर लहान लोखंडी माशी: लांब माशीचा उलटा, 24,050 वर पिन केलेला वगळता जवळपास कुठेही रु. 370 नफा, परंतु 91 टक्के नफ्याच्या संभाव्यतेसह निर्देशांक स्ट्राइकवर स्थिरावल्यास रु. 6,130 नुकसान.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वर लहान लोखंडी माशी: लांब माशीचा उलटा, 24,050 वर पिन केलेला वगळता जवळपास कुठेही रु. 370 चा नफा, परंतु 91 टक्के नफ्याच्या संभाव्यतेसह निर्देशांक स्ट्राइकवर स्थिरावल्यास रु. 6,130 नुकसान.</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>शॉर्ट आयर्न फ्लायवर नफ्याची 91 टक्के शक्यता मोहक आहे, परंतु 6,130 रुपयांच्या तोट्याच्या विरोधात ती फक्त 370 रुपये जिंकते. एक खराब पिन सोळा विजय पूर्ववत करते. आणि लेबलांद्वारे दिशाभूल करू नका: लाँग आयर्न फ्लाय ही क्रेडिट आवृत्ती आहे, शॉर्ट आयर्न फ्लाय डेबिट आवृत्ती आहे, जी अंतर्ज्ञान विरुद्ध चालते. प्रत्येकाला त्याच्या नऊ संख्येने न्याय द्या, त्याच्या नावाने कधीही.</p>\n</div></div>\n<h2 id=\"the-call-butterfly-the-same-peak-from-one-option-type\">कॉल बटरफ्लाय: एका पर्याय प्रकारातील समान शिखर</h2>\n<p>तुम्ही एकच पर्याय प्रकार वापरून कोणताही स्ट्रॅडल न विकता तो समान तंबू तयार करू शकता. ए <strong>फुलपाखराला कॉल करा</strong> मध्यभागी शिखरावर जाण्यासाठी तीन स्ट्राइक आणि चार कॉल लेग वापरते.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>23,950</td>\n<td>486.9 भरले</td>\n<td>31,649 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री कॉल (x2)</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td>अधिक रु 55,354 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल खरेदी करा</td>\n<td>24,150</td>\n<td>370.1 भरले</td>\n<td>24,053 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>348 रु</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही खाली एक कॉल विकत घ्या, मुख्य भागावर दोन विक्री करा आणि वर एक खरेदी करा. दोन विकले गेलेले कॉल बहुतेक प्रीमियम आणतात, एक लहान सोडून <strong>348 रुपये निव्वळ डेबिट</strong>, तुमचे <strong>जास्तीत जास्त नुकसान</strong>, NIFTY पंखांच्या बाहेर पूर्ण झाल्यास त्रास सहन करावा लागतो. द <strong>कमाल नफा 6,152 रुपये आहे</strong>, NIFTY 24,050 पिन केले तरच पोहोचले, जेथे दोन निरुपयोगी विकल्या गेलेल्या कॉलच्या तुलनेत खालच्या विंगचे पूर्ण शंभर गुण आहेत. द <strong>breakevens 23,954 आणि 24,148 आहेत</strong>, पुन्हा नफा होण्याची शक्यता <strong>9 टक्के</strong>, आणि सुमारे रु. 64,000 च्या फरकाने 1 ते 17.7 पर्यंत चमकदार धोका पत्करण्याचे बक्षीस.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-butterfly.png\" alt=\"NIFTY वर कॉल बटरफ्लाय: एकट्या कॉल्समधून बनवलेले, 24,050 बॉडीवर 6,152 रुपयांवर पोहोचणारा तीव्र नफा टेंट, 23,954 आणि 24,148 वर ब्रेकवेन्स आणि पंखांच्या बाहेर 348 रुपयांचा तोटा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वर कॉल बटरफ्लाय: एकट्या कॉल्समधून बनवलेले, 24,050 बॉडीवर 6,152 रुपयांवर पोहोचणारा तीव्र नफा तंबू, 23,954 आणि 24,148 वर ब्रेकव्हेन्स आणि पंखांच्या बाहेर 348 रुपयांचा तोटा.</figcaption></figure>\n<p>हा चार्ट लांब लोखंडी माशीच्या बाजूला ठेवा आणि ते जवळजवळ सारखेच चित्र आहेत: 24,050 वर एक तीव्र शिखर, समान ब्रेकवेन्स आणि 9 टक्के शक्यता, वेगळ्या रोख प्रवाहासाठी वेगवेगळ्या पायांनी बांधलेले.</p>\n<h2 id=\"the-put-butterfly-two-routes-one-shape\">पुट बटरफ्लाय: दोन मार्ग, एक आकार</h2>\n<p>द <strong>फुलपाखरू ठेवा</strong> केवळ पुट वापरून समान शिखरावर पोहोचते, कॉल आवृत्तीचा मिरर.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>24,150</td>\n<td>३३९.२ भरले</td>\n<td>22,045 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री पुट (x2)</td>\n<td>24,050</td>\n<td>295.1 मिळाले</td>\n<td>अधिक रु. 38,363 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>पुट खरेदी करा</td>\n<td>23,950</td>\n<td>२५६.६ भरले</td>\n<td>16,679 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>361 रु</strong></td>\n</tr>\n</tbody></table>\n<p>त्याची किंमत ए <strong>361 रुपये निव्वळ डेबिट</strong>, त्याचे <strong>जास्तीत जास्त नुकसान</strong>, आणि देते अ <strong>6,139 रुपये कमाल नफा</strong> जर NIFTY पिन 24,050. ब्रेकइव्हन्स 23,955 आणि 24,148 आहेत, पुन्हा नफा मिळण्याची शक्यता 9 टक्के आणि मार्जिन सुमारे 63,877 रुपये आहे. कॉल बटरफ्लाय आणि पुट बटरफ्लाय शेजारी ठेवा आणि तुम्ही त्यांचे पेऑफ वेगळे सांगू शकत नाही.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-butterfly.png\" alt=\"NIFTY वर पुट बटरफ्लाय: एकट्या पुट्सपासून बनवलेले, 24,050 वर 6,139 रुपयांचे समान शिखर, 23,955 आणि 24,148 वर ब्रेकवेन्स आणि पंखांच्या बाहेर जवळपास 361 रुपयांचे नुकसान, कॉल आणि पुट्स हे एका आकाराचे दोन मार्ग आहेत हे सिद्ध करते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY वर पुट बटरफ्लाय: एकट्या पुट्सपासून बनवलेले, 24,050 वर 6,139 रुपयांचे समान शिखर, 23,955 आणि 24,148 वर ब्रेकवेन्स आणि पंखांच्या बाहेर जवळपास 361 रुपयांचे नुकसान, कॉल आणि पुट्स हे एका आकाराचे दोन मार्ग आहेत हे सिद्ध करते.</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>कॉल बटरफ्लाय ची किंमत 348 रुपये आहे आणि पुट बटरफ्लाय 361 रुपये आहे, काही रुपये वेगळे आहेत आणि दोन्ही समान रिवॉर्ड आणि समान 9 टक्के शक्यतांसाठी समान स्ट्राइक पिन करतात. सखोल धडा: पेऑफ आकार एका पर्याय प्रकाराशी जोडलेला नाही. कॉल आणि पुट्स या दोन भाषा आहेत ज्या एकाच चित्राचे वर्णन करतात आणि एक कुशल व्यापारी त्यांना पाहिजे त्या आकारापर्यंत पोहोचण्यासाठी स्वस्त किंवा अधिक द्रव असलेले पाय निवडतो.</p>\n</div></div>\n<h2 id=\"choosing-among-the-pin-the-strike-family\">पिन-द-स्ट्राइक कुटुंबातून निवडणे</h2>\n<p>NIFTY कुठे स्थिरावतो यावर आता तुमच्याकडे चार मार्ग आहेत. निवड रोख प्रवाह आणि शक्यतांवर येते, तंबूच्या आकारावर नाही.</p>\n<table>\n<thead>\n<tr>\n<th>रचना</th>\n<th>पासून बांधले</th>\n<th>खर्च किंवा क्रेडिट</th>\n<th>जास्तीत जास्त नफा</th>\n<th>कमाल नुकसान</th>\n<th>POP</th>\n<th>समास</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>लांब लोखंडी माशी</td>\n<td>लहान स्ट्रॅडल अधिक दोन पंख</td>\n<td>क्रेडिट रु 6,130</td>\n<td>6,130 रु</td>\n<td>370 रु</td>\n<td>9%</td>\n<td>६३,९४० रु</td>\n</tr>\n<tr>\n<td>फुलपाखराला कॉल करा</td>\n<td>चार कॉल</td>\n<td>डेबिट रु. 348</td>\n<td>6,152 रु</td>\n<td>348 रु</td>\n<td>9%</td>\n<td>64,000 रु</td>\n</tr>\n<tr>\n<td>फुलपाखरू ठेवा</td>\n<td>चार पुट</td>\n<td>डेबिट रु. 361</td>\n<td>६,१३९ रु</td>\n<td>361 रु</td>\n<td>9%</td>\n<td>63,877 रु</td>\n</tr>\n<tr>\n<td>लहान लोखंडी माशी</td>\n<td>उलट, चार पाय</td>\n<td>डेबिट रु. 6,130</td>\n<td>370 रु</td>\n<td>6,130 रु</td>\n<td>91%</td>\n<td>६९,४९० रु</td>\n</tr>\n</tbody></table>\n<p>तीन पिन-द-स्ट्राइक बेट्स रु. 6,100 च्या जवळ शिखर, एक लहान नुकसान आणि 9 टक्के शक्यता सामायिक करतात. एका ऑप्शन प्रकारात लहान ज्ञात डेबिट भरण्यासाठी बटरफ्लाय निवडा किंवा प्रीमियम जमा करण्यासाठी क्रेडिट आयर्न फ्लाय निवडा. लहान लोखंडी माशी फक्त स्पष्ट डोळ्यांनी वापरा, कारण दुर्मिळ पिनवर मोठ्या नुकसानासह लहान विजयाची उच्च शक्यता कठोर व्यवस्थापनाची मागणी करते.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>पिन-द-स्ट्राइक ट्रेड्स एक्सपायरी जवळ ठेवा, आठवडे लवकर नाही, त्यामुळे NIFTY ला शरीरातून बाहेर पडण्यासाठी कमी जागा आहे. आणि चकचकीत रिवॉर्ड मल्टिपलला ऑड्ससह कधीही गोंधळात टाकू नका: 9 टक्के, लांब माशी आणि फुलपाखरे स्वस्त, लक्ष्यित, कमी-संभाव्यता बेट आहेत, उत्पन्न मशीन नाहीत. बिल्डरने नोंदवलेले जास्तीत जास्त नुकसान वाचा, चार पायांची मोठी एकूण उलाढाल कधीही नाही.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>एक पिन-द-स्ट्राइक ट्रेड म्हणजे लोखंडी कंडर एका बिंदूवर कोसळला आहे: जरNIFTYबॉडी स्ट्राइकवर 24,050 जवळजवळ पूर्ण झाले तरच ते सर्वात जास्त पैसे देते.</li>\n<li>द <strong>लांब लोखंडी माशी</strong> गोळा करते <strong>6,130 रुपये निव्वळ क्रेडिट</strong> (त्याचा कमाल नफा), फक्त जोखीम <strong>370 रु</strong> (विंग रुंदी वजा क्रेडिट), आणि 23,956 आणि 24,148 वर देखील ब्रेक होतो.</li>\n<li>द <strong>फुलपाखराला कॉल करा</strong> आणि <strong>फुलपाखरू ठेवा</strong> एका ऑप्शन प्रकारातून समान शिखरावर पोहोचा, रु. 348 किंवा रु. 361 च्या छोट्या डेबिटसाठी, कॉल आणि पुट हे एका आकाराचे दोन मार्ग आहेत हे सिद्ध करणे.</li>\n<li>तिन्ही पिन-द-स्ट्राइक बेट सामायिक करतात a <strong>नफ्याची 9 टक्के शक्यता</strong>: क्वचितच संकलित केलेल्या जोखमीसाठी एक गौरवशाली बक्षीस, म्हणून त्यांना स्वस्त लांब शॉट्स म्हणून आकार द्या.</li>\n<li>द <strong>लहान लोखंडी माशी</strong> उलट आहे, दुर्मिळ पिनवर रु. 6,130 च्या तोट्याच्या विरुद्ध रु. 370 जिंकण्याची 91 टक्के संधी. सर्व चार रू. 64,000 च्या जवळ माफक फरकाने परिभाषित-जोखीम आहेत. त्यांना तयार करा <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong> शिखर किती वेगाने कोसळते हे पाहण्यासाठी.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"खरा व्यापार, रुपयाने रुपया","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"मार्जिन आणि मार्जिनवर परतावा","id":"margin-and-return-on-margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"लहान लोखंडी माशी: उच्च संभाव्यता व्युत्क्रम","id":"the-short-iron-fly-the-high-probability-inverse"},{"level":2,"text":"कॉल बटरफ्लाय: एका पर्याय प्रकारातील समान शिखर","id":"the-call-butterfly-the-same-peak-from-one-option-type"},{"level":2,"text":"पुट बटरफ्लाय: दोन मार्ग, एक आकार","id":"the-put-butterfly-two-routes-one-shape"},{"level":2,"text":"पिन-द-स्ट्राइक कुटुंबातून निवडणे","id":"choosing-among-the-pin-the-strike-family"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":4,"hasContent":true},"17":{"html":"<p>आधीच्या अध्यायातील गुणोत्तर परत स्प्रेडने त्यांनी विकल्यापेक्षा अधिक पर्याय विकत घेतले, त्यामुळे ते डेबिटसाठी उघडले, एक परिभाषित तोटा ठेवला आणि फक्त मोठ्या, जलद हालचालीवर पैसे दिले. हा धडा त्या गुणोत्तराला डोक्यावर घेतो. आता तुम्ही खरेदी करण्यापेक्षा जास्त विकता. तुम्ही अगोदर फॅट क्रेडिट गोळा करता, तुम्ही विकल्या स्ट्राइककडेNIFTY′ हळूवारपणे वाहून गेल्यास तुम्हाला सर्वात जास्त फायदा होतो आणि तुम्हाला एक उघडा पर्याय आहे जो निर्देशांक चुकीच्या मार्गाने खूप पुढे गेल्यास पळून जाऊ शकतो. हे आहेत <strong>कॉल गुणोत्तर प्रसार</strong> आणि <strong>गुणोत्तर पसरवा</strong>. ते हुशार दिसतात, ते अनेकदा जिंकतात, परंतु अनकॅप्ड बाजू खरी आहे, म्हणून दोन्ही तक्ते डोळे उघडे ठेवून वाचा.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>प्रमाण प्रसार</strong> पैसे देऊन एक पर्याय विकत घेतो आणि त्याच प्रकारचे दोन थोडे पुढे विकतो. तुम्ही विकत घेतलेल्यापेक्षा एक अधिक विकले असल्यामुळे, विक्री केलेल्या स्ट्राइकच्या पलीकडे स्थिती निव्वळ कमी झुकते, जिथे धोका असतो. हा एक क्रेडिट ट्रेड आहे ज्याला NIFTY तुम्ही विकलेल्या स्ट्राइककडे वळवायचे आहे आणि त्या स्ट्राइकवर त्याच्या शिखरावर पैसे देऊन तिथेच थांबायचे आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>गुणोत्तर स्प्रेड दोन पर्याय विकतो आणि एक खरेदी करतो, क्रेडिटसाठी उघडतो. ते एका विस्तृत क्षेत्रामध्ये नफा मिळवते, विकल्या गेलेल्या स्ट्राइकवर अगदी शिखरावर पोहोचते आणि नंतर त्याच्या पलीकडे एकच नग्न पर्याय उघड करते. तुम्ही गोळा केलेले श्रेय हे त्या अनकॅप्ड शेपटीला घेऊन जाण्यासाठी बक्षीस आहे.</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">खरा व्यापार, रुपयाने रुपया</h2>\n<p>येथे आहे <strong>कॉल गुणोत्तर प्रसार</strong> वास्तविक NIFTY किमतींवर, 26 जून 2026 रोजी निर्देशांकासह कॅप्चर केले <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत जवळपास 32 दिवसांनी संपेल. तुम्ही 24,050 वर एक कॉल खरेदी करा आणि दोन 24,150 कॉल एक स्ट्राइक जास्त विकता.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री कॉल (x2)</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>अधिक रु 48,107 मध्ये</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक 20,430 रु</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही एका खरेदी केलेल्या कॉलसाठी रु. 27,677 भरता आणि दोन विकल्या गेलेल्या कॉलसाठी रु. 48,107 घेता, त्यामुळे स्थिती निरोगी व्यक्तीसाठी उघडते <strong>20,430 रुपये निव्वळ क्रेडिट</strong>. NIFTY फक्त 24,050 वर किंवा त्यापेक्षा कमी राहिल्यास, जेथे प्रत्येक कॉल निरर्थक कालबाह्य होत असेल तर ते ठेवण्याचे श्रेय तुमचे आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-ratio-spread.png\" alt=\"NIFTY कॉल रेशो स्प्रेड: 24,150 स्ट्राइकवर रु. 20,430 क्रेडिट फ्लोअरवरून रु. 26,930 च्या तीव्र शिखरावर चढून जाणारा नफा, 24,564 वर ब्रेकइव्हन, आणि एक एक्स्पायरी लाइन जी त्यावरील मर्यादेशिवाय खाली येते कारण तुम्ही एक अतिरिक्त कॉल कमी आहात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY कॉल रेशो स्प्रेड: 24,150 स्ट्राइकवर रु. 20,430 क्रेडिट फ्लोअरवरून रु. 26,930 च्या तीव्र शिखरावर चढून जाणारा नफा, 24,564 वर ब्रेकइव्हन आणि एक एक्स्पायरी लाइन जी त्यावरील मर्यादेशिवाय खाली येते कारण तुम्ही एक अतिरिक्त कॉल कमी आहात.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p><strong>कमाल नफा रु. 26,930 आहे, जो विकलेल्या स्ट्राइकवर पोहोचला आहे.</strong> NIFTY 24,050 वरून 24,150 पर्यंत वाढल्याने, तुमच्या खरेदी केलेल्या कॉलचे मूल्य वाढेल, तर दोन विकले गेलेले कॉल अजूनही निरुपयोगी आहेत, त्यामुळे नफा वाढतो. अगदी 24,150 वर खरेदी केलेल्या कॉलचे मूल्य पूर्ण शंभर पॉइंट्स, 6,500 रुपये आहे, तुमच्याकडे आधीपासून असलेल्या क्रेडिटच्या वर. तर शिखर 20,430 अधिक 6,500 आहे, जे आहे <strong>26,930 रु</strong>.</p>\n<p><strong>कमाल नुकसान अमर्यादित आहे.</strong> 24,150 च्या पुढे पुश करा आणि दोन विकले गेलेले कॉल तुमच्या विरुद्ध उठतील. तुम्ही आता एक नेट कॉल कमी करत आहात, कमाल मर्यादा नसताना 65 रुपये प्रति पॉइंट गमावत आहात. ही नग्न शेपूट आहे आणि ती कधीही थांबत नाही.</p>\n<p><strong>ब्रेकईव्हन 24,564 आहे.</strong> 24,150 च्या वर तुमचा सिंगल नेट शॉर्ट कॉल रु. 26,930 च्या शिखरावरून 65 रुपये प्रति पॉइंट परत देतो. शिखराची किंमत प्रति शेअर सुमारे 414 पॉइंट कुशन आहे, त्यामुळे एक्सपायरी लाइन 24,150 च्या वर शून्य 414 पॉइंट ओलांडते, येथे <strong>24,564</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>क्रेडिट प्लस विकलेल्या स्ट्राइकवर खरेदी केलेला कॉल</td>\n<td>रु. 20,430 अधिक रु 6,500 = रु. 26,930</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>शिखर वर नग्न अतिरिक्त लहान कॉल</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>विक्री स्ट्राइक अधिक प्रति शेअर पीक कुशन</td>\n<td>24,150 अधिक 414 = 24,564</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>पाच बंद किंमतींवर व्यापार सेटल करा आणि उतार, शिखर आणि क्लिफ पहा. एका कॉलचे मूल्य कमाल (NIFTY वजा स्ट्राइक, 0) प्रति शेअर आहे आणि नेट प्रति लॉट 65 आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>लांब 24,050 CE (तुमच्या मालकीचे)</th>\n<th>दोन लहान 24,150 CE (तुम्हाला देणे आहे)</th>\n<th>निव्वळ पी आणि एल प्रति लॉट</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,950</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु 20,430 (क्रेडिट फ्लोअर)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक 20,430 रु</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100</td>\n<td>0</td>\n<td>अधिक रु 26,930 (शिखर)</td>\n</tr>\n<tr>\n<td>24,564</td>\n<td>514</td>\n<td>828</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,700</td>\n<td>650</td>\n<td>1,100</td>\n<td>उणे रु 8,820 (तोटा वाढतो)</td>\n</tr>\n</tbody></table>\n<p>24,050 च्या खाली लाइन 20,430 च्या क्रेडिट फ्लोअरवर सपाट आहे. तेथून ते रु. 26,930 च्या शिखरावर 24,150 वर पोहोचते, नंतर दुसऱ्या शॉर्ट कॉल बाईट्स म्हणून खाली वळते, 24,564 वर शून्य ओलांडते आणि पलीकडे मजल्याशिवाय पडते. 24,700 वर तुम्ही आधीच 8,820 रुपये खाली आहात आणि प्रत्येक पुढील पॉइंटसाठी आणखी 65 रुपये मोजावे लागतील.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>कॉल रेशो स्प्रेडमध्ये कमाल तोटा असतो जो अमर्यादित असतो. 24,150 चा अतिरिक्त विकला जाणारा कॉल नग्न आहे, त्यामुळे एकदा NIFTY 24,564 च्या ब्रेकईव्हनच्या पुढे गेल्यावर तुम्ही कमाल मर्यादा नसलेल्या प्रत्येक बिंदूसाठी 65 रुपये गमावाल. एक्स्चेंज जवळजवळ रु. 1.76 लाख मार्जिन रोखते कारण त्या अनकॅप्ड टेलमुळे. तोटा सुरू होण्यापूर्वी फायद्याची सोयीस्कर संभाव्यता रुंद उशीतून येते, परंतु शिखर ओलांडून मजबूत रॅली विजयाच्या स्ट्रिंगला एका मोठ्या तोट्यात बदलू शकते.</p>\n</div></div>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>द <strong>नफ्याची शक्यता 72 टक्के आहे</strong>. हा उच्च आकडा रुंद कुशनमधून येतो: NIFTY 24,564 ब्रेकइव्हनच्या खाली कुठेही बसू शकतो आणि तुम्ही हिरव्या रंगात पूर्ण कराल आणि बहुतेक वेळा 32 दिवसांमध्ये असे होते. चार्ट पहा आणि ब्रेकईव्हन वरच्या सिग्मा बँडच्या बाहेर चांगले बसते, बाजाराला अपेक्षित हलवा. व्यापार अनेकदा तंतोतंत जिंकतो कारण धोका मोठ्या रॅलीनंतरच सुरू होतो.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>अमर्यादित, कधीही एकटे नसावे या शब्दापुढील लाभाची 72 टक्के संभाव्यता वाचा. अनकॅप्ड शेपटीला जोडलेला उच्च विजयाचा दर हा क्लासिक ट्रॅप आहे: तो तुम्हाला महिनोन्महिने सतत पैसे देतो, त्यानंतर एकच तीक्ष्ण रॅली तुम्ही जमा केलेल्यापेक्षा कितीतरी पटीने जास्त परत मिळते. जर तुम्ही अजूनही शिकत असाल, तर परिभाषित-जोखीम असलेल्या नातेवाईकांना प्राधान्य द्या किंवा तुम्ही व्यापार करण्यापूर्वी दूर विकत घेतलेल्या कॉलसह नग्न बाजू कॅप करा.</p>\n</div></div>\n<h2 id=\"margin-and-return-on-margin\">मार्जिन आणि मार्जिनवर परतावा</h2>\n<p>नग्न शेपटीमुळे, एक्सचेंज एक जड अवरोधित करते <strong>सुमारे 1,76,491 रुपये मार्जिन</strong>, बर्याच वेळा समान आकाराच्या परिभाषित स्प्रेडची आवश्यकता असेल. मोकळ्या पैशांसारखे वाटणारे क्रेडिटसाठी उघडले असले तरीही ही रचना धोकादायक आहे हे रोखीने सांगणारी ही मोठी संख्या एक्सचेंज आहे.</p>\n<p>चालू <strong>मार्जिन वर परत</strong>, रु. 1,76,491 ब्लॉक केलेल्या रु. 26,930 चे शिखर सुमारे आहे <strong>15 टक्के</strong>, परंतु नेमक्या विकल्या गेलेल्या स्ट्राइकवर हे सर्वोत्तम प्रकरण आहे, तुम्ही मोजू शकणाऱ्या क्रमांकावर नाही आणि ते अमर्यादित नकारात्मक बाजूकडे दुर्लक्ष करते. उत्पन्न म्हणून उद्धृत करण्यापूर्वी नेहमी विषमतेने आणि शेपटीने शिखराचे वजन करा.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>ही निव्वळ शॉर्ट पोझिशन आहे, तुम्ही दोन पर्याय विकले आणि एक विकत घेतला, त्यामुळे शिल्लक वेळेवर क्षय तुमच्यासाठी काम करतो. चार्ट पहा: द <strong>निळ्या डॅशची T+0 रेखा</strong> एक्सपायरी पीकच्या खाली केशरी बसते आणि प्रत्येक शांत दिवस त्या शिखराकडे पोझिशन उंचावतो कारण विकले गेलेले वेळ मूल्य वितळते. पकड अशी आहे की NIFTY वागतानाच क्षय मदत करते. एकदा निर्देशांक शिखरावर गेल्यावर, वेळ महत्त्वाची ठरते आणि नग्न कॉलमुळे तोटा होतो.</p>\n<h2 id=\"the-put-ratio-spread\">पुट रेशो पसरला</h2>\n<p>द <strong>गुणोत्तर पसरवा</strong> तीच कल्पना खालच्या दिशेने दर्शविली आहे. तुम्ही एक ॲट-द-मनी पुट खरेदी करता आणि दोन पुट थोडे कमी विकता, तुमच्याकडे निव्वळ शॉर्ट एक पुट लोअर स्ट्राइकच्या खाली ठेवता.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री पुट (x2)</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>अधिक रु. 33,352 मध्ये</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु 14,170 इंच</strong></td>\n</tr>\n</tbody></table>\n<p>तुम्ही विकत घेतलेल्या पुटसाठी 19,182 रुपये द्या आणि दोन विकल्या गेलेल्या पुटसाठी 33,352 रुपये गोळा करा. <strong>14,170 रुपये निव्वळ क्रेडिट</strong>, NIFTY 24,050 वर किंवा त्यापेक्षा जास्त राहिल्यास पूर्ण ठेवली जाते. शिखर खालच्या स्ट्राइकवर बसते: NIFTY 23,950 च्या खाली आल्याने, विकत घेतलेला नफा निरुपयोगी राहतो, तर त्याचा नफा वाढतो. <strong>कमाल रु. 20,670</strong> जेव्हा NIFTY 23,950 पिन करते. त्या खाली दोन विकले जाणारे पुट तुमच्या विरुद्ध चालू आहेत, तुम्ही निव्वळ शॉर्ट वन पुट आहात आणि द <strong>ब्रेकईव्हन 23,632 आहे</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-ratio-spread.png\" alt=\"NIFTY पुट रेशो स्प्रेड: 23,950 स्ट्राइकवर रु. 14,170 क्रेडिट फ्लोअरवरून रु. 20,670 च्या शिखरावर पोहोचणारा नफा, 23,632 वर ब्रेकइव्हन, आणि तोटा जो त्याखालील खूप मोठ्या आकड्याकडे वाढतो कारण तुम्ही एक अतिरिक्त पुट लहान आहात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY पुट रेश्यो स्प्रेड: 23,950 स्ट्राइकवर रु. 14,170 क्रेडिट फ्लोअरवरून रु. 20,670 च्या शिखरावर पोहोचणारा नफा, 23,632 वर ब्रेकइव्हन, आणि तोटा जो त्याखालील खूप मोठ्या आकड्याकडे वाढतो कारण तुम्ही एक अतिरिक्त पुट लहान आहात.</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>लांब 24,050 PE (तुमच्या मालकीचे)</th>\n<th>दोन लहान 23,950 PE (तुम्हाला देणे आहे)</th>\n<th>निव्वळ पी आणि एल प्रति लॉट</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,100</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु 14,170 (क्रेडिट फ्लोअर)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु. 14,170</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100</td>\n<td>0</td>\n<td>अधिक रु 20,670 (शिखर)</td>\n</tr>\n<tr>\n<td>23,632</td>\n<td>418</td>\n<td>636</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>23,500</td>\n<td>550</td>\n<td>900</td>\n<td>उणे रु 8,580 (तोटा वाढतो)</td>\n</tr>\n</tbody></table>\n<p>आकार कॉल आवृत्ती मिरर. 24,050 च्या वर 14,170 मजल्यावरील रेषा सपाट आहे, 23,950 वर 20,670 च्या शिखरावर उतरते, 23,632 वर शून्य ओलांडते आणि खाली खोल जाते. द <strong>नफ्याची शक्यता 68 टक्के आहे</strong>, आणि मार्जिन सुमारे रु 1,70,795 आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>पुट रेशो स्प्रेडमध्ये खूप मोठा डाउनसाइड तोटा होतो, जर NIFTY शून्यावर आला तर सुमारे रु. 15.4 लाख म्हणून सूचीबद्ध केले जाते. अतिरिक्त विकले गेलेले 23,950 पुट हे नकारात्मकतेसाठी उघड आहे, म्हणून एकदा NIFTY 23,632 च्या खाली ब्रेक झाला की तुम्ही 65 रुपये प्रति पॉइंट गमावाल आणि फक्त शून्याचा मजला तो थांबेल. त्यामुळे एक्सचेंज सुमारे रु. 1.71 लाख मार्जिन ब्लॉक करते. नफ्याची 68 टक्के संभाव्यता शेपटीची खोली नव्हे तर वरील रुंद उशी प्रतिबिंबित करते. एक तीव्र घसरण या व्यापाराला सर्वात जास्त त्रास देते.</p>\n</div></div>\n<h2 id=\"how-a-ratio-spread-differs-from-a-back-spread\">रेशो स्प्रेड बॅक स्प्रेडपेक्षा कसा वेगळा आहे</h2>\n<p>हे क्रेडिट रेशो स्प्रेड्स आणि डेबिट रेशो बॅक स्प्रेड्समध्ये गोंधळ घालणे सोपे आहे. ते विरुद्ध आहेत, आणि फरक हा आहे की तुम्ही कोणत्या बाजूने जास्त वजन करता.</p>\n<ul>\n<li>ए <strong>परत पसरणे</strong> दोन विकत घेतो आणि एक विकतो, त्यामुळे ते निव्वळ लांब आहे. हे एक लहान डेबिट देते, एक परिभाषित तोटा ठेवते आणि फेडण्यासाठी मोठ्या, जलद हालचालीची आवश्यकता असते.</li>\n<li>ए <strong>प्रमाण प्रसार</strong> दोन विकतो आणि एक विकत घेतो, त्यामुळे निव्वळ कमी आहे. ते क्रेडिट गोळा करते, NIFTY विकल्या गेलेल्या स्ट्राइकला पिन केल्यास, आणि त्याच्या पलीकडे एक नग्न शेपूट उघड करते.</li>\n</ul>\n<p>बॅक स्प्रेडला हिंसा हवी आहे आणि मोठ्या मोबदल्यासाठी कमी विजयाचा दर स्वीकारतो. गुणोत्तर स्प्रेडला विकल्या गेलेल्या स्ट्राइककडे सौम्य, स्थिर वळण हवे आहे आणि उच्च विजय दरासाठी नग्न शेपूट स्वीकारते. समान पाय, विरुद्ध गुणोत्तर, विरुद्ध वर्ण.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>मार्जिनची तुलना करा. दोन्ही गुणोत्तर स्प्रेड ब्लॉक 1.7 लाख रुपयांपेक्षा जास्त आहे, तर मागील अध्यायातील बॅक स्प्रेड्स फक्त 46,000 ते 52,000 रुपये ब्लॉक केले आहेत. एक्स्चेंज तुम्हाला रोखीत सांगत आहे की रेशो स्प्रेडची नग्न शेपूट ही अधिक धोकादायक रचना आहे, जरी ती सहज पैशांसारखी वाटणारी क्रेडिटसाठी उघडते.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>गुणोत्तर स्प्रेड एक पर्याय विकत घेतो आणि त्याच प्रकारातील दोन विकतो, क्रेडिटसाठी उघडतो आणि विकल्या गेलेल्या स्ट्राइकवर अचूकपणे पोहोचतो.</li>\n<li>द <strong>कॉल गुणोत्तर प्रसार</strong> गोळा करते <strong>20,430 रु</strong>, येथे शिखर <strong>26,930 रु</strong> 24,150 वर, 24,564 वर देखील ब्रेक होतो आणि नंतर एक वाहून नेतो <strong>अमर्यादित</strong> नग्न अतिरिक्त कॉल पासून वरील नुकसान.</li>\n<li>द <strong>गुणोत्तर पसरवा</strong> गोळा करते <strong>14,170 रु</strong>, येथे शिखर <strong>20,670 रु</strong> 23,950 वर, 23,632 वर देखील ब्रेक होतो आणि नग्न एक्स्ट्रा पुटच्या खाली खूप मोठा डाउनसाइड तोटा होतो.</li>\n<li>दोघांनी ए <strong>फायद्याची उच्च शक्यता</strong>, 72 आणि 68 टक्के, कारण धोक्याची सुरुवात मोठ्या हालचालीनंतरच होते, परंतु विजयाचा दर एका अनकॅप्ड शेपटीच्या पुढे बसतो, त्यामुळे कधीही क्रेडिटनुसार आकार घेऊ नका.</li>\n<li>भारी <strong>समास</strong> 1.7 लाख रुपयांच्या जवळ नग्न पायाची एक्सचेंज किंमत आहे. गुणोत्तर स्प्रेड बॅक स्प्रेडच्या विरुद्ध आहे: निव्वळ शॉर्ट, क्रेडिट आणि मजबूत हालचालीवर धोकादायक.</li>\n<li>दोन्ही मध्ये तयार करा <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong>, नंतर मॉडेल केलेली किंमत ब्रेकईव्हनच्या पुढे ड्रॅग करा आणि एट-एक्सपायरी लाइन मजल्याशिवाय खाली पडताना पहा. ते दृश्य म्हणजे नग्न शेपटीचा संपूर्ण धडा आहे.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"खरा व्यापार, रुपयाने रुपया","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"मार्जिन आणि मार्जिनवर परतावा","id":"margin-and-return-on-margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"पुट रेशो पसरला","id":"the-put-ratio-spread"},{"level":2,"text":"रेशो स्प्रेड बॅक स्प्रेडपेक्षा कसा वेगळा आहे","id":"how-a-ratio-spread-differs-from-a-back-spread"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"18":{"html":"<p>तुम्हाला नुकत्याच भेटलेल्या गुणोत्तराने उदार क्रेडिट गोळा केले परंतु एक शेपूट उघडे आणि उघडे ठेवले. जर तुम्ही जवळजवळ सर्व श्रेय ठेवू शकता आणि तरीही एक शेपूट पूर्णपणे पुसून टाकू शकता, जेणेकरून संपूर्ण दिशा तुम्हाला त्रास देऊ शकत नाही? त्यामागची युक्ती आहे <strong>जेड सरडा</strong> आणि त्याचा आरसा, द <strong>उलटा जेड सरडा</strong>. प्रत्येक विकलेल्या पर्यायांच्या जोडीला एक स्वस्त विकत घेतलेला विंग जोडतो, अशा प्रकारे व्यवस्था केली जाते की तुम्ही गोळा केलेले क्रेडिट गमावू शकणाऱ्या स्प्रेडपेक्षा मोठे असेल. जेव्हा क्रेडिट त्या स्प्रेडपेक्षा मोठे असते, तेव्हा चार्टची एक संपूर्ण बाजू कधीही शून्याच्या खाली जाऊ शकत नाही. ही या कोर्समधील सर्वात सुंदर कल्पनांपैकी एक आहे आणि एकदा तुम्ही ती पाहिली की तुम्ही ती कधीही पाहू शकणार नाही.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>जेड सरडा</strong> उत्पन्नासाठी पुट विकतो, अधिक उत्पन्नासाठी कॉल विकतो आणि वरच्या बाजूस कुंपण घालण्यासाठी आणखी एक कॉल खरेदी करतो. गोळा केलेले क्रेडिट त्या कॉल स्प्रेडच्या रुंदीपेक्षा मुद्दाम मोठे आहे, त्यामुळे कितीही उच्च NIFTY चढले तरी, कॅप्ड कॉल लॉस आधीच बँक केलेल्या पैशांपेक्षा कमी आहे. वरची बाजू गमावू शकत नाही. जोखीम फक्त एका बाजूला राहते, ज्या बाजूकडे तुमचा दृष्टिकोन आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>जेड सरड्याची स्वाक्षरी ही त्याच्या संरक्षित स्प्रेडच्या रुंदीपेक्षा मोठी क्रेडिट असते. जेव्हा ते धरून ठेवते, तेव्हा ती संपूर्ण बाजू गमावू शकत नाही: विकत घेतलेले विंग तेथे तोटा कॅप करते आणि तुम्ही बँक केलेले क्रेडिट कॅपपेक्षा मोठे असते. तुमच्याकडे फक्त एकाच दिशेने धोका आहे, दोन्ही नाही.</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">खरा व्यापार, रुपयाने रुपया</h2>\n<p>येथे आहे <strong>जेड सरडा</strong> वास्तविक NIFTY किमतींवर, 26 जून 2026 रोजी निर्देशांकासह कॅप्चर केले <strong>24,056</strong> आणि 28 जुलै 2026 ची मुदत जवळपास 32 दिवसांनी संपेल. तुम्ही पैशाच्या खाली ठेवलेला 23,950 विकता, त्यावरील 24,150 कॉलची विक्री करा आणि 24,250 कॉल विंग म्हणून विकत घ्या.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>विक्री ठेवा</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>अधिक रु 16,679 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>कॉल विक्री</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>अधिक रु 24,057 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>कॉल खरेदी करा</td>\n<td>24,250</td>\n<td>316.1 भरले</td>\n<td>20,557 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु. 20,179 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>दोन विकले गेलेले पर्याय त्यांच्यामध्ये 40,736 रुपये आणतात आणि विकत घेतलेल्या 24,250 कॉलची किंमत 20,557 रुपये आहे. <strong>20,179 रुपये निव्वळ क्रेडिट</strong>. ते श्रेयही तुमचेच आहे <strong>जास्तीत जास्त नफा</strong>, 23,950 ते 24,150 पर्यंत विकल्या गेलेल्या स्ट्राइक दरम्यान जेव्हाही NIFTY पूर्ण होते, तेव्हा पूर्ण ठेवले जाते, जेथे सर्व तीन पर्याय निरर्थक कालबाह्य होतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-jade-lizard.png\" alt=\"NIFTY जेड लिझार्ड: मध्यभागी 20,179 रुपयांचा सपाट कमाल नफा, उजवी बाजू जी कितीही उच्च असली तरीही नफ्यातच राहते NIFTY चढते कारण क्रेडिट कॉल स्प्रेड कव्हर करते आणि 23,640 वर एकच डाउनसाइड ब्रेकवेन जेथे नग्न शॉर्ट पुट चावणे सुरू होते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY जेड सरडा: मध्यभागी 20,179 रुपयांचा सपाट कमाल नफा, उजवी बाजू जी कितीही उच्च असली तरीही नफ्यातच राहते कारण क्रेडिट कॉल स्प्रेड कव्हर करते आणि 23,640 वर एकच डाउनसाइड ब्रेकईव्हन जेथे नग्न शॉर्ट पुट चावणे सुरू होते.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p><strong>जास्तीत जास्त नफा म्हणजे निव्वळ क्रेडिट, रु 20,179.</strong> 23,950 ते 24,150 पर्यंत कुठेही तिन्ही पर्याय निरुपयोगी ठरतात आणि तुम्ही संपूर्ण क्रेडिट ठेवता.</p>\n<p><strong>अजिबात वरचा धोका नाही.</strong> पाय 2 आणि 3 हे अस्वल कॉल तयार करतात जे फक्त शंभर पॉइंट रुंद, 24,150 ते 24,250 पर्यंत पसरतात, ज्याचे सर्वात वाईट नुकसान शंभर पट 65 आहे, जे 6,500 रुपये आहे. परंतु तुम्ही 20,179 रुपये जमा केले, 6,500 रुपयांपेक्षा कितीतरी जास्त. त्यामुळे जरीNIFTY′ रॉकेट दूर झाले तरी, कॉल पसरत असताना तुमची क्रेडिट ते कव्हर करते त्यापेक्षा जास्त आहे आणि तरीही तुम्ही सुमारे 20,179 उणे 6,500, जे 13,679 रुपये आहे. चार्टची संपूर्ण उजवी बाजू हिरवी राहते.</p>\n<p><strong>जास्तीत जास्त नुकसान केवळ डाउनसाइडवर होते आणि ब्रेकइव्हन 23,640 आहे.</strong> विकलेला 23,950 पुट नग्न आहे. क्रेडिटची किंमत प्रति शेअर सुमारे 310 पॉइंट्स आहे, त्यामुळे NIFTY पुट स्ट्राइकपेक्षा 310 पॉइंट खाली येऊ शकते. <strong>23,640</strong>, नुकसान संपूर्ण क्रेडिट खाण्यापूर्वी. त्या खाली तोटा खूप मोठ्या आकड्याकडे वाढतो, जर निर्देशांक शून्यावर घसरला तर सुमारे रु. 15.4 लाख म्हणून सूचीबद्ध.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>निव्वळ क्रेडिट</td>\n<td>20,179 रु</td>\n</tr>\n<tr>\n<td>वरची बाजू</td>\n<td>क्रेडिट वजा कॉल स्प्रेड रुंदी</td>\n<td>रुपये 20,179 उणे 6,500 रुपये = नफा, कोणताही धोका नाही</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>प्रति शेअर स्ट्राइक वजा क्रेडिट ठेवा</td>\n<td>23,950 वजा 310 = 23,640</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>पाच बंद भावांवर व्यापार सेटल करा. पुट कमाल (स्ट्राइक मायनस NIFTY, 0) आणि कॉल किमतीची कमाल आहे(NIFTY वजा स्ट्राइक, 0) प्रति शेअर, नेट प्रति लॉट 65 सह.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>लघु 23,950 PE (तुम्ही देणे आहे)</th>\n<th>लहान 24,150 CE (तुम्ही देणे बाकी आहे)</th>\n<th>लांब 24,250 CE (तुमच्या मालकीचे)</th>\n<th>निव्वळ पी आणि एल प्रति लॉट</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,400</td>\n<td>550</td>\n<td>0</td>\n<td>0</td>\n<td>उणे रु 15,571 (उणे नुकसान)</td>\n</tr>\n<tr>\n<td>23,640</td>\n<td>310</td>\n<td>0</td>\n<td>0</td>\n<td>सुमारे रु. (डाउनसाइड ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु 20,179 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु 20,179 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,450</td>\n<td>0</td>\n<td>300</td>\n<td>200</td>\n<td>अधिक रु 13,679 (वरची मर्यादा, तरीही नफा)</td>\n</tr>\n</tbody></table>\n<p>खाली वाचा आणि जादू तळाच्या ओळीत आहे. वरच्या विकल्या गेलेल्या स्ट्राइकपेक्षा NIFTY 300 पॉइंट्स वर असतानाही, तुम्ही अजूनही 13,679 रुपये बँक आहात, कारण विकत घेतलेल्या 24,250 कॉल कॉल कॅप्समध्ये कॉल पसरतात आणि क्रेडिट कव्हर करते. गमावण्याचा एकमेव मार्ग म्हणजे 23,640 च्या खाली घसरण, जेथे नग्न ठेवतात. एक शेपूट फक्त पुसली गेली आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>जेड सरडा अजूनही नग्न शॉर्ट पुट वाहून नेतो, त्यामुळे त्याचे डाउनसाइड नुकसान खूप मोठे आहे, जर NIFTY शून्यावर पडल्यास सुमारे 15.4 लाख रुपये सूचीबद्ध केले जातात. कोणताही वरचा धोका नाही, परंतु डाव्या शेपटी वास्तविक आहे. एकदा NIFTY 23,640 च्या ब्रेकइव्हनच्या खाली गेल्यावर तुम्ही प्रत्येक पॉइंटसाठी 65 रुपये गमावाल, त्यामुळेच एक्सचेंज सुमारे 1.71 लाख रुपयांचे मार्जिन ब्लॉक करते. जेड सरडेला एक बुलिश टू न्यूट्रल क्रेडिट ट्रेड म्हणून वागवा ज्याचा बचाव करण्यासाठी गंभीर नकारात्मक बाजू आहे, मोफत लंच नाही.</p>\n</div></div>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>द <strong>नफ्याची शक्यता 68 टक्के आहे</strong>. NIFTY 23,640 ब्रेकइव्हनच्या वर कुठेही बसू शकतो आणि तुम्ही हिरव्या रंगात पूर्ण कराल, जे एक विस्तृत कुशन आहे, आणि तो कितीही धावला तरीही संपूर्ण वरचा फायदा होतो. चार्ट खालच्या सिग्मा बँडच्या खाली बसलेला ब्रेकईव्हन दर्शवितो, त्यामुळे गमावलेला एकमेव परिणाम म्हणजे डाउनसाइडला खरा ब्रेक.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>खूप मोठा तोटा या शब्दांपुढील नफ्याची 68 टक्के संभाव्यता वाचा. जेड सरडा बहुतेक वेळा जिंकतो आणि वरची चिंता पूर्णपणे काढून टाकतो, परंतु वाचलेली नकारात्मक बाजू नग्न असते. एक अनुकूल विजय दर फक्त अर्धा व्यापार आहे. जेड सरडा फक्त तेव्हाच ठेवा जेव्हा तुमचा रक्षण करण्याची किंवा शॉर्ट पुट बंद करण्याची योजना असेल जर NIFTY तुटण्यास सुरुवात झाली आणि त्याचा आकार द्या जेणेकरून त्या बाजूला एक खराब अंतर खाते खराब करू शकत नाही.</p>\n</div></div>\n<h2 id=\"margin-and-return-on-margin\">मार्जिन आणि मार्जिनवर परतावा</h2>\n<p>कारण शॉर्ट पुट नग्न आहे, एक्सचेंज एक जड अवरोधित करते <strong>सुमारे रु. 1,70,750 चे मार्जिन</strong>. खरेदी केलेला कॉल उलट धोका कमी करतो परंतु पुटसाठी काहीही करत नाही, त्यामुळे मार्जिन मोठा राहतो, ती एक उघडी शेपूट वाहून नेण्याची रोख किंमत.</p>\n<p>चालू <strong>मार्जिन वर परत</strong>, रु. 1,70,750 ब्लॉक केलेले रु. 20,179 क्रेडिट सुमारे आहे <strong>12 टक्के</strong> महिन्याभरात जर NIFTY ब्रेकइव्हनच्या वर असेल. ते एक अस्सल उत्पन्न आहे, परंतु ते अपरिभाषित नकारात्मक बाजूवर चालते, म्हणून जोखीमनुसार त्याचा न्याय करा, शीर्षकानुसार नाही.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>जेड सरडा हा निव्वळ विक्रेता आहे, जो 20,179 रुपये प्रीमियम गोळा करतो, त्यामुळे वेळेचा क्षय तुमच्यासाठी काम करतो. द <strong>निळ्या डॅशची T+0 रेखा</strong> मध्यभागी ऑरेंज ॲट-एक्सपायरी प्रॉफिट शेल्फच्या खाली बसते आणि प्रत्येक शांत दिवस विक्रीचे पर्याय वितळल्यामुळे स्थिती उंचावते. जोपर्यंत NIFTY 23,640 च्या वर आहे तोपर्यंत वेळ तुमच्या बाजूने आहे. त्याखाली, क्षय मदत करणे थांबवते आणि नग्न पुट ताब्यात घेते.</p>\n<h2 id=\"the-reverse-jade-lizard\">रिव्हर्स जेड सरडा</h2>\n<p>द <strong>उलटा जेड सरडा</strong> त्याऐवजी नकारात्मक बाजू पुसून टाकण्यासाठी संरचना फ्लिप करते. तुम्ही पैशाच्या वरचा कॉल विकता, त्याखालील पुट विकता आणि नकारात्मक बाजूंना कुंपण घालण्यासाठी आणखी पुट विकत घेता.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल विक्री</td>\n<td>24,150</td>\n<td>370.1 प्राप्त झाले</td>\n<td>अधिक रु 24,057 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>23,950</td>\n<td>256.6 प्राप्त झाले</td>\n<td>अधिक रु 16,679 मध्ये</td>\n</tr>\n<tr>\n<td>3</td>\n<td>पुट खरेदी करा</td>\n<td>23,850</td>\n<td>224.1 भरले</td>\n<td>14,570 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>अधिक रु 26,166 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<p>दोन विकल्या गेलेल्या पर्यायांची किंमत 40,736 रुपये आहे, विकत घेतलेल्या 23,850 पुटची किंमत 14,570 रुपये आहे आणि पोझिशन एकासाठी उघडते. <strong>26,166 रुपये निव्वळ क्रेडिट</strong>, जास्तीत जास्त नफा देखील, 23,950 आणि 24,150 च्या दरम्यान ठेवला. या वेळी पाय 2 आणि 3 एक वळू पुट 23,950 ते 23,850 पर्यंत शंभर गुण पसरले, ज्याचे सर्वात जास्त नुकसान 6,500 रुपये आहे. तुमची रु. 26,166 ची क्रेडिट बौना आहे, त्यामुळे क्रॅश कमी झाल्यास क्रेडिट सहज कव्हर करते, तुमचे सुमारे 19,666 रु. त्यामुळे रिव्हर्स जेड सरडे असते <strong>कोणताही नकारात्मक धोका नाही</strong>. नग्न बाजू आता वरची बाजू आहे, विकले गेले 24,150 कॉल, एकल सह <strong>24,553 वर ब्रेकईव्हन</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-reverse-jade-lizard.png\" alt=\"NIFTY रिव्हर्स जेड लिझार्ड: मधोमध 26,166 रुपयांचा सपाट कमाल नफा, डावी बाजू जी कितीही दूर गेली तरी नफ्यातच राहते कारण NIFTY कितीही कमी झाले तरी क्रेडिट पुट स्प्रेड कव्हर करते आणि 24,553 वर सिंगल अपसाइड ब्रेकइव्हन जेथे नग्न शॉर्ट कॉल मर्यादेशिवाय चालतो.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY रिव्हर्स जेड लिझार्ड: मधोमध 26,166 रुपयांचा सपाट कमाल नफा, डावी बाजू जी कितीही दूर गेली तरी नफ्यातच राहते कारण NIFTY कितीही कमी झाले कारण क्रेडिट पुट स्प्रेड कव्हर करते आणि 24,553 वर सिंगल अपसाइड ब्रेकइव्हन जेथे नग्न शॉर्ट कॉल मर्यादेशिवाय चालतो.</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>लहान 24,150 CE (तुम्ही देणे बाकी आहे)</th>\n<th>लघु 23,950 PE (तुम्ही देणे बाकी आहे)</th>\n<th>लांब 23,850 PE (तुमच्या मालकीचे)</th>\n<th>निव्वळ पी आणि एल प्रति लॉट</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,600</td>\n<td>0</td>\n<td>350</td>\n<td>250</td>\n<td>अधिक रु. 19,666 (डाउनसाइड कॅप्ड, तरीही नफा)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु 26,166 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>अधिक रु 26,166 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,553</td>\n<td>403</td>\n<td>0</td>\n<td>0</td>\n<td>सुमारे रु. (अपसाइड ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,750</td>\n<td>600</td>\n<td>0</td>\n<td>0</td>\n<td>उणे रु 12,834 (तोटा मर्यादेशिवाय वाढतो)</td>\n</tr>\n</tbody></table>\n<p>वरच्या पंक्तीमध्ये जेड लिझार्डची जादू उलटसुलटपणे दिसून येते: अगदी कमी विकल्या गेलेल्या स्ट्राइकपेक्षा NIFTY 350 पॉइंट्सने खाली, तरीही तुम्ही रु. 19,666 बँक आहात, कारण खरेदी केलेल्या 23,850 पुट कॅप्स द पुट स्प्रेड. द <strong>नफ्याची शक्यता 72 टक्के आहे</strong>, आणि मार्जिन सुमारे रु 1,76,758 आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>रिव्हर्स जेड सरड्याचे जास्तीत जास्त नुकसान होते जे अमर्यादित असते. विकल्या गेलेल्या 24,150 कॉलला त्याच्या वर कोणतेही संरक्षण नाही, त्यामुळे एकदा NIFTY 24,553 च्या ब्रेकईव्हनच्या पुढे गेल्यावर तुम्हाला कमाल मर्यादा नसताना 65 रुपये प्रति पॉइंट गमवावे लागतील, म्हणूनच एक्सचेंज सुमारे 1.77 लाख रुपयांचे मार्जिन ब्लॉक करेल. नकारात्मक बाजू पूर्णपणे झाकलेली आहे, परंतु येथे मंदीचा तटस्थ झुकाव रॅलीवर अस्सल अनकॅप्ड शेपटीसह येतो. शॉर्ट कॉल ठेवण्यापूर्वी त्याचा बचाव करण्याची योजना तयार करा.</p>\n</div></div>\n<h2 id=\"why-the-credit-erases-a-tail\">का श्रेय एक शेपूट पुसून टाकते</h2>\n<p>दोन्ही रचना स्पष्टपणे सांगण्यासारख्या अंकगणिताच्या एका तुकड्यावर अवलंबून आहेत. संरक्षित बाजूस तुम्ही शंभर पॉइंट रुंद स्प्रेड धरला आहे आणि सर्वात जास्त शंभर पॉइंट स्प्रेड 6,500 रुपये गमावू शकतो. जर तुम्ही जमा केलेले क्रेडिट रु. 6,500 पेक्षा मोठे असेल, तर त्या बाजूच्या सर्वात वाईट परिस्थितीतही तुम्हाला नफा मिळतो. क्रेडिट संपूर्ण स्प्रेड लॉस शोषून घेते आणि तरीही पैसे शिल्लक आहेत.</p>\n<p>हे संपूर्ण रहस्य आहे. तुम्ही महागडे संरक्षण खरेदी करत नाही. तुम्ही एका रिच विकल्या गेलेल्या पर्यायातून प्रीमियम वापरत आहात दुसऱ्या बाजूला असलेल्या छोट्या स्प्रेडसाठी देय देण्यापेक्षा अधिक, फक्त एका दिशेने जोखीम ठेवून मोबदला.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>जेड सरडा तटस्थ ते उत्साही असतो: जेव्हा उजव्या बाजूच्या बुलेटप्रूफसह आणि फक्त बचाव करण्यासाठी पडलेल्या अवस्थेसह NIFTY वर ठेवतो किंवा वर जातो तेव्हा ते पैसे कमवते. रिव्हर्स जेड सरडा तटस्थ ते मंदीचा असतो: जेव्हा NIFTY मऊ करते किंवा धरून ठेवते, डाव्या बाजूच्या बुलेटप्रूफसह आणि बचावासाठी फक्त रॅली असते तेव्हा त्याचा फायदा होतो. ज्याची नग्न शेपटी तुमच्या वास्तविक दृश्यापासून दूर आहे ती निवडा, म्हणजे तुम्हाला ज्या बाजूची भीती वाटते ती बाजू तुम्हाला दुखवू शकत नाही.</p>\n</div></div>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>जेड सरडा पुट आणि कॉल विकतो आणि कॉल स्प्रेड रुंदीपेक्षा मोठे क्रेडिट गोळा करून आणखी एक कॉल खरेदी करतो. <strong>वरची बाजू गमावू शकत नाही</strong>.</li>\n<li>तो गोळा करतो <strong>20,179 रु</strong> (त्याचा जास्तीत जास्त नफा), 23,950 आणि 24,150 च्या दरम्यान संपूर्ण क्रेडिट ठेवते आणि फक्त खाली असलेल्या नकारात्मक बाजूंना धोका असतो <strong>23,640 ब्रेकइव्हन</strong>, जेथे नग्न शॉर्ट पुट चावणे.</li>\n<li>रिव्हर्स जेड सरडा ते पलटवतो: a <strong>26,166 रु</strong> क्रेडिट नकारात्मक बाजू पूर्णपणे मिटवते, एक सोडून <strong>अमर्यादित</strong> वरची शेपटी <strong>24,553 ब्रेकईव्हन</strong>.</li>\n<li>दोघेही 68 आणि 72 टक्के फायद्याची उच्च संभाव्यता घालतात, कारण एक संपूर्ण शेपूट काढली जाते, परंतु जिवंत शेपूट नग्न असते आणि <strong>मार्जिनचे रु. 1.7 लाख</strong>.</li>\n<li>अशी रचना निवडा जिची उघडी शेपूट तुमच्या दृष्टीकोनातून दूर असेल: जेड सरडा जेव्हा तुम्ही हलके झुकता तेव्हा बुलिश, उलट जेव्हा तुम्ही हलके झुकता तेव्हा मंदपणा.</li>\n<li>दोन्ही मध्ये तयार करा <strong>सँडबॉक्स ट्रेडिंग ( OpenAlgo मधील विश्लेषक मोड)</strong>, संरक्षित बाजूकडे किंमत ड्रॅग करा आणि तेथे कधीही लाल होणार नाही हे पहा, नंतर तोटा कुठे सुरू होतो हे पाहण्यासाठी ती उघड्या बाजूला ड्रॅग करा.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"खरा व्यापार, रुपयाने रुपया","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"मार्जिन आणि मार्जिनवर परतावा","id":"margin-and-return-on-margin"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"रिव्हर्स जेड सरडा","id":"the-reverse-jade-lizard"},{"level":2,"text":"का श्रेय एक शेपूट पुसून टाकते","id":"why-the-credit-erases-a-tail"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"19":{"html":"<p>आतापर्यंतच्या प्रत्येक संरचनेने एकच आकार, एक तंबू, एक शेल्फ किंवा एक दरी काढली आहे. हा धडा एकाच तक्त्यावर त्यापैकी दोन स्टॅक करतो. तुम्हाला आधीच माहित असलेले पेऑफ घेणारे चित्र, ते कॉपी करणे, आणि आकृती एक ऐवजी दोन स्वतंत्र कुबडे वाढेपर्यंत प्रत किंमत अक्षावर सरकवणे. त्यामागचे रहस्य आहे <strong>बॅटमॅन</strong>, द <strong>दुहेरी माशी</strong>, आणि द <strong>दुहेरी कंडोर</strong>. प्रत्येकाने दोन श्रेणी रचना शेजारी शेजारी ठेवल्या आहेत आणि एका बिंदूवर न ठेवताNIFTY′ दोनपैकी एका झोनमध्ये स्थायिक होईल. ते पडद्यावर भयंकर दिसतात, तरीही प्रत्येकजण फक्त दोन परिचित तुकडे आहेत जे एक आकृती सामायिक करतात.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>तिघेही एकाच प्रश्नाचे उत्तर देतात: तुम्हाला एकाच पिनऐवजी ट्विन-पीक किंवा विस्तीर्ण नफा क्षेत्र हवे असल्यास काय? ए <strong>बॅटमॅन</strong> पैशाच्या खाली पुट रेशो विंग त्याच्या वर असलेल्या कॉल रेशो विंगवर बोल्ट करा, त्यांच्यामध्ये शांतपणे बुडवून दोन उंच शिखरे वाढवा. ए <strong>दुहेरी माशी</strong> दोन फुलपाखरे शेजारी शेजारी ठेवतात आणि अ <strong>दुहेरी कंडोर</strong> दोन कंडोर्स शेजारी शेजारी ठेवतात, प्रत्येक मध्यभागी लॉस व्हॅलीसह दुहेरी नफा क्षेत्र देते. बॅटमॅन तुम्हाला निव्वळ क्रेडिट देतो परंतु प्रत्येक टोकाला एक नग्न शेपूट लपवतो. दुहेरी माशी आणि दुहेरी कंडर पूर्णपणे परिभाषित-जोखीम आहेत, तुम्ही प्रवेश करण्यापूर्वी तिकीटावर सर्वात वाईट केस छापलेले आहेत.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>बॅटमॅन, दुहेरी माशी आणि दुहेरी कंडोर प्रत्येक ठिकाणी दोन श्रेणी रचना शेजारी शेजारी ठेवतात, त्यामुळे पेऑफ एका ऐवजी दोन नफा क्षेत्र वाढतो. बॅटमॅन हा एक विस्तृत, उच्च-संभाव्यता क्रेडिट ट्रेड आहे ज्याच्या दोन्ही टोकांना उघड्या शेपट्या आहेत. डबल फ्लाय आणि डबल कंडोर स्वस्त, परिभाषित-जोखीम बेट्स आहेत जे NIFTY दोन्ही बाजूंनी मध्यम हलवा करतात आणि दोनपैकी एका झोनमध्ये उतरतात.</p>\n</div></div>\n<h2 id=\"the-batman-leg-by-leg\">बॅटमॅन, पायाने पाय</h2>\n<p>बॅटमॅन त्याचे नाव त्याच्या बाह्यरेषेवरून घेतो, पैशाच्या दोन्ही बाजूला दोन शिखरे गुराखीच्या कानाप्रमाणे वाढतात, त्यांच्यामध्ये बुडवून ठेवतात. तुम्ही ते 28 जुलै 2026 च्या एक्सपायरीला दोन रेशो विंग्समधून तयार करा, पैशाच्या खाली पुट विंग आणि त्याच्या वर कॉल विंग.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रकार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 खरेदी करा</td>\n<td>23,550</td>\n<td>ठेवा</td>\n</tr>\n<tr>\n<td>2</td>\n<td>2 विक्री करा</td>\n<td>23,300</td>\n<td>ठेवा</td>\n</tr>\n<tr>\n<td>3</td>\n<td>1 खरेदी करा</td>\n<td>24,550</td>\n<td>कॉल करा</td>\n</tr>\n<tr>\n<td>4</td>\n<td>2 विक्री करा</td>\n<td>24,800</td>\n<td>कॉल करा</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>सुमारे रु 5,941</strong></td>\n</tr>\n</tbody></table>\n<p>दोन विकल्या गेलेल्या जोड्या दोन पायांच्या किंमतीपेक्षा जास्त प्रीमियम आणतात, त्यामुळे बॅटमॅन सुमारे रु 5,941 च्या निव्वळ क्रेडिटसाठी उघडतो. डीप विंग स्ट्राइक 23,300 आणि 24,800 स्नॅपशॉटच्या मध्यवर्ती स्ट्राइकच्या पलीकडे बसतात, म्हणून आम्ही प्रत्येक डीप प्रीमियम ऐवजी संरचना आणि त्याचे निव्वळ क्रेडिट कोट करतो. प्रत्येक विंग एक गुणोत्तर फ्रंट स्प्रेड आहे, लांब एक पर्याय आणि लहान दोन पुढे, आणि प्रत्येक स्वतःचे शिखर तयार करतो.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-batman.png\" alt=\"NIFTY बॅटमॅन: पैशाच्या दोन्ही बाजूंनी 22,191 रुपयांपर्यंत पोहोचणारा दुहेरी नफ्याचा शिखर, स्पॉटभोवती 5,941 रुपयांचे क्रेडिट धारण करणारा एक शांत डिप आणि 22,959 आणि 25,141 वर ब्रेकव्हेन्स ज्याच्या पलीकडे नग्न गुणोत्तर शेपटी खूप मोठ्या मजल्याशिवाय पळतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY बॅटमॅन: पैशाच्या दोन्ही बाजूंनी 22,191 रुपयांपर्यंत पोहोचणारी दुहेरी नफ्याची शिखरे, स्पॉटच्या आसपास 5,941 रुपयांचे क्रेडिट धारण करणारी एक शांत बुडबुडी आणि 22,959 आणि 25,141 वर ब्रेकव्हेन्स ज्याच्या पलीकडे नग्न गुणोत्तर शेपटी फार मोठ्या मजल्याशिवाय पळून जातात.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p>बॅटमॅनचे हेडलाइन नंबर सर्व त्याच्या दोन पंखांमधून सरळ पडतात, लक्षात ठेवण्याची आवश्यकता नाही.</p>\n<p><strong>जास्तीत जास्त नफा एकतर शॉर्ट स्ट्राइकवर येतो, रु. 22,191.</strong> कॉल बाजूला घ्या. जर NIFTY 24,800 वर संपला, तर तुमचा लांब 24,550 कॉल 250 पॉइंट्सचा आहे तर दोन्ही लहान 24,800 कॉल्स निरर्थक कालबाह्य होतात. त्या 250 गुणांचे मूल्य 250 गुणिले 65 आहे, जे 16,250 रुपये आहे आणि तुम्ही अजूनही 5,941 रुपये क्रेडिट ठेवा. त्यामुळे शिखर 16,250 अधिक 5,941 आहे, 22,191 रुपये आहे. पुट विंग 22,191 रुपयांमध्ये 23,300 वर पोहोचला आहे.</p>\n<p><strong>ब्रेकवेन्स नग्न शेपटीतून येतात.</strong> 24,800 च्या वर तुम्ही नेट शॉर्ट एक कॉल आहात, त्यामुळे प्रत्येक पॉईंट जास्तीसाठी रु. 22,191 चे शिखर 65 रुपये वर वितळते. 22,191 ला 65 ने भागल्यास सुमारे 341 गुण मिळतात, त्यामुळे वरचा ब्रेकइव्हन 24,800 अधिक 341 आहे, जो 25,141 आहे. लोअर ब्रेकइव्हन 23,300 वजा 341, जे 22,959 आहे. मागील एकतर बिंदू हानी चालू राहते, वर कमाल मर्यादा नाही आणि खाली खूप मोठा मजला.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>क्रेडिट प्लस 250-पॉइंट विंग कॅप्चर</td>\n<td>रु 5,941 अधिक रु. 16,250 म्हणजे रु. 22,191</td>\n</tr>\n<tr>\n<td>अप्पर ब्रेकवेन</td>\n<td>शॉर्ट कॉल स्ट्राइक प्लस पॉइंट्समध्ये शिखर</td>\n<td>24,800 अधिक 341 बरोबर 25,141</td>\n</tr>\n<tr>\n<td>लोअर ब्रेकइव्हन</td>\n<td>पॉइंट्समध्ये शॉर्ट पुट स्ट्राइक वजा शिखर</td>\n<td>23,300 वजा 341 बरोबर 22,959</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>नग्न शेपटी, कमाल मर्यादा नाही</td>\n<td>अमर्यादित</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>बॅटमॅनला क्लोजिंग किमतींच्या प्रसारावर सेटल करा आणि दुहेरी-पीक आकार स्वतःच दिसून येईल. प्रत्येक पंक्ती प्रति लॉट ६५ आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>पंख काय करतात</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>22,800</td>\n<td>शेपूट चालू ठेवा</td>\n<td>उणे रु. 10,309, आणि घसरण</td>\n</tr>\n<tr>\n<td>22,959</td>\n<td>कमी ब्रेकवेन</td>\n<td>सुमारे रु</td>\n</tr>\n<tr>\n<td>23,300</td>\n<td>विंग शिखर ठेवा</td>\n<td>अधिक रु 22,191 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,056</td>\n<td>शांत मध्यभागी</td>\n<td>अधिक रु 5,941 (क्रेडिट)</td>\n</tr>\n<tr>\n<td>24,800</td>\n<td>कॉल विंग पीक</td>\n<td>अधिक रु 22,191 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>25,141</td>\n<td>वरचे ब्रेकवेन</td>\n<td>सुमारे रु</td>\n</tr>\n<tr>\n<td>25,400</td>\n<td>कॉल टेल चालू</td>\n<td>उणे रु. 16,809, आणि वाढत आहे</td>\n</tr>\n</tbody></table>\n<p>मधूनच वाचा. स्पॉटच्या आसपास पोझिशन फक्त त्याचे रु 5,941 क्रेडिट ठेवते, दोन कानांमधील बुडविणे. एकतर शॉर्ट स्ट्राइककडे जा आणि एक विंग त्याच्या रु. 22,191 च्या शिखरावर परतफेड करेल. ब्रेकईव्हनच्या पुढे जा आणि नग्न शेपूट ताब्यात घेईल, तोटा 25,141 पेक्षा जास्त मर्यादेशिवाय वाढत आहे आणि 22,959 च्या खाली असलेल्या खूप मोठ्या आकृतीकडे.</p>\n<h2 id=\"your-odds\">आपल्या शक्यता</h2>\n<p>बॅटमॅनचा <strong>नफ्याची शक्यता सुमारे 78 टक्के आहे</strong>, कोर्सच्या या भागात सर्वाधिक क्रेडिट-ट्रेड शक्यता. हा आकडा थेट ब्रेकवेन्समधील रुंदीवरून येतो. NIFTY ची अंदाजे 12.7 टक्के निहित अस्थिरता आणि 32 दिवस शिल्लक वापरून, बाजार 22,959 आणि 25,141 च्या दरम्यान एक्सपायरीपर्यंत इंडेक्स पूर्ण होण्याची 78 टक्के शक्यता ठेवतो आणि तो संपूर्ण बँड नफा आहे. चार्टवरील फिकट सिग्मा बँड ब्रेकवेन्सच्या आत चांगले बसतात, त्यामुळेच शक्यता इतकी जास्त आहे.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>ते 78 टक्के कधीही वाचू नका, त्याशिवाय जास्तीत जास्त नुकसान न वाचता. बॅटमॅन पाच पैकी साधारणपणे चार वेळा जिंकतो, पण एक गमावलेला वेळ हा वरच्या बाजूने ओपन-एंडेड असतो, जेथे नग्न कॉलला कमाल मर्यादा नसते आणि डाउनसाइडवर खूप मोठी असते, जेथे नग्न पुट्स शून्यावर जमिनीकडे धावतात. तोट्याशी संलग्न नफ्याची उच्च संभाव्यता ही सर्वात मोहक आणि पर्यायांमध्ये सर्वात धोकादायक आकार आहे. दुखापत होईल अशा हालचालीनुसार आकार द्या, किती वेळा पैसे द्यावे यावर नाही.</p>\n</div></div>\n<h2 id=\"margin-the-heaviest-in-the-course\">मार्जिन, अभ्यासक्रमातील सर्वात भारी</h2>\n<p>कारण बॅटमॅन दोन नग्न लहान जोड्या घेऊन जातो, एक्सचेंज ब्लॉक करते <strong>मार्जिनचे रु. 209,721</strong>, या कोर्समध्ये कोठेही सर्वात मोठी मागणी आहे, ज्याला परिभाषित स्प्रेडप्रमाणे संकुचित करण्यासाठी कोणतेही संरक्षणात्मक दूरचे पंख नाहीत. त्या मार्जिनच्या तुलनेत, 5,941 रुपयांचे शांत मध्यम क्रेडिट हे 3 टक्क्यांपेक्षा कमी उत्पन्न आहे आणि अगदी लहान स्ट्राइकवर एक परिपूर्ण पिन, 22,191 रुपयांचे शिखर, केवळ 11 टक्के आहे. नग्न पर्यायांसह विकत घेतलेला एक विस्तृत विजय क्षेत्र ठेवण्यासाठी कधीही स्वस्त नाही.</p>\n<h2 id=\"time-decay\">वेळ क्षय</h2>\n<p>बॅटमॅन हा निव्वळ क्रेडिट ट्रेड आहे, त्यामुळे शांत दिवस आपल्या मार्गावर झुकतात. जसजसे एक्स्पायरी जवळ येते तसतसे तुम्ही लांब असलेल्या पर्यायांपेक्षा तुमचा क्षय लवकर होतो, जरNIFTY′ लहान स्ट्राइककडे वळला तर पेऑफ शिखराकडे जाईल. निळी T+0 रेषा चार्टच्या मध्यभागी नारिंगी ॲट-एक्सपायरी रेषेच्या खाली बसते, जोपर्यंत किमती पंखांच्या आत राहते तोपर्यंत हळूहळू रिवॉर्ड मिळतात अशा स्थितीची स्वाक्षरी.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>बॅटमॅनला प्रभावीपणे अमर्यादित कमाल नुकसान होते. अतिरिक्त विकल्या गेलेल्या 24,800 कॉल्सद्वारे ते वर नग्न आहे आणि अतिरिक्त विकल्या गेलेल्या 23,300 पुट्सद्वारे खाली नग्न आहे. 25,141 च्या वरच्या ब्रेकईव्हनला गेल्यावर तोटा रॅलीमध्ये कोणत्याही कमाल मर्यादेशिवाय चढतो, त्यामुळे वरची बाजू खरोखर अमर्यादित आहे; 22,959 च्या खालच्या ब्रेकईव्हनच्या पुढे ते घसरणीवर खूप मोठ्या आकड्याकडे खोलवर जाते, केवळ निर्देशांक शून्यावर पोहोचतो. नफ्याची 78 टक्के संभाव्यता विस्तृत शांत बँडचे वर्णन करते, दोन्ही शेपटीच्या आकाराचे नाही. हा व्यावसायिकांचा श्रेणी व्यापार आहे, नवशिक्याचे पहिले श्रेय नाही आणि एखाद्या कार्यक्रमात तो कधीही नग्न होऊ नये.</p>\n</div></div>\n<h2 id=\"the-double-fly\">दुहेरी माशी</h2>\n<p>दुहेरी माशी पूर्णपणे परिभाषित जोखमीसाठी बॅटमॅनच्या उघड्या शेपटीचा व्यापार करते. हे दोन फुलपाखरे शेजारी शेजारी ठेवते, एक 23,650 च्या खाली आणि एक त्याच्या वर 24,450 च्या जवळ, त्यामुळे सध्याच्या किमतीपेक्षा एका तंबूऐवजी तुम्हाला दोन तंबू मिळतील ज्यामध्ये दरी आहे.</p>\n<table>\n<thead>\n<tr>\n<th>घटक</th>\n<th>नफा क्षेत्र</th>\n<th>शिखर जवळ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>लोअर फुलपाखरू</td>\n<td>23,495 ते 23,805</td>\n<td>23,650</td>\n</tr>\n<tr>\n<td>वरचे फुलपाखरू</td>\n<td>24,295 ते 24,605</td>\n<td>24,450</td>\n</tr>\n</tbody></table>\n<p>चार <strong>ब्रेकवेन्स, 23,495, 23,805, 24,295 आणि 24,605</strong>, दोन तंबूंच्या कडा चिन्हांकित करा. तुम्हाला खालच्या तंबूत आणि वरच्या तंबूत फायदा होतो. तुम्ही तुमचे सर्वात जास्त नुकसान एकतर मध्यवर्ती खोऱ्यात किंवा दोन्ही तंबूंच्या बाहेरील भागात कराल, जिथे प्रत्येक लांब पंखाने आधीच नुकसान पूर्ण केले आहे. द <strong>कमाल नफा रु 10,072 आहे</strong> शिखरावर, आणि कारण प्रत्येक पाय संतुलित आहे आणि दूरचे पंख विकत घेतले आहेत, अ <strong>कमाल तोटा फक्त 2,928 रुपये आहे</strong>, एंटर करण्यासाठी तुम्ही दिलेले छोटे निव्वळ डेबिट आणि या ट्रेडमध्ये तुम्हाला कधीही खर्च होऊ शकतो.</p>\n<table>\n<thead>\n<tr>\n<th>मेट्रिक</th>\n<th>मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>10,072 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>2,928 रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>23,495 / 23,805 / 24,295 / 24,605</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>सुमारे 24 टक्के</td>\n</tr>\n<tr>\n<td>बक्षीस मिळण्याचा धोका</td>\n<td>1 : 3.4</td>\n</tr>\n<tr>\n<td>धोक्यात निव्वळ खर्च</td>\n<td>सुमारे रु. 2,928</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>130,313 रु</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-double-fly.png\" alt=\"NIFTY दुहेरी फ्लाय: दोन नफ्याचे तंबू, एक 23,650 च्या जवळ आणि एक 24,450 च्या जवळ, स्पॉटच्या आजूबाजूच्या लॉस व्हॅलीने विभक्त, 23,495, 23,805, 24,295 आणि 24,605 ​​वर चार ब्रेकइव्हनसह आणि फक्त 29,28 रुपयांचा तोटा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY दुहेरी फ्लाय: दोन नफ्याचे तंबू, एक 23,650 च्या जवळ आणि एक 24,450 च्या जवळ, स्पॉटच्या आसपास लॉस व्हॅलीने विभक्त केलेले, 23,495, 23,805, 24,295 आणि 24,605 ​​वर चार ब्रेकइव्हनसह आणि फक्त 29,28 रुपये निश्चित केलेले नुकसान.</figcaption></figure>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>जेव्हा NIFTY दोन्ही बाजूने मध्यम हालचाल करते आणि दोन तंबूंपैकी एका तंबूत उतरते तेव्हा दुहेरी माशीचा फायदा होतो आणि किंमत मध्य दरीत स्थिर राहिल्यास किंवा बाहेरील पंखांच्या पलीकडे गेल्यास तो तोटा होतो. हे 10,072 रुपयांच्या बक्षीसाच्या तुलनेत 2,928 रुपयांचे परिभाषित नुकसान जोडते, स्वच्छ 1 ते 3.4 पेऑफ, परंतु फायद्याची 24 टक्के संभाव्यता कॅचबद्दल प्रामाणिक आहे:NIFTY′ जिंकण्यासाठी बऱ्यापैकी अरुंद झोनमध्ये उतरावे लागेल.</p>\n</div></div>\n<h2 id=\"the-double-condor\">दुहेरी कंडर</h2>\n<p>दुहेरी कंडोर म्हणजे सपाट शीर्षांसह दुहेरी माशी. हे दोन कंडोर्स शेजारी शेजारी ठेवतात, एक पैशाच्या अगदी खाली आणि एक वर, म्हणून प्रत्येक नफा क्षेत्र तीव्र शिखराऐवजी एक लहान पठार आहे. त्या विस्तीर्ण गोड स्पॉटसाठी ट्रेड-ऑफ एक लहान बक्षीस आहे.</p>\n<table>\n<thead>\n<tr>\n<th>घटक</th>\n<th>नफा क्षेत्र</th>\n<th>केंद्र जवळ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>लोअर कंडोर</td>\n<td>23,807 ते 23,991</td>\n<td>23,899</td>\n</tr>\n<tr>\n<td>वरचा कंडर</td>\n<td>24,107 ते 24,291</td>\n<td>24,199</td>\n</tr>\n</tbody></table>\n<p>चार <strong>ब्रेकवेन्स, 23,807, 23,991, 24,107 आणि 24,291</strong>, दुहेरी माशीपेक्षा पैशाच्या जवळ बसा, म्हणून या संरचनेला एक लहान हालचाल हवी आहे. तुम्हाला खालच्या टेबलवर 23,807 ते 23,991 पर्यंत आणि वरच्या टेबलवर 24,107 ते 24,291 पर्यंत नफा मिळतो आणि तुम्ही अरुंद मध्य व्हॅलीमध्ये 24,050 च्या आसपास किंवा बाहेरील कडांच्या पलीकडे हराल. द <strong>कमाल नफा रु 2,675 आहे</strong> आणि <strong>जास्तीत जास्त नुकसान फक्त 575 रुपये आहे</strong>, तिघांपैकी सर्वात स्वस्त आणि तुम्ही देय असलेल्या छोट्या डेबिटच्या समान.</p>\n<table>\n<thead>\n<tr>\n<th>मेट्रिक</th>\n<th>मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>रु. 2,675</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>५७५ रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>23,807 / 23,991 / 24,107 / 24,291</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>सुमारे 16 टक्के</td>\n</tr>\n<tr>\n<td>बक्षीस मिळण्याचा धोका</td>\n<td>1 : 4.6</td>\n</tr>\n<tr>\n<td>निव्वळ डेबिट</td>\n<td>५७५ रु</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>रु. 127,183</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-double-condor.png\" alt=\"NIFTY दुहेरी कंडोर: दोन फ्लॅट-टॉप केलेले प्रॉफिट टेबल, एक 23,900 च्या जवळ आणि एक 24,200 च्या जवळ, स्पॉटच्या आसपास लॉस व्हॅलीने विभक्त केलेले, चार ब्रेकइव्हन्ससह आणि फक्त 575 रुपयांचा एक छोटा परिभाषित सर्वात वाईट तोटा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY दुहेरी कंडोर: दोन फ्लॅट-टॉप केलेले नफा टेबल, एक 23,900 च्या जवळ आणि एक 24,200 च्या जवळ, स्पॉटच्या आसपास लॉस व्हॅलीने विभक्त केलेले, चार ब्रेकइव्हन्ससह आणि फक्त 575 रुपयांचा एक छोटा परिभाषित सर्वात वाईट तोटा.</figcaption></figure>\n<h2 id=\"how-the-three-compare\">तिघांची तुलना कशी होते</h2>\n<table>\n<thead>\n<tr>\n<th>रणनीती</th>\n<th>जास्तीत जास्त नफा</th>\n<th>कमाल नुकसान</th>\n<th>लाभाची शक्यता</th>\n<th>धोका</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>बॅटमॅन</td>\n<td>22,191 रु</td>\n<td>अमर्यादित</td>\n<td>78 टक्के</td>\n<td>दोन्ही बाजूंनी नग्न</td>\n</tr>\n<tr>\n<td>दुहेरी माशी</td>\n<td>10,072 रु</td>\n<td>2,928 रु</td>\n<td>24 टक्के</td>\n<td>परिभाषित</td>\n</tr>\n<tr>\n<td>दुहेरी कंडर</td>\n<td>रु. 2,675</td>\n<td>५७५ रु</td>\n<td>16 टक्के</td>\n<td>परिभाषित</td>\n</tr>\n</tbody></table>\n<p>तिघांची दोन छावण्या झाली. द <strong>बॅटमॅन</strong> हा एक उच्च-संभाव्यता क्रेडिट ट्रेड आहे जो मोठ्या श्रेणीमध्ये जिंकतो परंतु दोन्ही बाजूंना नग्न शेपूट लपवतो आणि कोर्समध्ये सर्वात जास्त फरक असतो. द <strong>दुहेरी माशी</strong> आणि <strong>दुहेरी कंडोर</strong> कोणत्याही प्रकारे मध्यम चालीवर पूर्णपणे परिभाषित-जोखीम बेट आहेत, फक्त रु 2,928 आणि रु 575 च्या सर्वात वाईट केसेससह, परंतु कमी शक्यता, कारण किंमत भरण्यासाठी बऱ्यापैकी घट्ट क्षेत्रामध्ये उतरणे आवश्यक आहे. रिवॉर्ड आणि ऑड्सचा व्यवहार कसा होतो याकडे लक्ष द्या: बॅटमॅन नग्न शेपटी विकून त्याचा 78 टक्के जिंकण्याचा दर विकत घेतो, तर दुहेरी कॉन्डोरचा 1 ते 4.6 पेऑफ फक्त 16 टक्के ऑड्सवर येतो. तेथे कोणतेही विनामूल्य दुपारचे जेवण नाही, फक्त नग्न धोका किंवा लहान, कमी संभाव्य बक्षीस.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>नवशिक्यासाठी, दुहेरी माशी आणि दुहेरी कंडर हे या कुटुंबाचे सुरक्षित सदस्य आहेत. त्यांची सर्वात वाईट केस तिकिटावर छापलेली आहे, काही हजार रुपये किंवा त्याहून कमी, आणि ते तुम्हाला शिकवतात की रचलेल्या संरचना तुम्हाला पळून जाणारे नुकसान उघड न करता कसे वागतात. दोन्ही बाजूंनी एकाच वेळी नग्न पर्यायांचा बचाव करणे तुम्हाला पूर्णपणे सोयीस्कर होईपर्यंत बॅटमॅनला सोडा, आणि त्याच्या दुहेरी शेपट्या कधीही अनहेज्ड इव्हेंटमध्ये घेऊन जाऊ नका.</p>\n</div></div>\n<p>तुम्ही सँडबॉक्स ट्रेडिंगमध्ये तिन्ही तयार करू शकता (OpenAlgo मध्ये विश्लेषक मोड) आणि मॉडेल केलेली किंमत तंबूमध्ये ड्रॅग करू शकता आणि प्रत्येक रचना कुठे जिंकते आणि हरते हे अनुभवण्यासाठी आणि बॅटमॅनवर, नग्न शेपटीचा ताबा पाहण्यासाठी एका पंखाच्या मागे जाऊ शकता. पुढे आपण या एक्सपायरी-डे स्ट्रक्चर्समधून अशा ट्रेड्सकडे जातो जे कालांतराने काम करतात, कॅलेंडर आणि कर्णरेषा पसरतात.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>बॅटमॅन, दुहेरी माशी आणि दुहेरी कंडोर सर्व ठिकाणी <strong>शेजारी शेजारी दोन श्रेणी संरचना</strong>, एका ऐवजी दोन नफा क्षेत्र वाढवणे.</li>\n<li>द <strong>बॅटमॅन</strong> 5,941 च्या क्रेडिटसाठी उघडतो, एकतर शॉर्ट स्ट्राइकवर 22,191 रुपयांवर पोहोचतो आणि येथे विस्तृत बँडमध्ये जिंकतो <strong>78 टक्के शक्यता</strong>, पण त्याचे नुकसान आहे <strong>अमर्यादित</strong> दोन्ही बाजूंच्या नग्न शेपटींद्वारे.</li>\n<li>त्याचे ब्रेकवेव्हन्स, <strong>22,959 आणि 25,141</strong>, शॉर्ट स्ट्राइक वरून थेट गुणांमध्ये अधिक किंवा उणे शिखरावर या आणि त्यांना मागे टाकून नुकसान दूर होईल.</li>\n<li>द <strong>दुहेरी माशी</strong> परिभाषित-जोखीम: कमाल नफा रु 10,072, कमाल तोटा फक्त रु 2,928, चार ब्रेकइव्हन्स, 24 टक्के शक्यतांवर 1 ते 3.4 पेऑफ.</li>\n<li>द <strong>दुहेरी कंडोर</strong> सर्वात स्वस्त आणि सपाट आहे: कमाल नफा रु 2,675, कमाल तोटा फक्त रु 575, रुंद जुळे टेबल पण सर्वात कमी शक्यता 16 टक्के.</li>\n<li>नवशिक्यांनी सह रहावे <strong>परिभाषित-जोखीम जोडी</strong> आणि बॅटमॅनला एक व्यावसायिक साधन म्हणून वागवा, ज्याचा आकार नेहमी दुखापत होईल अशा हालचालीनुसार आकारला जातो, कधीही जमा केलेल्या क्रेडिटनुसार नाही.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"बॅटमॅन, पायाने पाय","id":"the-batman-leg-by-leg"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"आपल्या शक्यता","id":"your-odds"},{"level":2,"text":"मार्जिन, अभ्यासक्रमातील सर्वात भारी","id":"margin-the-heaviest-in-the-course"},{"level":2,"text":"वेळ क्षय","id":"time-decay"},{"level":2,"text":"दुहेरी माशी","id":"the-double-fly"},{"level":2,"text":"दुहेरी कंडर","id":"the-double-condor"},{"level":2,"text":"तिघांची तुलना कशी होते","id":"how-the-three-compare"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"20":{"html":"<p>तुम्ही आतापर्यंत भेटलेली प्रत्येक रणनीती दिशा किंवा हालचालीच्या आकारावर पैज लावते. कॅलेंडर वेगळे आहेत. ते वेळेवरच पैज लावतात. ए <strong>कॅलेंडरचा प्रसार</strong> जवळच्या एक्सपायरीमध्ये पर्याय विकतो आणि नंतरच्या एक्सपायरीमध्ये त्याच प्रकारचा पर्याय विकत घेतो, एका साध्या वस्तुस्थितीतून पैसे मिळवतो: जवळ-महिन्याचा पर्याय दूरच्या महिन्यापेक्षा त्याचे वेळेचे मूल्य कमी करतो. जर NIFTY स्ट्राइकजवळ शांतपणे बसला तर पुढचा पाय वितळला, तर तुमच्या मालकीचा मागचा पाय अजूनही त्याचे बहुतेक मूल्य टिकवून ठेवतो आणि दोघांमधील अंतर हा तुमचा नफा आहे. हा धडा 26 जून 2026, स्पॉट 24,056, लॉट 65, एक्सपायरी 28 जुलै 2026 जवळ आणि 25 ऑगस्ट 2026 पर्यंत एक्सपायरी झालेल्या रिअल NIFTY ऑप्शन डेटावर यापैकी तीन टाइम ट्रेड तयार करतो.</p>\n<h2 id=\"the-one-line-idea-sell-the-near-own-the-far\">एक-लाइन कल्पना: जवळचे विकणे, दूरचे मालक</h2>\n<p>वेळेचे मूल्य समान रीतीने पर्यायातून बाहेर पडत नाही. जेव्हा कालबाह्यता दूर असते तेव्हा ते हळू हळू वाहून जाते, नंतर शेवटचे दिवस जवळ आल्यावर जलद होते. 28 जुलैचा पर्याय आणि 25 ऑगस्टचा पर्याय दोन्ही आज वेळेचे मूल्य धारण करतो, परंतु पुढच्या महिन्यात जुलै एक जवळजवळ सर्व गमावतो तर ऑगस्ट एक, नवीन महिना बाकी असताना, क्वचितच लक्षात येते. कॅलेंडर हा फरक काढतो. आपण <strong>जवळ-महिना पाय विक्री</strong> आणि <strong>दूर-महिना पाय खरेदी करा</strong> त्याच स्ट्राइकवर, आणि कारण मागील-महिन्याच्या पर्यायाची किंमत नेहमीच जास्त असते, तुम्ही थोडे पैसे द्या <strong>निव्वळ डेबिट</strong> व्यापार चालू ठेवण्यासाठी.</p>\n<p>आता चार्ट काय काढतो ते पहा. नारंगी \"At Expiry\" रेषा येथे प्लॉट केली आहे <strong>एक्सपायरी जवळ</strong>, ज्या क्षणी तुमचा विकलेला जुलै पाय मरण पावला. जर NIFTY 28 जुलै रोजी स्ट्राइकच्या जवळ बसला तर, पुढचा पाय निरुपयोगी होईल आणि तुम्ही त्याचा प्रीमियम ठेवता, तर तुमच्या मालकीच्या मागच्या पायाचे आयुष्य अजून एक महिना आहे आणि त्यामुळे वेळेचे मूल्य चांगले आहे. मृत पुढचा पाय आणि जिवंत मागचा पाय यांच्यातील स्प्रेड हे तुम्ही भरलेल्या डेबिटपेक्षा जास्त मोलाचे आहे आणि ते अधिशेष तुमचा नफा आहे. प्रत्येक बंद किंमतीवर प्लॉट करा आणि तुम्हाला ए <strong>तंबू</strong>, दोन्ही बाजूंनी खाली उतरलेल्या स्ट्राइकमधील शिखर.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>कॅलेंडरचा प्रसार बराच काळ असतो. तुम्ही विकलेल्या जवळपास-महिन्याच्या पर्यायाचा जलद क्षय गोळा करता आणि तुमच्या मालकीच्या दूर-महिन्याच्या पर्यायाच्या संथ क्षयसाठी पैसे द्या. जेव्हा NIFTY जवळच्या एक्सपायरीच्या वेळी संपते तेव्हा ते सर्वात जास्त पैसे कमवते, जिथे पुढचा पाय निरुपयोगी मरतो आणि मागचा पाय सर्वात जास्त वेळ ठेवतो. कोणत्याही मार्गाने खूप दूर वाहून जातात आणि दोन्ही पाय एकत्रितपणे त्यांचे वेळेचे मूल्य गमावतात, तंबू कोसळतो आणि तुम्ही भरलेल्या डेबिटच्या जवळ गमावता.</p>\n</div></div>\n<h2 id=\"the-call-calendar-rupee-by-rupee\">कॉल कॅलेंडर, रुपया दर रुपया</h2>\n<p>प्लेनेस्ट व्हर्जन ॲट-द-मनी स्ट्राइकमध्ये दोन कॉल वापरते.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>कालबाह्य</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 विक्री करा</td>\n<td>28 जुलै 2026</td>\n<td>24,050 कॉल</td>\n<td>425.8 प्राप्त झाले</td>\n<td>अधिक रु 27,677 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>1 खरेदी करा</td>\n<td>25 ऑगस्ट 2026</td>\n<td>24,050 कॉल</td>\n<td>627.8 भरले</td>\n<td>40,807 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>13,130 रु</strong></td>\n</tr>\n</tbody></table>\n<p>दूरच्या कॉलची किंमत जवळच्या कॉलपेक्षा प्रति शेअर 202 पॉइंट्सने जास्त आहे, म्हणून तुम्ही ए <strong>13,130 रुपये निव्वळ डेबिट</strong>, जे 202 गुणिले 65 आणि तुमचा कमाल हिस्सा आहे.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-calendar.png\" alt=\"NIFTY कॉल कॅलेंडर, 28 जुलै 24,050 कॉल विक्री आणि 25 ऑगस्ट 24,050 कॉल खरेदी. ऑरेंज एट-एक्सपायरी लाइन 24,050 स्ट्राइकच्या जवळ एक तंबू बनवते, जिथे 14,480 रुपयांचा जास्तीत जास्त नफा बसतो, 23,495 आणि 24,634 वर ब्रेकइव्हन्सवर खाली उतरतो.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY कॉल कॅलेंडर, 28 जुलै 24,050 कॉल विक्री आणि 25 ऑगस्ट 24,050 कॉल खरेदी. ऑरेंज एट-एक्सपायरी लाइन 24,050 स्ट्राइकच्या जवळ एक तंबू बनवते, जिथे 14,480 रुपयांचा जास्तीत जास्त नफा बसतो, 23,495 आणि 24,634 वर ब्रेकइव्हन्सवर खाली उतरतो.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p><strong>संपावर जास्तीत जास्त नफा 14,480 रुपये आहे.</strong> NIFTY 28 जुलै रोजी 24,050 वाजता संपेल तेव्हा, तुमचा विकलेला जुलै कॉल निरर्थक ठरतो, तर तुमचा ऑगस्ट कॉल अजूनही पूर्ण महिन्याचे वेळेचे मूल्य आहे. तुम्ही भरलेल्या डेबिटपेक्षा त्या जिवंत मागच्या पायाचे अधिशेष हे सर्वोच्च आहे, रु. 14,480.</p>\n<p><strong>जास्तीत जास्त नुकसान 13,090 रुपये आहे, संपापासून दूर.</strong> NIFTY एकतर दिशेला पुश करा आणि दोन्ही कॉल्स त्यांचे जवळजवळ सर्व वेळ गमावतील, त्यामुळे दोन समान-स्ट्राइक कॉलमधील स्प्रेड शून्यावर कोसळेल आणि तुम्ही संपूर्ण डेबिट गमावाल. संपूर्ण रु. 13,130 ऐवजी ते रु. 13,090 आहे कारण मागील-महिन्याचा कॉल जवळच्या कालबाह्यतेवर कधीही शून्य मूल्यापर्यंत पोहोचत नाही.</p>\n<p><strong>ब्रेकवेन्स 23,495 आणि 24,634 आहेत</strong>, दोन किमती जिथे तंबू शून्य ओलांडतो, कॅलेंडर पैसे कमवते त्यामध्ये बँड तयार करतो.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>मागील महिन्याचे वेळेचे मूल्य शिल्लक, डेबिट वजा</td>\n<td>14,480 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>डेबिट, मागील महिन्याच्या मूल्याची कमी</td>\n<td>13,090 रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>जिथे तंबू शून्य ओलांडतो, स्ट्राइकच्या आसपास</td>\n<td>23,495 / 24,634</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-the-near-expiry\">नजीकच्या समाप्ती येथे परिणाम चालणे</h2>\n<p>कॉल कॅलेंडर 28 जुलै रोजी पाच बंद किंमतींवर सेटल करा, प्रति लॉट 65. विकले गेलेले जुलै कॉल तंतोतंत मूळ मूल्यावर सेटल होतात, परंतु ऑगस्ट कॉल अजूनही तुमच्या मालकीचा एक महिना टिकवून ठेवतो, म्हणून त्याचे मूल्य येथे आहे <strong>मॉडेल केलेले आणि अंदाजे</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY 28 जुलै रोजी</th>\n<th>24,050 कॉल तुम्ही विकले</th>\n<th>तुमच्या मालकीचे २४,०५० कॉल (अंदाजे)</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,200</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>पातळ, थोडे वेळ मूल्य बाकी</td>\n<td>सुमारे उणे रु 13,090 (जास्तीत जास्त तोटा)</td>\n</tr>\n<tr>\n<td>23,495</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>माफक मूल्य धारण करते</td>\n<td>सुमारे रु. (लोअर ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>अजूनही श्रीमंत, आयुष्याचा एक महिना बाकी आहे</td>\n<td>अधिक रु 14,480 (कमाल नफा)</td>\n</tr>\n<tr>\n<td>24,634</td>\n<td>तुमच्या विरुद्ध 584 किमतीची</td>\n<td>खोल, परंतु पसरणे पातळ आहे</td>\n<td>सुमारे रु. (अपर ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>25,100</td>\n<td>तुमच्या विरुद्ध 1,050 मूल्य आहे</td>\n<td>खोल, थोडे अतिरिक्त वेळ मूल्य</td>\n<td>सुमारे उणे रु 13,090 (जास्तीत जास्त तोटा)</td>\n</tr>\n</tbody></table>\n<p>टेबलमधील तंबू वाचा. स्ट्राइकच्या वेळी तुम्ही संपूर्ण 14,480 रुपये गोळा कराल, जिथे मृत पुढचा पाय आणि जिवंत मागचा पाय सर्वात दूर आहे. एकाही दिशेला सरकवा आणि ब्रेकइव्हन्सवर नफा शून्यावर कमी होतो, नंतर रु. 13,090 कमाल तोट्याच्या दिशेने घसरत राहते कारण दोन्ही कॉल त्यांचे वेळेचे मूल्य एकत्र गमावतात. ही परिस्थिती सारणी जवळच्या कालबाह्यतेच्या वेळी तयार केली जाते, ज्या क्षणी कॅलेंडर तयार केले जाते.</p>\n<h2 id=\"your-odds-margin-and-return\">तुमची शक्यता, मार्जिन आणि परतावा</h2>\n<p>कॉल कॅलेंडरचे <strong>नफ्याची शक्यता सुमारे 47 टक्के आहे</strong>. NIFTY ची अंदाजे 12.7 टक्के निहित अस्थिरता आणि 32 दिवसांची मुदत संपण्यासाठी, बाजार 28 जुलैपर्यंत निर्देशांकाला 23,495 ते 24,634 बँडमध्ये पूर्ण होण्याची शक्यता कमी देते.</p>\n<p>तुमच्या मालकीच्या दूर-महिन्याच्या लेगमुळे, कॅलेंडर परिभाषित-जोखीम आहे आणि त्याचे मार्जिन माफक आहे, सुमारे <strong>५८,३७३ रु</strong>, लाखांपेक्षा खूप खाली एक नग्न शॉर्ट मागणी करेल. त्या मार्जिनच्या तुलनेत, रु. 14,480 शिखर हा स्ट्राइक पिन केल्यास अंदाजे 25 टक्के परतावा आहे, एक महिन्याचे चांगले उत्पन्न आहे, जरी त्या सर्वोत्कृष्ट केसला 24,050 वर पूर्ण होण्यासाठी NIFTY आवश्यक आहे.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>कॅलेंडर स्थिर उभे राहून जिंकते, त्यामुळे एका महिन्यातNIFTY′ किती अंतरावर भटकतो याच्या तुलनेत त्याचा नफा बँड किती रुंद आहे यावरून त्याचा न्याय करा. 23,495 ते 24,634 च्या बँडमध्ये 47 टक्के संधी तुम्हाला सांगते की या व्यापाराला खरोखर शांत महिना हवा आहे. आपण हलण्याची अपेक्षा करत असल्यास, तंबू कितीही आकर्षक दिसत असला तरीही कॅलेंडर हे चुकीचे साधन आहे.</p>\n</div></div>\n<h2 id=\"time-decay-is-the-whole-point\">वेळेचा क्षय हा संपूर्ण मुद्दा आहे</h2>\n<p>या कोर्समधील इतर प्रत्येक डेबिट ट्रेडसाठी, वेळ क्षय हा शत्रू आहे. कॅलेंडर ते पलटवते. तुम्ही जवळ-महिना जलद-क्षय पर्याय लहान आहात आणि मंद-क्षय होणारा दूर-महिना लांब आहात, म्हणून प्रत्येक शांत दिवशी तुम्ही विकलेला पुढचा पाय तुमच्या मालकीच्या मागच्या पायापेक्षा अधिक वेगाने मूल्य गमावतो आणि तुमच्या बाजूने अंतर वाढेल. निळी T+0 रेषा स्ट्राइकच्या जवळ नारंगी तंबूच्या खाली बसते आणि जसजशी मुदत संपते तेव्हा स्थिती त्या नारिंगी शिखराकडे वाढते. कॅलेंडर ही येथे एक रचना आहे जी कालांतराने भरली जाते.</p>\n<h2 id=\"the-put-calendar\">पुट कॅलेंडर</h2>\n<p>एकाच स्ट्राइकवर पुटसाठी दोन्ही कॉल स्वॅप करा आणि तुम्हाला पुट कॅलेंडर मिळेल.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>कालबाह्य</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 विक्री करा</td>\n<td>28 जुलै 2026</td>\n<td>24,050 ठेवले</td>\n<td>295.1 मिळाले</td>\n</tr>\n<tr>\n<td>2</td>\n<td>1 खरेदी करा</td>\n<td>25 ऑगस्ट 2026</td>\n<td>24,050 ठेवले</td>\n<td>384.6 भरले</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>5,818 रु</strong></td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th>मेट्रिक</th>\n<th>मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>11,236 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>५,८१७ रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>23,570 / 24,548</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>सुमारे 42 टक्के</td>\n</tr>\n<tr>\n<td>बक्षीस मिळण्याचा धोका</td>\n<td>1 : 1.93</td>\n</tr>\n<tr>\n<td>निव्वळ डेबिट</td>\n<td>५,८१८ रु</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>48,986 रु</td>\n</tr>\n<tr>\n<td>आता एकूण P&amp;L</td>\n<td>सुमारे रु</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-calendar.png\" alt=\"NIFTY पुट कॅलेंडर, 28 जुलै 24,050 पुट विकत आहे आणि 25 ऑगस्ट 24,050 पुट विकत आहे. हाच तंबूचा आकार स्ट्राइकच्या जवळ आहे, परंतु त्याची किंमत फक्त 5,818 रुपये आहे आणि 1 ते 1.93 च्या जोखमीसाठी अधिक मजबूत बक्षीस दर्शवते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY पुट कॅलेंडर, 28 जुलै 24,050 पुट विकत आहे आणि 25 ऑगस्ट 24,050 पुट विकत आहे. हाच तंबूचा आकार स्ट्राइकच्या जवळ आहे, परंतु त्याची किंमत फक्त 5,818 रुपये आहे आणि 1 ते 1.93 च्या जोखमीसाठी अधिक मजबूत बक्षीस दर्शवते.</figcaption></figure>\n<p>आकार समान तंबू आहे, परंतु संख्या दयाळू आहेत. या स्नॅपशॉटवर पुट कॅलेंडरची किंमत फक्त 5,818 रुपये आहे, जी कॉल आवृत्तीपेक्षा खूपच कमी आहे, तरीही 11,236 रुपयांचा त्याचा जास्तीत जास्त नफा जवळपास तितकाच मोठा आहे. म्हणूनच त्याचे <strong>रिवॉर्डचा धोका 1 ते 1.93 आहे</strong>, तिघांपैकी सर्वोत्कृष्ट: अकरा पेक्षा जास्त करण्यासाठी तुम्ही सहा हजारांपेक्षा कमी जोखीम घ्याल. ब्रेकेव्हन्स, 23,570 आणि 24,548, स्ट्राइकभोवती तंबू तयार करतात आणि 5,817 रुपयांचे जास्तीत जास्त नुकसान मूलत: तुम्ही भरलेले डेबिट आहे.</p>\n<h2 id=\"the-diagonal-calendar\">कर्ण कॅलेंडर</h2>\n<p>ए <strong>कर्ण कॅलेंडर</strong> वेळ घटक ठेवतो परंतु दुसरा ट्विस्ट जोडतो: दोन पाय वेगवेगळ्या स्ट्राइकवर तसेच वेगवेगळ्या एक्सपायरींवर बसतात. तुम्ही अजूनही जवळचा महिना विकता आणि दूरचा महिना विकत घेता, परंतु स्ट्राइक गॅप तंबू झुकवते आणि रुंद करते, त्यास सममितीय शिखराऐवजी दिशात्मक झुकते.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>कालबाह्य</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 विक्री करा</td>\n<td>28 जुलै 2026</td>\n<td>24,050 कॉल</td>\n<td>425.8 प्राप्त झाले</td>\n</tr>\n<tr>\n<td>2</td>\n<td>1 खरेदी करा</td>\n<td>25 ऑगस्ट 2026</td>\n<td>24,150 कॉल</td>\n<td>५६१.१ भरले</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>सुमारे 8,791 रु</strong></td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th>मेट्रिक</th>\n<th>मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>14,881 रु</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>15,161 रु</td>\n</tr>\n<tr>\n<td>ब्रेकवेन्स</td>\n<td>23,382 / 24,593</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>सुमारे 50 टक्के</td>\n</tr>\n<tr>\n<td>बक्षीस मिळण्याचा धोका</td>\n<td>1 : 0.98</td>\n</tr>\n<tr>\n<td>निव्वळ डेबिट</td>\n<td>सुमारे रु 8,791</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>55,782 रु</td>\n</tr>\n<tr>\n<td>आता एकूण P&amp;L</td>\n<td>सुमारे रु</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-diagonal-calendar.png\" alt=\"NIFTY कर्ण कॅलेंडर, जवळचा-महिना 24,050 कॉल विकतो आणि दूर-महिना 24,150 कॉल खरेदी करतो. तंबू रुंद आहे आणि एका बाजूला झुकलेला आहे, 23,382 आणि 24,593 वर ब्रेकइव्हन्स आणि 14,881 रुपये कमाल नफा आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY कर्ण कॅलेंडर, जवळचा-महिना 24,050 कॉल विकतो आणि दूर-महिना 24,150 कॉल खरेदी करतो. तंबू रुंद आहे आणि एका बाजूला झुकलेला आहे, 23,382 आणि 24,593 वर ब्रेकइव्हन्स आणि 14,881 रुपये कमाल नफा आहे.</figcaption></figure>\n<p>कारण दूरचा कॉल एक स्ट्राइक जास्त बसतो, डेबिट साध्या कॉल कॅलेंडरपेक्षा लहान आहे, सुमारे रु 8,791, आणि पेऑफ आता संतुलित नाही. त्याचे ब्रेकेव्हन्स, 23,382 आणि 24,593, एकमेकांपासून विस्तीर्ण बसतात, त्यामुळे ते पैसे कमवण्याआधी एक मोठी हालचाल सहन करते, म्हणूनच त्याची नफा मिळण्याची शक्यता, सुमारे 50 टक्के, या तिघांपैकी सर्वाधिक आहे. त्या विस्तीर्ण तंबूची किंमत रु. 15,161 चे जास्तीत जास्त नुकसान आहे, डेबिटपेक्षा एक टच जास्त, कारण स्ट्राइक गॅप म्हणजे तीव्र हालचाल तुम्ही भरलेल्या रकमेपेक्षा थोडी जास्त खर्च करू शकते. रु. 14,881 चा जास्तीत जास्त नफा अजूनही येतो जेव्हा NIFTY नजीकच्या एक्सपायरीच्या वेळी मागील महिन्याच्या स्ट्राइककडे वळते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>कर्ण हा कॅलेंडरचा अधिक लवचिक चुलत भाऊ आहे. दोन स्ट्राइक किती अंतरावर बसतात हे निवडून, तंबू किती रुंद आहे आणि तो कोणत्या दिशेने झुकतो हे तुम्ही ठरवता, जेणेकरून तुम्ही सौम्य दिशात्मक दृश्य तसेच वेळेवर दृश्य व्यक्त करू शकता. हे अद्याप परिभाषित-जोखीम आहे, परंतु स्ट्राइक गॅप साध्या कॅलेंडरच्या विपरीत, साध्या डेबिटपेक्षा सर्वात वाईट केस थोडी मोठी बनवते.</p>\n</div></div>\n<h2 id=\"choosing-and-managing-a-calendar\">कॅलेंडर निवडणे आणि व्यवस्थापित करणे</h2>\n<p>तिन्ही बाजूला ठेवा आणि ट्रेड-ऑफ स्पष्ट आहेत.</p>\n<table>\n<thead>\n<tr>\n<th>रणनीती</th>\n<th>डेबिट</th>\n<th>जास्तीत जास्त नफा</th>\n<th>कमाल नुकसान</th>\n<th>जोखमीसाठी बक्षीस</th>\n<th>POP</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>कॅलेंडरवर कॉल करा</td>\n<td>13,130 रु</td>\n<td>14,480 रु</td>\n<td>13,090 रु</td>\n<td>1 : 1.11</td>\n<td>47 टक्के</td>\n</tr>\n<tr>\n<td>कॅलेंडर ठेवा</td>\n<td>५,८१८ रु</td>\n<td>11,236 रु</td>\n<td>५,८१७ रु</td>\n<td>1 : 1.93</td>\n<td>42 टक्के</td>\n</tr>\n<tr>\n<td>कर्ण कॅलेंडर</td>\n<td>८,७९१ रु</td>\n<td>14,881 रु</td>\n<td>15,161 रु</td>\n<td>1 : 0.98</td>\n<td>50 टक्के</td>\n</tr>\n</tbody></table>\n<p>तिघांनाही एकच गोष्ट हवी आहे, एक शांत NIFTY जो स्ट्राइकच्या जवळ रेंगाळत राहतो, तर जवळचा-महिना पाय सडतो. ते काही आठवडे बाजूला वळवण्याची अपेक्षा असलेल्या बाजारपेठेसाठी अनुकूल आहेत, ज्याची तुम्हाला अपेक्षा नाही. कारण तुम्ही सर्वात जास्त गमावू शकता ते अंदाजे डेबिट आहे, ते वेळेची विक्री करण्याचा एक परिभाषित-जोखमीचा मार्ग आहे, ज्यामध्ये लाखो रुपयांपेक्षा 49,000 ते 58,000 रुपयांपर्यंत मार्जिन आहे.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>लहान स्ट्रॅडल किंवा स्ट्रँगलच्या विपरीत, कॅलेंडरमध्ये अमर्यादित शेपटी नसते. तुमच्या मालकीचा मागील-महिना लेग आहे आणि तो दीर्घ पर्याय तुमच्या नुकसानास तुम्ही भरलेल्या डेबिटवर मोजतो. हे कॅलेंडर हे अशा काही मार्गांपैकी एक बनवते ज्याद्वारे नवशिक्या ओपन-एंडेड जोखमीशिवाय वेळेचा क्षय विकू शकतो. त्या सुरक्षेची किंमत अशी आहे की तुम्ही मागील महिन्याच्या पर्यायासाठी देखील पैसे द्यावे, म्हणून कॅलेंडर हा डेबिट व्यापार आहे, क्रेडिट नाही.</p>\n</div></div>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>कॅलेंडर परिभाषित-जोखीम आहे, परंतु त्यात एक लपलेली संवेदनशीलता आहे ज्याचा नवशिक्याने आदर केला पाहिजे: गर्भित अस्थिरता. तुमच्या मालकीच्या मागच्या महिन्याच्या लेगमध्ये तुम्ही विकलेल्या पुढच्या पायापेक्षा जास्त अस्थिरता असते, त्यामुळे तुम्ही आत गेल्यानंतर गर्भित अस्थिरतेमध्ये तीव्र घट तंबूला आकुंचित करू शकते आणि NIFTY उत्तम प्रकारे वागले तरीही तुमचे नुकसान होऊ शकते. तंबू फक्त स्ट्राइकच्या जवळच खरा आहे, म्हणून एखाद्या ज्ञात इव्हेंटच्या आधी ठेवलेले कॅलेंडर जे NIFTY फ्लाइंग पाठवू शकते हे एक खराब पैज आहे. नियोजित शॉकमध्ये नव्हे तर शांत परिस्थितीत कॅलेंडरचा व्यापार करा.</p>\n</div></div>\n<p>सँडबॉक्स ट्रेडिंगमध्ये आकाराची पूर्वाभ्यास करा (OpenAlgoमधील विश्लेषक मोड) आणि तुम्ही स्ट्राइक आणि एक्सपायरींना धक्का देताना तंबू वाढताना आणि पडताना पहा. कॅलेंडरच्या सहाय्याने तुम्ही वेळ आणि दिशा व्यापार करायला शिकलात. पुढे आपण सरळ रेषेकडे परत येऊ, सिंथेटिक भविष्य.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>ए <strong>कॅलेंडरचा प्रसार</strong> जवळचा-महिना पर्याय विकतो आणि त्याच स्ट्राइकवर दूर-महिना विकत घेतो, त्यातून नफा मिळवतो <strong>जलद क्षय</strong> पुढचा पाय.</li>\n<li>मोबदला म्हणजे ए <strong>तंबू</strong> नजीकच्या समाप्तीच्या वेळी स्ट्राइकच्या शिखरावर पोहोचणे, जिथे मृत पुढचा पाय आणि जिवंत मागचा पाय सर्वात दूर आहे.</li>\n<li>द <strong>कॅलेंडर कॉल करा</strong> 13,130 रु.ची किंमत आहे, रु. 14,480 वर आहे आणि 23,495 आणि 24,634 वर ब्रेक इव्हन आहे, शिखरावर 25 टक्क्यांच्या जवळ मार्जिनवर परतावा.</li>\n<li>द <strong>कॅलेंडर ठेवा</strong> येथे समान आकाराचा सर्वात स्वस्त मार्ग आहे, रु. 11,236 शिखरासाठी 5,818 डेबिट आणि जोखीमसाठी 1 ते 1.93 बक्षीस; द <strong>कर्ण</strong> सर्वाधिक 50 टक्के शक्यतांसाठी तंबू रुंद आणि झुकते परंतु सर्वात वाईट स्थिती रु. 15,161.</li>\n<li>कॅलेंडर आहेत <strong>परिभाषित-जोखीम</strong> आणि येथे फक्त संरचना <strong>वेळ क्षय मदत करते</strong>, परंतु ते गर्भित अस्थिरतेच्या घटाबद्दल संवेदनशील आहेत आणि त्यांना शांत, इव्हेंट-मुक्त महिना हवा आहे.</li>\n</ul>\n","toc":[{"level":2,"text":"एक-लाइन कल्पना: जवळचे विकणे, दूरचे मालक","id":"the-one-line-idea-sell-the-near-own-the-far"},{"level":2,"text":"कॉल कॅलेंडर, रुपया दर रुपया","id":"the-call-calendar-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"नजीकच्या समाप्ती येथे परिणाम चालणे","id":"walking-the-outcomes-at-the-near-expiry"},{"level":2,"text":"तुमची शक्यता, मार्जिन आणि परतावा","id":"your-odds-margin-and-return"},{"level":2,"text":"वेळेचा क्षय हा संपूर्ण मुद्दा आहे","id":"time-decay-is-the-whole-point"},{"level":2,"text":"पुट कॅलेंडर","id":"the-put-calendar"},{"level":2,"text":"कर्ण कॅलेंडर","id":"the-diagonal-calendar"},{"level":2,"text":"कॅलेंडर निवडणे आणि व्यवस्थापित करणे","id":"choosing-and-managing-a-calendar"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"21":{"html":"<p>अंकगणित पर्यायांचा एक शांत तुकडा आहे जो प्रत्येक नवशिक्याला पहिल्यांदा पाहिल्यावर आश्चर्यचकित करतो. विकत घेतलेला कॉल आणि विकलेला पुट, समान किंमतीला मारलेला, वक्र नसलेल्या गोष्टीमध्ये जोडा. ते एक सरळ रेषा बनवतात जी फ्यूचर्स पोझिशनप्रमाणेच उगवते आणि पडते. हे नाते, जे पर्याय भविष्यात एकत्र केले जाऊ शकतात आणि भविष्याला पर्यायांमध्ये वेगळे केले जाऊ शकते, ही संपूर्ण विषयातील सर्वात उपयुक्त कल्पना आहे. या प्रकरणात आम्ही ठेवले <strong>दीर्घ कृत्रिम भविष्य</strong> आणि <strong>लहान कृत्रिम भविष्य</strong> शेजारी, नंतर बांधकाम करण्यासाठी समान बिल्डिंग-ब्लॉक विचार वापरा <strong>कव्हर कॉल</strong>, उत्पन्नाचा व्यापार जो तुमच्या मालकीच्या होल्डिंगच्या वर बसतो. सर्व आकडे 26 जून 2026, स्पॉट 24,056, ATM स्ट्राइक 24,050, लॉट 65, एक्सपायरी 28 जुलै 2026 रोजी कॅप्चर केलेला वास्तविक NIFTY पर्याय डेटा वापरतात.</p>\n<h2 id=\"the-one-line-idea\">एका ओळीची कल्पना</h2>\n<p>ए <strong>कृत्रिम भविष्य</strong> एकाच स्ट्राइकवर दोन पर्यायांमधून पुन्हा तयार केलेले दीर्घ भविष्य आहे. कॉल विकत घ्या आणि पुट विका आणि भविष्यातील सर्व उलथापालथ आणि त्याचे सर्व डाउनसाइड एकाच सरळ कर्णरेषेत चिकटलेले तुमच्या मालकीचे आहेत. कॉल विक्री करा आणि पुट खरेदी करा आणि तुम्ही आरसा तयार केला आहे, एक लहान भविष्य. दृश्य हे असेच स्पष्ट दिशात्मक पैज आहे जे भविष्यात व्यक्त करते, परंतु तुम्हाला आधीच समजत असलेल्या पर्यायांमधून एकत्र केले जाते.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>एकाच स्ट्राइकवर लांब कॉल आणि शॉर्ट पुट दीर्घ भविष्य घडवतात. त्याच स्ट्राइकवर एक लहान कॉल आणि लांब पुट एक लहान भविष्य बनवते. हे पर्यायांच्या केंद्रस्थानी असलेले समानता संबंध आहे: भविष्य म्हणजे फक्त एक कॉल आणि पुट एकत्र जोडलेले आहे आणि तीनपैकी कोणतेही एक इतर दोनमधून पुन्हा तयार केले जाऊ शकते. अधिक जटिल संरचनांमध्ये हे सरळ रेषेचे आकार ओळखणे हे तुम्ही विकसित करू शकणाऱ्या सर्वात शक्तिशाली वाचन कौशल्यांपैकी एक आहे.</p>\n</div></div>\n<h2 id=\"the-long-synthetic-future-rupee-by-rupee\">लांब सिंथेटिक भविष्य, रुपया दर रुपया</h2>\n<p>तेजीच्या धोरणांमध्ये तुम्हाला हा आकार थोडक्यात मिळाला. ते कशापासून बनवले आहे ते येथे आहे, एक खरेदी केलेला कॉल आणि एक विकलेला पुट, दोन्ही ॲट-द-मनी स्ट्राइकवर.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल खरेदी करा</td>\n<td>24,050</td>\n<td>425.8 भरले</td>\n<td>रु 27,677 बाहेर</td>\n</tr>\n<tr>\n<td>2</td>\n<td>विक्री ठेवा</td>\n<td>24,050</td>\n<td>295.1 मिळाले</td>\n<td>अधिक 19,182 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ डेबिट</strong></td>\n<td><strong>सुमारे 8,496 रुपये</strong></td>\n</tr>\n</tbody></table>\n<p>विकत घेतलेला कॉल तुम्हाला भविष्यातील सर्व गोष्टींचा हात देतो. विकलेले तुम्हाला भविष्यातील सर्व नकारात्मक बाजू देतात. त्यांना एकत्र चिकटवा आणि वक्र एकाच कर्णरेषेत रद्द करा जे दोन्ही दिशांच्या बिंदूसाठी NIFTY बिंदूचा मागोवा घेते. कॉलची किंमत 425.8 आहे आणि पुट तुम्हाला 295.1 देते, त्यामुळे तुम्ही फरकासह भाग घ्या, प्रति शेअर 130.7 गुण, जे एक आहे <strong>सुमारे 8,496 रुपये निव्वळ डेबिट</strong> प्रति लॉट.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-synthetic.png\" alt=\"NIFTY दीर्घ सिंथेटिक भविष्य, 24,050 कॉल खरेदी करणे आणि 24,050 पुट विकणे. केशरी रेषा ही एक सरळ कर्णरेषा आहे, जी 24,181 च्या ब्रेकईव्हनच्या वर मर्यादेशिवाय वाढत आहे आणि त्याच्या खाली रुपयासाठी रुपया घसरत आहे, अगदी दीर्घ भविष्याप्रमाणे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY दीर्घ सिंथेटिक भविष्य, 24,050 कॉल खरेदी करणे आणि 24,050 पुट विकणे. केशरी रेषा ही एक सरळ कर्णरेषा आहे, जी 24,181 च्या ब्रेकईव्हनच्या वर मर्यादेशिवाय वाढत आहे आणि त्याच्या खाली रुपयासाठी रुपया घसरत आहे, अगदी दीर्घ भविष्याप्रमाणे.</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">तीन संख्या आणि ते कुठून येतात</h2>\n<p><strong>ब्रेकईव्हन 24,181 आहे.</strong> कोणत्याही बंद किंमतीवर, कॉलचे आंतरिक मूल्य वजा पुटचे आंतरिक मूल्य फक्त NIFTY वजा 24,050 स्ट्राइक आहे. ते ठेवण्यासाठी तुम्ही 130.7 पॉइंट दिले आहेत, त्यामुळे एकदा NIFTY 24,050 अधिक 130.7, जे 24,181 आहे ते क्लिअर केल्यावर तुम्ही फायदेशीर व्हाल.</p>\n<p><strong>कमाल नफा अमर्यादित आहे.</strong> ब्रेकइव्हनच्या वर रेषा एका दीर्घ भविष्याप्रमाणे, कमाल मर्यादा नसलेल्या बिंदूसाठी बिंदू वाढवते.</p>\n<p><strong>कमाल नुकसान रु. 1,571,746 आहे.</strong> ब्रेकइव्हनच्या खाली रुपयाला रुपया पडतो. मजला खरोखर एक मजला नाही, फक्त NIFTY शून्याच्या खाली जाऊ शकत नाही, आणि जर तो सर्व मार्गाने पडला तर तोटा सुमारे 1,571,746 रुपयांपर्यंत पोहोचेल.</p>\n<table>\n<thead>\n<tr>\n<th>क्रमांक</th>\n<th>ते कसे बांधले जाते</th>\n<th>हा व्यापार</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ब्रेकवेन</td>\n<td>स्ट्राइक प्लस पॉइंट्समधील निव्वळ डेबिट</td>\n<td>24,050 अधिक 130.7 बरोबर 24,181</td>\n</tr>\n<tr>\n<td>जास्तीत जास्त नफा</td>\n<td>बिंदूसाठी बिंदू उगवतो, कमाल मर्यादा नाही</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>शून्यावर पूर्ण घसरण, मर्यादित पण प्रचंड</td>\n<td>रु 1,571,746</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">एक्सपायरी येथे परिणाम चालणे</h2>\n<p>लाँग सिंथेटिकला पाच बंद किंमतींवर सेटल करा, प्रति लॉट 65. खरेदी केलेला कॉल त्याच्या आंतरिक मूल्याच्या मूल्याचा आहे, विकलेला पुट त्याच्या अंतर्गत मूल्याचे दायित्व आहे आणि अंतिम स्तंभात सरळ रेषा साधी आहे.</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY कालबाह्यतेवर</th>\n<th>तुम्ही विकत घेतलेला २४,०५० कॉल</th>\n<th>24,050 ला तुम्ही विकले</th>\n<th>निव्वळ नफा किंवा तोटा</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>22,000</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>तुमच्या विरुद्ध 2,050 मूल्य आहे</td>\n<td>उणे रु 141,746</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>उणे रु 8,496 (डेबिट)</td>\n</tr>\n<tr>\n<td>24,181</td>\n<td>131 किमतीची</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>सुमारे रु. (ब्रेकइव्हन)</td>\n</tr>\n<tr>\n<td>25,000</td>\n<td>950 किमतीची</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>अधिक रु 53,255</td>\n</tr>\n<tr>\n<td>26,000</td>\n<td>1,950 किमतीची</td>\n<td>निरर्थक कालबाह्य होते</td>\n<td>अधिक रु. 118,255</td>\n</tr>\n</tbody></table>\n<p>सरळ रेषेच्या पलीकडे अर्थ लावण्यासारखे काहीही नाही आणि तो मुद्दा आहे. 24,181 च्या वर तुम्ही कमाल मर्यादा नसलेल्या पॉइंटसाठी पॉइंट मिळवाल. याच्या खाली तुम्ही पॉइंट फॉर पॉइंट गमावता आणि शून्यावर घसरल्याने रु. 1,571,746 सर्वात वाईट स्थिती निर्माण होते. निळी T+0 रेषा केशरी रंगाच्या वर जवळजवळ बसते, कारण सिंथेटिक भविष्यात क्षय होण्यासाठी जवळजवळ वेळ लागत नाही, त्यामुळे वेळ ही स्थिती क्वचितच हलवते. त्याची <strong>नफ्याची शक्यता सुमारे 44 टक्के आहे</strong>एक्सपायरी द्वारे 24,181 ब्रेकइव्हन क्लिअर करत NIFTY वर मार्केट वाचले आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>दीर्घ सिंथेटिक भविष्यकाळ अगदी लांब NIFTY भविष्याप्रमाणे वागतो, त्यामुळे त्याचा धोका द्वि-बाजूचा आणि खूप मोठा आहे. जरNIFTY′ शून्यावर कोसळला, तर विकले जाणारे पुट नग्न शॉर्ट लेग असेल आणि एक्सचेंज सुमारे रु. 173,537 चे भारी मार्जिन ब्लॉक करेल तर सुमारे 1,571,746 रुपयांचे नुकसान होईल. या संरचनेत कुठेही संरक्षक मजला नाही. तुम्ही फ्युचर्स पोझिशन द्याल त्याच आदराने त्याचा व्यवहार करा, कधीही सौम्य पर्याय व्यापार म्हणून.</p>\n</div></div>\n<h2 id=\"the-short-synthetic-future\">लहान कृत्रिम भविष्य</h2>\n<p>दोन्ही पाय फ्लिप करा आणि तुम्हाला आरशाची प्रतिमा मिळेल. कॉल विक्री करा, पुट खरेदी करा आणि तुम्ही दोन पर्यायांमधून एक लहान भविष्य तयार केले आहे.</p>\n<table>\n<thead>\n<tr>\n<th>पाय</th>\n<th>कृती</th>\n<th>संप</th>\n<th>प्रति शेअर प्रीमियम</th>\n<th>रोख प्रवाह प्रति लॉट 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>कॉल विक्री</td>\n<td>24,050</td>\n<td>425.8 प्राप्त झाले</td>\n<td>अधिक रु 27,677 मध्ये</td>\n</tr>\n<tr>\n<td>2</td>\n<td>पुट खरेदी करा</td>\n<td>24,050</td>\n<td>२९५.१ भरले</td>\n<td>19,182 रु</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>निव्वळ क्रेडिट</strong></td>\n<td><strong>सुमारे रु 8,496 मध्ये</strong></td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th>मेट्रिक</th>\n<th>मूल्य</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>जास्तीत जास्त नफा</td>\n<td>रु 1,571,746</td>\n</tr>\n<tr>\n<td>कमाल नुकसान</td>\n<td>अमर्यादित</td>\n</tr>\n<tr>\n<td>ब्रेकवेन</td>\n<td>24,181</td>\n</tr>\n<tr>\n<td>लाभाची शक्यता</td>\n<td>सुमारे 56 टक्के</td>\n</tr>\n<tr>\n<td>बक्षीस मिळण्याचा धोका</td>\n<td>NA</td>\n</tr>\n<tr>\n<td>निव्वळ क्रेडिट</td>\n<td>सुमारे रु 8,496</td>\n</tr>\n<tr>\n<td>मार्जिन आवश्यक आहे</td>\n<td>रु. 169,046</td>\n</tr>\n<tr>\n<td>आता एकूण P&amp;L</td>\n<td>सुमारे रु</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-synthetic.png\" alt=\"NIFTY शॉर्ट सिंथेटिक भविष्य, 24,050 कॉल विकून आणि 24,050 पुट खरेदी. नारिंगी रेषा ही सरळ कर्ण आहे जी 24,181 च्या ब्रेकईव्हनच्या खाली नफ्यात पडते आणि त्याच्या वरच्या तोट्यात जाते, अगदी कमी भविष्याप्रमाणे तोट्याची कमाल मर्यादा नाही.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>NIFTY शॉर्ट सिंथेटिक भविष्य, 24,050 कॉल विकून आणि 24,050 पुट खरेदी. नारिंगी रेषा ही सरळ कर्ण आहे जी 24,181 च्या ब्रेकईव्हनच्या खाली नफ्यात पडते आणि त्याच्या वरच्या तोट्यात जाते, अगदी कमी भविष्याप्रमाणे तोट्याची कमाल मर्यादा नाही.</figcaption></figure>\n<p>लांब सिंथेटिक वरपासून खालपर्यंत फ्लिप केल्याने लहान सिंथेटिक वाचा. 24,181 च्या ब्रेकइव्हनच्या खाली लाइन नफ्यात येते, जी डाउनसाइड मोठी आहे परंतु मर्यादित आहे, कारणNIFTY′ शून्याच्या खाली येऊ शकत नाही, म्हणून 1,571,746 रुपये कमाल नफा. ब्रेकईव्हनच्या वर कोणतीही मर्यादा नसलेली रेषा तोट्यात जाते. लाँग सिंथेटिक सारख्याच पाच बंद किंमती चालवा आणि प्रत्येक निव्वळ आकृतीचे चिन्ह उलट करा: जिथे लांब आवृत्ती 22,000 वर 141,746 रुपये गमावते, लहान आवृत्ती ते मिळवते आणि जिथे लांब आवृत्ती 26,000 वर 118,255 रुपये मिळवते, तिथे लहान आवृत्ती कोणत्याही कमाल मर्यादेशिवाय गमावते.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>लहान सिंथेटिक भविष्यात वरचा धोका आहे. विकलेला कॉल हा एक नग्न शॉर्ट लेग आहे आणि जर NIFTY कठोरपणे रॅली करत असेल तर तोटा कोणत्याही कमाल मर्यादेशिवाय वाढतो, म्हणूनच बिल्डर जास्तीत जास्त तोटा अमर्यादित म्हणून प्रिंट करतो आणि एक्सचेंज सुमारे रु. 169,046 मार्जिन ब्लॉक करतो. 8,496 रुपयांचे छोटे क्रेडिट कोणत्याही प्रकारे तुम्ही वाहून घेतलेला धोका दर्शवत नाही. हे वेषात एक लहान भविष्य आहे आणि एक म्हणून व्यवस्थापित करणे आवश्यक आहे.</p>\n</div></div>\n<h2 id=\"the-covered-call\">कव्हर कॉल</h2>\n<p>कव्हर कॉल हे स्ट्रॅटेजी बिल्डरमध्ये टेम्प्लेट नाही, कारण तुम्ही जोडलेल्या पर्यायाऐवजी त्याचा एक पाय तुम्ही आधीच धरून ठेवलेला आहे. पण ते त्याच भागांच्या विचारातून बांधले गेले आहे, म्हणून ते येथे आहे. दीर्घNIFTY′ पोझिशन धारण करणाऱ्या ट्रेडरचे चित्रण करा, भविष्यात सांगा, जो स्थिर, कडेकडेने हलक्या उच्च बाजारावर समाधानी आहे. त्या होल्डिंगमधून उत्पन्न मिळविण्यासाठी, ते <strong>वर्तमान किमतीच्या वर कॉल विक्री करा</strong>, येथे 24,150 कॉल, आणि 370.1 प्रति शेअरचा प्रीमियम पॉकेट करा, लॉटसाठी सुमारे 24,057 रुपये.</p>\n<p>दोन तुकडे असे काम करतात.</p>\n<ul>\n<li>द <strong>लांब NIFTY भविष्य</strong> नेहमीच्या पॉईंट-फॉर-पॉइंट एक्सपोजर देते, NIFTY जसजसा वाढतो तसतसा वाढतो आणि जसजसा तो पडतो तसतसा तोटा होतो.</li>\n<li>द <strong>24,150 कॉल विकले</strong> थेट प्रीमियम आणते. जोपर्यंत NIFTY कालबाह्य होऊन 24,150 च्या खाली पूर्ण होत नाही तोपर्यंत तो कॉल निरर्थक ठरतो आणि प्रीमियम हे होल्डिंगच्या वरचे शुद्ध उत्पन्न असते.</li>\n</ul>\n<p>परिणाम म्हणजे एक अशी स्थिती जी दर महिन्याला थोडी अतिरिक्त कमाई करते, एका स्पष्ट सवलतीच्या बदल्यात बाजार शांत राहतो: तुमची वरची बाजू मर्यादित आहे. NIFTY 24,150 च्या पुढे गेल्यास, पुढील प्रत्येक पॉइंट तुमचा भविष्यातील नफा विकलेल्या कॉलने गमावलेल्या पॉइंटशी जुळतो, त्यामुळे स्ट्राइकच्या वर तुमचा नफा वाढणे थांबते. 24,150 आणि तुम्ही गोळा केलेला प्रीमियम हा तुमचा सर्वोत्तम मुद्दा आहे.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>कव्हर केलेल्या कॉलच्या पेऑफकडे बारकाईने पहा आणि तुम्हाला ते ओळखता येईल. दीर्घ भविष्य आणि लहान कॉल ही शॉर्ट पुट सारखीच वाकलेली रेषा तयार करते: वरच्या बाजूस मर्यादित, मर्यादित नफा आणि डाउनसाइडवर दीर्घ, उतार तोटा. कव्हर केलेला कॉल हा सिंथेटिक शॉर्ट पुट आहे. ही पुन्हा समता कल्पना आहे आणि कव्हर कॉल हा उत्पन्नाचा व्यापार का आहे आणि वाढीचा व्यापार का नाही हे स्पष्ट करते. तुम्ही आज प्रीमियमच्या बदल्यात तुमची वरची बाजू विकत आहात.</p>\n</div></div>\n<p>कव्हर्ड कॉल एखाद्या गुंतवणूकदाराला अनुकूल आहे ज्याला शांत ताणतणावांमध्ये होल्डिंग ठेवायचे आहे आणि त्यातून उत्पन्न पिळायचे आहे, मोठ्या रॅलीचा पाठलाग करणाऱ्या ट्रेडरला नाही. प्रीमियम खाली जाताना एक लहान उशी देखील देते, कारण तुम्ही गोळा केलेले उत्पन्न कोणत्याही घसरणीच्या पहिल्या भागाची भरपाई करते. पण ती गादी पातळ आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>कव्हर केलेला कॉल तुमच्या नकारात्मक बाजूचे संरक्षण करत नाही. बाजार घसरला तर तुमचे दीर्घ NIFTY भवितव्य अजूनही मोठ्या प्रमाणात गमावू शकते, आणि सर्व विक्री कॉल तुम्हाला प्रथम उशी म्हणून लहान प्रीमियम आहे. आपण अन्यथा ठेवू इच्छित नसलेल्या होल्डिंगवर उत्पन्न मिळविण्यासाठी कॉल विकणे ही एक चूक आहे, कारण वाईट जवळजवळ पूर्णपणे उघडे ठेवून आपण फक्त चांगला परिणाम मर्यादित केला आहे. कव्हर केलेल्या कॉलचा वापर फक्त अशा स्थितीवर करा ज्यामध्ये तुम्हाला खरोखर आनंद वाटतो आणि त्याचा आकार वास्तविक पडण्यासाठी करा, तुम्ही ज्या शांततेची अपेक्षा करत आहात त्यासाठी नाही.</p>\n</div></div>\n<h2 id=\"three-ways-to-hold-a-directional-view\">दिशात्मक दृश्य ठेवण्याचे तीन मार्ग</h2>\n<table>\n<thead>\n<tr>\n<th>स्थिती</th>\n<th>पासून बांधले</th>\n<th>आकार</th>\n<th>धोका</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>लांब सिंथेटिक भविष्य</td>\n<td>लांब कॉल, शॉर्ट पुट</td>\n<td>सरळ रेषा</td>\n<td>मोठा दुतर्फा, नग्न पुट</td>\n</tr>\n<tr>\n<td>लघु कृत्रिम भविष्य</td>\n<td>शॉर्ट कॉल, लाँग पुट</td>\n<td>सरळ रेषा खाली</td>\n<td>अनलिमिटेड वरची, नग्न कॉल</td>\n</tr>\n<tr>\n<td>कव्हर केलेला कॉल</td>\n<td>लांब होल्डिंग, लहान कॉल</td>\n<td>वरची बाजू, पूर्ण उतार</td>\n<td>होल्डिंग वर पूर्ण downside</td>\n</tr>\n</tbody></table>\n<p>सिंथेटिक्स ही दिशात्मक दृश्याची शुद्ध अभिव्यक्ती, एक सरळ रेषा, लढण्यासाठी वेळ नाही आणि भविष्याचा पूर्ण धोका आहे. कव्हर केलेला कॉल सर्वात सौम्य आहे: तो स्थिर प्रीमियमच्या बदल्यात ओपन-एंडेड अपसाइड सोडून देतो आणि जेव्हा तुमची मालकी आधीपासून असेल आणि तुम्हाला अंतर्निहित हवे असेल तेव्हाच ते अर्थपूर्ण ठरते. तिन्हींपैकी एकही स्प्रेडच्या पद्धतीने परिभाषित-जोखीम नाही, म्हणून नवशिक्यासाठी ते आधीच्या अध्यायांच्या बांधलेल्या रचनांच्या पलीकडे एक स्पष्ट पाऊल ठेवतात. स्ट्रॅटेजी बिल्डरमध्ये शॉर्ट स्ट्रॅडलच्या शेजारी लांब सिंथेटिक तयार करा आणि दोन्ही ब्लॉकला दीड लाखांपेक्षा जास्त मार्जिन पहा: सरळ रेषेतील सिंथेटिक हा भविष्यातील जोखमीचा शॉर्टकट नसून दोन पर्यायांमधून पुन्हा तयार केलेला धोका आहे. तुम्ही वास्तविक पैसे कमवण्यापूर्वी यापैकी कोणत्याही सँडबॉक्स ट्रेडिंगमध्ये (Analyser मोड OpenAlgo मध्ये) रिहर्सल करा.</p>\n<p>तुम्ही आता पाहिले आहे की पर्याय फ्युचर्समध्ये कसे एकत्र होतात आणि विकलेला कॉल होल्डिंगला उत्पन्न व्यापारात कसे बदलतो. ही वास्तविक, फ्युचर्स-ग्रेड जोखीम असलेल्या संरचना आहेत, परिभाषित-जोखीम स्प्रेडपासून स्पेक्ट्रमच्या विरुद्ध टोक. पुढील प्रकरणांमध्ये आम्ही पोझिशन्स तयार करण्यापासून त्यांचा बचाव करण्याकडे वळतो, प्रत्येक व्यापाऱ्याला शेवटी प्रश्न पडतो, जेव्हा व्यापार तुमच्या विरोधात जातो तेव्हा तुम्ही काय करता.</p>\n<h2 id=\"key-takeaways\">मुख्य उपाय</h2>\n<ul>\n<li>ए <strong>कृत्रिम भविष्य</strong> दोन पर्यायांमधून भविष्याची पुनर्बांधणी करते: अ <strong>लाँग कॉल प्लस शॉर्ट पुट</strong> एक लांब भविष्य आहे, a <strong>लहान कॉल अधिक लांब पुट</strong> एक लहान भविष्य आहे.</li>\n<li>द <strong>लांब सिंथेटिक</strong> निव्वळ डेबिटची किंमत सुमारे 8,496 रुपये आहे, अगदी ब्रेक इव्हन <strong>24,181</strong>, त्याच्या वरच्या मर्यादेशिवाय वाढतो आणि त्याच्या खाली रु. 1,571,746 च्या तोट्याकडे येतो.</li>\n<li>द <strong>लहान कृत्रिम</strong> त्याचा आरसा आहे, एक लहान क्रेडिट आहे ज्याची किंमत 1,571,746 रु. <strong>अमर्यादित</strong> रॅलीत नुकसान.</li>\n<li>दोघे वाहून जातात <strong>फ्युचर्स-ग्रेड, द्विपक्षीय जोखीम</strong>, रु. 1.6 लाख पेक्षा जास्त मार्जिन ब्लॉक करा आणि जवळजवळ कोणतेही वेळेचे मूल्य धरू नका, त्यामुळे T+0 आणि एक्सपायरी लाइन ओव्हरलॅप होतात.</li>\n<li>द <strong>कव्हर कॉल</strong> दीर्घ होल्डिंग अधिक विकलेला उच्च कॉल आहे: स्थिर प्रीमियम उत्पन्न, अ <strong>वरची बाजू</strong>, आणि एक अजूनही-मोठा नकारात्मक बाजू, ज्यामुळे ते अ <strong>सिंथेटिक शॉर्ट पुट</strong>.</li>\n<li>यापैकी कोणतेही परिभाषित-जोखीम नाही, म्हणून ते नवशिक्यासाठी स्प्रेडच्या पलीकडे एक पाऊल बसतात आणि वास्तविक प्रतिकूल हालचालीसाठी आकारले पाहिजेत, तुम्ही ज्या शांततेची अपेक्षा करत आहात त्याकरिता कधीही.</li>\n</ul>\n","toc":[{"level":2,"text":"एका ओळीची कल्पना","id":"the-one-line-idea"},{"level":2,"text":"लांब सिंथेटिक भविष्य, रुपया दर रुपया","id":"the-long-synthetic-future-rupee-by-rupee"},{"level":2,"text":"तीन संख्या आणि ते कुठून येतात","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"एक्सपायरी येथे परिणाम चालणे","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"लहान कृत्रिम भविष्य","id":"the-short-synthetic-future"},{"level":2,"text":"कव्हर कॉल","id":"the-covered-call"},{"level":2,"text":"दिशात्मक दृश्य ठेवण्याचे तीन मार्ग","id":"three-ways-to-hold-a-directional-view"},{"level":2,"text":"मुख्य उपाय","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"22":{"html":"<p>या कोर्समधील प्रत्येक स्ट्रॅटेजी घालण्यासाठी काहीतरी खर्च येतो. डेबिट स्प्रेडवर तुम्ही भरलेल्या प्रीमियमची किंमत असते. क्रेडिट स्ट्रॅटेजी तुम्हाला पैसे देते असे दिसते, तरीही ते शांतपणे पार्श्वभूमीत काहीतरी मोठे करण्याची मागणी करते: <strong>समास</strong>. गळा विकणे, लोखंडी कंडर चालवणे किंवा सिंथेटिकमध्ये फ्युचर्स लेग पकडणे, आणि जोपर्यंत पोझिशन उघडे आहे तोपर्यंत एक्सचेंज पैसे रोखते. नवशिक्यासाठी हे सहसा संपूर्ण विषयाचे सर्वात मोठे आश्चर्य असते. तुम्ही 10,000 रुपये जमा केलेत, मग तुमच्या खात्यात एक लाखाहून अधिक रक्कम अचानक का गोठवली गेली? हा धडा याचे उत्तर देतो आणि नंतर तुम्हाला तो भाग दाखवतो जो बहुतेक नवीन ट्रेडर्स कधीच शोधत नाहीत: तुम्हाला नेहमी रोख गोठवायची गरज नाही. तुमच्या मालकीच्या वस्तू तुम्ही गहाण ठेवू शकता.</p>\n<h2 id=\"why-a-short-position-blocks-margin\">लहान स्थिती मार्जिन का अवरोधित करते</h2>\n<p>पर्यायाचा खरेदीदार प्रीमियम भरतो आणि नंतर पूर्ण होतो. ते गमावू शकतात ते आधीच दिलेले आहे, त्यामुळे एक्सचेंजला त्यांच्याकडून अधिक सुरक्षिततेची आवश्यकता नाही. विक्रेता उलट आहे. ते एक लहान प्रीमियम गोळा करतात परंतु मोठे, काहीवेळा ओपन-एंडेड दायित्व स्वीकारतात, म्हणून एक्सचेंज ठेवीची मागणी करते, <strong>समास</strong>, व्यापार चुकीचा झाल्यास विक्रेता प्रत्यक्षात पैसे देऊ शकेल अशी सुरक्षितता म्हणून. प्रत्येक फ्युचर्स लेगच्या बाबतीतही असेच आहे.</p>\n<p>तो मार्जिन एकल अनियंत्रित आकृती नाही. हे दोन भागांमधून बांधले आहे.</p>\n<ul>\n<li><strong>SPAN मार्जिन</strong> गाभा आहे. SPAN हे एक्स्चेंजचे जोखीम मॉडेल आहे आणि तुमच्या अचूक स्थितीतील सर्वात वाईट-केस एक-दिवसीय हालचाल कव्हर करण्यासाठी ही रक्कम मोजली जाते. एक लहान गळा, जो मोठ्या हालचालीवर कोणत्याही प्रकारे गमावू शकतो, एक मोठा SPAN संख्या काढतो. एक परिभाषित-जोखमीचा लोखंडी कंडर, जेथे विकत घेतलेले पंख नुकसान कमी करतात, ते खूपच लहान आकाराचे काढतात.</li>\n<li><strong>एक्सपोजर मार्जिन</strong> एक्स्चेंज SPAN च्या शीर्षस्थानी जोडणारा एक अतिरिक्त बफर आहे, जो असामान्यपणे हिंसक दिवसासाठी दुसरा कुशन आहे.</li>\n</ul>\n<p>दोन जोडा आणि तुमच्याकडे आहे <strong>एकूण मार्जिन आवश्यक आहे</strong>, ऑर्डर पूर्ण होण्यापूर्वी तुमच्या खात्यामध्ये ब्लॉक केलेली रक्कम आणि तुम्ही बंद होईपर्यंत ब्लॉक केलेली राहिली पाहिजे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>SPAN प्लस एक्सपोजरच्या बरोबरीने लहान किंवा फ्युचर्स पोझिशन ब्लॉक मार्जिन. तुम्ही गोळा करत असलेल्या छोट्या क्रेडिटशी त्याचा काहीही संबंध नाही. हे तुम्ही वाहून घेतलेल्या जोखीमला प्रतिबिंबित करते, म्हणूनच एक नग्न लहान गळा समान अंतर्निहित परिभाषित-जोखीम कंडरपेक्षा कितीतरी जास्त जोडतो.</p>\n</div></div>\n<p>OpenAlgo समाविष्ट आहे a <strong>मार्जिन कॅल्क्युलेटर</strong> त्यामुळे यापैकी काहीही अंदाज नाही. तुम्ही याला तुमच्या रणनीतीचे पाय, प्रत्येकाची बाजू आणि प्रमाण द्या आणि ते SPAN मार्जिन, एक्सपोजर मार्जिन आणि एकूण आवश्यक परतावा देते. तुम्ही मल्टी-लेग ऑर्डर देण्यापूर्वी ते तपासल्यास तुमच्या खात्यात स्थान बसते की नाही हे काही सेकंदात तुम्हाला कळते आणि ते परिभाषित-जोखीम संरचनांबद्दल एक आनंददायी तथ्य देखील प्रकट करते: कारण एक्सचेंज तुमचे खरेदी केलेले पंख पाहू शकते, ते तुमच्या आत बसलेल्या नग्न शॉर्टच्या तुलनेत कंडोर किंवा फुलपाखरासाठी खूपच कमी मार्जिन आकारते. परिभाषित जोखीम ठेवणे स्वस्त आहे, फक्त सुरक्षित नाही.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>संपूर्ण रणनीतीवर मार्जिन कॅल्क्युलेटर चालवा, पायी चालत नाही. एक्स्चेंज एकत्रित स्थितीला मार्जिन करते, त्यामुळे लोखंडी कंडोरसारखी हेज केलेली रचना त्याच्या खऱ्या, मर्यादित जोखमीवर आकारली जाते. वेगळे पाय म्हणून त्याची किंमत ठरवणे तुम्हाला प्रत्यक्षात बाजूला ठेवण्याची आवश्यकता असलेल्या गोष्टींचा अतिरेक होईल.</p>\n</div></div>\n<h2 id=\"the-cash-drag-problem\">रोख-ड्रॅग समस्या</h2>\n<p>येथे व्यावहारिक वेदना आहे. समजा निर्देशांकावर लहान गळ्यात मार्जिनची सुमारे 1,50,000 रु. जर तुम्हाला रु. 1,50,000 रु. 1,50,000 संपूर्ण महिन्यासाठी निष्क्रिय रोख ठेवावे लागतील, तर ती रोख सुरक्षा म्हणून तिथे बसून तुम्हाला काहीही मिळत नाही. अनेक पदांवर कार्यरत असलेल्या सक्रिय व्यापाऱ्यासाठी लाखो रुपये गोठलेले आणि अनुत्पादक ठरू शकतात. म्हणजे <strong>रोख ड्रॅग</strong>, आणि पैसे गमावले नसले तरीही ही एक वास्तविक किंमत आहे.</p>\n<p>व्यवस्थेकडे समंजस उत्तर आहे. बहुतेक ट्रेडर्सकडे आधीपासून मालमत्ता, शेअर्स, फंड, बॉण्ड्स आहेत जे डिमॅट खात्यात बसण्याशिवाय काहीच करत नाहीत. त्या मालमत्ता निष्क्रिय रोख रकमेऐवजी सुरक्षा म्हणून का उभ्या राहू देत नाहीत? प्रतिज्ञा हीच परवानगी देते.</p>\n<h2 id=\"pledging-collateral-instead-of-cash\">रोख रकमेऐवजी तारण ठेवणे</h2>\n<p>जेव्हा आपण <strong>प्रतिज्ञा</strong> एक सुरक्षा, तुम्ही तुमच्या डिपॉझिटरीला व्यापारासाठी संपार्श्विक म्हणून चिन्हांकित करण्यास सांगता. मालमत्ता तुमचे डिमॅट खाते कधीही सोडत नाही, तरीही तुम्हाला त्याचा लाभांश किंवा व्याज मिळते आणि तरीही तुम्ही ते मालक आहात. हे फक्त सुरक्षितता म्हणून ध्वजांकित केले जाते आणि त्या बदल्यात त्याचे मूल्य तुमच्या ट्रेडिंग मार्जिनमध्ये जोडले जाते. त्यानंतर तुम्ही ते मार्जिन पर्याय विकण्यासाठी वापरू शकता किंवा समतुल्य रोख न ठेवता फ्युचर्स ठेवू शकता.</p>\n<p>एक झेल आहे, आणि तो न्याय्य आहे. एक्सचेंज तुम्हाला तारण ठेवलेल्या सिक्युरिटीचे पूर्ण मूल्य देणार नाही, कारण सिक्युरिटी स्वतःच किंमतीत कमी होऊ शकते. हे लागू होते अ <strong>धाटणी</strong>, बाजार मूल्यावर सूट आणि केवळ केस कापल्यानंतरची रक्कम मार्जिन म्हणून मोजली जाते. एक स्थिर, द्रव मालमत्तेला एक लहान धाटणी मिळते. अस्थिर स्टॉकला मोठा मिळतो.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-collateral.png\" alt=\"प्लेजिंग तुमच्या मालकीच्या सुरक्षिततेला मार्जिन म्हणून उभे करू देते, एक्स्चेंज त्याचे बाजार मूल्य हेअरकटद्वारे ट्रिम करते आणि कमी केलेली रक्कम वापरण्यायोग्य मार्जिन बनते, या नियमासह एकूण मार्जिनपैकी अर्धा भाग अजूनही रोख किंवा रोख-समतुल्य द्वारे पूर्ण करणे आवश्यक आहे.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>प्लेजिंग तुमच्या मालकीच्या सुरक्षिततेला मार्जिन म्हणून उभे करू देते, एक्स्चेंज त्याचे बाजार मूल्य हेअरकटद्वारे ट्रिम करते आणि कमी केलेली रक्कम वापरण्यायोग्य मार्जिन बनते, या नियमासह एकूण मार्जिनपैकी अर्धा भाग अजूनही रोख किंवा रोख-समतुल्य द्वारे पूर्ण करणे आवश्यक आहे.</figcaption></figure>\n<p>एक साधे उदाहरण ते ठोस बनवते. मोठ्या स्टॉकचे 1,00,000 रुपये तारण ठेवा आणि कदाचित वीस ते पंचवीस टक्के केस कापल्यानंतर, तुम्हाला वापरण्यायोग्य मार्जिनचे सुमारे 75,000 ते 80,000 रुपये मिळू शकतात. सरकारी रोखे किंवा लिक्विड फंडाचे रु 1,00,000 तारण ठेवा आणि हेअरकट लहान आहे, त्यामुळे तुम्हाला जवळपास रु. 95,000 किंवा त्याहून अधिक मिळतील. संपार्श्विक जितके सुरक्षित तितके अधिक मार्जिन देते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>हेअरकट म्हणजे सुरक्षिततेचे मूल्य किती आहे आणि मार्जिन म्हणून मोजण्याची परवानगी आहे यामधील अंतर आहे. ते विकले जाण्यापूर्वी मूल्य कमी होण्यापासून एक्सचेंजचे संरक्षण करते. मालमत्ता जितकी स्थिर असेल तितकी धाटणी लहान असेल, म्हणूनच G-Sec एकल स्टॉकपेक्षा संपार्श्विक म्हणून पुढे पसरते.</p>\n</div></div>\n<h2 id=\"the-cash-component-rule\">रोख-घटक नियम</h2>\n<p>तारण ठेवलेल्या सिक्युरिटीज शक्तिशाली असतात, परंतु ते संपूर्ण काम करू शकत नाहीत. एक्सचेंजला ते आवश्यक आहे <strong>तुमच्या एकूण मार्जिनपैकी किमान अर्धा भाग रोख किंवा रोख समतुल्य स्वरूपात पूर्ण केला जाईल</strong>, बाकीचे स्टॉक आणि इक्विटी फंड यांसारख्या नॉन-कॅश संपार्श्विकांमध्ये अनुमत आहेत. हा रोख-घटक नियम आहे आणि तो अस्तित्त्वात आहे जेणेकरून एखादी स्थिती तुमच्या विरोधात गेल्यास, दैनंदिन तोटा भरून काढण्यासाठी हातात खरी रोकड आहे, केवळ गहाण ठेवलेले शेअर्स नाहीत जे स्वतः कमी होत आहेत.</p>\n<p>रोख-समतुल्य ही जवळ-जवळ-रोख वस्तू आहेत ज्यात या उद्देशासाठी एक्सचेंज जवळजवळ रोख प्रमाणेच व्यवहार करते, ज्यामध्ये आपण गहाण ठेवू शकता अशा काही मालमत्तांचा सोयीस्करपणे समावेश होतो, जसे की सरकारी सिक्युरिटीज, सार्वभौम सुवर्ण रोखे आणि लिक्विड फंड. त्यामुळे एक समजूतदार संपार्श्विक मिश्रण नॉन-कॅश अर्ध्या भागासाठी तारण ठेवलेल्या स्टॉकचा एक थर आणि रोख-समतुल्य अर्ध्या भागासाठी लिक्विड फंड किंवा जी-सेकचा थर असू शकतो. जर तुम्ही नॉन-कॅश संपार्श्विकावर खूप जास्त झुकत असाल आणि रोख घटकामध्ये कमी पडलात, तर ब्रोकर तुटवड्यावर व्याज आकारतो, जो तुमचे परतावा शांतपणे खातो.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>तारण ठेवलेल्या स्टॉक्ससह पूर्णपणे पोझिशनसाठी कधीही निधी देऊ नका. किमान अर्धा मार्जिन रोख किंवा रोख-समतुल्य असणे आवश्यक आहे आणि दैनंदिन मार्क-टू-मार्केट तोटा नेहमी रोखीने डेबिट केला जातो. रोख बफर नसलेल्या नॉन-कॅश संपार्श्विकांनी भरलेले पुस्तक म्हणजे हिंसक दिवशी जबरदस्तीने बाहेर पडणारे खाते.</p>\n</div></div>\n<h2 id=\"what-counts-as-collateral-for-f-o\">F&amp;O साठी संपार्श्विक म्हणून काय मोजले जाते</h2>\n<p>तुम्हाला फ्युचर्स आणि पर्यायांसाठी तारण ठेवण्याची परवानगी असलेल्या मालमत्तेची यादी विस्तृत आहे, जो F&amp;O मार्जिनला लवचिक बनवण्याचा एक भाग आहे. F&amp;O एक्सपोजरसाठी मंजूर केलेल्या संपार्श्विकात हे समाविष्ट आहे:</p>\n<ul>\n<li><strong>सार्वभौम सुवर्ण रोखे (SGBs)</strong></li>\n<li><strong>सरकारी रोखे (G-Secs)</strong></li>\n<li><strong>म्युच्युअल फंड</strong></li>\n<li><strong>ईटीएफ</strong></li>\n<li><strong>साठा</strong> (मंजूर, द्रव)</li>\n<li><strong>REITs</strong> (रिअल इस्टेट गुंतवणूक ट्रस्ट)</li>\n<li><strong>आमंत्रण</strong> (पायाभूत सुविधा गुंतवणूक ट्रस्ट)</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-collateral-types.png\" alt=\"F&amp;O साठी संपार्श्विक म्हणून स्वीकारलेली मालमत्ता SGBs, G-Secs, म्युच्युअल फंड, ETF, स्टॉक, REITs आणि InvITs कव्हर करते, तर कॅश-मार्केट खरेदीसाठी मार्जिन ट्रेडिंग सुविधा सध्या फक्त ETF आणि स्टॉक स्वीकारते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>F&amp;O साठी संपार्श्विक म्हणून स्वीकारलेली मालमत्ता SGBs, G-Secs, म्युच्युअल फंड, ETF, स्टॉक, REITs आणि InvITs कव्हर करते, तर कॅश-मार्केट खरेदीसाठी मार्जिन ट्रेडिंग सुविधा सध्या फक्त ETF आणि स्टॉक स्वीकारते.</figcaption></figure>\n<p>ती यादी वाचण्याचा एक उपयुक्त मार्ग म्हणजे केस कापणे. शीर्षस्थानी सरकार-समर्थित आणि निधी साधने, SGBs, G-Secs आणि लिक्विड फंड, स्थिर आहेत आणि बहुतेकदा लहान धाटणीसह तुमच्या रोख-समतुल्य घटकासाठी मोजले जातात. बाजारातील किमतीची साधने कमी होतात, स्टॉक्स, REITs आणि InvITs, मोठे केस कापतात आणि नॉन-कॅश बाजूला बसतात. दोन्ही मिक्स केल्याने तुम्हाला एकूण मार्जिन आणि तुमच्याकडे आधीपासून असलेल्या मालमत्तेतील रोख-घटक नियम दोन्ही पूर्ण करता येतात.</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>तुम्हाला एक परिभाषित-जोखीम पोझिशन चालवायची आहे ज्यासाठी सुमारे रु 1,50,000 मार्जिन आवश्यक आहे. ते रोखीत गोठवण्याऐवजी, तुम्ही लिक्विड फंडाचे अंदाजे रु 1,00,000 तारण ठेवता, जे रोख-समतुल्य आहे आणि त्याच्या पूर्ण मूल्याच्या जवळपास देते, रोख अर्धा कव्हर करते, आणि तुम्ही सुमारे रु 1,00,000 स्टॉक गहाण ठेवता, जे केस कापल्यानंतर अंदाजे रु. 75,000 नॉन-कॅश मार्जिन जोडते. त्यांच्या दरम्यान पोझिशनला निधी दिला जातो, तुमचा रोख घटक समाधानी असतो आणि तुमची निष्क्रिय मालमत्ता शेवटी तुमच्यासाठी काम करत असते.</p>\n</div></div>\n<h2 id=\"a-different-list-mtf-collateral\">वेगळी यादी: MTF संपार्श्विक</h2>\n<p>शेजारचा एक नियम जाणून घेणे योग्य आहे, कारण नवशिक्या बहुतेकदा दोघांना गोंधळात टाकतात. द <strong>मार्जिन ट्रेडिंग सुविधा (MTF)</strong> F&amp;O पासून वेगळी गोष्ट आहे. MTF तुम्हाला कॅश मार्केटमधील शेअर्स अर्धवट-कर्ज घेतलेल्या पैशाने खरेदी करू देतो आणि त्याची स्वतःची, स्वीकार्य संपार्श्विकांची संकुचित यादी आहे. MTF एक्सपोजरसाठी, फक्त <strong>ईटीएफ आणि स्टॉक्स</strong> सध्या स्वीकारले आहेत.</p>\n<p>त्यामुळे समान स्टॉक कोणत्याही जगात तारण ठेवला जाऊ शकतो, परंतु SGBs, G-Secs, म्युच्युअल फंड, REITs आणि InvITs चे ब्रॉड मेनू जे F&amp;O स्वीकारते ते सर्व आज MTF पर्यंत पोहोचत नाही.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>हे असेच राहू शकत नाही. मार्जिन ट्रेडिंग सुविधेवरील SEBI सल्लामसलत पेपरमध्ये बदल प्रस्तावित केले आहेत, आणि जर त्यातील तरतुदी त्यांच्या सध्याच्या स्वरूपात मंजूर झाल्या, तर MTF साठी स्वीकारलेले संपार्श्विक F&amp;O सूचीशी जुळण्यासाठी विस्तृत होऊ शकते, ज्यामुळे दोन्ही प्रभावीपणे एकसारखे बनतील. या क्षेत्रातील नियम विकसित होतात, त्यामुळे अचूक याद्या कायमस्वरूपी कायद्याऐवजी वर्तमान सराव म्हणून हाताळा आणि आपण प्रतिज्ञा करण्यापूर्वी नवीनतम स्थितीची पुष्टी करा.</p>\n</div></div>\n<h2 id=\"the-practical-takeaway\">व्यावहारिक टेकअवे</h2>\n<p>संपार्श्विक ही शांत कार्यक्षमता आहे जी विचारशील पर्याय व्यापाऱ्याला पैसे निष्क्रिय ठेवणाऱ्यापासून वेगळे करते. लहान किंवा फ्युचर्स पोझिशनची मागणी असलेली मार्जिन खरी आहे आणि SPAN प्लस एक्सपोजरद्वारे सेट केली जाते, जे तुम्ही व्यापार करण्यापूर्वी OpenAlgo मार्जिन कॅल्क्युलेटर तुम्हाला दाखवेल. परंतु तुम्हाला ते मार्जिन गोठवलेल्या रोखीने पूर्ण करण्याची गरज नाही. तुमच्या मालकीची मालमत्ता गहाण ठेवा, केस कापण्याचा आणि रोख-घटक नियमाचा आदर करा आणि तेच भांडवल तुमच्या पोर्टफोलिओला आणि तुमच्या धोरणांना एकाच वेळी समर्थन देऊ शकते. बेफिकीरपणे वापरलेले, लीव्हरेज आणि थिन कॅश बफर म्हणजे खाती कशी उडवतात. समंजस संपार्श्विक मिश्रण आणि रोख अर्ध्या भागावर प्रामाणिक नजरेने वापरलेले, मार्जिन हे एक साधन बनते जे तुम्हाला व्यवस्थापित करणाऱ्या आश्चर्याऐवजी तुम्ही व्यवस्थापित करता. पुढील प्रकरण कल्पनेपासून सरावापर्यंत प्रतिज्ञा घेते, केस कापण्याची गणिते, त्यातून जास्तीत जास्त फायदा मिळवण्याच्या दोन युक्त्या आणि आदर राखण्यासाठी मार्जिन-कॉल रिस्क.</p>\n","toc":[{"level":2,"text":"लहान स्थिती मार्जिन का अवरोधित करते","id":"why-a-short-position-blocks-margin"},{"level":2,"text":"रोख-ड्रॅग समस्या","id":"the-cash-drag-problem"},{"level":2,"text":"रोख रकमेऐवजी तारण ठेवणे","id":"pledging-collateral-instead-of-cash"},{"level":2,"text":"रोख-घटक नियम","id":"the-cash-component-rule"},{"level":2,"text":"F&O साठी संपार्श्विक म्हणून काय मोजले जाते","id":"what-counts-as-collateral-for-f-o"},{"level":2,"text":"वेगळी यादी: MTF संपार्श्विक","id":"a-different-list-mtf-collateral"},{"level":2,"text":"व्यावहारिक टेकअवे","id":"the-practical-takeaway"}],"imgCount":2,"hasContent":true},"23":{"html":"<p>शेवटच्या प्रकरणात तुम्ही शिकलात की पर्याय विकणे आणि फ्युचर्स ब्लॉक मार्जिन धारण करणे, आणि रोख गोठवण्याऐवजी तुमच्या मालकीची मालमत्ता गहाण ठेवून तुम्ही ते मार्जिन पूर्ण करू शकता. हा अध्याय ते व्यावहारिक बनवतो. प्लेजिंग हे ट्रेडरचे सर्वात उपयुक्त आणि सर्वात गैरसमज असलेल्या साधनांपैकी एक आहे. चांगले वापरले, ते तुमच्या दीर्घकालीन पोर्टफोलिओला एकही शेअर न विकता तुमच्या ट्रेडिंगसाठी शांतपणे निधी देऊ देते. निष्काळजीपणे वापरल्यास, हे घसरत चाललेल्या बाजाराला तुम्ही ठेवू इच्छित असलेल्या होल्डिंगच्या सक्तीच्या विक्रीमध्ये बदलू शकते. केस कापण्याचे गणित, छुप्या व्याजाचा खर्च, दोन खऱ्या अर्थाने उपयुक्त युक्त्या आणि जोखमीकडे प्रामाणिकपणे बघून त्याचा स्मार्ट पद्धतीने वापर करायला शिकू या.</p>\n<h2 id=\"what-pledging-actually-does\">प्रतिज्ञा प्रत्यक्षात काय करते</h2>\n<p>प्लेजिंग म्हणजे तुम्ही तुमच्या ब्रोकरला म्हणत आहात की, माझे शेअर्स सिक्युरिटी म्हणून धरा आणि त्या बदल्यात मला ट्रेडसाठी अतिरिक्त मार्जिन द्या. शेअर्स तुमचे डिमॅट खाते कधीही सोडत नाहीत. तुम्ही अजूनही त्यांचे मालक आहात, तुम्हाला अजूनही त्यांचे लाभांश आणि बोनस मिळतात, ते फक्त संपार्श्विक म्हणून ध्वजांकित केले जातात. त्या बदल्यात, त्यांचे मूल्य, कमी झाल्यानंतर आम्ही एका क्षणात भेटू, तुमच्या ट्रेडिंग मार्जिनमध्ये जोडले जाईल.</p>\n<p>एक साधे चित्र. समजा तुमच्या डिमॅट खात्यात सुमारे 2,00,000 रुपये किमतीचे शेअर्स निष्क्रिय आहेत. ट्रेडिंग फंड उभारण्यासाठी त्यांना विकण्याऐवजी, तुम्ही ते गहाण ठेवा आणि वापरण्यायोग्य मार्जिनचे अंदाजे रु 1,70,000 मिळवा. ते मार्जिन अधिक शेअर्स, F&amp;O पोझिशन किंवा इंट्राडे ट्रेड खरेदी करण्यास समर्थन देऊ शकते. तुम्ही नवीन रोख न ठेवता आणि तुमच्याकडे जे आहे ते न विकता वाढवले. असे संपूर्ण आवाहन आहे.</p>\n<p>समोर दोन गोष्टी जाणून घेण्यासारख्या आहेत. प्रथम, फक्त मंजूर सिक्युरिटीज तारण ठेवल्या जाऊ शकतात, प्रत्येक स्टॉक पात्र ठरत नाही. शेअर्सच्या पलीकडे तुम्ही लिक्विड ईटीएफ, लिक्विड फंड, इक्विटी ईटीएफ आणि म्युच्युअल फंड देखील गहाण ठेवू शकता. मंजूर केलेली यादी तुमच्या ब्रोकरच्या प्लॅटफॉर्मवर आणि एक्सचेंज वेबसाइटवर राहते. दुसरे, प्रतिज्ञा हे औपचारिकतेपासून मुक्त नाही, परंतु ते द्रुत आहे. तुम्ही त्याची विनंती करा, डिपॉझिटरीमध्ये प्रमाणीकरण स्टेपसह मंजूर करा आणि मार्जिन सहसा त्याच दिवशी जमा केले जाते.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>तुम्ही तारण ठेवता तेव्हा, मालमत्ता तुमचीच राहते आणि तुमच्या डिमॅट खात्यात राहते, फक्त संपार्श्विक म्हणून चिन्हांकित केली जाते. तुम्ही लाभांश आणि बोनस ठेवता आणि तुम्ही कधीही लॉक-इन न करता, कधीही अनप्लेज करू शकता. प्लेजिंग तुम्हाला विक्री न करता ट्रेडिंग मार्जिन देते, जो त्याचा सर्वात मोठा फायदा आहे.</p>\n</div></div>\n<h2 id=\"the-haircut-decides-how-much-you-get\">तुम्हाला किती मिळेल हे हेअरकट ठरवते</h2>\n<p>तुम्हाला मार्जिन म्हणून तारण ठेवलेल्या सिक्युरिटीचे पूर्ण बाजार मूल्य प्राप्त होत नाही. एक्सचेंज लागू होते a <strong>धाटणी</strong>, बाजार मूल्याची टक्केवारी घट, आणि केस कापल्यानंतर वापरण्यायोग्य मार्जिन बनल्यानंतर फक्त शिल्लक राहिलेली रक्कम. हेअरकट हे सावकारासाठी सुरक्षितता बफर आहे ज्याच्या किंमतीमध्ये घट होत आहे.</p>\n<p>एक उदाहरण ते ठोस बनवते. 20 टक्के केस कापून 10,000 रुपयांची सुरक्षा गहाण ठेवा आणि तुम्हाला वापरण्यायोग्य मार्जिन म्हणून 8,000 रुपये मिळतील. इतर 2,000 रुपये बफर म्हणून परत ठेवले आहेत. धाटणी प्रत्येक मालमत्तेसाठी समान नसते. स्थिर, द्रव साधनांमध्ये लहान धाटणी असतात, तर जोखमीचे, अस्थिर स्टॉक्समध्ये मोठे असतात, कारण अस्थिर स्टॉक ब्रोकर विकू शकण्यापूर्वी आणखी घसरू शकतो.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-haircut-ladder.png\" alt=\"तारण तुम्हाला किती मार्जिन देते हे हेअरकट ठरवते: रोख ETF मध्ये सुमारे 6 टक्के लहान धाटणी असते त्यामुळे तुम्हाला मार्जिन म्हणून सुमारे 94 टक्के, सरकार-समर्थित उपकरणे सुमारे 10 टक्के, आणि अस्थिर स्टॉक एक मोठे, परिवर्तनीय हेअरकट म्हणून तुम्हाला लक्षणीयरीत्या कमी मिळतात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>तारण तुम्हाला किती मार्जिन देते हे हेअरकट ठरवते: रोख ETF मध्ये सुमारे 6 टक्के लहान धाटणी असते त्यामुळे तुम्हाला मार्जिन म्हणून सुमारे 94 टक्के, सरकार-समर्थित उपकरणे सुमारे 10 टक्के, आणि अस्थिर स्टॉक एक मोठे, परिवर्तनीय हेअरकट म्हणून तुम्हाला लक्षणीयरीत्या कमी मिळतात.</figcaption></figure>\n<p>त्यामुळे तुम्हाला प्रत्यक्षात मिळणारे मार्जिन हे केवळ मालमत्तेच्या मूल्यावर अवलंबून नाही तर तिच्या धाटणीवर अवलंबून असते आणि ते हेअरकट कालांतराने बदलू शकतात. स्थिर मोठ्या स्टॉकमध्ये 9 टक्क्यांच्या जवळ हेअरकट असू शकते, तर जंपियरमध्ये 18 टक्के किंवा त्याहून अधिक असू शकते, त्यामुळे समान 2,00,000 रुपये होल्डिंग्स तुम्हाला कोणत्या स्टॉकच्या आधारावर खूप भिन्न मार्जिन देऊ शकतात.</p>\n<h2 id=\"cash-collateral-versus-non-cash-collateral\">रोख संपार्श्विक विरुद्ध नॉन-कॅश संपार्श्विक</h2>\n<p>तारण मालमत्ता दोन बादल्यांमध्ये मोडते आणि तुम्ही किती करू शकता आणि त्याची किंमत काय आहे या दोन्हीसाठी फरक महत्त्वाचा आहे.</p>\n<ul>\n<li><strong>रोख आणि रोख समतुल्य संपार्श्विक</strong>: लिक्विड ईटीएफ, लिक्विड फंड, सरकारी सिक्युरिटीज, सार्वभौम सुवर्ण रोखे आणि ट्रेझरी बिले. प्रणाली या जवळजवळ रोख प्रमाणे हाताळते.</li>\n<li><strong>नॉन-कॅश किंवा इक्विटी संपार्श्विक</strong>: सामान्य स्टॉक, इक्विटी ईटीएफ आणि इक्विटी म्युच्युअल फंड.</li>\n</ul>\n<p>त्यांना जोडणारा नियम येथे आहे. तुम्ही F&amp;O साठी तारण मार्जिन वापरता तेव्हा, किमान <strong>एकूण मार्जिनपैकी निम्मी रक्कम रोख किंवा रोख समतुल्य स्वरूपात भेटली पाहिजे</strong>, आणि दुसरा अर्धा नॉन-कॅश असू शकतो. शेवटच्या प्रकरणातील हा समान रोख-घटक नियम आहे आणि तारण म्हणजे त्याची किंमत दृश्यमान आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>जर तुम्ही अर्धवट रोख रक्कम कमी केली आणि रात्रीच्या स्थितीसाठी नॉन-कॅश संपार्श्विक सह निधी दिला तर, एक्सचेंज त्या तुटवड्यावर व्याज आकारते, सध्या दररोज सुमारे 0.035 टक्के, जे वर्षभरात अंदाजे 12.775 टक्के आहे. रोख रकमेशिवाय तारण ठेवलेल्या स्टॉक्सवर पूर्णपणे झुका आणि पोझिशन उघडलेल्या प्रत्येक दिवशी तुम्ही शांतपणे व्याज देत आहात.</p>\n</div></div>\n<p>एक द्रुत क्रमांक. म्हणा की एखाद्या पोझिशनसाठी मार्जिनच्या 1,00,000 रुपयांची आवश्यकता आहे आणि तुमच्याकडे तारण ठेवलेल्या स्टॉकचे 1,00,000 रुपये आहेत परंतु कोणतेही द्रव संपार्श्विक नाही. 50,000 रुपयांची रोखीची गरज नाही, म्हणून ते तुमच्या स्टॉकद्वारे फंड केले जाते आणि त्या 50,000 रुपयांच्या तुटवड्यावरील व्याज दररोज सुमारे 17.5 रुपये आहे. दररोज लहान, परंतु जोपर्यंत पोझिशन उघडे आहे तोपर्यंत ते चालते आणि ते तुमच्या रिटर्नवर शुद्ध ड्रॅग आहे.</p>\n<h2 id=\"trick-one-prefer-liquid-collateral\">युक्ती एक, द्रव संपार्श्विक प्राधान्य</h2>\n<p>पहिली स्मार्ट सवय म्हणजे अस्थिर स्टॉकवर झुकून राहण्यापेक्षा जिथे जमेल तिथे लिक्विड, रोख-समतुल्य संपार्श्विक तारण ठेवणे. दोन स्पष्ट कारणे आहेत.</p>\n<p>प्रथम साधी कार्यक्षमता आहे. लिक्विड कोलॅटरलमध्ये लहान धाटणी असते, त्यामुळे ते तुम्हाला प्रति रुपया गहाण ठेवण्यासाठी अधिक मार्जिन देते. कॅश ईटीएफमध्ये फक्त 6 टक्के केस कापता येतात, जे तुम्हाला अंदाजे 94 टक्के मार्जिन देतात. सार्वभौम सुवर्ण रोखे, सरकारी सिक्युरिटीज, लिक्विड फंड आणि ट्रेझरी बिले सुमारे 10 टक्के केस कापतात, सुमारे 90 टक्के देतात. स्टॉक आणि इक्विटी फंड, त्यांच्या मोठ्या आणि परिवर्तनीय धाटणीसह, तुम्हाला कमी आणि अनिश्चित रक्कम देतात.</p>\n<p>दुसरे कारण म्हणजे सुरक्षितता. जेव्हा तुम्ही स्थिर रोख तारण ठेवता तेव्हा त्याचे मूल्य क्वचितच हलते, त्यामुळे तुमचे मार्जिन स्थिर राहते आणि संपार्श्विक बाजूकडून तुम्हाला मार्जिन कॉलचा सामना करावा लागत नाही. त्याऐवजी अस्थिर स्टॉक गहाण ठेवा आणि जर बाजार घसरला तर तुमच्या तारणाचे मूल्यही कमी होईल. तुमचे मार्जिन कमी होत आहे आणि तुमचे ब्रोकर तुम्हाला टॉप अप करण्यास सांगू शकतात. 6 टक्के हेअरकटवर 1,00,000 रुपये लिक्विड इन्स्ट्रुमेंट गहाण ठेवा आणि तुमच्याकडे स्थिर मार्जिन 94,000 रुपये आहे. 20 टक्के हेअरकटमध्ये अस्थिर स्टॉकचे 1,00,000 रुपये तारण ठेवा आणि तुम्ही 80,000 रुपयांपासून सुरुवात करा, परंतु स्टॉकमध्ये 20 टक्के घसरण झाल्यास त्याचे मूल्य 80,000 रुपयांपर्यंत घसरते आणि त्या कमी मूल्यावरील हेअरकट तुमचे फक्त 64,000 रुपये उरते. हा तुटवडा तुम्ही फक्त तारण ठेवलेल्या तारणावर मार्जिन कॉल ट्रिगर करू शकतो, कधीही व्यापार केला नाही.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तुमच्याकडे पर्याय असल्यास, तुमच्या मार्जिनच्या अर्ध्या रोख रकमेसाठी लिक्विड संपार्श्विक तारण ठेवा आणि लहान, नॉन-कॅश टॉप-अप म्हणून अस्थिर स्टॉक ठेवा. तुम्हाला अधिक मार्जिन मिळते, तुम्ही रोख-शॉर्टफॉल व्याज भरणे टाळता आणि तुम्ही मार्जिन कॉल ट्रिगर करणाऱ्या तुमच्या स्वतःच्या संपार्श्विकाचा धोका दूर करता.</p>\n</div></div>\n<h2 id=\"trick-two-the-covered-call\">युक्ती दोन, कव्हर कॉल</h2>\n<p>जर तुमचा पोर्टफोलिओ सर्व इक्विटी असेल आणि तुमच्याकडे कोणतीही लिक्विड इन्स्ट्रुमेंट नसेल तर? तुम्ही अजूनही तारण ठेवलेला स्टॉक ए द्वारे काम करण्यासाठी ठेवू शकता <strong>कव्हर कॉल</strong>, तुम्ही पूर्वी भेटलेले धोरण. तरीही तुमच्याकडे असलेल्या शेअर्समधून उत्पन्न मिळवण्याची कल्पना आहे.</p>\n<p>समजा तुमच्याकडे रु. 1,318 जवळचे 500RELIANCE′ शेअर्स आहेत, ज्याचे होल्डिंग रु. 6,59,000 आहे. तुम्ही त्यांना गहाण ठेवता आणि साधारण 9 टक्के केस कापल्यानंतर तुम्हाला सुमारे 6,00,000 रुपये मार्जिन मिळेल. त्या मार्जिनच्या विरूद्ध तुम्ही उच्च RELIANCE कॉलचा एक लॉट विकता, 1360 स्ट्राइक सुमारे 16 रुपये प्रति शेअरसाठी आहे, जे तुमच्या खात्यात अंदाजे 8,000 रुपये प्रीमियम ठेवते. जर RELIANCE 1360 पेक्षा जास्त संपला, तर तुमचे शेअर्स वाढले आहेत आणि तो नफा विक्री कॉल ऑफसेट करतो. जर ते 1360 च्या खाली पूर्ण झाले तर, कॉल निरुपयोगी होईल आणि तुम्ही पर्वा न करता तुम्ही धारण केलेल्या शेअर्सवरील उत्पन्न म्हणून प्रीमियम ठेवता. जरी रोख-घटक खर्च लक्षात ठेवा, कारण F&amp;O मार्जिनच्या मागे रोख रक्कम नसल्यास, शॉर्ट कॉल उघडेपर्यंत शॉर्टफॉलवर व्याज लागू होते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>कव्हर कॉल हा तारण असताना सर्व-इक्विटी पोर्टफोलिओ कमावण्याचा नैसर्गिक मार्ग आहे. तुम्ही नवीन दिशात्मक पैज घेत नाही आहात, तुम्ही स्ट्राइकच्या वरची बाजू भाड्याने देत आहात जी तुम्हाला तरीही विकण्यास आनंद होईल आणि त्यासाठी प्रीमियम गोळा करत आहात.</p>\n</div></div>\n<h2 id=\"how-you-pledge-and-the-real-risk\">आपण कसे प्रतिज्ञा, आणि वास्तविक धोका</h2>\n<p>यांत्रिकी सरळ आहेत. तुमच्या ब्रोकरच्या प्लॅटफॉर्मवर तुम्ही तुमच्या होल्डिंगवर जाता, तारण ठेवण्यासाठी साठा आणि प्रमाण निवडा आणि विनंती सबमिट करा. डिपॉझिटरीच्या मंजुरीच्या पायरीनंतर, मार्जिन त्याच दिवशी, सामान्यतः काही मिनिटांत जमा केले जाते. अनप्लेजिंग त्याच मार्गाचे अनुसरण करते आणि ते विनामूल्य आहे आणि जर तुम्ही तारण ठेवलेला स्टॉक विकला तर तो विक्रीचा भाग म्हणून आपोआप अनप्लेज केला जातो. ब्रोकरद्वारे अचूक पडदे भिन्न असतात, परंतु आकार सर्वत्र समान असतो.</p>\n<p>आता जोखीम, कारण तारण ठेवल्याने दोन्ही मार्ग कापतात. धोका पूर्णपणे गहाण ठेवण्यामध्ये राहतो <strong>अस्थिर, नॉन-कॅश</strong> संपार्श्विक आणि नंतर त्याच्या विरुद्ध व्यापार.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-pledge-margincall.png\" alt=\"अस्थिर स्टॉक गहाण ठेवण्याचा धोका: जर त्याची किंमत कमी झाली, तर नवीन कमी मूल्यावर हेअरकट लागू केले गेले, तुमचे वापरण्यायोग्य मार्जिन पोझिशनच्या आवश्यकतेपेक्षा कमी होते, ब्रोकर मार्जिन कॉल जारी करतो आणि जर तुम्ही पैसे देऊ शकत नसाल तर तारण ठेवलेले शेअर्स कमतरता भरून काढण्यासाठी विकले जातात.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>अस्थिर स्टॉक गहाण ठेवण्याचा धोका: जर त्याची किंमत कमी झाली, तर नवीन कमी मूल्यावर हेअरकट लागू केले गेले, तुमचे वापरण्यायोग्य मार्जिन पोझिशनच्या आवश्यकतेपेक्षा कमी होते, ब्रोकर मार्जिन कॉल जारी करतो आणि जर तुम्ही पैसे देऊ शकत नसाल तर तारण ठेवलेले शेअर्स कमतरता भरून काढण्यासाठी विकले जातात.</figcaption></figure>\n<p>एक उदाहरण चाला. तुम्ही Rs 2,00,000 किमतीचे RELIANCE शेअर्स गहाण ठेवता आणि, 9 टक्के केस कापल्यानंतर, सुमारे Rs 1,82,000 मार्जिन मिळवा, जे तुम्ही F&amp;O पोझिशनसाठी वापरता. मग RELIANCE 10 टक्के कमी झाले, त्यामुळे तुमची तारण आता 1,80,000 रुपये आहे आणि त्यावर 9 टक्के हेअरकट केवळ 1,63,800 रुपये मार्जिन सोडते. तुमच्याकडे आता अंदाजे रु. 18,200 चा तुटवडा आहे. ब्रोकर मुद्दे अ <strong>मार्जिन कॉल</strong>, तुम्हाला ती रक्कम रोख रकमेमध्ये जोडण्यासाठी किंवा आणखी तारण ठेवण्यास सांगत आहे. जर तुम्ही हे करू शकत नसाल, तर ब्रोकर तुमचे तारण ठेवलेले पुरेसे शेअर्स सध्याच्या बाजारभावानुसार ते अंतर भरून काढण्यासाठी विकेल. त्या सक्तीच्या विक्रीमुळे शेअर्सचे नुकसान होते आणि तुमचे दीर्घकालीन होल्डिंग कमी होते. त्यामुळे एक वाईट दिवस तुम्हाला दोनदा महागात पडू शकतो, एकदा व्यापारावर आणि एकदा पोर्टफोलिओवर ज्याचा तुम्ही कधीही विक्री करू इच्छित नव्हता.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>अस्थिर स्टॉक गहाण ठेवणे आणि त्याविरुद्ध व्यापार करणे तुमची जोखीम दुप्पट करते. बाजारातील घसरण तुमच्या F&amp;O स्थितीला हानी पोहोचवू शकते आणि तुमचे तारण ठेवलेले तारण संकुचित करू शकते आणि जर तुम्ही परिणामी मार्जिन पूर्ण करू शकत नसाल तर ब्रोकर तुमचे शेअर्स तुम्हाला खराब किंमतीला विकतो. जबरदस्तीने केलेली विक्री हा तारण ठेवण्याचा खरा धोका आहे, केस कापण्याचा नाही.</p>\n</div></div>\n<h2 id=\"so-should-you-pledge\">तर गहाण ठेवावे का?</h2>\n<p>वचन देणे खरोखर शक्तिशाली आहे, परंतु ते प्रत्येकासाठी किंवा प्रत्येक परिस्थितीसाठी नाही. तीन प्रामाणिक चाचण्या हे ठरवतात.</p>\n<ul>\n<li>प्लेजिंग तुम्हाला अतिरिक्त खरेदी शक्ती देते, परंतु ते तुमची जोखीम देखील वाढवते. आपण ते व्यवस्थापित करण्यास तयार नसल्यास, ते वगळणे चांगले आहे.</li>\n<li>अल्प-मुदतीच्या संधींचा पाठलाग करणाऱ्या सक्रिय व्यापाऱ्यासाठी, तारण हे एक उपयुक्त साधन आहे. दीर्घकालीन गुंतवणूकदार ज्याला फक्त ठेवायचे आहे, ते त्यांना आवश्यक नसलेली जोखीम जोडते.</li>\n<li>कठोर स्टॉप लॉस आणि शिस्तबद्ध पोझिशन साइझिंग सोबतच तारण ठेवणे अर्थपूर्ण आहे. त्याशिवाय, ते लहान चुकांचे मोठ्यामध्ये रूपांतर करते.</li>\n</ul>\n<p>स्पष्ट जोखीम योजनेमध्ये वापरलेले, तारण ठेवल्याने तुमच्या आधीपासून असलेल्या मालमत्तेतील तरलता अनलॉक होते आणि तुमचा पोर्टफोलिओ आणि तुमची रणनीती एकाच वेळी कार्य करू देते. एक न वापरता, ते शांतपणे आपल्या होल्डिंग्सच्या कायमस्वरूपी नुकसानामध्ये नियमित बाजार बुडवून बदलू शकते. निधीची बाजू आता समजल्यामुळे, पुढचा अध्याय तुमचा मार्जिन किमान, मार्जिन पेनल्टीच्या जगापेक्षा कमी पडल्यावर काय होते याकडे वळतो.</p>\n","toc":[{"level":2,"text":"प्रतिज्ञा प्रत्यक्षात काय करते","id":"what-pledging-actually-does"},{"level":2,"text":"तुम्हाला किती मिळेल हे हेअरकट ठरवते","id":"the-haircut-decides-how-much-you-get"},{"level":2,"text":"रोख संपार्श्विक विरुद्ध नॉन-कॅश संपार्श्विक","id":"cash-collateral-versus-non-cash-collateral"},{"level":2,"text":"युक्ती एक, द्रव संपार्श्विक प्राधान्य","id":"trick-one-prefer-liquid-collateral"},{"level":2,"text":"युक्ती दोन, कव्हर कॉल","id":"trick-two-the-covered-call"},{"level":2,"text":"आपण कसे प्रतिज्ञा, आणि वास्तविक धोका","id":"how-you-pledge-and-the-real-risk"},{"level":2,"text":"तर गहाण ठेवावे का?","id":"so-should-you-pledge"}],"imgCount":2,"hasContent":true},"24":{"html":"<p>पोझिशन किती मार्जिन ब्लॉक करते आणि तारण ठेवून निधी कसा मिळवायचा हे आता तुम्हाला माहिती आहे. मार्जिन कथेचा शेवटचा भाग म्हणजे जेव्हा तुम्ही कमी पडता तेव्हा काय होते. एक्सचेंज फक्त एकदाच तुमचे मार्जिन तपासत नाही आणि त्याबद्दल विसरत नाही. हे वारंवार, यादृच्छिकपणे, दिवसभर तपासते आणि प्रत्येक वेळी जेव्हा तुम्ही आवश्यक किमान कमी करता तेव्हा ते दंड आकारते. हे धनादेश नेमके कसे कार्य करतात हे समजून घेणे आणि त्यांना चालना देणाऱ्या दैनंदिन परिस्थितीमुळेच एक व्यापाऱ्याला वेगळे केले जाते जो त्यांचे परतावा रोखून ठेवतो जो शांतपणे दंड भरून रक्त काढतो. हा अध्याय मार्जिन नियमांच्या उजव्या बाजूला राहण्याबद्दल आहे.</p>\n<h2 id=\"the-minimum-margin-you-must-always-hold\">किमान मार्जिन तुम्ही नेहमी धारण केले पाहिजे</h2>\n<p>कारण लीव्हरेज्ड पोझिशन तुमच्या खात्यातील रोख रकमेपेक्षा जास्त गमावू शकते, नियामकांना तुमच्या ब्रोकरला अशा प्रत्येक ट्रेडवर किमान मार्जिन गोळा करणे आवश्यक आहे आणि ते किमान पर्यायी नाही. रक्कम एक्सचेंजद्वारे परिभाषित केली जाते, ब्रोकरद्वारे नाही.</p>\n<ul>\n<li>साठी <strong>इक्विटी</strong>, किमान म्हणतात <strong>VAR अधिक ELM</strong> (जोखमीचे मूल्य आणि अत्यंत तोटा मार्जिन).</li>\n<li>साठी <strong>F&amp;O</strong>, ते आहे <strong>SPAN प्लस एक्सपोजर</strong> तुम्हाला आधीच माहित आहे.</li>\n</ul>\n<p>पीक-मार्जिन नियम आले असल्याने, ही किमान संपूर्ण उद्योगात एकसमान आहे. ब्रोकर यापुढे विक्री बिंदू म्हणून अतिरिक्त इंट्राडे लीव्हरेज देऊ शकत नाही. तुम्ही कोणताही व्यापार करता, समान किमान मार्जिन लागू होते आणि ते तुमच्या खात्यात असणे अपेक्षित आहे.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>किमान मार्जिन एक्सचेंजद्वारे सेट केले जाते आणि सर्वत्र समान असते. F&amp;O साठी ते SPAN अधिक एक्सपोजर आहे, इक्विटीसाठी ते VAR अधिक ELM आहे. तुम्ही कमीत कमी ही रक्कम कोणत्याही लीव्हरेज्ड पोझिशनमध्ये ठेवली पाहिजे आणि ब्रोकरकडे तुम्हाला कमी ठेवू देण्याचा कोणताही कायदेशीर मार्ग नाही.</p>\n</div></div>\n<h2 id=\"peak-margin-the-random-checks\">पीक मार्जिन, यादृच्छिक चेक</h2>\n<p>सर्वात नवशिक्यांना आश्चर्यचकित करणारा भाग येथे आहे. एक्सचेंज फक्त दिवसाच्या शेवटी तुमचे मार्जिन तपासत नाही. पीक-मार्जिन प्रणाली अंतर्गत, क्लिअरिंग कॉर्पोरेशन घेते <strong>एकाधिक यादृच्छिक स्नॅपशॉट्स</strong> ट्रेडिंग दिवसादरम्यान प्रत्येक ट्रेडरच्या पोझिशन्स आणि मार्जिन, तसेच दिवसाच्या शेवटी चेक. इंट्राडे स्नॅपशॉट्स कधी पडतील हे तुम्हाला माहीत नाही, आणि अचूक आकडा कायमचा निश्चित करण्याऐवजी एक्सचेंजद्वारे सेट केला जातो.</p>\n<p>त्या प्रत्येक क्षणी, तुमच्या खात्यात पूर्ण आवश्यक मार्जिन असणे आवश्यक आहे. तुम्ही एका स्नॅपशॉटमध्ये कमी असल्यास, तुम्हाला उरलेल्या दिवसासाठी पुरेसा मार्जिन असला किंवा नसला तरी, त्या क्षणी झालेली कमतरता रेकॉर्ड केली जाते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-margin-snapshots.png\" alt=\"क्लिअरिंग कॉर्पोरेशन दिवसभरातील अनेक यादृच्छिक क्षणी तुमचे मार्जिन तपासते आणि दिवसाच्या शेवटी चेक करते, आणि त्यापैकी कोणत्याही एकावर आवश्यक मार्जिन कमी असणे ही कमतरता नोंदवते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>क्लिअरिंग कॉर्पोरेशन दिवसभरातील अनेक यादृच्छिक क्षणी तुमचे मार्जिन तपासते आणि दिवसाच्या शेवटी चेक करते, आणि त्यापैकी कोणत्याही एकावर आवश्यक मार्जिन कमी असणे ही कमतरता नोंदवते.</figcaption></figure>\n<p>म्हणूनच व्यापारी बंद होण्यापूर्वी टॉप अप करू शकत नाही आणि ते सुरक्षित असल्याचे गृहीत धरू शकत नाही. यादृच्छिक स्नॅपशॉट्सचा अर्थ असा आहे की कमतरता टाळण्याचा एकमेव विश्वासार्ह मार्ग म्हणजे दिवसभर संपूर्ण मार्जिन धारण करणे, केवळ सोयीस्कर क्षणांवर नाही.</p>\n<h2 id=\"the-penalty-slabs\">पेनल्टी स्लॅब</h2>\n<p>जेव्हा एखादी कमतरता आढळली, तेव्हा कोणत्याही स्नॅपशॉटवर किंवा दिवसाच्या शेवटी, आपण कमी केलेल्या रकमेवर दंड आकारला जातो. दर टायर्ड आहेत.</p>\n<table>\n<thead>\n<tr>\n<th>दिवसा उणीव</th>\n<th>कमतरतेवर दंड</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1 लाख रुपयांपेक्षा कमी</td>\n<td>0.5 टक्के</td>\n</tr>\n<tr>\n<td>१ लाख रुपये किंवा त्याहून अधिक</td>\n<td>1 टक्के</td>\n</tr>\n<tr>\n<td>एका महिन्यात तीनपेक्षा जास्त वेळा</td>\n<td>5 टक्के पर्यंत</td>\n</tr>\n</tbody></table>\n<p>त्यामुळे 50,000 रुपये कमी झाल्यास 250 रुपये दंड आकारला जातो, तर 2,00,000 रुपये कमी झाल्यास 2,000 रुपये दंड आकारला जातो. वारंवार कमी पडणे, एकाच महिन्यात तीनपेक्षा जास्त वेळा, आणि दर 5 टक्क्यांपर्यंत वाढू शकतो. हे दंड एक्सचेंजद्वारे गोळा केले जातात आणि कोर सेटलमेंट गॅरंटी फंडमध्ये जमा केले जातात. ते तुमच्या ब्रोकरने शोधलेले शुल्क नाहीत, ते नियामक शुल्क आहेत आणि ते थेट तुमच्या रिटर्नमधून येतात.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>तुमच्या संपूर्ण पोझिशनवर नाही, तर कमीपणावर मार्जिन पेनल्टी आकारली जाते, परंतु ती वेगाने वाढते. वारंवार होणाऱ्या छोट्या उणिवा शांतपणे ट्रेडिंग खाते खोडून काढतात आणि एका महिन्यात तीन घटना पार केल्याने दर वाढतो. सर्वात स्वस्त दंड हा आहे जो तुम्ही नेहमी मार्जिन बफर धरून कधीही ट्रिगर करत नाही.</p>\n</div></div>\n<h2 id=\"upfront-versus-non-upfront-shortfalls\">अपफ्रंट विरुद्ध नॉन-अपफ्रंट कमतरता</h2>\n<p>सर्व उणीवांना सारखेच वागवले जात नाही आणि कोण पैसे द्यायचे हे फरक ठरवतो.</p>\n<ul>\n<li>अ <strong>आगाऊ कमतरता</strong> तुम्ही पोझिशनमध्ये प्रवेश करता त्या क्षणी पुरेसे मार्जिन नसेल किंवा तुम्ही आधीच पोझिशनमध्ये आल्यानंतर आवश्यक मार्जिन तुमच्यापेक्षा जास्त असेल. ब्रोकरकडून अपफ्रंट पेनल्टी तुमच्यापर्यंत पोहोचू शकत नाहीत, त्यामुळे ब्रोकर ते सहन करतो. दुसरी बाजू अशी आहे की ब्रोकर तुम्हाला अपफ्रंट मार्जिनशिवाय व्यापारात प्रवेश करू देणार नाहीत.</li>\n<li>ए <strong>नॉन-अपफ्रंट कमतरता</strong> एक मार्जिन आहे जो तुम्ही प्रविष्ट केल्यानंतर देय होतो. सर्वात स्पष्ट उदाहरण म्हणजे फ्युचर्स पोझिशनवर मार्क-टू-मार्केट तोटा, जिथे तुमच्याकडे निधी आणण्यासाठी दुसऱ्या दिवसापर्यंत, टी प्लस वन आहे. स्टॉक डेरिव्हेटिव्ह्जवरील एक्सपायरी-वीक डिलिव्हरी मार्जिन आणि इतर तदर्थ मार्जिन देखील येथे येतात. नॉन-अपफ्रंट दंड तुमच्यापर्यंत पोहोचवला जाऊ शकतो.</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>व्यावहारिक उपाय म्हणजे पेनल्टी कोणत्या बादलीत पडते हे लक्षात ठेवणे नव्हे, तर मार्जिनची कमतरता टाळण्याची नेहमीच तुमची समस्या असते हे लक्षात घेणे. ब्रोकरने दंड सहन केला किंवा तो पास केला, कमीपणाचा अर्थ असा आहे की तुमची पोझिशन्स कमी आहेत आणि तुमच्यासाठी बंद होण्याचा धोका आहे.</p>\n</div></div>\n<h2 id=\"the-everyday-situations-that-trip-traders\">दररोजच्या परिस्थिती ज्या व्यापाऱ्यांना ट्रिप करतात</h2>\n<p>बेपर्वा अतिउत्साहाचा परिणाम क्वचितच होतो. ते सामान्यत: सामान्य परिस्थितीतून येतात जेथे तुम्ही आधीच व्यापारात आल्यानंतर आवश्यक मार्जिन शांतपणे वाढतो. तीन जाणून घेण्यासारखे आहेत.</p>\n<ul>\n<li><strong>एक लहान पर्याय तुमच्या विरोधात फिरत आहे.</strong> जेव्हा तुम्ही एखादा पर्याय विकता, तेव्हा फ्युचर्ससारखे कोणतेही दैनिक मार्क-टू-मार्केट सेटलमेंट नसते. त्याऐवजी, पोझिशन तुमच्या विरुद्ध जात असताना, आवश्यक मार्जिन फक्त वर जाते. जर तुमच्याकडे अतिरिक्त मार्जिन नसेल, तर ते अपफ्रंट शॉर्टफॉल म्हणून मानले जाते. म्हणूनच लहान विक्रेत्याने नेहमी स्पेअर मार्जिन ठेवणे आवश्यक आहे, फक्त पहिल्या दिवशी आवश्यक रक्कम नाही.</li>\n<li><strong>हेज लेग बंद करणे.</strong> हेज्ड पोझिशनला नग्न स्थितीपेक्षा खूपच कमी मार्जिनची आवश्यकता असते, कारण एक्स्चेंज जोखीम मर्यादित असल्याचे पाहू शकते. खरेदी केलेल्या पुटद्वारे संरक्षित केलेल्या फ्युचर्स पोझिशनचे चित्रण करा, ज्याला एकत्रितपणे फक्त थोड्या फरकाची आवश्यकता असू शकते. पुट बंद करा आणि फ्युचर्स पोझिशन अचानक नग्न होते, त्यामुळे त्याचे मार्जिन लगेच परत वर येते. तुमच्याकडे तेवढी मोठी रक्कम नसल्यास, हेज निघून गेल्यावर तुमची कमतरता असेल.</li>\n<li><strong>अस्थिरतेत उडी.</strong> जेव्हा बाजार अस्थिर होतात, तेव्हा एक्सचेंज संपूर्ण बोर्डवर SPAN आणि एक्सपोजर मार्जिन वाढवू शकते. काल पूर्णपणे मार्जिन केलेली स्थिती आज तुमच्या स्वतःच्या कोणत्याही कृतीशिवाय लहान असू शकते.</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>रणनीतीचा जोखीम-कमी करणारा पाय नेहमी शेवटचा काढा, प्रथम कधीही नाही. जोखमीच्या आधी संरक्षणात्मक पाय बंद करून तुम्ही लोखंडी कंडर किंवा हेज्ड भविष्य सोडल्यास, जे शिल्लक आहे त्यावरील मार्जिन वाढेल आणि दोन ऑर्डरमधील अंतरामध्ये तुम्ही कमी पडू शकता. प्रथम नग्न धोका बंद करा, संरक्षण शेवटचे.</p>\n</div></div>\n<h2 id=\"staying-penalty-free\">दंडमुक्त राहणे</h2>\n<p>यापैकी काहीही टाळणे कठीण नाही, फक्त खोली सोडण्याची सवय लागते. जे व्यापारी कधीही दंड भरत नाहीत ते असेच असतात जे त्यांच्या शेवटच्या मार्जिनपर्यंत कधीही व्यापार करत नाहीत.</p>\n<ul>\n<li>ठेवा ए <strong>मार्जिन बफर</strong>. तुम्ही व्यापार करण्यापूर्वी OpenAlgo मार्जिन कॅल्क्युलेटर चालवा आणि तुम्ही आवश्यकतेपेक्षा अधिक आरामात धरले असल्याची पुष्टी करा, त्यामुळे इंट्राडे वाढ तुम्हाला कमी पडू देत नाही.</li>\n<li>फंड फ्युचर्स मार्क-टू-मार्केट नुकसान, टी प्लस वन डेडलाइनच्या आधी दुसऱ्या दिवशी.</li>\n<li>जेव्हा तुम्ही लहान पर्याय असाल, तेव्हा स्थिती तुमच्या विरुद्ध जात असताना वाढत्या मार्जिनकडे लक्ष द्या आणि त्यासाठी अतिरिक्त निधी ठेवा.</li>\n<li>सुरक्षित क्रमाने मल्टी-लेग स्ट्रॅटेजीज अनवाइंड करा, नग्न पाय प्रथम, हेज शेवटचे.</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>मार्जिन दंड जवळजवळ पूर्णपणे टाळता येण्याजोगा आहेत. ते व्यापारासाठी शिक्षा नाहीत, ते यादृच्छिक धनादेशांपैकी एक जमिनीवर आल्यावर अल्प-मार्जिन राहण्याची किंमत आहे. बफर धरा, वेळेवर फ्युचर्स लॉस फंड करा आणि योग्य क्रमाने बचाव करा आणि तुम्ही त्यांना कधीही भेटणार नाही.</p>\n</div></div>\n<p>आता तुम्हाला प्रत्येक बाजूने मार्जिन समजले आहे, ते काय आहे, तारण आणि तारण द्वारे निधी कसा द्यायचा आणि दंडापासून मुक्त कसे राहायचे. ते या कोर्समधील प्रत्येक धोरणामागील व्यावहारिक यंत्रणा पूर्ण करते. शेवटच्या प्रकरणात आम्ही यांत्रिकीपासून मागे हटतो आणि हे सर्व प्रश्नाचे उत्तर देतो, वास्तविक दृश्य आणि वास्तविक खात्यासह, तुम्ही प्रत्यक्षात कोणती रणनीती निवडता आणि एकदा ती चालू झाल्यावर तुम्ही ती कशी व्यवस्थापित करता.</p>\n","toc":[{"level":2,"text":"किमान मार्जिन तुम्ही नेहमी धारण केले पाहिजे","id":"the-minimum-margin-you-must-always-hold"},{"level":2,"text":"पीक मार्जिन, यादृच्छिक चेक","id":"peak-margin-the-random-checks"},{"level":2,"text":"पेनल्टी स्लॅब","id":"the-penalty-slabs"},{"level":2,"text":"अपफ्रंट विरुद्ध नॉन-अपफ्रंट कमतरता","id":"upfront-versus-non-upfront-shortfalls"},{"level":2,"text":"दररोजच्या परिस्थिती ज्या व्यापाऱ्यांना ट्रिप करतात","id":"the-everyday-situations-that-trip-traders"},{"level":2,"text":"दंडमुक्त राहणे","id":"staying-penalty-free"}],"imgCount":1,"hasContent":true},"25":{"html":"<p>आत्तापर्यंत या कोर्समधील प्रत्येक रणनीती अशी आहे जी तुम्ही धारण केली आहे आणि ती कालबाह्य होईल. तुम्ही एक आकार निवडला, तुम्ही ज्या क्षणी प्रवेश केला त्या क्षणी तुम्हाला तुमचा जास्तीत जास्त नफा आणि तोटा माहित होता आणि तुम्ही वाट पाहिली. पण तुम्ही वाट पाहत असताना खऱ्या बाजारपेठा क्वचितच स्थिर बसतात. सोमवारी आरामात निघालेल्या छोट्या गळ्यात NIFTY गुरुवारपर्यंत त्याच्या स्ट्राइकपैकी एकावर दबाव आणू शकतो. बुल पुट स्प्रेड इंडेक्स त्याच्या विकलेल्या स्ट्राइककडे वळताना पाहू शकतो. जेव्हा असे घडते तेव्हा तुमच्याकडे धरून बसण्यापलीकडे तिसरा पर्याय असतो: तुम्ही हे करू शकता <strong>समायोजित करा</strong>. समायोजित करणे म्हणजे ते उघडे असताना स्थिती बदलणे, त्याचा बचाव करणे, वेळ विकत घेणे किंवा नवीन दृश्यावर पुन्हा केंद्रीत करणे. हा धडा मुख्य ऍडजस्टमेंट चाली शिकवतो आणि ते कधी वापरायचे नाही हे देखील तितकेच महत्वाचे आहे. येथे कोणतेही नवीन आकडे नाहीत, फक्त व्यापार लाइव्ह झाल्यावर व्यवस्थापित करण्याची कला.</p>\n<h2 id=\"why-adjust-at-all\">अजिबात कशाला समायोजित करा</h2>\n<p>आधीच चालू असलेल्या स्थितीला स्पर्श करण्याची फक्त तीन प्रामाणिक कारणे आहेत.</p>\n<ul>\n<li><strong>तोटा लहान किंवा अधिक परिभाषित मध्ये कमी करण्यासाठी.</strong> चाचणी केलेला लहान पाय परिभाषित-जोखमीच्या स्प्रेडमध्ये बदलला जाऊ शकतो, त्यामुळे पळून गेलेला तोटा कॅप्ड होतो.</li>\n<li><strong>वेळ खरेदी करण्यासाठी.</strong> जर तुमचा दृष्टिकोन अजूनही बरोबर असेल परंतु हालचाल अद्याप झाली नसेल, तर तुम्ही ट्रेडला नंतरच्या एक्सपायरीमध्ये ढकलून काम करण्यासाठी अधिक जागा देऊ शकता.</li>\n<li><strong>नवीन दृश्यावर पुन्हा केंद्रीत करण्यासाठी.</strong> जर NIFTY हलला असेल आणि तुमचे वाचन खरोखरच बदलले असेल, तर तुम्ही नवीन किमतीच्या आसपास बसण्यासाठी रचना बदलू शकता.</li>\n</ul>\n<p>त्या यादीत काय नाही ते लक्षात घ्या: तुम्ही चुकीचे होते हे मान्य करणे टाळण्यासाठी समायोजित करणे किंवा नुकसान परत करण्याच्या आशेने नवीन जोखीम जोडणे. खाती नष्ट करण्याचे ते दोन मार्ग आहेत. खाली दिलेली प्रत्येक हालचाल तेव्हाच उपयुक्त ठरते जेव्हा ती तीन वास्तविक कारणांपैकी एक कारणीभूत ठरते.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>समायोजन जादू खोडरबर नाही. तुम्ही केलेल्या प्रत्येक बदलाची स्वतःची किंमत, स्वतःचा नवीन जोखीम आणि ब्लॉक केलेल्या मार्जिनवर स्वतःचा प्रभाव असतो. चांगल्या ऍडजस्टमेंटचे उद्दिष्ट हे आहे की तुमच्या प्रामाणिक वर्तमान दृश्याच्या सापेक्ष तुमची स्थिती सुधारणे, तोटा घेण्यास नकार देणे नाही. जर तुम्ही जुळवण्याचे एकमेव कारण म्हणजे तोट्याचा ट्रेड बंद करणे तुम्ही सहन करू शकत नाही, तर तो बंद करणे नेहमीच योग्य असते.</p>\n</div></div>\n<h2 id=\"rolling-out-in-time\">वेळेत बाहेर पडणे</h2>\n<p>पहिली चाल आहे <strong>गुंडाळणे</strong>, आणि ते सर्वात सौम्य आहे. तुम्ही लेग किंवा संपूर्ण पोझिशन जवळच्या एक्सपायरीमध्ये बंद करता आणि नंतरच्या एक्सपायरीमध्ये तीच रचना पुन्हा उघडता. कारण पुढील-तारीखांचे पर्याय अधिक वेळेचे मूल्य धारण करतात, त्यांच्या विक्रीमुळे तुम्ही जवळच्या पर्यायांची परत खरेदी करण्यासाठी खर्च केलेल्यापेक्षा जास्त क्रेडिट मिळते, त्यामुळे पुढील निव्वळ क्रेडिटसाठी रोल आउट अनेकदा केले जाऊ शकते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-strangle.png\" alt=\"एक NIFTY 23,950 पुट आणि विकले 24,150 कॉलसह शॉर्ट स्ट्रॅन्गल. जेव्हा निर्देशांक यापैकी एका स्ट्राइककडे वळतो, तेव्हा संपूर्ण रचना नंतरच्या कालबाह्यतेवर आणल्याने वेळ खरेदी होतो आणि सहसा अतिरिक्त क्रेडिट गोळा होते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>एक NIFTY 23,950 पुट आणि विकले 24,150 कॉलसह शॉर्ट स्ट्रॅन्गल. जेव्हा निर्देशांक यापैकी एका स्ट्राइककडे वळतो, तेव्हा संपूर्ण रचना नंतरच्या कालबाह्यतेवर आणल्याने वेळ खरेदी होतो आणि सहसा अतिरिक्त क्रेडिट गोळा होते.</figcaption></figure>\n<p>वरील लहान गळा घ्या. समजा NIFTY दोन आठवडे वाहून गेले आहेत आणि आता प्रीमियम क्षय होण्यासाठी थोडा वेळ शिल्लक असताना वरच्या स्ट्राइकवर झुकत आहे. रोल आउट करणे म्हणजे जवळपास महिन्याचे दोन्ही पाय परत विकत घेणे आणि पुढच्या एक्स्पायरीमध्ये तेच गळा विकणे. तुम्ही बाजाराला पुन्हा रेंजमध्ये स्थिरावण्यासाठी व्यापाराला आणखी एक महिना द्याल आणि विशेषाधिकारासाठी तुम्ही अधिक प्रीमियम गोळा करता. तुम्ही ज्या जोखमीसाठी वेळ विकत घेत आहात ती नाहीशी होत नाही, परंतु कॅलेंडर संपल्यामुळे तुम्ही तोटा सहन करण्यास भाग पाडण्यास नकार दिला आहे.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>वेळेत शॉर्ट पोझिशन आउट केल्याने ओपन-एंडेड जोखीम जास्त काळ जिवंत राहते. शॉर्ट स्ट्रॅन्गलला अजूनही त्याच्या वरील तोट्यावर कमाल मर्यादा नाही आणि खाली फक्त शून्यावर मजला आहे, आणि नंतरच्या कालबाह्यतेमध्ये ढकलण्याचा अर्थ असा आहे की तुम्हाला एका अतिरिक्त महिन्यासाठी या जोखमीचा सामना करावा लागेल. जेव्हा तुमचा NIFTY श्रेणीत राहण्याचा तुमचा दृष्टिकोन खरोखरच अखंड असेल तेव्हाच रोल आउट करा, बाजार तुम्हाला खरा असल्याचे सांगत असलेल्या नुकसानास विलंब करण्यासाठी प्रतिक्षेप म्हणून कधीही नाही.</p>\n</div></div>\n<h3 id=\"rolling-a-strike-up-or-down\">स्ट्राइक वर किंवा खाली रोल करणे</h3>\n<p>दुसरी चाल समान एक्सपायरी ठेवते पण <strong>चाचणी केलेल्या स्ट्राइकला किंमतीपासून दूर हलवते</strong>. NIFTY तुमच्या विकलेल्या 24,150 कॉलच्या विरोधात पुश अप करत असल्यास, तुम्ही तो कॉल परत विकत घेऊ शकता आणि उच्च स्ट्राइकवर नवीन कॉल विकू शकता, एक किंवा दोन पावले पुढे म्हणा. चाचणी केलेला पाय आता कृतीपासून पुढे आहे, म्हणून तो कमी तात्काळ दबावाखाली आहे.</p>\n<p>हे श्वास घेण्याची खोली विकत घेते, परंतु ते क्वचितच विनामूल्य असते. स्ट्राइकची विक्री केल्याने तुम्ही परत विकत घेतलेल्या रकमेपेक्षा कमी प्रीमियम मिळतो, त्यामुळे स्ट्राइक वर किंवा खाली केल्याने तुमच्या मूळ क्रेडिटचा काही भाग खर्च होतो आणि तुम्ही सावध न राहिल्यास स्थितीचा धोका वाढू शकतो. त्याबद्दल विचार करण्याचा प्रामाणिक मार्ग: तुमची संरक्षणाची लाइन किंमतीपासून पुढे नेण्यासाठी तुम्ही थोडे पैसे देत आहात, परत दिलेल्या क्रेडिटमध्ये. तुम्ही हे केल्यावर, एका वेळी एक बाजू बदला आणि दुसऱ्याला स्पर्श करण्यापूर्वी संपूर्ण पेऑफ पुन्हा वाचा. चाचणी न केलेले पुट जागेवर सोडताना चाचणी केलेला कॉल वर हलवल्याने अनेकदा गळचेपी पुन्हा केंद्रीत होते, तर दोन्ही एकाच वेळी, घाईघाईने हलवणे, शांत बचावात्मक समायोजन शांतपणे एका नवीन, मोठ्या स्थितीत बदलते ज्याला तुम्ही कधीही धरायचे नव्हते.</p>\n<h2 id=\"reshaping-the-structure\">संरचनेचा आकार बदलणे</h2>\n<p>चालींचे तिसरे कुटुंब व्यापाराचे स्वरूप बदलते, सामान्यतः खुल्या जोखमीचे परिभाषित जोखमीमध्ये रूपांतर करण्यासाठी.</p>\n<ul>\n<li><strong>एक प्रसार रुंद करा.</strong> बुल पुट स्प्रेड ज्याची चाचणी केली जात आहे तो स्प्रेडच्या कमी जोड्यांमध्ये खाली आणला जाऊ शकतो, ज्यामुळे स्प्रेड पूर्णपणे पैशामध्ये येण्यापूर्वी निर्देशांक घसरण्यास अधिक जागा देते. संपूर्ण संरचना परिभाषित-जोखीम राहते.</li>\n<li><strong>लोखंडी कंडर बनविण्यासाठी उलट बाजू जोडा.</strong> जर तुम्ही एकच क्रेडिट स्प्रेड चालवत असाल आणि एका बाजूला बाजार तुमच्या बाजूने गेला असेल, तर तुम्ही दुसऱ्या बाजूलाही स्प्रेड विकू शकता. बुल पुट स्प्रेड प्लस बेअर कॉल स्प्रेड हा एक लोखंडी कंडर आहे आणि दुसरा स्प्रेड जोडल्याने अधिक क्रेडिट मिळते आणि तुमचा फायदेशीर क्षेत्र रुंदावतो. हे तेव्हाच करा जेव्हा नवीन बाजू खरोखरच किंमतीपासून दूर असेल, जेणेकरून तुम्ही तुमच्या एक्सपोजरला दुप्पट न करता, तुम्हाला सहजतेने घेतलेल्या जोखमीसाठी प्रीमियम गोळा करत आहात.</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-put-spread.png\" alt=\"एक NIFTY बैल पुट स्प्रेड, 24,050 पुट विकून 23,950 पुट खरेदी करतो. NIFTY विकल्या गेलेल्या स्ट्राइकपासून दूर गेल्यास, बाजाराच्या वर पसरलेला बेअर कॉल जोडल्याने या सिंगल स्प्रेडला अतिरिक्त क्रेडिटसाठी संपूर्ण लोखंडी कंडरमध्ये रूपांतरित केले जाते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">तक्ता</span>एक NIFTY बैल पुट स्प्रेड, 24,050 पुट विकून 23,950 पुट खरेदी करतो. NIFTY विकल्या गेलेल्या स्ट्राइकपासून दूर गेल्यास, बाजाराच्या वर पसरलेला बेअर कॉल जोडल्याने या सिंगल स्प्रेडला अतिरिक्त क्रेडिटसाठी पूर्ण लोखंडी कंडरमध्ये रूपांतरित केले जाते.</figcaption></figure>\n<p>या सर्वांमधून चालणारा धागा असा आहे की आपण ठेवण्याचा किंवा पुनर्संचयित करण्याचा प्रयत्न करीत आहात, <strong>परिभाषित धोका</strong>. स्प्रेड रुंद केल्याने ते बद्ध राहते. स्प्रेडला लोखंडी कंडरमध्ये बदलणे दोन्ही बाजूंना बद्ध ठेवते. नवशिक्या सुरक्षितपणे करू शकणारे हे समायोजन आहेत, कारण सर्वात वाईट परिस्थिती प्रत्येक टप्प्यावर ज्ञात संख्या राहते.</p>\n<h2 id=\"capping-a-runaway-short\">एक धावपळ लहान कॅपिंग</h2>\n<p>सर्वांत महत्त्वाची बचावात्मक चाल म्हणजे ओपन-एंडेड जोखीम बंदमध्ये बदलणे. जर तुमचा नग्न पाय लहान असेल, विकलेला कॉल किंवा कोणतेही संरक्षण नसलेले विकलेले पुट असेल आणि बाजार त्याच्या विरोधात चालू असेल, तर तुम्ही हे करू शकता <strong>तोटा भरून काढण्यासाठी आणखी एक लांब पाय जोडा</strong>. तुमच्या विकल्या कॉलच्या वर कॉल खरेदी करा किंवा तुमच्या विकल्या पुटच्या खाली पुट करा, आणि नग्न शॉर्ट हे ज्ञात कमाल नुकसानासह क्रेडिट स्प्रेड बनते.</p>\n<p>हे एक समायोजन आहे जे केवळ जोखीम हलवण्याऐवजी खरोखर कमी करते. संरक्षणात्मक विंग विकत घेण्यासाठी तुम्ही तुमचे काही क्रेडिट परत देता, परंतु त्या बदल्यात अमर्यादित शेपूट निघून जाते, त्याऐवजी परिभाषित संख्येने तुम्ही जगू शकता.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>संरक्षक विंग विकत घेऊन पळून गेलेला शॉर्ट कॅप करणे ही योग्य चाल आहे. अतिरिक्त प्रीमियम गोळा करण्यासाठी आणि तुमचे नुकसान कमी करण्यासाठी अधिक नग्न लहान पाय जोडणे हे चुकीचे आहे आणि नवशिक्यांसाठी व्यवस्थापित करता येण्याजोग्या नुकसानाला खाते-समाप्तीमध्ये बदलण्याचा हा एकमेव मार्ग आहे. नियम सोपा आहे: समायोजन तुमची जोखीम कमी करू शकते किंवा ते स्थिर ठेवू शकते, परंतु यामुळे आधीच गमावलेल्या स्थितीचा ओपन-एंडेड धोका कधीही वाढू नये. गमावलेल्याला वाचवण्यासाठी जोखीम जोडू नका.</p>\n</div></div>\n<h2 id=\"adjusting-honestly-in-openalgo\">OpenAlgo मध्ये प्रामाणिकपणे समायोजन करत आहे</h2>\n<p>OpenAlgo चा स्ट्रॅटेजी बिल्डर तुम्हाला एक रुपया देण्याआधी यातील प्रत्येक हालचालीचे मॉडेल बनवू देतो, जेणेकरून तुमच्या नऊ नंबरचे समायोजन नक्की काय करते ते तुम्ही पाहू शकता. कार्यप्रवाह मुद्दाम प्रामाणिक आहे.</p>\n<ul>\n<li><strong>एक्झिट किमतीसह बंद पाय चिन्हांकित करा.</strong> तुम्ही चाचणी केलेला शॉर्ट परत विकत घेता किंवा जवळपास-महिन्याचा लेग बंद करता तेव्हा, ते बंद करण्यासाठी तुम्ही दिलेली किंमत रेकॉर्ड करा. त्या पायावर लक्षात आलेला नफा किंवा तोटा लॉक होतो.</li>\n<li><strong>नवीन पाय जोडा.</strong> गुंडाळलेल्या स्ट्राइकची विक्री करा, नंतरची समाप्ती उघडा किंवा संरचनेत ताजे पाय म्हणून संरक्षणात्मक पंख विकत घ्या.</li>\n<li><strong>मेट्रिक्स आणि मार्जिन पुन्हा तपासा.</strong> नवीन जास्तीत जास्त नफा, नवीन कमाल तोटा, नवीन ब्रेकइव्हन्स आणि सर्वात वरती नवीन मार्जिन आवश्यकता वाचा. तुमच्या जोखमीचे निराकरण करणारे पण तुमचे ब्लॉक केलेले मार्जिन दुप्पट करणारे समायोजन तुमचे खाते असू शकत नाही.</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>प्रत्येक वेळी मार्जिन पुन्हा तपासण्याचे कारण म्हणजे समायोजने अनेकदा ते झपाट्याने बदलतात. संरक्षक विंगसह नग्न शॉर्ट कॅप केल्याने सामान्यतः मार्जिन कमी होते, कारण एक्सचेंजला आता खुल्या दायित्वाऐवजी परिभाषित-जोखीम पसरते. वेळेत शॉर्ट आउट करणे किंवा दुसरी शॉर्ट साइड जोडणे, सहसा ते वाढवते. तुम्ही ॲडजस्ट ऑर्डर देण्यापूर्वी तुमच्या खात्यामध्ये नवीन मार्जिन आरामात बसत असल्याची नेहमी खात्री करा आणि सँडबॉक्स ट्रेडिंगमध्ये संपूर्ण क्रमाची पूर्वाभ्यास करा (Analyser मोड OpenAlgo मध्ये).</p>\n</div></div>\n<h2 id=\"adjust-or-simply-exit\">समायोजित करा किंवा फक्त बाहेर पडा</h2>\n<p>व्यापाराचा बचाव केव्हा करायचा आणि तो कधी बंद करायचा आणि पुढे जायचे हे जाणून घेणे हा सर्वात कठीण निर्णय आहे. सर्वात स्वच्छ चाचणी म्हणजे एक प्रश्न विचारणे: <strong>प्रबंध अजूनही वैध आहे का?</strong></p>\n<ul>\n<li>जर तुमचे मूळ कारण अजूनही टिकून राहिल्यास, तुमच्या विरुद्धची हालचाल फक्त आवाज आहे, आणि स्थिती अजूनही परिभाषित-जोखीम आहे किंवा तसे केले जाऊ शकते, तर <strong>समायोजित करा</strong>. रफ पॅचद्वारे तुम्ही चांगला व्यापार व्यवस्थापित करत आहात.</li>\n<li>तुम्ही प्रविष्ट केलेले कारण तुटलेले असल्यास, बाजाराने तुमच्या विरुद्ध दिशा स्पष्टपणे निवडली आहे किंवा व्यापाराचा बचाव करणे म्हणजे तुम्हाला परवडणार नाही अशी जोखीम जोडणे होय. <strong>बाहेर पडा</strong>. तोटा लहान असतानाच घ्या आणि पुढील सेटअपसाठी तुमचे भांडवल ठेवा.</li>\n</ul>\n\n<div class=\"callout example\"><span class=\"callout-tag\">खरे उदाहरण</span><div><p>दोन चाचणी केलेले लहान गळा, दोन भिन्न उत्तरे. प्रथम, NIFTY पातळ, दिशाहीन ट्रेडिंगवर तुमच्या कॉल स्ट्राइककडे भटकले आहे, ते श्रेणीबद्ध राहण्याचा तुमचा दृष्टिकोन अबाधित आहे, आणि तुमच्याकडे भरपूर मार्जिन आहे: चाचणी केलेला कॉल वर आणि बाहेर फिरवा, थोडे अधिक क्रेडिट गोळा करा आणि त्यास जागा द्या. दुस-यामध्ये, एक मजबूत ट्रेंड तयार झाला आहे, NIFTY तुमच्या स्ट्राइकवर खात्रीने तोडले आहे, आणि बचाव करण्याचा एकमेव मार्ग म्हणजे विक्री सुरू ठेवणे: बचाव करण्यासाठी काहीही नाही. ते बंद करा, परिभाषित तोटा स्वीकारा आणि ट्रेंड विरुद्ध व्यापार थांबवा.</p>\n</div></div>\n<p>नीट जुळवून घेणे म्हणजे खराब महिना टिकून राहणाऱ्या व्यापाऱ्याला न करणाऱ्यापासून वेगळे करणे. तुमची तीन प्रामाणिक कारणे धरा, प्रत्येक हालचाल परिभाषित जोखमीच्या आत ठेवा, प्रत्येक वेळी मार्जिन पुन्हा तपासा आणि आधीच गमावलेल्या स्थितीत कधीही धोका वाढवू नका. त्या शिस्तीने, या कोर्समधील धोरणे केवळ तुम्ही धारण केलेले आकारच बनत नाहीत, तर तुम्ही चालवू शकता असे व्यापार बनतात.</p>\n","toc":[{"level":2,"text":"अजिबात कशाला समायोजित करा","id":"why-adjust-at-all"},{"level":2,"text":"वेळेत बाहेर पडणे","id":"rolling-out-in-time"},{"level":3,"text":"स्ट्राइक वर किंवा खाली रोल करणे","id":"rolling-a-strike-up-or-down"},{"level":2,"text":"संरचनेचा आकार बदलणे","id":"reshaping-the-structure"},{"level":2,"text":"एक धावपळ लहान कॅपिंग","id":"capping-a-runaway-short"},{"level":2,"text":"OpenAlgo मध्ये प्रामाणिकपणे समायोजन करत आहे","id":"adjusting-honestly-in-openalgo"},{"level":2,"text":"समायोजित करा किंवा फक्त बाहेर पडा","id":"adjust-or-simply-exit"}],"imgCount":2,"hasContent":true},"26":{"html":"<p>पेऑफ चार्ट तुम्हाला सांगते की ट्रेड एक्सपायरीला कुठे संपतो. तिथल्या वाटेवर व्यापार कसा वाटेल, शांत दिवशी फायदा होतो किंवा रक्तस्त्राव होतो किंवा बाजाराचा मूड बदलला तर त्याचे काय होते हे ते सांगत नाही. त्यासाठी तुम्हाला आणखी दोन लेन्स लागतील. पहिला संच आहे <strong>निव्वळ ग्रीक</strong>, एका दिवसापासून दुसऱ्या दिवसापर्यंत तुमची स्थिती कशी श्वास घेते याचे वर्णन करणाऱ्या लहान संख्या. दुसरा आहे <strong>अस्थिरता व्यवस्था</strong>, सध्याचे पर्याय त्यांच्या स्वतःच्या भूतकाळाच्या तुलनेत महाग आहेत की स्वस्त आहेत हा साधा पण शक्तिशाली प्रश्न. रणनीती निवडण्यासाठी हा धडा विश्लेषणात्मक पूल आहे. एकदा तुम्ही एखाद्या पोझिशनचे निव्वळ ग्रीक वाचू शकलात आणि वर्तमान गर्भित अस्थिरता त्याच्या स्वतःच्या इतिहासावर ठेवू शकता, तेव्हा योग्य रचना अंदाज बनणे थांबते आणि निर्णय घेणे सुरू होते.</p>\n<h2 id=\"a-position-is-the-sum-of-its-legs\">स्थिती म्हणजे त्याच्या पायांची बेरीज</h2>\n<p>तुम्ही भेटलेली प्रत्येक मल्टी-लेग स्ट्रॅटेजी सिंगल ऑप्शन्समधून तयार केली आहे आणि प्रत्येक पर्यायाची स्वतःची ग्रीक आहेत. सुंदर, सोपी वस्तुस्थिती अशी आहे की ग्रीक लोक जोडतात. संपूर्ण स्थिती काय करते हे शोधण्यासाठी, प्रत्येक पायाच्या चिन्हाचा आदर करून, प्रत्येक पायावर समान ग्रीक जोडा. विकत घेतलेला पाय ग्रीक जोडतो; विकलेला पाय तो वजा करतो. डेल्टा, गॅमा, थीटा आणि वेगा हे चार महत्त्वाचे आहेत.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-position-greeks.png\" alt=\"मल्टी-लेग पोझिशनचे चार नेट ग्रीक, प्रत्येक पायावर समान ग्रीक जोडून तयार होतात: नेट डेल्टा म्हणजे दिशात्मक झुकाव, निव्वळ गामा म्हणजे किती वेगाने झुकते ते बदलते, नेट थीटा म्हणजे रुपयाच्या वेळेचा क्षय दररोज कमावतो किंवा खर्च होतो, आणि निव्वळ वेगा म्हणजे निहित अस्थिरतेची हालचाल झाल्यास पोझिशनला किती फायदा होतो किंवा तोटा होतो.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>मल्टी-लेग पोझिशनचे चार नेट ग्रीक, प्रत्येक पायावर समान ग्रीक जोडून तयार होतात: नेट डेल्टा म्हणजे दिशात्मक झुकाव, निव्वळ गामा म्हणजे किती वेगाने झुकते ते बदलते, नेट थीटा म्हणजे रुपयाच्या वेळेचा क्षय दररोज कमावतो किंवा खर्च होतो, आणि निव्वळ वेगा म्हणजे निहित अस्थिरतेची हालचाल झाल्यास पोझिशनला किती फायदा होतो किंवा तोटा होतो.</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>रणनीती ही फक्त त्याच्या पायांची बेरीज असते आणि त्याचप्रमाणे त्याचे ग्रीक देखील असतात. पाय जोडा आणि तुम्हाला पोझिशनचा नेट डेल्टा, नेट गामा, नेट थीटा आणि नेट वेगा मिळेल. हे चार आकडे तुम्हाला स्थिर पेऑफ चार्टमधून बाहेर पडलेली प्रत्येक गोष्ट सांगतात: ते कोणत्या मार्गाने झुकते, ते किती लवकर बदलते, वेळ तुम्हाला पैसे देत आहे किंवा शुल्क आकारत आहे का, आणि तुम्ही गर्भित अस्थिरतेतील बदलासाठी किंवा विरुद्ध पैज लावत आहात.</p>\n</div></div>\n<h2 id=\"reading-the-four-net-greeks\">चार निव्वळ ग्रीक वाचणे</h2>\n<p>आमच्या अँकरवर ठोस ट्रेड करा: 24,056 जवळ NIFTY स्पॉट, 24,050 वर पैशाचा स्ट्राइक, 28 जुलै 2026 ची मुदत जवळपास 32 दिवस संपत आहे, लॉट साइज 65. 24,050 कॉल विक्री करा आणि 24,050 एकत्र ठेवा <strong>लहान स्ट्रॅडल</strong>, प्रति लॉट 46,858 रुपये क्रेडिट गोळा करत आहे. एका वेळी त्याच्या चार निव्वळ ग्रीक चाला, कारण ते जवळजवळ प्रत्येक प्रीमियम-विक्री स्थितीचे वर्णन करतात जे तुम्ही कधीही चालवाल.</p>\n<p><strong>निव्वळ डेल्टा</strong> NIFTY मध्ये एका-बिंदूच्या हालचालीसाठी पोझिशनला किती फायदा होतो किंवा तोटा होतो हे दिशात्मक प्रदर्शन आहे. शॉर्ट कॉलमध्ये नकारात्मक डेल्टा असतो, शॉर्ट पुटमध्ये सकारात्मक डेल्टा असतो आणि पैशावर ते जवळजवळ रद्द करतात. त्यामुळे लहान स्ट्रॅडल आहे <strong>डेल्टा-न्यूट्रल जवळ</strong>: वर किंवा खाली एक छोटीशी झुळूक तुमचा नफा आणि तोटा क्वचितच हलवते. याउलट बुल कॉल स्प्रेड स्पष्टपणे सकारात्मक निव्वळ डेल्टा दर्शवेल, कारण त्याला निर्देशांक वाढवायचा आहे. साध्या शब्दात नेट डेल्टा हा प्रश्न आहे की मी कोणत्या दिशेने झुकत आहे आणि किती आहे.</p>\n<p><strong>निव्वळ गामा</strong> NIFTY जसजसा हलतो तसतसा तो डेल्टा किती वेगाने बदलतो. लहान स्ट्रॅडल आहे <strong>लहान गामा</strong>, म्हणजे त्याचा डेल्टा त्याच्या विरुद्ध वळतो: जसजसा निर्देशांक वाढतो तसतसे स्थान लहान होते, जसे ते खाली येते तसतसे स्थान लांब होते, म्हणून प्रत्येक हालचाल शेवटच्या पेक्षा थोडे अधिक दुखते. शॉर्ट गामा ही किंमत प्रत्येक प्रीमियम विक्रेता स्थिर उत्पन्नासाठी देते. लांब पर्याय उलट, लांब गामा आहेत, जेथे हालचाली आपल्याला अधिकाधिक मदत करतात.</p>\n<p><strong>नेट थीटा</strong> ते रुपये जे वेळ तुमच्या हातात पडतात किंवा तुमच्याकडून दररोज घेतात, बाकी सर्व काही स्थिर असते. लहान स्ट्रॅडल आहे <strong>सकारात्मक थीटा</strong>: तुम्ही निव्वळ विक्रेते आहात, त्यामुळे प्रत्येक दिवस उजाडणारा दिवस तुमच्यासाठी कमी असलेले पर्याय कमी करून वेळेचे मूल्य कमी करतो आणि तेच तुमचे उत्पन्न आहे. निव्वळ खरेदीदार, जसे की लांब पट्ट्यामध्ये, नकारात्मक थीटा असतो आणि ते दररोज भाडे भरतो. साध्या शब्दात थिटा म्हणजे घड्याळ हे माझे मित्र की माझे शत्रू.</p>\n<p><strong>नेट वेगा</strong> निहित अस्थिरतेतील बदलाचे प्रदर्शन, बाजाराची अपेक्षित श्रेणी रुंद किंवा संकुचित झाल्यास फायदा किंवा तोटा. लहान स्ट्रॅडल आहे <strong>लहान वेगा</strong>: गर्भित अस्थिरता कमी झाल्यास, तुम्ही विकलेले पर्याय परत खरेदी करण्यासाठी स्वस्त होतात आणि तुम्हाला फायदा होतो; जर ते वाढले, तर ते अधिक महाग होतात आणि तुम्ही गमावले, अगदी NIFTY एक बिंदू हलवण्यापूर्वीच. Vega साध्या शब्दात, मी भीती विकत आहे की विकत आहे.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>NIFTY वर एक लहान स्ट्रॅडल आणि चार पायांचे क्रेडिट आयर्न कंडोर समान ग्रीक स्वाक्षरी सामायिक करतात: डेल्टा-न्यूट्रल, शॉर्ट गॅमा, पॉझिटिव्ह थीटा, शॉर्ट वेगा. ते एक वाक्य संपूर्ण कथा सांगते. ते वेळेच्या क्षयातून आणि शांततेतून हळूहळू पैसे कमवतात, जर निर्देशांकाने मोठी हालचाल केली किंवा गर्भित अस्थिरता उडी घेतली तर ते गमावतात आणि जोपर्यंत ते दूर जात नाही तोपर्यंत ते कोणत्या दिशेने वाहतात याची त्यांना फारशी काळजी नसते.</p>\n</div></div>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>शिकवण्याचे उदाहरण म्हणून येथे वापरलेले लहान स्ट्रॅडल वरच्या बाजूला कमाल मर्यादा नसलेला तोटा आणि डाउनसाइडवर खूप मोठा परंतु मर्यादित तोटा आहे, 23,329 आणि 24,771 च्या 46,858 क्रेडिटच्या आसपास ब्रेकवेन्ससह. त्याची सकारात्मक थीटा आणि शॉर्ट वेगा आकर्षक आहेत, परंतु अमर्यादित धोका वास्तविक आहे. एक नवशिक्या ज्याला समान शॉर्ट-गामा, शॉर्ट-वेगा, पॉझिटिव्ह-थीटा प्रोफाइल हवे आहे त्यांनी ते क्रेडिट आयर्न कॉन्डर (कमाल नफा रु 5,616, कमाल तोटा रु. 884) सारख्या परिभाषित-जोखीम संरचनेसह व्यक्त केले पाहिजे, जे सर्वात वाईट केस एक ज्ञात संख्या ठेवते.</p>\n</div></div>\n<h2 id=\"implied-volatility-is-a-regime-not-a-number\">गर्भित अस्थिरता ही एक व्यवस्था आहे, संख्या नाही</h2>\n<p>नेट व्हेगा केवळ महत्त्वाचा आहे जर तुम्हाला माहित असेल की गर्भित अस्थिरता कोणत्या मार्गाने जाण्याची शक्यता आहे आणि हे असे नाही जे तुम्ही एकल कोट वाचता. NIFTY वर आजची एट-द-मनी गर्भित अस्थिरता सुमारे 12.7 टक्के आहे, परंतु 12.7 स्वतःच निरर्थक आहे. योग्य प्रश्न नेहमीच असतो, कशाच्या तुलनेत उच्च की कमी? गर्भित अस्थिरता आहे a <strong>शासन</strong>, आणि तुम्ही त्याचा स्वतःच्या अलीकडील इतिहासाविरुद्ध न्याय करता.</p>\n<p>दोन साधे उपाय त्या इतिहासावर ठेवतात. <strong>IV रँक</strong> त्या श्रेणीची टक्केवारी म्हणून, मागील वर्षातील सर्वात कमी आणि सर्वोच्च रीडिंग दरम्यान वर्तमान गर्भित अस्थिरता कुठे आहे हे विचारते. जर मागील वर्ष 10 ते 22 टक्के असेल आणि आज 12.7 असेल, तर रँक कमी आहे, कारण 12.7 बँडच्या तळाशी बसतो. <strong>IV पर्सेंटाइल</strong> थोडा वेगळा प्रश्न विचारतो: मागील वर्षाच्या दिवसांच्या कोणत्या अंशावर आजच्यापेक्षा कमी अस्थिरता निहित होती. 20 ची टक्केवारी म्हणजे पाचपैकी फक्त एक दिवस स्वस्त होता, त्यामुळे आजचा दिवस शांत आहे. रँक श्रेणीच्या टोकाची काळजी घेते, तुम्ही येथे कितीवेळा आला आहात याची पर्सेंटाइल काळजी घेते आणि सध्या प्रीमियम श्रीमंत आहे की स्वस्त आहे हे एकत्रितपणे सांगतात.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-iv-rank.png\" alt=\"गर्भित अस्थिरता त्याच्या स्वतःच्या बारा-महिन्याच्या इतिहासाच्या विरूद्ध न्यायली जाते: IV रँक मोजतो जेथे आजचा दिवस वर्षाच्या कमी आणि उच्च दरम्यान आहे, तर IV टक्केवारी आजच्या दिवसांपेक्षा शांत असलेल्या दिवसांचा वाटा मोजते, त्यामुळे 12.7 टक्के हीच कच्ची संख्या त्याच्या शीर्ष श्रेणीच्या तळाशी स्वस्त आणि श्रीमंत म्हणून वाचते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>गर्भित अस्थिरता त्याच्या स्वतःच्या बारा-महिन्याच्या इतिहासाच्या विरुद्ध न्यायली जाते: IV रँक मोजतो जेथे आजचा दिवस वर्षाच्या कमी आणि उच्च दरम्यान आहे, तर IV पर्सेंटाइल आजच्या पेक्षा शांत असलेल्या दिवसांचा वाटा मोजतो, त्यामुळे 12.7 टक्के हीच कच्ची संख्या त्याच्या शीर्ष श्रेणीच्या तळाशी स्वस्त आणि श्रीमंत म्हणून वाचते.</figcaption></figure>\n<p>निर्देशांक स्तरावर तुम्हाला याची स्वतः गणना करण्याची गरज नाही. <strong>भारत VIX</strong> संपूर्ण ऑप्शन चेनमधून व्युत्पन्न NIFTY च्या अपेक्षित तीस-दिवसांच्या अस्थिरतेवर बाजाराने प्रकाशित केलेले वाचन आहे. कमी आणि घसरणारा भारत VIX म्हणते की पर्याय बाजार शांतपणे किंमत ठरवत आहे, हे असे वातावरण आहे जेथे विकले जाणारे प्रीमियम शांतपणे नष्ट होते. एक उच्च आणि उगवणारा भारत VIX म्हणते की भीतीची किंमत मोजली जात आहे, प्रीमियम फॅट आहेत आणि त्यांची विक्री करणे अधिक फायदेशीर आणि अधिक धोकादायक आहे.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तुम्ही कोणताही अस्थिरता व्यापार करण्यापूर्वी, IV रँक, IV पर्सेंटाइल आणि भारत VIX एकत्रितपणे पहा. ते एका प्रश्नाचे उत्तर देतात जे ठरवते की आपण विक्रेता किंवा पर्याय खरेदीदार असावे: गर्भित अस्थिरता त्याच्या स्वत: च्या भूतकाळाच्या तुलनेत महाग आहे की स्वस्त? जेव्हा तुम्ही क्रेडिट आणि डेबिट स्ट्रक्चरमध्ये निवड करता तेव्हा ते एकल वाचन दिग्दर्शनावरील कोणत्याही दृश्यापेक्षा अधिक मूल्यवान असते.</p>\n</div></div>\n<h2 id=\"the-skew-puts-cost-more-than-equidistant-calls\">स्क्यू: इक्विडिस्टंट कॉल्सपेक्षा जास्त खर्च येतो</h2>\n<p>एकाच कालबाह्यतेच्या स्ट्राइकमध्ये गर्भित अस्थिरता एकसमान नसते. इंडेक्स ऑप्शन्सवर डाउनसाइड जवळजवळ नेहमीच वरच्या बाजूपेक्षा जास्त गर्भित अस्थिरतेवर व्यवहार करते. पैशाच्या खाली दिलेले अंतर त्याच्या वरच्या समान अंतराच्या कॉलपेक्षा अधिक समृद्ध गर्भित अस्थिरता असते. हे झुकते आहे <strong>अस्थिरता स्क्यू</strong>, आणि ते अस्तित्वात आहे कारण बाजार ते वाढण्यापेक्षा वेगाने घसरतात: गुंतवणूकदार डाउनसाइड संरक्षणासाठी पैसे देतात आणि ती सतत मागणी कमी स्ट्राइकची गर्भित अस्थिरता वाढवते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-vol-skew.png\" alt=\"निर्देशांक अस्थिरता तिरकस: एकाच कालबाह्यतेवर स्ट्राइकच्या विरूद्ध गर्भित अस्थिरतेचे प्लॉटिंग केल्याने खाली उताराची रेषा तयार होते, डावीकडे आउट-ऑफ-द-मनी पुट उजवीकडे समान अंतरावर असलेल्या आउट-ऑफ-द-मनी कॉलपेक्षा जास्त गर्भित अस्थिरता घेऊन जाते, कारण डाउनसाइड संरक्षणाची मागणी कायम असते.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>निर्देशांक अस्थिरता तिरकस: एकाच कालबाह्यतेवर स्ट्राइकच्या विरूद्ध गर्भित अस्थिरतेचे प्लॉटिंग केल्याने खाली उताराची रेषा तयार होते, डावीकडे आउट-ऑफ-द-मनी पुट उजवीकडे समान अंतरावर असलेल्या आउट-ऑफ-द-मनी कॉलपेक्षा जास्त गर्भित अस्थिरता घेऊन जाते, कारण डाउनसाइड संरक्षणाची मागणी कायम असते.</figcaption></figure>\n<p>तुम्ही स्ट्राइक निवडता त्या क्षणी तिरकस महत्त्वाचा असतो. जेव्हा तुम्ही NIFTY वर स्प्रेड आयर्न कंडोर किंवा बुल पुटची पुट साईड विकता, तेव्हा तुम्ही त्या श्रीमंत डाउनसाइड अस्थिरतेमध्ये विकता, त्यामुळे पुट विंग कॉल विंगपेक्षा स्पॉटपासून समान अंतरासाठी अधिक प्रीमियम आणते. याचा अर्थ असा आहे की सममितीय दिसणारी रचना क्वचितच खाली सममितीय असते: डाउनसाइड स्ट्राइकची किंमत वरच्या भागांपेक्षा अधिक भीतीसाठी असते. स्क्यू वाचणे तुम्हाला रेंज ट्रेडच्या दोन्ही बाजू समान पैज आहेत असे गृहीत धरण्यापासून थांबवते.</p>\n<h2 id=\"the-term-structure-near-against-far\">शब्द रचना: जवळ विरुद्ध दूर</h2>\n<p>दुसरा परिमाण म्हणजे वेळ. गर्भित अस्थिरता केवळ स्ट्राइकमध्ये नाही तर कालबाह्यतेमध्ये भिन्न असते. जवळच्या 28 जुलै 2026 च्या एक्सपायरीची 25 ऑगस्ट 2026 च्या एक्सपायरीशी तुलना केल्यास तुम्हाला <strong>मुदत रचना</strong>. शांत बाजारपेठेत ते हळूवारपणे वरच्या दिशेने सरकते, जवळच्या महिन्यापेक्षा दूरचा महिना किंचित जास्त गर्भित अस्थिरता वाहतो, कारण दीर्घ क्षितिजावर बरेच काही घडू शकते. तो ऊर्ध्वगामी आकार ही सामान्य अवस्था आहे.</p>\n<p>अ <strong>उलटा</strong> टर्म स्ट्रक्चर, जिथे जवळचा महिना लांबपेक्षा जास्त महाग असतो, ही एक चेतावणी आहे. हे सहसा परिणाम किंवा धोरणात्मक निर्णयासारख्या ज्ञात कार्यक्रमापूर्वी दिसून येते, जेव्हा बाजाराला खूप लवकर हालचाल होण्याची आणि नंतर शांततेत परत येण्याची अपेक्षा असते. वक्राचा आकार माहिती आहे: वरची मुदतीची रचना म्हणते की जवळची एक्सपायरी तुलनेने स्वस्त आहे, उलटे म्हणते की नजीकची एक्सपायरी इव्हेंट प्रीमियमने लोड केली आहे जी इव्हेंट पास झाल्यानंतर कोसळेल.</p>\n<p>नेमके हेच ए <strong>कॅलेंडर</strong> व्यापार कापणीसाठी बांधला जातो. जवळचा 28 जुलैचा पर्याय विकून टाका आणि त्याच स्ट्राइकवर फार 25 ऑगस्टचा पर्याय विकत घ्या, आणि तुम्ही जवळच्या तारखेची अस्थिरता कमी आणि लांबची लांबलचक अस्थिरता, जर जवळचा पाय लांबच्या पायांपेक्षा अधिक वेगाने क्षीण होत असेल तर नफा मिळवा, ही एक वरची मुदतीची रचना आणि स्थिर स्थान प्रदान करते.</p>\n<h2 id=\"matching-the-structure-to-the-regime\">संरचनेची शासनाशी जुळणी करणे</h2>\n<p>आता दोन लेन्स भेटतात. तुमच्या पोझिशनचे नेट वेगा वाचा, नंतर शासन वाचा आणि ते सहमत असल्याची खात्री करा.</p>\n<ul>\n<li>जेव्हा निहित अस्थिरता असते <strong>उच्च</strong> (समृद्ध IV रँक, उन्नत भारत VIX), प्रीमियम महाग आहे, म्हणून अनुकूल <strong>विक्री</strong> ते क्रेडिट स्प्रेड, क्रेडिट आयरन कंडर आणि शॉर्ट स्ट्रॅडल्स किंवा स्ट्रँगल्स हे सर्व आहेत <strong>लहान वेगा</strong>: जर गर्भित अस्थिरता सामान्य स्थितीत आली तर ते जिंकतात, जे श्रीमंत शासन करतात. नवशिक्यांसाठी, हे परिभाषित-जोखीम ठेवा, नग्न स्ट्रॅडलऐवजी लोखंडी कंडर.</li>\n<li>जेव्हा निहित अस्थिरता असते <strong>कमी</strong> (स्वस्त IV रँक, शांत भारत VIX), प्रीमियम स्वस्त आहे, म्हणून अनुकूल <strong>खरेदी</strong> ते डेबिट स्प्रेड आणि लांब पर्याय आहेत <strong>लांब वेगा</strong>: कमी पायावरून गर्भित अस्थिरता वाढल्यास ते जिंकतात आणि जेव्हा पर्याय स्वस्त असतात तेव्हा त्यांची किंमत कमी असते.</li>\n<li>जेव्हा धार त्याच्या पातळीपेक्षा वक्र आकारात असेल तेव्हा a वापरा <strong>कॅलेंडर</strong> व्यापार करण्यासाठी <strong>मुदत रचना</strong>, जवळच्या-तारीखातील अस्थिरतेला महाग विकणे आणि स्वस्त दूर-तारांकित अस्थिरतेचे मालक असणे.</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>उच्च विक्री करा आणि कमी खरेदी करा हा एक प्रारंभिक पूर्वाग्रह आहे, नियम नाही. उच्च गर्भित अस्थिरता केवळ तेव्हाच विकण्यायोग्य असते जेव्हा गर्भित हालचाली तुम्हाला प्रत्यक्षात साकार होण्याची अपेक्षा असल्याच्या विरूद्ध खरोखर समृद्ध असते आणि उच्च वाचन अनेकदा समोरील खरी घटना प्रतिबिंबित करते. कमाईच्या परिणामात किंवा पॉलिसीच्या दिवसात विक्री केल्याने तुम्हाला फॅट प्रीमियम आणि त्याच ट्रेडमध्ये क्रूर अंतर मिळू शकते. त्यामुळे इव्हेंट चेकसह वाचलेली व्यवस्था जोडा, जोखीम परिभाषित ठेवा आणि केवळ संख्या जास्त असल्यामुळे प्रीमियम कधीही विकू नका.</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>याला एकत्र बांधणारा नियम हे राजवटीच्या विरोधात तुमच्या निव्वळ वेगाचे लक्षण आहे. गर्भित अस्थिरता कमी झाल्यास शॉर्ट वेगा जिंकतो, म्हणून ते उच्च-IV′ नियमांमध्ये संबंधित आहे. गर्भित अस्थिरता वाढल्यास लॉन्ग वेगा जिंकतो, म्हणून ते कमी-IV′ नियमांमध्ये संबंधित आहे. जेव्हा गर्भित अस्थिरता आधीच स्वस्त असते तेव्हा शॉर्ट-वेगा ट्रेड करणे किंवा जेव्हा ते आधीच महाग असते तेव्हा लाँग-वेगा ट्रेड करणे हे राजवटीचा लढा आहे आणि सामान्यतः शासन जिंकते.</p>\n</div></div>\n<h2 id=\"the-practical-takeaway\">व्यावहारिक टेकअवे</h2>\n<p>ग्रीक आणि अस्थिरता शासन शैक्षणिक सजावट नाहीत; ते प्री-फ्लाइट चेक आहेत जे या कोर्सचा उर्वरित निर्णय तुम्ही बचाव करू शकता. शिस्त लहान आहे आणि ती कधीही बदलत नाही.</p>\n<ul>\n<li>पाय जोडा आणि निव्वळ ग्रीक वाचा. तुमचा नेट डेल्टा (तुम्ही कोणत्या मार्गाने झुकता), नेट गामा (किती वेगाने बदलतो), नेट थीटा (वेळ तुम्हाला पैसे देते की नाही) आणि नेट वेगा (तुम्ही विकत किंवा खरेदी करत असलात तरीही) जाणून घ्या.</li>\n<li>व्हेगा चिन्हावरून ठरवा की पोझिशन विक्रेता आहे की खरेदीदार अस्थिरतेचा, आणि तो कधीही अपघात होऊ देऊ नका.</li>\n<li>IV रँक, IV पर्सेंटाइल आणि भारत VIX सह वर्तमान गर्भित अस्थिरता त्याच्या स्वत:च्या इतिहासावर ठेवा, म्हणजे तुम्हाला कळेल की प्रीमियम श्रीमंत आहे की स्वस्त.</li>\n<li>तुम्ही स्ट्राइक निवडण्यापूर्वी स्क्यू आणि तुम्ही एक्सपायरी निवडण्यापूर्वी टर्म स्ट्रक्चर तपासा.</li>\n<li>जेव्हा शासन तुमच्या बाजूने असेल तेव्हाच ते लावा: जेव्हा गर्भित अस्थिरता जास्त असेल तेव्हा प्रीमियम विका, जेव्हा ते कमी असेल तेव्हा ते खरेदी करा आणि जेव्हा किनारी वक्र असेल तेव्हा कॅलेंडर व्यापार करा. त्या सवयीमुळे, तुम्ही अंतिम अध्यायात निवडलेली रणनीती तुम्ही ज्या मार्केटमध्ये आहात त्या आधीच फिट होईल.</li>\n</ul>\n","toc":[{"level":2,"text":"स्थिती म्हणजे त्याच्या पायांची बेरीज","id":"a-position-is-the-sum-of-its-legs"},{"level":2,"text":"चार निव्वळ ग्रीक वाचणे","id":"reading-the-four-net-greeks"},{"level":2,"text":"गर्भित अस्थिरता ही एक व्यवस्था आहे, संख्या नाही","id":"implied-volatility-is-a-regime-not-a-number"},{"level":2,"text":"स्क्यू: इक्विडिस्टंट कॉल्सपेक्षा जास्त खर्च येतो","id":"the-skew-puts-cost-more-than-equidistant-calls"},{"level":2,"text":"शब्द रचना: जवळ विरुद्ध दूर","id":"the-term-structure-near-against-far"},{"level":2,"text":"संरचनेची शासनाशी जुळणी करणे","id":"matching-the-structure-to-the-regime"},{"level":2,"text":"व्यावहारिक टेकअवे","id":"the-practical-takeaway"}],"imgCount":3,"hasContent":true},"27":{"html":"<p>तुम्ही हा संपूर्ण कोर्स मीटिंग स्ट्रॅटेजीज एका वेळी एक खर्च केला आहे, प्रत्येकाचा पेऑफ आकार आणि त्याच्या तीन क्रमांकांनुसार शिकत आहात. आता एक भाग येतो जो ठरवतो की यापैकी काहीही तुम्हाला पैसे कमवते की नाही: क्षणासाठी योग्य निवडणे आणि ते चालू झाल्यावर ते व्यवस्थापित करणे. रणनीती हे फक्त एक साधन आहे, आणि सर्वोत्तम साधन ते आहे जे नोकरी आणि तुमच्या खात्याच्या आकाराशी जुळते. हा शेवटचा अध्याय सर्वकाही एकत्र आणतो. हे तुमचे बाजाराचे दृश्य एका समंजस संरचनेत मॅप करते, तुम्ही परिभाषित जोखमीपासून सुरुवात का करावी हे स्पष्ट करते, एखाद्या स्थितीचा आकार कसा घ्यावा हे दाखवते जेणेकरुन एक खराब व्यापार तुमचा व्यापार संपुष्टात आणू शकत नाही आणि नफा मिळवण्यासाठी, समायोजित करण्यासाठी आणि दूर जाण्यासाठी स्पष्ट नियम मांडते. प्रत्येक व्यापारापूर्वी तुम्ही चालवू शकता अशा चेकलिस्टसह आम्ही पूर्ण करतो.</p>\n<h2 id=\"start-with-your-view-then-pick-the-shape\">आपल्या दृश्यासह प्रारंभ करा, नंतर आकार निवडा</h2>\n<p>या कोर्समधील प्रत्येक स्ट्रॅटेजी पुढे कुठे जाईल याविषयी वेगळ्या मताचे उत्तर देते. त्यामुळे पहिला प्रश्न कधीच कोणती रणनीती नसतो, तर प्रत्यक्षात काय होईल असे तुम्हाला वाटते. तुम्ही उत्साही, मंदीचे, शांततेची अपेक्षा करत आहात किंवा दोन्ही दिशेने मोठ्या हालचालीसाठी सज्ज आहात? एकदा ते प्रामाणिक आणि विशिष्ट झाल्यानंतर, रचना जवळजवळ स्वतःच निवडते.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-strategy-by-view.png\" alt=\"व्ह्यू-टू-स्ट्रॅटेजी सिलेक्टर: बुलिश, मंदीचा, तटस्थ आणि मोठ्या-मूव्ह मते प्रत्येक नकाशामध्ये त्यांच्याशी जुळणाऱ्या परिभाषित-जोखीम संरचनेसाठी, त्यामुळे तुम्हीNIFTY′ कडून प्रत्यक्षात अपेक्षित असलेल्या गोष्टींशी जुळणारा आकार निवडा.\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">आकृती</span>व्ह्यू-टू-स्ट्रॅटेजी सिलेक्टर: बुलिश, मंदीचा, तटस्थ आणि मोठ्या-मूव्ह मते प्रत्येक नकाशामध्ये त्यांच्याशी जुळणाऱ्या परिभाषित-जोखीम संरचनांसाठी, त्यामुळे तुम्हीNIFTY′ कडून प्रत्यक्षात अपेक्षित असलेल्या गोष्टींशी जुळणारा आकार निवडा.</figcaption></figure>\n<p>येथे सारणी सारखीच कल्पना आहे, संपूर्ण अभ्यासक्रमातून (स्पॉट 24,056, लॉट 65, 28 जुलै 2026 एक्सपायरी) वास्तविकNIFTY′ संख्या वापरून, जेणेकरून तुम्ही तीन संख्यांची शेजारी शेजारी तुलना करू शकता.</p>\n<table>\n<thead>\n<tr>\n<th>तुमचा दृष्टिकोन</th>\n<th>समंजस रचना</th>\n<th>ब्रेकवेन</th>\n<th>जास्तीत जास्त नफा</th>\n<th>कमाल नुकसान</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>सौम्यपणे तेजी</td>\n<td>बैल कॉल पसरला</td>\n<td>24,106</td>\n<td>रु. 2,876</td>\n<td>3,624 रु</td>\n</tr>\n<tr>\n<td>बुलिश, क्रेडिट पाहिजे</td>\n<td>बैल पसरला</td>\n<td>24,011</td>\n<td>2,506 रु</td>\n<td>3,994 रु</td>\n</tr>\n<tr>\n<td>सौम्यपणे मंदीचा</td>\n<td>अस्वल पसरले</td>\n<td>24,011</td>\n<td>3,994 रु</td>\n<td>2,506 रु</td>\n</tr>\n<tr>\n<td>मंदी, क्रेडिट पाहिजे</td>\n<td>अस्वल कॉल पसरला</td>\n<td>24,106</td>\n<td>3,624 रु</td>\n<td>रु. 2,876</td>\n</tr>\n<tr>\n<td>तटस्थ, एक श्रेणी धारण करते</td>\n<td>लांब लोखंडी कंडोर (बिल्डर, श्रेणी आवृत्ती)</td>\n<td>23,864 आणि 24,236</td>\n<td>५,६१६ रु</td>\n<td>रु 884</td>\n</tr>\n<tr>\n<td>तटस्थ, स्ट्राइक पिन करते</td>\n<td>लांब लोखंडी माशी (बिल्डर, पिन आवृत्ती)</td>\n<td>23,956 आणि 24,148</td>\n<td>6,130 रु</td>\n<td>370 रु</td>\n</tr>\n<tr>\n<td>मोठी चाल, कोणत्याही प्रकारे</td>\n<td>लांब स्ट्रॅडल</td>\n<td>23,329 आणि 24,771</td>\n<td>अमर्यादित</td>\n<td>46,858 रु</td>\n</tr>\n<tr>\n<td>मोठी चाल, स्वस्त</td>\n<td>लांब गळा</td>\n<td>23,323 आणि 24,777</td>\n<td>अमर्यादित</td>\n<td>40,729 रु</td>\n</tr>\n</tbody></table>\n<p>हे टेबल मेनू म्हणून वाचा, रँकिंग नाही. बुल कॉल स्प्रेड लोखंडी कंडरपेक्षा चांगले नाही; ते वेगवेगळ्या मतांना उत्तर देतात. शिस्त म्हणजे तुम्हाला आवडणारी रणनीती निवडण्याऐवजी तुमच्या प्रामाणिक मताला पंक्ती निवडू द्यावी आणि नंतर ते न्याय्य ठरविण्यासाठी दृष्टिकोन शोधून काढावा. हे देखील लक्षात ठेवा की नफ्याची संभाव्यता, जी तुम्ही बिल्डर पॅनेलमधून वाचू शकता, हा निवडीचा एक भाग आहे: घट्ट स्ट्राइकसह उच्च-क्रेडिट आयर्न कंडोर विस्तीर्ण स्ट्राइकपेक्षा कमी वेळा जिंकतो, म्हणून तुमचे स्ट्राइक तुम्हाला हव्या असलेल्या शक्यतांवर सेट करा.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>एक नामकरण टीप. बिल्डरने या दोन तटस्थ संरचनांना लाँग आयर्न कॉन्डोर आणि लाँग आयर्न फ्लाय असे लेबल दिले आहे. त्याच्या अधिवेशनात त्या श्रेणी-बाउंड, क्रेडिट-शैलीच्या आवृत्त्या आहेत: जेव्हा NIFTY पंखांच्या (कंडॉर) आत राहते किंवा मध्यभागी स्ट्राइक (माशी) पिन करते आणि विकत घेतलेले बाहेरचे पाय नुकसान कमी करतात, तेव्हा तुम्हाला नफा होतो, म्हणूनच टेबल लहान कॅप केलेला कमाल तोटा आणि मोठा कमाल नफा दर्शवितो. इतर प्लॅटफॉर्म काहीवेळा लांब आणि लहान लेबले विरुद्ध मार्गाने संलग्न करतात, म्हणून केवळ नावावर कधीही विश्वास ठेवू नका. तुम्ही व्यापार करण्यापूर्वी पेऑफ आकार आणि बिल्डर पॅनेलच्या नफ्याची संभाव्यता वाचा.</p>\n</div></div>\n\n<div class=\"callout key\"><span class=\"callout-tag\">मुख्य कल्पना</span><div><p>निर्णयांचा क्रम महत्त्वाचा. प्रथम NIFTY वर स्पष्ट, विशिष्ट दृश्य तयार करा. नंतर ती रचना निवडा जिचा पेऑफ आकार अचूक दृश्य बक्षीस देतो. प्रथम रणनीती निवडणे आणि त्यात बसण्यासाठी तुमचा दृष्टिकोन वाकवणे हा उत्तम प्रकारे चांगल्या संरचनेवर व्यापारी पैसे गमावण्याचा सर्वात सामान्य मार्ग आहे.</p>\n</div></div>\n<h2 id=\"defined-risk-first-always\">परिभाषित धोका प्रथम, नेहमी</h2>\n<p>या संपूर्ण कोर्समधून तुम्हाला एक नियम आठवत असेल तर तो बनवा. जोपर्यंत तुम्ही अनुभवी होत नाही तोपर्यंत व्यापार करा <strong>परिभाषित-जोखीम</strong> स्ट्रक्चर्स, ज्यांचे जास्तीत जास्त नुकसान एक निश्चित, ज्ञात संख्या आहे जे तुम्ही कधीही प्रविष्ट करण्यापूर्वी चार्टवर छापलेले आहे.</p>\n<p>टेबलावर परत बघा. बुल कॉल स्प्रेड 3,624 रुपयांचा धोका आहे आणि एक रुपया जास्त नाही. आयर्न कंडोरची जोखीम रु. 884 आहे, लोखंडी माशी फक्त रु. 370. यापैकी प्रत्येक तोटा मर्यादित आहे, कारण विकत घेतलेला पर्याय कुठेतरी तो कॅप करतो. आपण आपली कमाल गमावू शकता, परंतु आपण कधीही आश्चर्य गमावू शकत नाही.</p>\n<p>संरचनेसह कॉन्ट्रास्ट करा की हा कोर्स चेतावणींसह ध्वजांकित आहे: शॉर्ट स्ट्रॅडल आणि शॉर्ट स्ट्रँगल, कॉल आणि पुट रेशो स्प्रेड्स, लांब आणि शॉर्ट सिंथेटिक भविष्य, जेड लिझार्डच्या आत शॉर्ट पुट. त्या प्रत्येक एक वाहून <strong>अपरिभाषित किंवा अमर्यादित नुकसान</strong> कमीत कमी एका बाजूला, आणि जुळण्यासाठी मार्जिन, अनेकदा एकाच इंडेक्स लॉटसाठी दीड लाखांपेक्षा जास्त. ते चांगले पैसे देऊ शकतात आणि अनुभवी व्यापारी त्यांचा वापर करतात, परंतु NIFTY मधील एकल हिंसक हालचाली तुम्ही गोळा केलेल्या प्रीमियमच्या कितीतरी पटीने जास्त खर्च करू शकतात. तिथे शिकायला हवे असे नाही.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">डोके वर काढा</span><div><p>अमर्यादित किंवा ओपन-एंडेड लॉस, शॉर्ट स्ट्रॅडल आणि स्ट्रँगल्स, नग्न पायांसह रेशो स्प्रेड, सिंथेटिक फ्युचर्स आणि बेअर शॉर्ट पुट्स, अशा स्ट्रॅटेजीज तुम्ही गोळा करता त्यापेक्षा कितीतरी जास्त नुकसान करू शकतात आणि एकाच सत्रात ट्रेडिंग खाती संपवली आहेत. मास्टर डिफाइंड-रिस्क स्ट्रक्चर्स, जिथे तुम्ही त्यांच्या जवळ कुठेही जाण्यापूर्वी, चार्टवर सर्वात वाईट केस छापले जातात.</p>\n</div></div>\n<p>जोखीम महत्त्वाची व्याख्या करण्याचे दुसरे कारण आहे: ते तुम्हाला योग्य आकार देऊ देते, कारण तुम्हाला सर्वात वाईट परिस्थिती आधीच माहित आहे. एखाद्या स्थानाचे किती नुकसान होऊ शकते हे आपल्याला माहिती नसल्यास आणि अपरिभाषित-जोखमीचे व्यवहार आपल्यापासून ती संख्या लपवून ठेवत असल्यास आपण समजूतदारपणे आकार देऊ शकत नाही.</p>\n<h2 id=\"size-every-position-to-survive\">जगण्यासाठी प्रत्येक स्थितीचा आकार घ्या</h2>\n<p>अयशस्वी होण्याचा सर्वात जलद मार्ग म्हणजे चुकीची रणनीती निवडणे नाही. हे एका व्यापारावर खूप जास्त टाकत आहे आणि तुमच्या काठावर काम करण्याची वेळ येण्याआधीच ते नष्ट केले जात आहे. पोझिशन साइझिंग म्हणजे जगणे.</p>\n<p>व्यावसायिक वापरत असलेला साधा नियम म्हणजे कोणत्याही एकाच व्यापारावर तुमच्या खात्याचा फक्त एक छोटा तुकडा जोखीम पत्करावा <strong>एक ते दोन टक्के.</strong> परिभाषित जोखमीसह हे सोपे अंकगणित आहे, कारण तुमचे जास्तीत जास्त नुकसान ज्ञात आहे.</p>\n<ul>\n<li>समजा तुमचे खाते रु 5,00,000 आहे आणि तुम्ही दोन टक्के जोखीम कॅप केली आहे, जी प्रति ट्रेड रु 10,000 आहे.</li>\n<li>बुल कॉल स्प्रेड एका लॉटसाठी 3,624 रु. ते तुमच्या रु. 10,000 च्या मर्यादेत आरामात बसते आणि 7,248 रु.च्या जोखमीच्या दोन लॉट देखील त्यामध्ये असतील.</li>\n<li>लांब पल्ल्याची एका लॉटसाठी 46,858 रु. ते तुमच्या रु. 10,000 च्या मर्यादेच्या जवळपास पाचपट आहे, त्यामुळे एक लॉट आधीच खूप मोठा आहे आणि तुम्ही ते वगळू शकता किंवा स्वस्त स्ट्रक्चरची वाट पहा.</li>\n</ul>\n<p>मुद्दा अचूक टक्केवारीचा नाही. हे असे आहे की तुमचा आकार तुमच्या जास्तीत जास्त नुकसानातून प्रवाहित होतो, तुम्हाला किती आत्मविश्वास वाटतो यावरून नाही. आत्मविश्वास हे सर्वात वाईट संभाव्य आकाराचे इनपुट आहे, कारण सर्वात जास्त दुखावलेल्या ट्रेड्सच्या आधी तुम्हाला सर्वात आत्मविश्वास वाटतो.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">टीप</span><div><p>तुमच्या नुकसानीच्या मर्यादेपासून मागे काम करा. तुम्ही व्यापारात गमावू इच्छित असलेली रुपयाची रक्कम ठरवा, नंतर तुमच्या लॉटची संख्या मिळवण्यासाठी रणनीतीच्या कमाल तोट्याने प्रति लॉट भागा. जर उत्तर एकापेक्षा कमी लॉट असेल, तर तुमच्या खात्यासाठी व्यापार खूप मोठा आहे आणि तुम्ही ते वगळता. ही एक सवय बहुतेक खाते समाप्ती चुका टाळते.</p>\n</div></div>\n<h2 id=\"manage-the-trade-profit-adjust-exit\">व्यापार व्यवस्थापित करा: नफा, समायोजित करा, बाहेर पडा</h2>\n<p>जेव्हा तुम्ही ते उघडता तेव्हा स्थिती पूर्ण होत नाही. तुम्ही शांत असताना प्रवेश करण्यापूर्वी तुमचे व्यवस्थापन नियम ठरवा, कारण एकदा पैसा फिरला की तुमचा निर्णय खराब होतो.</p>\n<p><strong>नफा कधी घ्यायचा.</strong> जिंकण्यासाठी कालबाह्य होण्यासाठी तुम्हाला क्रेडिट ट्रेड ठेवण्याची गरज नाही. अनेक व्यापारी एक परिभाषित-जोखीम क्रेडिट स्ट्रक्चर बंद करतात जेव्हा त्याने त्याच्या जास्तीत जास्त नफ्याचा मोठा भाग घेतला की, अनेकदा अर्धा ते तीन चतुर्थांश, उलटसुलट स्थितीत असताना शेवटचा रुपया पिळून टाकण्याऐवजी. चांगला नफा लवकर घेतल्याने तुमचे भांडवल मोकळे होते आणि जोखीम काढून टाकते ज्याची तुम्हाला आता गरज नाही. डेबिट स्प्रेडसाठी, हीच कल्पना लागू होते: जर तुम्हाला हवी असलेली हालचाल बहुतेक झाली असेल आणि कालबाह्य होण्यापूर्वी स्थिती त्याच्या कमाल नफ्याच्या जवळ असेल, तर ते बंद केल्याने विजय मिळू शकतो.</p>\n<p><strong>केव्हा जुळवायचे.</strong> ॲडजस्ट करणे म्हणजे तुमच्या विरोधात गेलेला ट्रेड दुरुस्त करण्यासाठी पाय बदलणे, ॲडजस्टमेंट प्रकरणाचा विषय, उदाहरणार्थ अधिक क्रेडिट गोळा करण्यासाठी लोखंडी कंडोरची न तपासलेली बाजू जवळ आणणे किंवा धोक्यात आलेल्या शॉर्ट स्ट्राइकला आणखी दूर हलवणे. जुळवून घेणे हे खरे कौशल्य आहे, पण वाईटानंतर चांगले पैसे फेकून व्यापारी अडचणीत येतात. चतुर दुरुस्तीपेक्षा साध्या व्यवस्थापनाला प्राधान्य द्या. पराभूत झालेल्याला वाचवण्यासाठी जोखीम वाढवणारे समायोजन अनेकदा तुम्ही साइन अप केलेले परिभाषित नुकसान स्वीकारण्यापेक्षा वाईट असते.</p>\n<p><strong>कधी बाहेर पडायचे.</strong> जेव्हा व्यापाराचे कारण निघून जाईल, जेव्हा तुमचा दृष्टिकोन बदलला असेल किंवा जेव्हा तुम्ही आगाऊ सेट केलेल्या तोट्याच्या पातळीवर पोझिशन पोहोचेल तेव्हा बाहेर पडा. परिभाषित जोखमीसह तुमच्याकडे नेहमी काहीही न करण्याचा पर्याय असतो आणि सर्वात वाईट परिस्थिती बाहेर येऊ द्या, कारण ती मर्यादित असते, परंतु भांडवल टिकवून ठेवण्यासाठी लवकर बाहेर पडणे हे सामान्यतः व्यापाराचे पूर्ण नुकसान पाहण्यापेक्षा शहाणपणाचे असते. तोटा टाळण्यासाठी तुमचा धोका कधीही वाढवू नका; अशा प्रकारे एक लहान परिभाषित नुकसान अपरिभाषित मध्ये बदलते.</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">नोंद</span><div><p>तुम्ही प्रवेश करण्यापूर्वी तुमचे निर्गमन ठरवा. तुम्ही कोठे बंद कराल ते नफ्याची पातळी, तुम्ही कुठे थांबाल ते नुकसान पातळी आणि तुम्ही कोणत्या तारखेपर्यंत बाहेर पडाल याची पर्वा न करता लिहा. शांततेत केलेली योजना प्रत्येक वेळी घाबरून घेतलेल्या निर्णयावर मात करते.</p>\n</div></div>\n<h2 id=\"your-pre-trade-checklist\">तुमची पूर्व-व्यापार चेकलिस्ट</h2>\n<p>कोणतीही रणनीती ठेवण्यापूर्वी ही यादी चालवा. आपण प्रत्येक ओळीचे उत्तर देऊ शकत नसल्यास, व्यापार तयार नाही.</p>\n<ul>\n<li><strong>पहा.</strong> मी एका साध्या वाक्यात सांगू शकतो की मी काय अपेक्षा करतो NIFTY आणि साधारणपणे कधीपर्यंत?</li>\n<li><strong>आकार.</strong> या संरचनेचा मोबदला प्रत्यक्षात त्या दृश्याला पुरस्कृत करतो आणि मी त्याचा तक्ता पाहिला आहे का?</li>\n<li><strong>तीन संख्या.</strong> मी प्रवेश करण्यापूर्वी मला ब्रेकइव्हन, जास्तीत जास्त नफा आणि जास्तीत जास्त तोटा माहित आहे का?</li>\n<li><strong>शक्यता.</strong> मी नफ्याची संभाव्यता तपासली आहे आणि बक्षीस त्याचे समर्थन करते का?</li>\n<li><strong>परिभाषित धोका.</strong> माझे सर्वात वाईट केस कॅप केलेले आणि ज्ञात आहे? नसल्यास, मी खरोखरच ओपन-एंडेड नुकसान आणि त्याचे मोठे फरक समजून घेतो आणि स्वीकारतो का?</li>\n<li><strong>आकार.</strong> माझ्या खात्याच्या एका छोट्या तुकड्यात जोखीम ठेवून माझ्या लॉटची संख्या माझ्या तोट्याच्या मर्यादेतून येते का?</li>\n<li><strong>बाहेर पडते.</strong> मी कुठे नफा घेतो, कुठे तोटा कमी केला आणि मी बाहेर पडल्याची तारीख मी लिहून ठेवली आहे का?</li>\n<li><strong>तालीम.</strong> मी ते स्ट्रॅटेजी बिल्डरमध्ये तयार केले आहे आणि, जर ते माझ्यासाठी नवीन असेल, तर ते सँडबॉक्स ट्रेडिंगमध्ये (Analyser मोड OpenAlgo मध्ये) प्रथम चालवा?</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">तुम्हाला माहीत आहे का</span><div><p>जे व्यापारी टिकतात ते क्वचितच हुशार धोरणे असलेले असतात. ते असे आहेत जे एका साध्या संरचनेशी स्पष्ट दृश्याशी जुळतात, त्यांची जोखीम परिभाषित ठेवतात, गमावलेल्या स्ट्रीकमध्ये टिकून राहण्यासाठी आकार लहान ठेवतात आणि त्यांच्या स्वत: च्या बाहेर पडण्याच्या योजनेचे अनुसरण करतात. या अभ्यासक्रमातील प्रत्येक साधन त्या शिस्तीत कार्य करते आणि त्याशिवाय कोणतेही कार्य करत नाही.</p>\n</div></div>\n<p>ते म्हणजे लघुचित्रातील संपूर्ण हस्तकला. तुम्हाला आता नामांकित रचना माहित आहेत, कोणताही मोबदला त्याचा आकार आणि नऊ संख्यांनुसार कसा वाचायचा आणि जोखमीचा प्रामाणिक आदर ठेवून व्यापार कसा निवडावा, आकार कसा घ्यावा आणि व्यवस्थापित करा. परिभाषित-जोखीम संरचनांपासून सुरुवात करत रहा, तुमचा आकार लहान ठेवा आणि वास्तविक पैसे येण्यापूर्वी स्ट्रॅटेजी बिल्डरमध्ये रिहर्सल करत रहा. रणनीती नेहमीच असतील. तुमच्या भांडवलाचे रक्षण करण्यामुळे तुम्ही पुढच्या वर्षी व्यापार करत आहात हा भाग त्यांना महत्त्वाचा ठरतो.</p>\n","toc":[{"level":2,"text":"आपल्या दृश्यासह प्रारंभ करा, नंतर आकार निवडा","id":"start-with-your-view-then-pick-the-shape"},{"level":2,"text":"परिभाषित धोका प्रथम, नेहमी","id":"defined-risk-first-always"},{"level":2,"text":"जगण्यासाठी प्रत्येक स्थितीचा आकार घ्या","id":"size-every-position-to-survive"},{"level":2,"text":"व्यापार व्यवस्थापित करा: नफा, समायोजित करा, बाहेर पडा","id":"manage-the-trade-profit-adjust-exit"},{"level":2,"text":"तुमची पूर्व-व्यापार चेकलिस्ट","id":"your-pre-trade-checklist"}],"imgCount":1,"hasContent":true}}
